        if (obs.drilling >= 6) {
            if (mem.ti >= 0 && mem.ti < mem.hints.length) {
                var hd2 = Math.sqrt(Math.pow(mem.hints[mem.ti].x - obs.x, 2) + Math.pow(mem.hints[mem.ti].y - obs.y, 2));
                if (hd2 < 35) mem.hints[mem.ti].done = true;
            }
            mem.mode = 0; mem.ti = -1; mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t;
            mem.cL = 0; mem.cR = 0;
            return { left: 0, right: 0, drill: false };
        }
        var hl = 0;
        if (Math.abs(obs.pitch) > 0.2) {
            hl = Math.min(0.35, Math.abs(obs.pitch) * 0.04);
            if (obs.pitch < 0) hl = -hl;
        }
        if (spd > 0.05) {
            if (obs.pitch > 0.2) hl += 0.15;
            else if (obs.pitch < -0.2) hl -= 0.15;
            else hl -= 0.1;
        }
        hl = Math.max(-0.4, Math.min(0.4, hl));
        return { left: hl, right: hl, drill: true };
    }

    if (mem.mode === 2) {
        if (Math.sqrt(Math.pow(obs.x - mem.bx, 2) + Math.pow(obs.y - mem.by, 2)) < 3) {
            mem.mode = 3; mem.cL = 0; mem.cR = 0;
            return { left: 0, right: 0, drill: false };
        }
        return nav(obs, mem, rays, mem.bx, mem.by, head, spd);
    }

    if (mem.mode === 3) {
        var dBase = Math.sqrt(Math.pow(obs.x - mem.bx, 2) + Math.pow(obs.y - mem.by, 2));
        if (dBase > 4.5) {
            mem.mode = 0; mem.ti = -1; mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t;
        } else if (cr === 0 && bat > 0.3 && tl > 80) {
            mem.mode = 0; mem.ti = -1; mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t; mem.stT = 0;
        }
        var dl = 0;
        if (Math.abs(obs.pitch) > 0.2) {
            dl = Math.min(0.3, Math.abs(obs.pitch) * 0.03);
            if (obs.pitch < 0) dl = -dl;
        }
        return { left: dl, right: dl, drill: false };
    }

    var dBase = Math.sqrt(Math.pow(obs.x - mem.bx, 2) + Math.pow(obs.y - mem.by, 2));

    if (cr >= mem.cap || (cr > 0 && (bat < 0.12 || tl < 60 || tl < dBase / 0.4 + 30))) {
        mem.mode = 2; mem.cL = 0; mem.cR = 0;
        return nav(obs, mem, rays, mem.bx, mem.by, head, spd);
    }

    if (obs.site && cr < mem.cap) {
        var sb = obs.site.bearing;
        var sd = obs.site.distance;

        if (sd < 1.5 && spd < 0.1) {
            mem.mode = 1; mem.cL = 0; mem.cR = 0;
            return { left: 0, right: 0, drill: true };
        }
        if (sd < 2 && spd > 0.4) return { left: -0.25, right: -0.25, drill: false };
        if (sd < 1.5 && spd >= 0.1) return { left: -0.15, right: -0.15, drill: false };

        if (Math.abs(sb) > 45) {
            var td = sb > 0 ? 1 : -1;
            mem.cL = 0; mem.cR = 0;
            return { left: -0.2 * td, right: 0.2 * td, drill: false };
        }

        var aSpd = 0.35;
        if (sd < 3) aSpd = 0.15;
        else if (sd < 5) aSpd = 0.25;

        var steer = sb * 0.012;
        steer = Math.max(-0.5, Math.min(0.5, steer));

        if (rays[4] < 1.8) {
            var ls = rays[0] + rays[1] + rays[2] + rays[3];
            var rs = rays[5] + rays[6] + rays[7] + rays[8];
            return ls > rs ? { left: -0.2, right: 0.2, drill: false } : { left: 0.2, right: -0.2, drill: false };
        }
        if (spd > 0.8) return { left: -0.15, right: -0.15, drill: false };

        var aL = aSpd * (1 - steer);
        var aR = aSpd * (1 + steer);
        mem.cL = mem.cL * 0.6 + aL * 0.4;
        mem.cR = mem.cR * 0.6 + aR * 0.4;
        return { left: mem.cL, right: mem.cR, drill: false };
    }

    if (mem.ti < 0 || mem.ti >= mem.hints.length || mem.hints[mem.ti].done) {
        mem.ti = pick(obs, mem, cr, bat, tl);
        mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t; mem.stT = 0;
    }

    if (mem.ti < 0) {
        if (obs.science > 0.05 && bat > 0.3 && tl > 100) {
            var wa = obs.t * 0.3;
            return nav(obs, mem, rays, obs.x + 15 * Math.cos(wa), obs.y + 15 * Math.sin(wa), head, spd);
        }
        mem.mode = 2; mem.cL = 0; mem.cR = 0;
        return nav(obs, mem, rays, mem.bx, mem.by, head, spd);
    }

    var hint = mem.hints[mem.ti];
    var dh = Math.sqrt(Math.pow(hint.x - obs.x, 2) + Math.pow(hint.y - obs.y, 2));

    if (dh < mem.pd - 2) { mem.pd = dh; mem.ppT = obs.t; }

    if (obs.t - mem.ppT > 70 || mem.stT > 25) {
        hint.done = true; mem.ti = -1; mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t; mem.stT = 0;
        return { left: 0, right: 0, drill: false };
    }

    if (dh < 12) {
        if (mem.sT < 0) mem.sT = obs.t;
        var sTime = obs.t - mem.sT;
        if (sTime > 5 && obs.science < 0.005) {
            hint.done = true; mem.ti = -1; mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t;
            return { left: 0, right: 0, drill: false };
        }
        if (sTime > 75) {
            hint.done = true; mem.ti = -1; mem.sT = -1; mem.pd = 9999; mem.ppT = obs.t;
            return { left: 0, right: 0, drill: false };
        }
        var pts = [[0, 0], [15, 0], [15, 15], [0, 15], [-15, 15], [-15, 0], [-15, -15], [0, -15], [15, -15]];
        var idx = Math.floor(sTime / 8) % pts.length;
        return nav(obs, mem, rays, hint.x + pts[idx][0], hint.y + pts[idx][1], head, spd);
    }

    mem.sT = -1;
    return nav(obs, mem, rays, hint.x, hint.y, head, spd);
}

function nav(obs, mem, rays, tx, ty, head, spd) {
    tx = Math.max(5, Math.min(mem.size - 5, tx));
    ty = Math.max(5, Math.min(mem.size - 5, ty));
    var dx = tx - obs.x;
    var dy = ty - obs.y;
    var dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < 1.5) return { left: 0, right: 0, drill: false };

    var da = Math.atan2(dy, dx) * 180 / Math.PI;
    var he = da - head;
    while (he > 180) he -= 360;
    while (he < -180) he += 360;

    var mn = 15;
    for (var i = 0; i < 9; i++) if (rays[i] < mn) mn = rays[i];

    if (mn < 1.5) {
        var ls = rays[0] + rays[1] + rays[2] + rays[3];
        var rs = rays[5] + rays[6] + rays[7] + rays[8];
        mem.turning = false;
        return ls > rs ? { left: -0.2, right: 0.2, drill: false } : { left: 0.2, right: -0.2, drill: false };
    }

    if (mem.stT > 8) {
        var d = (Math.floor(obs.t / 10) % 2) ? 1 : -1;
        return { left: -0.3 * d, right: 0.3 * d, drill: false };
    }

    var tL, tR;
    if (Math.abs(he) > (mem.turning ? 28 : 50)) {
        mem.turning = true;
        var td = he > 0 ? 1 : -1;
        tL = -0.22 * td;
        tR = 0.22 * td;
    } else {
        mem.turning = false;
        var sp = 0.65;
        if (dist < 15) sp = Math.max(0.15, dist * 0.045);
        if (mn < 3) sp = Math.min(sp, 0.2);
        else if (mn < 5) sp = Math.min(sp, 0.35);
        else if (mn < 8) sp = Math.min(sp, 0.5);
        if (rays[4] < 2.5) sp = Math.min(sp, 0.15);
        else if (rays[4] < 4) sp = Math.min(sp, 0.3);
        if (spd > 1.2) sp = Math.min(sp, 0.2);
        var st = he * 0.012;
        st = Math.max(-0.5, Math.min(0.5, st));
        tL = sp * (1 - st);
        tR = sp * (1 + st);
    }

    var a = 0.35;
    mem.cL = (mem.cL || 0) * (1 - a) + tL * a;
    mem.cR = (mem.cR || 0) * (1 - a) + tR * a;
    return {
        left: Math.max(-1, Math.min(1, mem.cL)),
        right: Math.max(-1, Math.min(1, mem.cR)),
        drill: false
    };
}

function pick(obs, mem, cr, bat, tl) {
    var best = -1, bs = -1, nearest = -1, nd = 9999;
    for (var i = 0; i < mem.hints.length; i++) {
        var h = mem.hints[i];
        if (h.done) continue;
        var d = Math.sqrt(Math.pow(h.x - obs.x, 2) + Math.pow(h.y - obs.y, 2));
        var dB = Math.sqrt(Math.pow(h.x - mem.bx, 2) + Math.pow(h.y - mem.by, 2));
        var trip = d + dB + 15;
        if (d < nd) { nd = d; nearest = i; }
        if (trip * mem.epm * 1.5 + 0.15 > bat * 0.75) continue;
        if (trip / 0.4 + 40 > tl) continue;
        var s = h.e / (trip + 20);
        if (s > bs) { bs = s; best = i; }
    }
    if (best < 0 && nearest >= 0 && nd < 80 && bat > 0.2 && tl > 60) best = nearest;
    return best;
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  function num(v, d) {
    if (v === undefined || v === null) return d;
    var n = Number(v);
    return Number.isFinite(n) ? n : d;
  }
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }
  function wrap(a) {
    a = ((a + 180) % 360 + 360) % 360 - 180;
    return a;
  }
  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1, dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function rad(d) {
    return d * Math.PI / 180;
  }

  var rawX = num(obs.x, 200);
  var rawY = num(obs.y, 200);
  var rawHeading = num(obs.heading, 0);
  var wheelL = num(obs.wheelLeft, 0);
  var wheelR = num(obs.wheelRight, 0);
  var pitch = num(obs.pitch, 0);
  var battery = num(obs.battery, 1);
  var solar = Math.max(0, num(obs.solar, 0));
  var science = Math.max(0, num(obs.science, 0));
  var drillProgress = Math.max(0, num(obs.drilling, 0));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var timeLeft = num(obs.timeLeft, 1200);
  var dt = 0.1;

  if (!mem.initialized) {
    var mission = obs.mission || {};
    var size = mission.size;
    var sx = 400, sy = 400;
    if (typeof size === "number") {
      sx = size;
      sy = size;
    } else if (size && typeof size === "object") {
      sx = num(size.width, num(size.w, num(size.x, 400)));
      sy = num(size.height, num(size.h, num(size.y, 400)));
    } else if (Array.isArray(size)) {
      sx = num(size[0], 400);
      sy = num(size[1], 400);
    }
    var base = mission.base || {};
    mem.sizeX = Math.max(30, sx);
    mem.sizeY = Math.max(30, sy);
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));
    mem.seconds = num(mission.seconds, 1200);
    mem.cands = [];
    var hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi] || {};
      var hx = num(h.x, NaN), hy = num(h.y, NaN);
      if (!Number.isFinite(hx) || !Number.isFinite(hy)) continue;
      var hv = Math.max(0.05, num(h.estimate, num(h.value, 1)));
      var duplicate = -1;
      for (var hj = 0; hj < mem.cands.length; hj++) {
        if (dist(hx, hy, mem.cands[hj].x, mem.cands[hj].y) < 5) {
          duplicate = hj;
          break;
        }
      }
      if (duplicate >= 0) {
        mem.cands[duplicate].value = Math.max(mem.cands[duplicate].value, hv);
      } else {
        mem.cands.push({
          x: clamp(hx, 1, mem.sizeX - 1),
          y: clamp(hy, 1, mem.sizeY - 1),
          value: hv,
          status: 0,
          stage: "travel"
        });
      }
    }
    mem.targetIdx = -1;
    mem.returning = false;
    mem.siteLock = null;
    mem.scout = null;
    mem.exploreGoal = null;
    mem.gridVisited = [];
    mem.tick = 0;
    mem.headingBias = 0;
    mem.ePerM = 0.0022;
    mem.eRate = 0.0014;
    mem.energyWinE = 0;
    mem.energyWinD = 0;
    mem.energyWinT = 0;
    mem.totalTravel = 0;
    mem.holdBiasL = 0;
    mem.holdBiasR = 0;
    mem.wasHolding = false;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastOmegaCmd = 0;
    mem.lastCarried = carried;
    mem.poseInit = false;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  var tick = mem.tick;
  var centerV = (wheelL + wheelR) * 0.5;
  var wheelTravel = (Math.abs(wheelL) + Math.abs(wheelR)) * 0.5 * dt;

  if (mem.prevHeading !== undefined) {
    var predictedYaw = ((wheelR - wheelL) / 0.6) * dt * 57.2957795;
    var observedYaw = wrap(rawHeading - mem.prevHeading);
    var yawResidual = wrap(observedYaw - predictedYaw);
    if (Math.abs(yawResidual) > 70 && Math.abs(predictedYaw) < 25) {
      mem.headingBias = wrap(num(mem.headingBias, 0) - yawResidual);
      mem.compassJumpTick = tick;
    }
  }
  mem.prevHeading = rawHeading;
  var trueHeading = wrap(rawHeading + num(mem.headingBias, 0));

  if (!mem.poseInit) {
    mem.px = rawX;
    mem.py = rawY;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = tick;
    mem.gpsTravel = 0;
    mem.gpsStale = false;
    mem.poseInit = true;
  }

  var rawMove = dist(rawX, rawY, mem.lastRawX, mem.lastRawY);
  var anchorMove = dist(rawX, rawY, mem.gpsAnchorX, mem.gpsAnchorY);
  mem.gpsTravel = num(mem.gpsTravel, 0) + wheelTravel;
  if (anchorMove > 0.8) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = tick;
    mem.gpsTravel = 0;
  }
  var wasGpsStale = !!mem.gpsStale;
  mem.gpsStale = (tick - num(mem.gpsAnchorTick, tick) > 30 &&
                   num(mem.gpsTravel, 0) > 2.2);

  var predX = mem.px + centerV * dt * Math.cos(rad(trueHeading));
  var predY = mem.py + centerV * dt * Math.sin(rad(trueHeading));
  if (!mem.gpsStale && rawMove > 0.015) {
    var ex = rawX - predX, ey = rawY - predY;
    var errLen = Math.sqrt(ex * ex + ey * ey);
    if (errLen < 18) {
      if (errLen > 5) {
        ex *= 5 / errLen;
        ey *= 5 / errLen;
      }
      var alpha = wasGpsStale ? 0.60 : (rawMove > 0.25 ? 0.38 : 0.13);
      predX += alpha * ex;
      predY += alpha * ey;
    }
  }
  mem.px = predX;
  mem.py = predY;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  if (mem.courseX === undefined) {
    mem.courseX = rawX;
    mem.courseY = rawY;
    mem.courseTicks = 0;
    mem.courseSin = 0;
    mem.courseCos = 0;
    mem.courseCount = 0;
    mem.courseBad = false;
  }
  mem.courseTicks++;
  if (!mem.gpsStale && Math.abs(centerV) > 0.4) {
    if (Math.abs(wheelR - wheelL) < 0.5 &&
        Math.abs(num(mem.lastOmegaCmd, 0)) < 0.5) {
      mem.courseSin += Math.sin(rad(rawHeading));
      mem.courseCos += Math.cos(rad(rawHeading));
      mem.courseCount++;
    } else {
      mem.courseBad = true;
    }
  }
  if (mem.courseTicks >= 20) {
    var cd = dist(rawX, rawY, mem.courseX, mem.courseY);
    if (!mem.gpsStale && !mem.courseBad && mem.courseCount >= 12 && cd > 1.4 &&
        tick - num(mem.compassJumpTick, -1000) > 20) {
      var courseAngle = Math.atan2(rawY - mem.courseY, rawX - mem.courseX) * 57.2957795;
      if (centerV < 0) courseAngle = wrap(courseAngle + 180);
      var meanHeading = Math.atan2(mem.courseSin, mem.courseCos) * 57.2957795;
      var measuredBias = wrap(courseAngle - meanHeading);
      if (Math.abs(measuredBias) < 70) {
        mem.headingBias = wrap(num(mem.headingBias, 0) +
          0.06 * wrap(measuredBias - num(mem.headingBias, 0)));
      }
    }
    mem.courseX = rawX;
    mem.courseY = rawY;
    mem.courseTicks = 0;
    mem.courseSin = 0;
    mem.courseCos = 0;
    mem.courseCount = 0;
    mem.courseBad = false;
    trueHeading = wrap(rawHeading + num(mem.headingBias, 0));
  }

  mem.totalTravel = num(mem.totalTravel, 0) + wheelTravel;
  if (mem.totalTravel > 5) mem.calibrated = true;

  var wasDocked = !!obs.docked;
  var priorBattery = mem.prevBattery;
  if (priorBattery !== undefined && !wasDocked) {
    var grossEnergy = Math.max(0, priorBattery - battery + solar * dt);
    var active = Math.abs(num(mem.lastCmdL, 0)) +
                 Math.abs(num(mem.lastCmdR, 0)) > 0.12 ||
                 wheelTravel > 0.01 || drillProgress > 0;
    if (active) {
      mem.energyWinE = num(mem.energyWinE, 0) + grossEnergy;
      mem.energyWinD = num(mem.energyWinD, 0) + wheelTravel;
      mem.energyWinT = num(mem.energyWinT, 0) + dt;
    }
    if (mem.energyWinT >= 1.5) {
      if (mem.energyWinE > 0.00008 && mem.energyWinT > 0.3) {
        var rRate = mem.energyWinE / mem.energyWinT;
        var rateAlpha = rRate > mem.eRate ? 0.42 : 0.12;
        mem.eRate = clamp(mem.eRate + rateAlpha * (rRate - mem.eRate),
                          0.00015, 0.10);
        if (mem.energyWinD > 0.25) {
          var rMeter = mem.energyWinE / mem.energyWinD;
          if (rMeter > 0.00015 && rMeter < 0.12) {
            var meterAlpha = rMeter > mem.ePerM ? 0.45 : 0.10;
            mem.ePerM = clamp(mem.ePerM + meterAlpha * (rMeter - mem.ePerM),
                              0.00015, 0.12);
          }
        }
      }
      mem.energyWinE = 0;
      mem.energyWinD = 0;
      mem.energyWinT = 0;
    }
    if (priorBattery - battery > 0.08) mem.energyShockTick = tick;
  } else if (wasDocked) {
    mem.energyWinE = 0;
    mem.energyWinD = 0;
    mem.energyWinT = 0;
  }
  mem.prevBattery = battery;

  var rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  if (!Array.isArray(mem.rayLast)) {
    mem.rayLast = [];
    mem.raySame = [];
    mem.rayStartX = [];
    mem.rayStartY = [];
    mem.rayBad = [];
  }
  var rays = [];
  for (var ri = 0; ri < 9; ri++) {
    var rd = num(rawRays[ri], 15);
    if (rd < 0 || rd > 15.2) rd = 15;
    rd = clamp(rd, 0, 15);
    if (mem.rayLast[ri] === undefined) {
      mem.rayLast[ri] = rd;
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayBad[ri] = false;
    } else if (Math.abs(rd - mem.rayLast[ri]) < 0.025) {
      mem.raySame[ri] = num(mem.raySame[ri], 0) + 1;
      if (mem.raySame[ri] > 120 && rd < 14.8 &&
          dist(mem.px, mem.py, mem.rayStartX[ri], mem.rayStartY[ri]) > 5) {
        mem.rayBad[ri] = true;
      }
    } else {
      if (mem.rayBad[ri] && Math.abs(rd - mem.rayLast[ri]) > 1.0) {
        mem.rayBad[ri] = false;
      }
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
    }
    mem.rayLast[ri] = rd;
    rays[ri] = mem.rayBad[ri] ? 15 : rd;
  }

  function emit(left, right, drill, omega, holding) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    if (!holding) {
      mem.wasHolding = false;
      mem.holdBiasL = num(mem.holdBiasL, 0) * 0.90;
      mem.holdBiasR = num(mem.holdBiasR, 0) * 0.90;
    }
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastOmegaCmd = num(omega, 0);
    return { left: left, right: right, drill: !!drill };
  }

  function driveRaw(v, omega) {
    var lTarget = clamp(v - 0.3 * omega, -2.5, 2.5);
    var rTarget = clamp(v + 0.3 * omega, -2.5, 2.5);
    var lCmd = lTarget / 3 + 0.13 * (lTarget - wheelL);
    var rCmd = rTarget / 3 + 0.13 * (rTarget - wheelR);
    return emit(lCmd, rCmd, false, omega, false);
  }

  function holdCommands() {
    if (!mem.wasHolding) {
      mem.holdBiasL = 0;
      mem.holdBiasR = 0;
    }
    mem.wasHolding = true;
    mem.holdBiasL = clamp(num(mem.holdBiasL, 0) - 0.035 * wheelL * dt, -0.12, 0.12);
    mem.holdBiasR = clamp(num(mem.holdBiasR, 0) - 0.035 * wheelR * dt, -0.12, 0.12);
    var feed = clamp(0.18 * Math.sin(rad(pitch)), -0.12, 0.12);
    var l = clamp(feed + mem.holdBiasL - 0.36 * wheelL, -0.25, 0.25);
    var r = clamp(feed + mem.holdBiasR - 0.36 * wheelR, -0.25, 0.25);
    return [l, r];
  }

  function holdOutput(drill) {
    var hc = holdCommands();
    return emit(hc[0], hc[1], drill, 0, true);
  }

  function sideSign(preference) {
    var right = (rays[0] + rays[1] + rays[2] + rays[3]) * 0.25;
    var left = (rays[5] + rays[6] + rays[7] + rays[8]) * 0.25;
    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    if (preference > 0.1) return 1;
    if (preference < -0.1) return -1;
    return num(mem.avoidSign, 1) >= 0 ? 1 : -1;
  }

  function edgeDistance(angleRel) {
    var a = rad(trueHeading + angleRel);
    var dx = Math.cos(a), dy = Math.sin(a);
    var best = 1e9;
    if (dx > 0.001) best = Math.min(best, (mem.sizeX - 2 - mem.px) / dx);
    if (dx < -0.001) best = Math.min(best, (2 - mem.px) / dx);
    if (dy > 0.001) best = Math.min(best, (mem.sizeY - 2 - mem.py) / dy);
    if (dy < -0.001) best = Math.min(best, (2 - mem.py) / dy);
    return Math.max(0, best);
  }

  function selectedHeading(goalErr, speed) {
    goalErr = wrap(goalErr);
    var front = Math.min(rays[3], rays[4], rays[5]);
    if (front < 4.6) {
      if (tick > num(mem.avoidUntil, -1)) {
        mem.avoidSign = sideSign(goalErr);
        mem.avoidUntil = tick + 20;
      }
    } else if (tick > num(mem.avoidUntil, -1)) {
      mem.avoidSign = 0;
    }

    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    var g = clamp(goalErr, -80, 80);
    candidates.push(g);
    candidates.push(clamp(g - 18, -80, 80));
    candidates.push(clamp(g + 18, -80, 80));

    var safe = 3.4 + 0.65 * clamp(speed, 0, 1.6);
    var best = g, bestCost = 1e30;
    for (var ci = 0; ci < candidates.length; ci++) {
      var c = candidates[ci];
      var duplicate = false;
      for (var cj = 0; cj < ci; cj++) {
        if (Math.abs(candidates[cj] - c) < 0.5) duplicate = true;
      }
      if (duplicate) continue;
      var dg = Math.abs(wrap(c - goalErr));
      var cost = 0.00012 * dg * dg;

      for (var rj = 0; rj < 9; rj++) {
        var d = rays[rj];
        if (d >= 14.95) continue;
        var alpha = -80 + 20 * rj;
        var da = Math.abs(wrap(c - alpha));
        if (da > 75) continue;
        var proximity = clamp((safe + 0.8 - d) / (safe + 0.8), 0, 1);
        var influence = Math.exp(-0.5 * (da / 22) * (da / 22));
        cost += 5.5 * proximity * proximity * influence;
        if (d < 1.25 && da < 22) cost += 1.6;
      }

      var e = edgeDistance(c);
      var edgeSafe = 5 + 1.2 * clamp(speed, 0, 1.6);
      if (e < edgeSafe) {
        var ep = (edgeSafe - e) / edgeSafe;
        cost += 7 * ep * ep;
      }
      if (front < 4.6 && Math.abs(c) > 10 &&
          Math.sign(c) !== Math.sign(num(mem.avoidSign, 0))) {
        cost += 0.035;
      }
      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }
    return best;
  }

  function rayAt(angle) {
    var q = clamp((angle + 80) / 20, 0, 8);
    var i = Math.floor(q);
    var f = q - i;
    if (i >= 8) return rays[8];
    return Math.min(rays[i], rays[i + 1], rays[i] * (1 - f) + rays[i + 1] * f);
  }

  function navigate(err, d, stopRadius, cruise, gain) {
    if (!Number.isFinite(d) || d < 0) return driveRaw(0, 0);
    err = wrap(err);
    var dir = selectedHeading(err, Math.abs(centerV));
    var v = Math.min(cruise, Math.max(0, d - stopRadius) * gain);

    var sensed = rayAt(dir);
    var capSpeed = cruise;
    if (sensed < 6) {
      capSpeed = clamp((sensed - 1.15) * 0.29, 0.12, 1.30);
    }
    var edge = edgeDistance(dir);
    if (edge < 8) {
      capSpeed = Math.min(capSpeed, clamp((edge - 1.1) * 0.25, 0.10, 1.25));
    }
    if (Math.abs(pitch) > 26) capSpeed = Math.min(capSpeed, 0.85);
    v = Math.min(v, capSpeed);

    if (Math.abs(dir) > 68) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(rad(dir)));
    }
    if (d <= stopRadius + 0.04) v = 0;
    var omega = clamp(2.1 * rad(dir), -2.1, 2.1);
    if (d <= stopRadius + 0.04) omega = 0;
    return driveRaw(v, omega);
  }

  function markCandidateDone(index) {
    if (index >= 0 && index < mem.cands.length) {
      mem.cands[index].status = 2;
      if (mem.targetIdx === index) mem.targetIdx = -1;
    }
  }

  var sampleDone = false;
  var oldCarried = num(mem.lastCarried, carried);
  if (carried > oldCarried) {
    sampleDone = true;
    var completedX = mem.siteLock ? mem.siteLock.x : mem.px;
    var completedY = mem.siteLock ? mem.siteLock.y : mem.py;
    var nearestIdx = -1, nearestD = 30;
    for (var mi = 0; mi < mem.cands.length; mi++) {
      var md = dist(completedX, completedY, mem.cands[mi].x, mem.cands[mi].y);
      if (md < nearestD && mem.cands[mi].status !== 2) {
        nearestD = md;
        nearestIdx = mi;
      }
    }
    if (nearestIdx >= 0) markCandidateDone(nearestIdx);
    if (mem.targetIdx >= 0 && mem.targetIdx < mem.cands.length) {
      var tc = mem.cands[mem.targetIdx];
      if (dist(completedX, completedY, tc.x, tc.y) < 30) {
        markCandidateDone(mem.targetIdx);
      }
    }
    mem.siteLock = null;
    mem.scout = null;
    mem.lastSampleTick = tick;
  }
  mem.lastCarried = carried;

  var siteObj = obs.site && typeof obs.site === "object" ? obs.site : null;
  var liveSite = siteObj &&
    Number.isFinite(num(siteObj.distance, NaN)) &&
    Number.isFinite(num(siteObj.bearing, NaN)) &&
    num(siteObj.distance, -1) >= 0;

  if (liveSite && !sampleDone) {
    var siteD0 = Math.max(0, num(siteObj.distance, 0));
    var siteB0 = num(siteObj.bearing, 0);
    var siteAng0 = rad(trueHeading + siteB0);
    var sx0 = mem.px + siteD0 * Math.cos(siteAng0);
    var sy0 = mem.py + siteD0 * Math.sin(siteAng0);
    if (mem.siteLock &&
        dist(sx0, sy0, mem.siteLock.x, mem.siteLock.y) < 6) {
      mem.siteLock.x = 0.55 * mem.siteLock.x + 0.45 * sx0;
      mem.siteLock.y = 0.55 * mem.siteLock.y + 0.45 * sy0;
      mem.siteLock.value = num(siteObj.value, mem.siteLock.value);
      mem.siteLock.lastSeen = tick;
    } else {
      mem.siteLock = {
        x: sx0,
        y: sy0,
        value: num(siteObj.value, 1),
        lastSeen: tick
      };
    }
  }
  if (mem.siteLock && drillProgress <= 0 &&
      tick - num(mem.siteLock.lastSeen, tick) > 6000) {
    mem.siteLock = null;
  }

  function reserveEnergy() {
    var cv = Math.max(0, num(obs.carriedValue, 0));
    return 0.15 + 0.035 * Math.min(5, carried) +
           (carried > 0 ? 0.02 : 0) + Math.min(0.04, cv * 0.0005);
  }

  function predictedEnergy(pathMeters) {
    var p = Math.max(0, pathMeters);
    var byDistance = num(mem.ePerM, 0.0022) * p * 1.25;
    var byTime = num(mem.eRate, 0.0014) * (p / 0.72) * 1.18;
    return Math.max(byDistance, byTime) + 0.025;
  }

  function candidatePath(c, fromX, fromY) {
    var out = dist(fromX, fromY, c.x, c.y);
    var search = 30;
    if (c.stage === "center") search = 40;
    if (c.stage === "ring") {
      var rem = Math.max(0, 12 - num(c.ringIndex, 0));
      search = Math.min(60, rem * 7.4);
    }
    return out + 1.55 * dist(c.x, c.y, mem.baseX, mem.baseY) + search;
  }

  function pickCandidate() {
    if (carried >= mem.capacity) return -1;
    var bestIndex = -1, bestScore = -1;
    for (var pi = 0; pi < mem.cands.length; pi++) {
      var c = mem.cands[pi];
      if (c.status !== 0) continue;
      if (c.blockedAt !== undefined) {
        if (num(mem.ePerM, 0.0022) >= c.blockedAt * 0.90) continue;
        c.blockedAt = undefined;
      }
      var outbound = dist(mem.px, mem.py, c.x, c.y);
      var path = candidatePath(c, mem.px, mem.py);
      var need = predictedEnergy(path) + reserveEnergy();
      if (need > 1.015) continue;
      var timeNeed = path / 0.68 * 1.25 + 24;
      if (timeNeed > timeLeft - 2) continue;
      var score = Math.max(0.05, c.value) /
                  (26 + outbound + 0.70 * dist(c.x, c.y, mem.baseX, mem.baseY) + 12);
      if (!mem.calibrated && outbound > 130) score *= 0.55;
      if (score > bestScore) {
        bestScore = score;
        bestIndex = pi;
      }
    }
    if (bestIndex >= 0) {
      var chosen = mem.cands[bestIndex];
      chosen.status = 1;
      chosen.stage = "travel";
      chosen.centerTicks = 0;
      chosen.ringIndex = 0;
      mem.targetIdx = bestIndex;
      mem.scout = null;
      mem.exploreGoal = null;
    }
    return bestIndex;
  }

  function activeCandidate() {
    if (mem.targetIdx >= 0 && mem.targetIdx < mem.cands.length &&
        mem.cands[mem.targetIdx].status === 1) {
      return mem.cands[mem.targetIdx];
    }
    mem.targetIdx = -1;
    for (var ai = 0; ai < mem.cands.length; ai++) {
      if (mem.cands[ai].status === 1) {
        mem.targetIdx = ai;
        return mem.cands[ai];
      }
    }
    return null;
  }

  function scoutWaypoint(s) {
    if (!s || s.index >= 12) return null;
    var a = s.startAngle + s.index * Math.PI / 6;
    return {
      x: clamp(s.x + 14 * Math.cos(a), 2, mem.sizeX - 2),
      y: clamp(s.y + 14 * Math.sin(a), 2, mem.sizeY - 2)
    };
  }

  function beginScout() {
    mem.scout = {
      x: mem.px,
      y: mem.py,
      centerScience: science,
      bestScience: science,
      bestX: mem.px,
      bestY: mem.py,
      index: 0,
      rounds: 0,
      startAngle: 0
    };
    mem.exploreGoal = null;
  }

  function updateScout() {
    var s = mem.scout;
    if (!s) return;
    if (science > s.bestScience) {
      s.bestScience = science;
      s.bestX = mem.px;
      s.bestY = mem.py;
    }
    var wp = scoutWaypoint(s);
    if (wp && dist(mem.px, mem.py, wp.x, wp.y) < 2.35) s.index++;
    if (s.index < 12) return;

    var improvement = s.bestScience >
      s.centerScience + Math.max(0.00001, Math.abs(s.centerScience) * 0.08);
    if (improvement && s.rounds < 3 &&
        dist(s.x, s.y, s.bestX, s.bestY) > 3) {
      s.x = s.bestX;
      s.y = s.bestY;
      s.centerScience = s.bestScience;
      s.rounds++;
      s.index = 0;
      s.bestScience = s.centerScience;
      s.bestX = s.x;
      s.bestY = s.y;
      var away = dist(mem.px, mem.py, s.x, s.y);
      s.startAngle = away > 1 ? Math.atan2(mem.py - s.y, mem.px - s.x) : 0;
    } else {
      mem.lastScoutX = mem.px;
      mem.lastScoutY = mem.py;
      mem.lastScoutTick = tick;
      mem.scout = null;
    }
  }

  function ensureExploreGoal() {
    if (mem.siteLock || carried >= mem.capacity) return;
    if (mem.scout) return;

    var scoutFar = mem.lastScoutX === undefined ||
      dist(mem.px, mem.py, mem.lastScoutX, mem.lastScoutY) > 14 ||
      tick - num(mem.lastScoutTick, -10000) > 300;
    if (science > 0.00001 && scoutFar) {
      beginScout();
      return;
    }

    if (mem.exploreGoal) {
      if (dist(mem.px, mem.py, mem.exploreGoal.x, mem.exploreGoal.y) < 3) {
        if (mem.exploreGoal.index >= 0) mem.gridVisited[mem.exploreGoal.index] = true;
        mem.exploreGoal = null;
      } else {
        return;
      }
    }

    if (!Array.isArray(mem.grid)) {
      mem.grid = [];
      for (var gy = 0; gy < 4; gy++) {
        for (var gx = 0; gx < 4; gx++) {
          mem.grid.push({
            x: (gx + 0.5) * mem.sizeX / 4,
            y: (gy + 0.5) * mem.sizeY / 4
          });
        }
      }
    }
    var best = -1, bestD = 1e30;
    var fallback = -1, fallbackD = 1e30;
    for (var gi = 0; gi < mem.grid.length; gi++) {
      if (mem.gridVisited[gi]) continue;
      var p = mem.grid[gi];
      var gd = dist(mem.px, mem.py, p.x, p.y);
      if (gd < fallbackD) {
        fallbackD = gd;
        fallback = gi;
      }
      var path = gd + 1.55 * dist(p.x, p.y, mem.baseX, mem.baseY) + 24;
      var need = predictedEnergy(path) + reserveEnergy();
      var tneed = path / 0.7 * 1.25 + 20;
      if (need <= 1.0 && tneed < timeLeft - 3 && gd < bestD) {
        bestD = gd;
        best = gi;
      }
    }
    if (best < 0 && fallback >= 0 && fallbackD < 35) best = fallback;
    if (best >= 0) {
      mem.exploreGoal = {
        x: mem.grid[best].x,
        y: mem.grid[best].y,
        index: best
      };
    }
  }

  function ensurePlan() {
    var c = activeCandidate();
    if (!c && carried < mem.capacity) {
      pickCandidate();
      c = activeCandidate();
    }
    if (c) {
      mem.scout = null;
      mem.exploreGoal = null;
      return;
    }
    if (carried < mem.capacity) ensureExploreGoal();
  }

  function updateCandidateStage() {
    if (mem.returning || mem.siteLock) return;
    var c = activeCandidate();
    if (!c) return;
    var cd = dist(mem.px, mem.py, c.x, c.y);

    if (c.stage === "travel" && cd < 2.65) {
      c.stage = "center";
      c.centerTicks = 0;
    }
    if (c.stage === "center" && cd < 3.0) {
      if (science > 0.00001) {
        c.stage = "ring";
        c.ringIndex = 0;
        c.ringStart = dist(mem.px, mem.py, c.x, c.y) > 2 ?
          Math.atan2(mem.py - c.y, mem.px - c.x) : 0;
        c.bestScience = science;
        c.bestX = mem.px;
        c.bestY = mem.py;
      } else {
        c.centerTicks = num(c.centerTicks, 0) + 1;
        if (c.centerTicks > 12) markCandidateDone(mem.targetIdx);
      }
    } else if (c.stage === "ring") {
      var idx = num(c.ringIndex, 0);
      if (idx >= 12) {
        markCandidateDone(mem.targetIdx);
      } else {
        var a = c.ringStart + idx * Math.PI / 6;
        var wx = clamp(c.x + 16 * Math.cos(a), 2, mem.sizeX - 2);
        var wy = clamp(c.y + 16 * Math.sin(a), 2, mem.sizeY - 2);
        if (science > num(c.bestScience, -1)) {
          c.bestScience = science;
          c.bestX = mem.px;
          c.bestY = mem.py;
        }
        if (dist(mem.px, mem.py, wx, wy) < 2.35) {
          c.ringIndex++;
          if (c.ringIndex >= 12) markCandidateDone(mem.targetIdx);
        }
      }
    }
  }

  function currentPlanPath() {
    if (mem.siteLock) {
      return dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y) +
        1.55 * dist(mem.siteLock.x, mem.siteLock.y, mem.baseX, mem.baseY) + 12;
    }
    var c = activeCandidate();
    if (c) return candidatePath(c, mem.px, mem.py);
    if (mem.scout) {
      var swp = scoutWaypoint(mem.scout);
      var remaining = Math.max(0, 12 - mem.scout.index) * 7.4;
      if (!swp) swp = { x: mem.px, y: mem.py };
      return dist(mem.px, mem.py, swp.x, swp.y) + remaining +
        1.55 * dist(mem.scout.x, mem.scout.y, mem.baseX, mem.baseY) + 12;
    }
    if (mem.exploreGoal) {
      return dist(mem.px, mem.py, mem.exploreGoal.x, mem.exploreGoal.y) +
        1.55 * dist(mem.exploreGoal.x, mem.exploreGoal.y, mem.baseX, mem.baseY) + 24;
    }
    return Infinity;
  }

  updateScout();
  ensurePlan();
  updateCandidateStage();
  ensurePlan();

  var beacon = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
  var beaconValid = beacon &&
    Number.isFinite(num(beacon.distance, NaN)) &&
    Number.isFinite(num(beacon.bearing, NaN)) &&
    num(beacon.distance, -1) >= 0;
  var homeD = beaconValid && num(beacon.distance, 1000) < 25 ?
    num(beacon.distance, 0) : dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homePath = homeD * 1.55 + 7;
  var homeEnergy = predictedEnergy(homePath);
  var reserve = reserveEnergy();
  var homeTime = homePath / 0.70 * 1.25 + 12;

  if (obs.docked) {
    if (carried > 0) {
      mem.returning = true;
      return emit(0, 0, false, 0, false);
    }
    ensurePlan();
    var planPath = currentPlanPath();
    if (!Number.isFinite(planPath)) {
      return emit(0, 0, false, 0, false);
    }
    if (planPath > 0 && planPath < 1e6 &&
        predictedEnergy(planPath) + reserveEnergy() > 1.05 &&
        mem.targetIdx >= 0 && !mem.siteLock) {
      var blocked = mem.cands[mem.targetIdx];
      blocked.status = 0;
      blocked.blockedAt = num(mem.ePerM, 0.0022);
      mem.targetIdx = -1;
      ensurePlan();
      planPath = currentPlanPath();
    }
    if (!Number.isFinite(planPath)) {
      return emit(0, 0, false, 0, false);
    }
    var chargeNeed = predictedEnergy(planPath) + reserveEnergy() + 0.015;
    var chargeTarget = clamp(chargeNeed, 0.18, 0.985);
    var chargeTime = planPath / 0.70 * 1.25 + 10;
    if (timeLeft < chargeTime || battery + 0.003 < chargeTarget) {
      mem.returning = true;
      return emit(0, 0, false, 0, false);
    }
    mem.returning = false;
  } else if (!mem.returning) {
    var mustReturn = false;
    if (carried >= mem.capacity) mustReturn = true;
    if (battery <= homeEnergy + reserve) mustReturn = true;
    if (battery < 0.035) mustReturn = true;
    if (carried > 0 && timeLeft < homeTime + 8) mustReturn = true;
    if (tick - num(mem.energyShockTick, -10000) < 20 &&
        battery < homeEnergy + reserve + 0.04) mustReturn = true;

    if (mustReturn && drillProgress > 0 &&
        battery > homeEnergy + 0.035 && timeLeft > homeTime + 1 &&
        carried < mem.capacity) {
      mustReturn = false;
    }
    if (mustReturn) mem.returning = true;
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.wasBumped && !obs.docked && drillProgress <= 0) {
    mem.recoverStart = tick;
    mem.recoverSign = sideSign(0);
  }
  mem.wasBumped = bumped;

  if (mem.stuckStartTick === undefined) {
    mem.stuckStartTick = tick;
    mem.stuckStartX = rawX;
    mem.stuckStartY = rawY;
    mem.stuckWheel = 0;
    mem.stuckCmd = 0;
    mem.stuckTurn = 0;
  }
  if (!obs.docked && drillProgress <= 0) {
    mem.stuckWheel = num(mem.stuckWheel, 0) + wheelTravel;
    mem.stuckCmd = num(mem.stuckCmd, 0) +
      (Math.abs(num(mem.lastCmdL, 0)) + Math.abs(num(mem.lastCmdR, 0))) * 0.5 * dt;
    mem.stuckTurn = num(mem.stuckTurn, 0) +
      Math.abs(num(mem.lastOmegaCmd, 0)) * dt;
    if (tick - mem.stuckStartTick >= 30) {
      var rawProgress = dist(rawX, rawY, mem.stuckStartX, mem.stuckStartY);
      if (!mem.gpsStale && rawProgress < 0.38 &&
          (mem.stuckWheel > 1.0 || mem.stuckCmd > 0.85) &&
          mem.stuckTurn < 1.8 && tick - num(mem.recoverStart, -10000) > 22) {
        mem.recoverStart = tick;
        mem.recoverSign = sideSign(0);
      }
      mem.stuckStartTick = tick;
      mem.stuckStartX = rawX;
      mem.stuckStartY = rawY;
      mem.stuckWheel = 0;
      mem.stuckCmd = 0;
      mem.stuckTurn = 0;
    }
  } else {
    mem.stuckStartTick = tick;
    mem.stuckStartX = rawX;
    mem.stuckStartY = rawY;
    mem.stuckWheel = 0;
    mem.stuckCmd = 0;
    mem.stuckTurn = 0;
  }

  if (obs.docked) {
    /* The dock branch above either held position or elected to leave. */
    if (mem.returning) return emit(0, 0, false, 0, false);
  }

  if (mem.returning) {
    if (mem.recoverStart !== undefined && tick - mem.recoverStart < 18 &&
        !obs.docked) {
      var elapsedR = tick - mem.recoverStart;
      var rs = num(mem.recoverSign, 1);
      if (elapsedR < 8) return driveRaw(-0.35, rs * 0.7);
      return driveRaw(0, rs * 1.35);
    }
    if (beaconValid && num(beacon.distance, 1000) < 25) {
      return navigate(num(beacon.bearing, 0), num(beacon.distance, 0),
                      1.0, 1.15, 0.48);
    }
    var bdx = mem.baseX - mem.px, bdy = mem.baseY - mem.py;
    var bd = Math.sqrt(bdx * bdx + bdy * bdy);
    var bErr = bd > 0.1 ?
      wrap(Math.atan2(bdy, bdx) * 57.2957795 - trueHeading) : 0;
    return navigate(bErr, bd, 1.0, 1.15, 0.48);
  }

  if (drillProgress > 0 && !sampleDone) {
    return holdOutput(true);
  }

  if (mem.siteLock && carried < mem.capacity) {
    var liveD = liveSite && !sampleDone ? num(siteObj.distance, 0) : NaN;
    var liveB = liveSite && !sampleDone ? num(siteObj.bearing, 0) : NaN;
    var siteDistance, siteErr, sensedNow = Number.isFinite(liveD);
    if (sensedNow) {
      siteDistance = liveD;
      siteErr = liveB;
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteDistance = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteDistance > 0.05 ?
        wrap(Math.atan2(sdy, sdx) * 57.2957795 - trueHeading) : 0;
    }

    if (siteDistance <= 1.55) {
      var hcmd = holdCommands();
      var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.13;
      var readyDistance = sensedNow ? siteDistance <= 1.47 : siteDistance <= 1.05;
      return emit(hcmd[0], hcmd[1], readyDistance && still, 0, true);
    }
    return navigate(siteErr, siteDistance, 0.95, 0.88, 0.72);
  }

  if (mem.recoverStart !== undefined && tick - mem.recoverStart < 18 &&
