    var doneY = mem.drillSite ? mem.drillSite.y :
                (mem.siteLock ? mem.siteLock.y : mem.py);
    var nearest = -1, nearestD = 36;
    for (var mi = 0; mi < mem.cands.length; mi++) {
      var cdist = dist(doneX, doneY, mem.cands[mi].x, mem.cands[mi].y);
      if (cdist < nearestD && mem.cands[mi].status !== 2) {
        nearestD = cdist;
        nearest = mi;
      }
    }
    if (nearest >= 0) {
      mem.cands[nearest].status = 2;
      mem.cands[nearest].blocked = false;
      if (mem.targetIdx === nearest) mem.targetIdx = -1;
    }
    if (mem.targetIdx >= 0 && mem.targetIdx < mem.cands.length) {
      var tc = mem.cands[mem.targetIdx];
      if (dist(doneX, doneY, tc.x, tc.y) < 36) {
        tc.status = 2;
        mem.targetIdx = -1;
      }
    }
    mem.siteLock = null;
    mem.drillSite = null;
    mem.lastSampleTick = tick;
  }
  mem.lastCarried = carried;

  var siteObj = obs.site && typeof obs.site === "object" ? obs.site : null;
  var liveSite = !!(siteObj &&
    Number.isFinite(num(siteObj.distance, NaN)) &&
    Number.isFinite(num(siteObj.bearing, NaN)) &&
    num(siteObj.distance, -1) >= 0);

  if (liveSite && carried < mem.capacity) {
    var sd0 = Math.max(0, num(siteObj.distance, 0));
    var sb0 = num(siteObj.bearing, 0);
    var sg = rad(trueHeading + sb0);
    var slx = mem.px + sd0 * Math.cos(sg);
    var sly = mem.py + sd0 * Math.sin(sg);

    if (mem.siteLock &&
        dist(slx, sly, mem.siteLock.x, mem.siteLock.y) < 9) {
      mem.siteLock.x = 0.65 * mem.siteLock.x + 0.35 * slx;
      mem.siteLock.y = 0.65 * mem.siteLock.y + 0.35 * sly;
      mem.siteLock.value = num(siteObj.value, mem.siteLock.value);
      mem.siteLock.lastSeen = tick;
      mem.siteLock.confirmed = true;
    } else {
      mem.siteLock = {
        x: slx,
        y: sly,
        value: num(siteObj.value, 1),
        lastSeen: tick,
        confirmed: true
      };
    }
  } else if (mem.siteLock && drillProgress <= 0 &&
             tick - num(mem.siteLock.lastSeen, tick) > 900) {
    mem.siteLock = null;
  }

  function activeCandidate() {
    if (mem.targetIdx >= 0 && mem.targetIdx < mem.cands.length &&
        mem.cands[mem.targetIdx].status === 1) {
      return mem.cands[mem.targetIdx];
    }
    mem.targetIdx = -1;
    for (var ai = 0; ai < mem.cands.length; ai++) {
      if (mem.cands[ai].status === 1) {
        mem.targetIdx = ai;
        return mem.cands[ai];
      }
    }
    return null;
  }

  function candidateSearchRemaining(c) {
    if (!c || c.phase === 0) return 95;
    if (c.phase === 1) {
      return 48 + Math.max(0, 4 - num(c.index, 0)) * 9;
    }
    if (c.phase === 2) {
      return Math.max(0, 8 - num(c.index, 0)) * 13;
    }
    return 0;
  }

  function candidateRoutePath(c, fromX, fromY) {
    if (!c) return Infinity;
    var out = dist(fromX, fromY, c.x, c.y);
    var back = dist(c.x, c.y, mem.baseX, mem.baseY);
    return 1.22 * (out + back) + candidateSearchRemaining(c);
  }

  function pickCandidate() {
    if (carried >= mem.capacity) return null;
    var best = -1, bestScore = -1;
    for (var pi = 0; pi < mem.cands.length; pi++) {
      var c = mem.cands[pi];
      if (c.status !== 0 || c.blocked) continue;

      var out = dist(mem.px, mem.py, c.x, c.y);
      var back = dist(c.x, c.y, mem.baseX, mem.baseY);
      var route = 1.22 * (out + back) + 95;
      var need = energyFor(route, carried);
      var tneed = route / 0.70 + 12;
      if (need > num(mem.maxBattery, battery) - 0.015) continue;
      if (tneed > timeLeft - 4) continue;

      var score = Math.max(0.05, c.value) /
                  (25 + out + 0.92 * back + 0.45 * 95);
      if (score > bestScore) {
        bestScore = score;
        best = pi;
      }
    }

    if (best < 0) return null;
    var chosen = mem.cands[best];
    chosen.status = 1;
    chosen.phase = 0;
    chosen.index = 0;
    chosen.refine = 0;
    chosen.searchX = chosen.x;
    chosen.searchY = chosen.y;
    chosen.startAngle = (best * 137.5) * PI / 180;
    chosen.baseScience = science;
    chosen.bestScience = science;
    chosen.bestX = mem.px;
    chosen.bestY = mem.py;
    mem.targetIdx = best;
    return chosen;
  }

  function candidatePoint(c) {
    if (!c) return null;
    if (c.phase === 0) {
      return { x: c.x, y: c.y, stop: 4.5 };
    }
    var radius, count, idx;
    if (c.phase === 1) {
      radius = 9;
      count = 4;
      idx = num(c.index, 0);
    } else {
      radius = 18;
      count = 8;
      idx = num(c.index, 0);
    }
    if (idx >= count) return null;
    var a = num(c.startAngle, 0) + idx * 2 * PI / count;
    return {
      x: clamp(num(c.searchX, c.x) + radius * Math.cos(a),
               3, mem.sizeX - 3),
      y: clamp(num(c.searchY, c.y) + radius * Math.sin(a),
               3, mem.sizeY - 3),
      stop: 1.9
    };
  }

  function markCandidateFailed(c) {
    if (!c) return;
    c.status = 2;
    if (mem.targetIdx >= 0 &&
        mem.cands[mem.targetIdx] === c) mem.targetIdx = -1;
  }

  function updateCandidateProgress() {
    var c = activeCandidate();
    if (!c || mem.siteLock || drillProgress > 0 || mem.returning) return;

    if (c.phase === 0) {
      if (dist(mem.px, mem.py, c.x, c.y) < 4.8) {
        c.phase = 1;
        c.index = 0;
        c.searchX = c.x;
        c.searchY = c.y;
        c.baseScience = science;
        c.bestScience = science;
        c.bestX = mem.px;
        c.bestY = mem.py;
      }
      return;
    }

    if (science > num(c.bestScience, -1)) {
      c.bestScience = science;
      c.bestX = mem.px;
      c.bestY = mem.py;
    }

    if (c.phase === 1) {
      if (num(c.index, 0) >= 4) {
        var improvement = num(c.bestScience, 0) -
                          num(c.baseScience, 0);
        var threshold = Math.max(0.012,
                                 Math.abs(num(c.baseScience, 0)) * 0.07);
        if (c.refine < 1 && improvement > threshold) {
          c.searchX = c.bestX;
          c.searchY = c.bestY;
          c.refine++;
          c.index = 0;
          c.baseScience = c.bestScience;
          c.bestX = mem.px;
          c.bestY = mem.py;
          return;
        }
        c.phase = 2;
        c.index = 0;
        return;
      }
      var p1 = candidatePoint(c);
      if (p1 && dist(mem.px, mem.py, p1.x, p1.y) < 2.35) {
        c.index++;
      }
      return;
    }

    if (c.phase === 2) {
      if (num(c.index, 0) >= 8) {
        markCandidateFailed(c);
        return;
      }
      var p2 = candidatePoint(c);
      if (p2 && dist(mem.px, mem.py, p2.x, p2.y) < 2.35) {
        c.index++;
        if (c.index >= 8) markCandidateFailed(c);
      }
    }
  }

  function beginFreeSearch(cx, cy, value, kind) {
    mem.freeSearch = {
      x: cx, y: cy,
      phase: 1,
      index: 0,
      refine: 0,
      startAngle: ((tick * 17) % 360) * PI / 180,
      baseScience: value,
      bestScience: value,
      bestX: mem.px,
      bestY: mem.py,
      kind: kind || "signal"
    };
  }

  function freePoint(s) {
    if (!s) return null;
    var radius, count, idx;
    if (s.phase === 1) {
      radius = 9;
      count = 4;
      idx = num(s.index, 0);
    } else {
      radius = 18;
      count = 8;
      idx = num(s.index, 0);
    }
    if (idx >= count) return null;
    var a = num(s.startAngle, 0) + idx * 2 * PI / count;
    return {
      x: clamp(s.x + radius * Math.cos(a), 3, mem.sizeX - 3),
      y: clamp(s.y + radius * Math.sin(a), 3, mem.sizeY - 3),
      stop: 1.9
    };
  }

  function freeSearchRemaining(s) {
    if (!s) return 0;
    if (s.phase === 1) {
      return 48 + Math.max(0, 4 - num(s.index, 0)) * 9;
    }
    return Math.max(0, 8 - num(s.index, 0)) * 13;
  }

  function updateFreeSearch() {
    var s = mem.freeSearch;
    if (!s || mem.siteLock || drillProgress > 0 || mem.returning) return;

    if (science > num(s.bestScience, -1)) {
      s.bestScience = science;
      s.bestX = mem.px;
      s.bestY = mem.py;
    }

    if (s.phase === 1) {
      if (num(s.index, 0) >= 4) {
        var gain = num(s.bestScience, 0) - num(s.baseScience, 0);
        var threshold = Math.max(0.012,
                                 Math.abs(num(s.baseScience, 0)) * 0.07);
        if (s.refine < 1 && gain > threshold) {
          s.x = s.bestX;
          s.y = s.bestY;
          s.refine++;
          s.index = 0;
          s.baseScience = s.bestScience;
          s.bestX = mem.px;
          s.bestY = mem.py;
          return;
        }
        s.phase = 2;
        s.index = 0;
        return;
      }
      var p1 = freePoint(s);
      if (p1 && dist(mem.px, mem.py, p1.x, p1.y) < 2.35) {
        s.index++;
      }
      return;
    }

    if (num(s.index, 0) >= 8) {
      if (s.kind === "initial") mem.initialFreeDone = true;
      mem.bestGlobalScience = Math.max(num(mem.bestGlobalScience, 0),
                                       num(s.bestScience, 0));
      mem.freeSearch = null;
      return;
    }
    var p2 = freePoint(s);
    if (p2 && dist(mem.px, mem.py, p2.x, p2.y) < 2.35) {
      s.index++;
      if (s.index >= 8) {
        if (s.kind === "initial") mem.initialFreeDone = true;
        mem.bestGlobalScience = Math.max(
          num(mem.bestGlobalScience, 0), num(s.bestScience, 0));
        mem.freeSearch = null;
      }
    }
  }

  function chooseExploreGoal() {
    if (mem.exploreGoal || mem.freeSearch || carried >= mem.capacity) return;
    var best = -1, bestScore = 1e30;
    for (var gi = 0; gi < mem.gridNodes.length; gi++) {
      if (mem.gridVisited[gi]) continue;
      var node = mem.gridNodes[gi];
      var d = dist(mem.px, mem.py, node.x, node.y);
      var back = dist(node.x, node.y, mem.baseX, mem.baseY);
      var route = 1.22 * (d + back) + 26;
      if (energyFor(route, carried) >
          num(mem.maxBattery, battery) - 0.01) continue;
      if (route / 0.68 + 10 > timeLeft - 3) continue;
      var score = d + 0.34 * back;
      if (score < bestScore) {
        bestScore = score;
        best = gi;
      }
    }
    if (best >= 0) {
      mem.exploreGoal = {
        x: mem.gridNodes[best].x,
        y: mem.gridNodes[best].y,
        index: best
      };
    }
  }

  function updateExploreState() {
    if (activeCandidate() || mem.siteLock || mem.returning ||
        carried >= mem.capacity || mem.freeSearch) return;

    var threshold = Math.max(0.025,
      Math.abs(num(mem.bestGlobalScience, 0)) * 0.12);

    if (mem.exploreGoal) {
      var gd = dist(mem.px, mem.py,
                    mem.exploreGoal.x, mem.exploreGoal.y);
      if (gd < 2.8) {
        if (mem.exploreGoal.index >= 0) {
          mem.gridVisited[mem.exploreGoal.index] = true;
        }
        mem.exploreGoal = null;
        if (science > num(mem.bestGlobalScience, 0) + threshold) {
          mem.bestGlobalScience = science;
          mem.lastSignalSearchTick = tick;
          beginFreeSearch(mem.px, mem.py, science, "signal");
        }
      } else if (science > num(mem.bestGlobalScience, 0) + threshold &&
                 tick - num(mem.lastSignalSearchTick, -10000) > 100) {
        mem.bestGlobalScience = science;
        mem.lastSignalSearchTick = tick;
        beginFreeSearch(mem.px, mem.py, science, "signal");
      }
    }
  }

  function ensurePlan(allowCandidate) {
    var c = activeCandidate();
    if (!c && allowCandidate && carried < mem.capacity) {
      c = pickCandidate();
    }
    if (c || !allowCandidate || carried >= mem.capacity ||
        mem.siteLock) return;

    if (mem.freeSearch) return;
    if (!mem.initialFreeStarted) {
      mem.initialFreeStarted = true;
      beginFreeSearch(mem.px, mem.py, science, "initial");
      return;
    }
    if (!mem.initialFreeDone) return;
    chooseExploreGoal();
  }

  function planPath() {
    if (mem.siteLock && carried < mem.capacity) {
      var sd = dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      var sb = dist(mem.siteLock.x, mem.siteLock.y,
                    mem.baseX, mem.baseY);
      return 1.25 * (sd + sb) + 8;
    }

    var c = activeCandidate();
    if (c) {
      return candidateRoutePath(c, mem.px, mem.py);
    }

    if (mem.freeSearch) {
      var fp = freePoint(mem.freeSearch);
      var dnext = fp ? dist(mem.px, mem.py, fp.x, fp.y) : 0;
      var back = dist(mem.freeSearch.x, mem.freeSearch.y,
                      mem.baseX, mem.baseY);
      return dnext + freeSearchRemaining(mem.freeSearch) +
             1.25 * back;
    }

    if (mem.exploreGoal) {
      var dnow = dist(mem.px, mem.py,
                      mem.exploreGoal.x, mem.exploreGoal.y);
      var db = dist(mem.exploreGoal.x, mem.exploreGoal.y,
                    mem.baseX, mem.baseY);
      return 1.22 * (dnow + db) + 26;
    }
    return Infinity;
  }

  if (docked && carried === 0) mem.returning = false;

  if (!mem.returning && !mem.siteLock && drillProgress <= 0) {
    updateCandidateProgress();
    updateFreeSearch();
    updateExploreState();
  }

  ensurePlan(!mem.returning || docked);

  var beacon = obs.beacon && typeof obs.beacon === "object" ?
               obs.beacon : null;
  var beaconDistance = beacon ? num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ? num(beacon.bearing, NaN) : NaN;
  var beaconValid = Number.isFinite(beaconDistance) &&
                    Number.isFinite(beaconBearing) &&
                    beaconDistance >= 0 && beaconDistance <= 22;

  var homeD = beaconValid ? beaconDistance :
    dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeAbsBearing = homeD > 0.05 ?
    angleTo(mem.px, mem.py, mem.baseX, mem.baseY) : trueHeading;
  var homeErr = beaconValid ? beaconBearing :
                wrap(homeAbsBearing - trueHeading);
  var homePath = 1.38 * homeD + 4;
  var homeNeed = energyFor(homePath, carried) + 0.025;
  var homeTime = homeD / 0.72 * 1.30 + 8;

  var siteDistance = Infinity;
  var siteErr = 0;
  if (mem.siteLock) {
    if (liveSite) {
      siteDistance = Math.max(0, num(siteObj.distance, 0));
      siteErr = num(siteObj.bearing, 0);
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteDistance = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteDistance > 0.05 ?
        wrap(Math.atan2(sdy, sdx) * DEG - trueHeading) : 0;
    }
  }

  var currentPath = planPath();
  var currentNeed = energyFor(currentPath, carried);

  if (docked) {
    if (carried > 0) {
      mem.chargeWaitTick = -1;
      return emit(0, 0, false, 0);
    }

    mem.returning = false;
    var attempts = 0;
    while (attempts < 3) {
      currentPath = planPath();
      currentNeed = energyFor(currentPath, carried);
      var currentTime = Number.isFinite(currentPath) ?
                        currentPath / 0.70 + 8 : Infinity;
      var currentC = activeCandidate();
      var tooMuch = currentNeed >
                    num(mem.maxBattery, battery) + 0.025;
      var tooLate = currentTime > timeLeft - 3;

      if (Number.isFinite(currentPath) && !tooMuch && !tooLate) break;

      if (currentC) {
        currentC.blocked = true;
        currentC.status = 0;
        if (mem.targetIdx >= 0 &&
            mem.cands[mem.targetIdx] === currentC) {
          mem.targetIdx = -1;
        }
      } else if (mem.freeSearch) {
        if (mem.freeSearch.kind === "initial") {
          mem.initialFreeDone = true;
        }
        mem.freeSearch = null;
      } else if (mem.exploreGoal) {
        if (mem.exploreGoal.index >= 0) {
          mem.gridVisited[mem.exploreGoal.index] = true;
        }
        mem.exploreGoal = null;
      } else {
        break;
      }
      ensurePlan(true);
      attempts++;
    }

    currentPath = planPath();
    currentNeed = energyFor(currentPath, carried);
    if (!Number.isFinite(currentPath)) {
      mem.chargeWaitTick = -1;
      return emit(0, 0, false, 0);
    }

    var planTime = currentPath / 0.70 + 8;
    if (planTime > timeLeft - 3) {
      mem.chargeWaitTick = -1;
      return emit(0, 0, false, 0);
    }

    if (currentNeed > num(mem.maxBattery, battery) + 0.025) {
      mem.chargeWaitTick = -1;
      return emit(0, 0, false, 0);
    }

    if (battery + 0.012 < currentNeed) {
      if (mem.chargeWaitTick < 0 ||
          Math.abs(currentNeed - num(mem.chargeWaitNeed, 0)) > 0.20) {
        mem.chargeWaitTick = tick;
        mem.chargeWaitBattery = battery;
        mem.chargeLastBattery = battery;
        mem.chargeWaitNeed = currentNeed;
      } else if (battery > num(mem.chargeLastBattery, battery) + 0.035) {
        mem.chargeWaitTick = tick;
        mem.chargeWaitBattery = battery;
        mem.chargeWaitNeed = currentNeed;
      }

      mem.chargeLastBattery = battery;

      if (tick - num(mem.chargeWaitTick, tick) > 900 &&
          battery - num(mem.chargeWaitBattery, battery) < 0.02) {
        var stuckC = activeCandidate();
        if (stuckC) {
          stuckC.blocked = true;
          stuckC.status = 0;
          mem.targetIdx = -1;
        } else if (mem.freeSearch) {
          if (mem.freeSearch.kind === "initial") {
            mem.initialFreeDone = true;
          }
          mem.freeSearch = null;
        } else if (mem.exploreGoal) {
          if (mem.exploreGoal.index >= 0) {
            mem.gridVisited[mem.exploreGoal.index] = true;
          }
          mem.exploreGoal = null;
        }
        mem.chargeWaitTick = -1;
        return emit(0, 0, false, 0);
      }
      return emit(0, 0, false, 0);
    }

    mem.chargeWaitTick = -1;
  } else {
    var mustReturn = !!mem.returning;

    if (carried >= mem.capacity) mustReturn = true;
    if (battery < homeNeed + 0.085) mustReturn = true;
    if (battery < 0.035) mustReturn = true;
    if (carried > 0 && timeLeft < homeTime + 12) mustReturn = true;
    if (Number.isFinite(currentNeed) &&
        battery < currentNeed + 0.025 && homeD > 3) {
      mustReturn = true;
    }
    if (!Number.isFinite(currentPath) &&
        (carried > 0 || homeD > 4)) {
      mustReturn = true;
    }
    if (tick - num(mem.energyShockTick, -10000) < 20 &&
        battery < homeNeed + 0.18) {
      mustReturn = true;
    }

    if (drillProgress > 0 && !sampleDone) {
      mustReturn = false;
    }

    mem.returning = mustReturn;
  }

  /* Detect collisions and lack of translational progress; recover gently. */
  var bumped = !!obs.bumped;
  if (bumped && !mem.prevBump && !docked && drillProgress <= 0) {
    mem.recoverTicks = 18;
    mem.recoverSign = sideSign();
    mem.recoverCount = num(mem.recoverCount, 0) + 1;
    var bc = activeCandidate();
    if (bc) {
      bc.bumpCount = num(bc.bumpCount, 0) + 1;
      if (bc.bumpCount > 4) markCandidateFailed(bc);
    }
  }
  mem.prevBump = bumped;

  if (!docked && drillProgress <= 0) {
    mem.stuckTravel = num(mem.stuckTravel, 0) + wheelTravel;
    mem.stuckCmd = num(mem.stuckCmd, 0) +
      (Math.abs(num(mem.lastCmdL, 0)) +
       Math.abs(num(mem.lastCmdR, 0))) * 0.5 * dt;

    if (tick - num(mem.stuckTick, tick) >= 70) {
      var progress = dist(rawX, rawY,
                          num(mem.stuckX, rawX),
                          num(mem.stuckY, rawY));
      if (!mem.gpsStale && progress < 0.62 &&
          (mem.stuckTravel > 2.0 || mem.stuckCmd > 3.0)) {
        mem.recoverTicks = Math.max(num(mem.recoverTicks, 0), 18);
        mem.recoverSign = sideSign();
        mem.recoverCount = num(mem.recoverCount, 0) + 1;
        var sc = activeCandidate();
        if (sc) {
          sc.stuckCount = num(sc.stuckCount, 0) + 1;
          if (sc.stuckCount > 4) markCandidateFailed(sc);
        }
      } else if (progress > 1.2) {
        mem.recoverCount = Math.max(0, num(mem.recoverCount, 0) - 1);
      }
      mem.stuckTick = tick;
      mem.stuckX = rawX;
      mem.stuckY = rawY;
      mem.stuckTravel = 0;
      mem.stuckCmd = 0;
    }
  } else {
    mem.stuckTick = tick;
    mem.stuckX = rawX;
    mem.stuckY = rawY;
    mem.stuckTravel = 0;
    mem.stuckCmd = 0;
  }

  if (mem.recoverTicks > 0 && !docked && drillProgress <= 0) {
    var elapsed = 18 - mem.recoverTicks;
    mem.recoverTicks--;
    var rs = num(mem.recoverSign, 1);
    if (elapsed < 7) return drive(-0.32, 0);
    return drive(0, rs * 1.05);
  }

  if (drillProgress > 0 && !sampleDone) {
    if (mem.siteLock && !mem.drillSite) {
      mem.drillSite = { x: mem.siteLock.x, y: mem.siteLock.y };
    }
    return holdOutput(true);
  }

  if (mem.returning) {
    if (beaconValid) {
      return navigate(beaconBearing, beaconDistance, 1.15, 0.98, 0.52);
    }
    var bdx = mem.baseX - mem.px;
    var bdy = mem.baseY - mem.py;
    var bd = Math.sqrt(bdx * bdx + bdy * bdy);
    var bErr = bd > 0.05 ?
      wrap(Math.atan2(bdy, bdx) * DEG - trueHeading) : 0;
    return navigate(bErr, bd, 1.15, 0.98, 0.52);
  }

  if (mem.siteLock && carried < mem.capacity) {
    if (siteDistance <= 1.5) {
      var hc = holdCommands();
      var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.14;
      var shouldDrill = siteDistance <= 1.40 && still;
      if (shouldDrill && !mem.drillSite) {
        mem.drillSite = { x: mem.siteLock.x, y: mem.siteLock.y };
      }
      return emit(hc[0], hc[1], shouldDrill, 0);
    }
