      var e = edgeDistance(c);
      var edgeSafe = 5.0 + 0.8 * clamp(Math.abs(speed), 0, 1.5);
      if (e < edgeSafe) {
        var ep = (edgeSafe - e) / edgeSafe;
        cost += 20 * ep * ep;
        if (e < 1.8) cost += 35;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }

    mem.lastSteer = best;
    return best;
  }

  function recoveryOutput() {
    var elapsed = 18 - num(mem.recoverTicks, 0);
    mem.recoverTicks = Math.max(0, num(mem.recoverTicks, 0) - 1);
