    if (mem.monitorKey !== key) {
      mem.monitorKey = key;
      mem.monitorStartTick = tick;
      mem.monitorStartDist = dist(mem.px, mem.py, gx, gy);
      mem.monitorCmd = 0;
      mem.monitorTravel = 0;
      mem.monitorFailures = 0;
    }

    mem.monitorCmd = num(mem.monitorCmd, 0) +
      0.5 * (Math.abs(num(mem.lastCmdL, 0)) +
             Math.abs(num(mem.lastCmdR, 0))) * dt;
    mem.monitorTravel = num(mem.monitorTravel, 0) + wheelTravel;

    if (tick - num(mem.monitorStartTick, tick) >= 160) {
