          mem.monitorFailures = 0;
          mem.monitorKey = null;
        }
        mem.recoverTicks = 18;
        mem.recoverSign = sideSign();
        mem.monitorStartTick = tick;
        mem.monitorStartDist = currentD;
        mem.monitorCmd = 0;
        mem.monitorTravel = 0;
        return true;
      }

      if (improvement > 2.0) {
        mem.monitorFailures = Math.max(0, num(mem.monitorFailures, 0) - 1);
      }
      mem.monitorStartTick = tick;
      mem.monitorStartDist = currentD;
      mem.monitorCmd = 0;
      mem.monitorTravel = 0;
    }
    return false;
  }

  function navigateVector(err, d, stopRadius, cruise, gain,
                          key, gx, gy, onSkip) {
    if (!Number.isFinite(d) || d < 0) return holdOutput(false);
    err = wrap(err);

    if (d <= stopRadius + 0.08) return holdOutput(false);

    if (monitorNavigation(gx, gy, key, stopRadius, onSkip)) {
      return recoveryOutput();
    }

    if (Math.abs(err) > 108) {
      var turn = err >= 0 ? 1 : -1;
      return drive(0, turn * 1.25);
    }

    var dir = chooseDirection(err, centerV);
    var v = Math.min(cruise, Math.max(0, (d - stopRadius) * gain));

    if (Math.abs(dir) > 64) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(rad(dir)));
    }

    var clear = rayAt(dir);
    if (clear < 5.5) {
      var cap = clamp((clear - 1.15) * 0.25, 0.08, cruise);
      v = Math.min(v, cap);
    }
    if (clear < 1.15) v = 0;

    var edge = edgeDistance(dir);
    if (edge < 8) {
      v = Math.min(v, clamp((edge - 1.1) * 0.22, 0.08, cruise));
    }
    if (edge < 1.2) v = 0;

    if (Math.abs(pitch) > 28) v = Math.min(v, 0.55);
    if (Math.abs(pitch) > 40) v = Math.min(v, 0.35);

    var omega = clamp(1.65 * rad(dir), -1.45, 1.45);
    return drive(v, omega);
  }

  function navigatePoint(x, y, stopRadius, cruise, gain,
                         key, onSkip) {
    var dx = x - mem.px, dy = y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var err = d > 0.05 ?
      wrap(Math.atan2(dy, dx) * DEG - trueHeading) : 0;
    return navigateVector(err, d, stopRadius, cruise, gain,
                          key, x, y, onSkip);
  }

  var siteObj = obs.site && typeof obs.site === "object" ? obs.site : null;
  var siteDistance0 = siteObj ? num(siteObj.distance, NaN) : NaN;
  var siteBearing0 = siteObj ? num(siteObj.bearing, NaN) : NaN;
  var liveSite = !!(siteObj &&
    Number.isFinite(siteDistance0) &&
    Number.isFinite(siteBearing0) &&
    siteDistance0 >= 0);

  var oldCarried = num(mem.lastCarried, carried);
  var sampleDone = carried > oldCarried;

  function activeCandidate() {
    if (mem.targetIdx >= 0 && mem.targetIdx < mem.cands.length &&
        mem.cands[mem.targetIdx].status === 1) {
      return mem.cands[mem.targetIdx];
    }
    mem.targetIdx = -1;
    for (var ai = 0; ai < mem.cands.length; ai++) {
      if (mem.cands[ai].status === 1) {
        mem.targetIdx = ai;
        return mem.cands[ai];
      }
    }
    return null;
  }

  function markCandidateDone(c) {
    if (!c) return;
    c.status = 2;
    if (mem.targetIdx >= 0 &&
        mem.cands[mem.targetIdx] === c) {
      mem.targetIdx = -1;
    }
  }

  function candidatePoint(c) {
    if (!c || c.phase !== 1 || c.index >= 20) return null;
    var a = num(c.startAngle, 0) + c.index * 2 * PI / 20;
    return {
      x: clamp(c.x + 15 * Math.cos(a), 3, mem.sizeX - 3),
      y: clamp(c.y + 15 * Math.sin(a), 3, mem.sizeY - 3)
    };
  }

  function candidateRoute(c) {
    if (!c) return Infinity;
    var back = dist(c.x, c.y, mem.baseX, mem.baseY);
    if (c.phase === 0) {
      return dist(mem.px, mem.py, c.x, c.y) + 109 + back;
    }
    var p = candidatePoint(c);
    var toNext = p ? dist(mem.px, mem.py, p.x, p.y) : 0;
    var remaining = Math.max(0, 20 - num(c.index, 0) - 1);
    return toNext + remaining * 4.7 + back;
  }

  function energyNeed(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    return 0.12 + Math.max(0, path) *
      num(mem.ePerM, 0.0018) * 1.17 +
      0.03 * Math.max(0, load || 0);
  }

  function pickCandidate() {
    if (carried > 0 || carried >= mem.capacity) return null;

    var best = -1;
    var bestScore = -1;
    for (var pi = 0; pi < mem.cands.length; pi++) {
      var c = mem.cands[pi];
      if (c.status !== 0 || c.blocked) continue;

      var out = dist(mem.px, mem.py, c.x, c.y);
      var back = dist(c.x, c.y, mem.baseX, mem.baseY);
      var route = out + back + 109;
      var need = energyNeed(route, carried);
      var timeNeed = route / 0.55 + 20;

      if (need > num(mem.maxBattery, battery) - 0.025) continue;
      if (timeNeed > timeLeft - 8) continue;

      var score = Math.max(0.05, c.value) /
                  (32 + out + 0.9 * back + 47);
      if (score > bestScore) {
        bestScore = score;
        best = pi;
      }
    }

    if (best < 0) return null;

    var chosen = mem.cands[best];
    chosen.status = 1;
    chosen.phase = 0;
    chosen.index = 0;
    chosen.startAngle = ((best * 137.5 + tick * 0.7) % 360) * PI / 180;
    mem.targetIdx = best;
    return chosen;
  }

  function signalPoint(s) {
    if (!s || s.index >= 8) return null;
    var a = num(s.startAngle, 0) + s.index * 2 * PI / 8;
    return {
      x: clamp(s.x + 8 * Math.cos(a), 3, mem.sizeX - 3),
      y: clamp(s.y + 8 * Math.sin(a), 3, mem.sizeY - 3)
    };
  }

  function signalNearby(x, y) {
    var centers = Array.isArray(mem.signalCenters) ? mem.signalCenters : [];
    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < 20) return true;
    }
    return false;
  }

  function rememberSignal(x, y) {
    if (!Array.isArray(mem.signalCenters)) mem.signalCenters = [];
    mem.signalCenters.push({ x: x, y: y, tick: tick });
    if (mem.signalCenters.length > 30) mem.signalCenters.shift();
  }

  function beginSignal(x, y, value) {
    mem.signal = {
      x: x,
      y: y,
      centerScience: value,
      bestScience: value,
      bestX: x,
      bestY: y,
      index: 0,
      rounds: 0,
      startAngle: ((tick * 17) % 360) * PI / 180
    };
    mem.exploreGoal = null;
  }

  function finishSignalRing(s) {
    if (!s) return;
    var threshold = Math.max(0.008, Math.abs(s.centerScience) * 0.04);
    if (s.bestScience > s.centerScience + threshold && s.rounds < 4) {
      s.x = s.bestX;
      s.y = s.bestY;
      s.centerScience = s.bestScience;
      s.rounds++;
      s.index = 0;
      s.bestX = s.x;
      s.bestY = s.y;
      s.startAngle += 0.37;
      return;
    }

    rememberSignal(s.x, s.y);
    mem.signal = null;
  }

  function signalRoute() {
    var s = mem.signal;
    if (!s) return Infinity;
    var p = signalPoint(s);
    var toNext = p ? dist(mem.px, mem.py, p.x, p.y) : 0;
    var remainingThis = Math.max(0, 8 - num(s.index, 0)) * 5.7;
    var remainingRounds = Math.max(0, 4 - num(s.rounds, 0)) * 46;
    var back = dist(s.x, s.y, mem.baseX, mem.baseY);
    return toNext + remainingThis + remainingRounds + back;
  }

  function chooseExploreGoal() {
    if (mem.exploreGoal || mem.signal || carried > 0) return;

    var best = -1;
    var bestScore = 1e30;
    for (var gi = 0; gi < mem.gridNodes.length; gi++) {
      if (mem.gridVisited[gi] || mem.gridBlocked[gi]) continue;

      var node = mem.gridNodes[gi];
      var d = dist(mem.px, mem.py, node.x, node.y);
      var back = dist(node.x, node.y, mem.baseX, mem.baseY);
      var route = d + back + 55;
      if (energyNeed(route, carried) >
          num(mem.maxBattery, battery) - 0.025) continue;
      if (route / 0.55 + 18 > timeLeft - 8) continue;

      var score = d + 0.45 * back;
      if (score < bestScore) {
        bestScore = score;
        best = gi;
      }
    }

    if (best >= 0) {
      mem.exploreGoal = {
        x: mem.gridNodes[best].x,
        y: mem.gridNodes[best].y,
        index: best,
        science0: science
      };
    }
  }

  function exploreRoute() {
    if (!mem.exploreGoal) return Infinity;
    var e = mem.exploreGoal;
    return dist(mem.px, mem.py, e.x, e.y) +
           dist(e.x, e.y, mem.baseX, mem.baseY) + 55;
  }

  function currentPlanPath() {
    if (mem.siteLock && !mem.returning) {
      return dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y) +
             dist(mem.siteLock.x, mem.siteLock.y,
                  mem.baseX, mem.baseY) + 8;
    }

    var c = activeCandidate();
    if (c) return candidateRoute(c);
    if (mem.signal) return signalRoute();
    if (mem.exploreGoal) return exploreRoute();
    return Infinity;
  }

  function ensurePlan() {
    if (carried > 0 || mem.returning || mem.siteLock) return;

    var c = activeCandidate();
    if (!c) {
      c = pickCandidate();
      if (c) {
        mem.signal = null;
        mem.exploreGoal = null;
        return;
      }
    }
    if (c) return;

    if (mem.signal) return;
    if (mem.exploreGoal) return;

    if (science > 0.035 && !signalNearby(mem.px, mem.py)) {
      beginSignal(mem.px, mem.py, science);
    } else {
      chooseExploreGoal();
    }
  }

  function updateWorkProgress() {
    if (mem.returning || carried > 0 || mem.siteLock || drillProgress > 0) {
      return;
    }

    var c = activeCandidate();
    if (c) {
      if (c.phase === 0) {
        if (dist(mem.px, mem.py, c.x, c.y) < 3.0) {
          c.phase = 1;
          c.index = 0;
        }
      } else {
        if (c.index >= 20) {
          markCandidateDone(c);
          return;
        }
        var cp = candidatePoint(c);
        if (cp && dist(mem.px, mem.py, cp.x, cp.y) < 2.4) {
          c.index++;
          if (c.index >= 20) markCandidateDone(c);
        }
      }
      return;
    }

    if (mem.signal) {
      var s = mem.signal;
      if (science > num(s.bestScience, -1)) {
        s.bestScience = science;
        s.bestX = mem.px;
        s.bestY = mem.py;
      }
      if (s.index >= 8) {
        finishSignalRing(s);
        return;
      }
      var sp = signalPoint(s);
      if (sp && dist(mem.px, mem.py, sp.x, sp.y) < 2.3) {
        s.index++;
        if (s.index >= 8) finishSignalRing(s);
      }
      return;
    }

    if (mem.exploreGoal) {
      var eg = mem.exploreGoal;
      var improvement = science - num(eg.science0, 0);
      var threshold = Math.max(0.035, Math.abs(num(eg.science0, 0)) * 0.18);
      if (improvement > threshold &&
          !signalNearby(mem.px, mem.py)) {
        beginSignal(mem.px, mem.py, science);
        mem.exploreGoal = null;
        return;
      }

      if (dist(mem.px, mem.py, eg.x, eg.y) < 2.8) {
        if (eg.index >= 0) mem.gridVisited[eg.index] = true;
        mem.exploreGoal = null;
        if (science > 0.025 && !signalNearby(mem.px, mem.py)) {
          beginSignal(mem.px, mem.py, science);
        }
      }
    }
  }

  /* A completed sample ends the sortie unless another site is immediately visible. */
  if (sampleDone) {
    var doneX = mem.siteLock ? mem.siteLock.x : mem.px;
    var doneY = mem.siteLock ? mem.siteLock.y : mem.py;

    var nearNext = liveSite &&
      siteDistance0 <= 7.5 &&
      carried < Math.min(2, mem.capacity) &&
      timeLeft > 30;

    for (var mi = 0; mi < mem.cands.length; mi++) {
      var mc = mem.cands[mi];
      if (mc.status === 2) continue;
      if (dist(doneX, doneY, mc.x, mc.y) < 32) {
        mc.status = 2;
      }
    }

    var sampledCandidate = activeCandidate();
    if (sampledCandidate) markCandidateDone(sampledCandidate);

    mem.siteLock = null;
    mem.samplesThisTrip = num(mem.samplesThisTrip, 0) + 1;
    mem.nearbyContinue = !!nearNext;
    mem.returning = !nearNext;
  }

  mem.lastCarried = carried;

  if (docked && carried === 0) {
    mem.returning = false;
    mem.nearbyContinue = false;
    mem.samplesThisTrip = 0;
  }

  /* Maintain the live site's local position estimate. */
  if (liveSite && !mem.returning &&
      carried < Math.min(2, mem.capacity)) {
    var sg = rad(trueHeading + siteBearing0);
    var slx = mem.px + siteDistance0 * Math.cos(sg);
    var sly = mem.py + siteDistance0 * Math.sin(sg);

    if (mem.siteLock &&
        dist(slx, sly, mem.siteLock.x, mem.siteLock.y) < 9) {
      mem.siteLock.x = 0.65 * mem.siteLock.x + 0.35 * slx;
      mem.siteLock.y = 0.65 * mem.siteLock.y + 0.35 * sly;
      mem.siteLock.value = num(siteObj.value, mem.siteLock.value);
      mem.siteLock.lastSeen = tick;
    } else {
      mem.siteLock = {
        x: slx,
        y: sly,
        value: num(siteObj.value, 1),
        lastSeen: tick
      };
    }
  }

  if (mem.siteLock && drillProgress <= 0 &&
      tick - num(mem.siteLock.lastSeen, tick) > 300) {
    mem.siteLock = null;
    if (carried > 0) mem.returning = true;
  }

  if (carried > 0) {
    if (carried >= Math.min(2, mem.capacity) ||
        !mem.nearbyContinue || !mem.siteLock) {
      mem.returning = true;
    } else {
      mem.returning = false;
    }
  }

  if (drillProgress > 0 && !sampleDone) {
    return holdOutput(true);
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.prevBump && !docked && drillProgress <= 0) {
    mem.recoverTicks = 18;
    mem.recoverSign = sideSign();
  }
  mem.prevBump = bumped;

  if (docked) {
    mem.recoverTicks = 0;
  } else if (mem.recoverTicks > 0 && drillProgress <= 0) {
    return recoveryOutput();
  }

  updateWorkProgress();
  ensurePlan();

  var beacon = obs.beacon && typeof obs.beacon === "object" ?
               obs.beacon : null;
  var beaconDistance = beacon ? num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ? num(beacon.bearing, NaN) : NaN;
  var beaconValid = Number.isFinite(beaconDistance) &&
                    Number.isFinite(beaconBearing) &&
                    beaconDistance >= 0 && beaconDistance <= 24;

  var homeD = beaconValid ? beaconDistance :
              dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homePath = homeD * 1.5 + 5;
  var homeNeed = energyNeed(homePath, carried);
  var homeTime = homeD / 0.65 * 1.35 + 12;

  var planPath = currentPlanPath();
  var planNeed = energyNeed(planPath, carried);
  var planTime = Number.isFinite(planPath) ? planPath / 0.50 + 20 : Infinity;

  function discardCurrentPlan() {
    var c = activeCandidate();
    if (c) {
      c.status = 0;
      c.blocked = true;
      mem.targetIdx = -1;
      return;
    }
    if (mem.siteLock) {
      mem.siteLock = null;
      return;
    }
    if (mem.signal) {
      rememberSignal(mem.signal.x, mem.signal.y);
      mem.signal = null;
      return;
    }
    if (mem.exploreGoal) {
      if (mem.exploreGoal.index >= 0) {
        mem.gridBlocked[mem.exploreGoal.index] = true;
      }
      mem.exploreGoal = null;
    }
  }

  if (docked) {
    if (carried > 0) {
      mem.returning = true;
      return emit(0, 0, false, 0);
    }

    mem.returning = false;
    var tries = 0;
    while (tries < 8) {
      planPath = currentPlanPath();
      planNeed = energyNeed(planPath, carried);
      planTime = Number.isFinite(planPath) ? planPath / 0.50 + 20 : Infinity;

      if (!Number.isFinite(planPath)) break;
      if (planNeed <= num(mem.maxBattery, battery) - 0.015) break;

      discardCurrentPlan();
      ensurePlan();
      tries++;
    }

    planPath = currentPlanPath();
    planNeed = energyNeed(planPath, carried);
    planTime = Number.isFinite(planPath) ? planPath / 0.50 + 20 : Infinity;

    if (!Number.isFinite(planPath) ||
        planTime > timeLeft - 8 ||
        planNeed > num(mem.maxBattery, battery) - 0.015 ||
        battery + 0.015 < planNeed) {
      return emit(0, 0, false, 0);
    }
  } else {
    var mustReturn = !!mem.returning;

    if (carried > 0 &&
        (!mem.nearbyContinue || carried >= Math.min(2, mem.capacity))) {
      mustReturn = true;
    }
    if (battery < homeNeed + 0.10 && homeD > 3) mustReturn = true;
    if (battery < 0.04) mustReturn = true;
    if (Number.isFinite(planNeed) &&
        battery < planNeed + 0.045 && homeD > 3) {
      mustReturn = true;
    }
    if (planTime > timeLeft - 6 && homeD > 3) mustReturn = true;
    if (timeLeft < homeTime + (carried > 0 ? 4 : 9) && homeD > 2) {
      mustReturn = true;
    }
    if (tick - num(mem.energyShockTick, -10000) < 50 &&
        homeD > 5 &&
        (carried > 0 || battery < homeNeed + 0.30)) {
      mustReturn = true;
    }
    if (!Number.isFinite(planPath) && homeD > 4) mustReturn = true;

    if (drillProgress > 0) mustReturn = false;
    mem.returning = mustReturn;
  }

  if (mem.returning) {
    if (beaconValid) {
      return navigateVector(beaconBearing, beaconDistance,
                            0.95, 0.78, 0.62,
                            "HOME", mem.baseX, mem.baseY, null);
    }

    var hx = mem.baseX - mem.px, hy = mem.baseY - mem.py;
    var hd = Math.sqrt(hx * hx + hy * hy);
    var he = hd > 0.05 ?
      wrap(Math.atan2(hy, hx) * DEG - trueHeading) : 0;
    return navigateVector(he, hd, 0.95, 0.78, 0.62,
                          "HOME", mem.baseX, mem.baseY, null);
  }

  if (mem.siteLock && carried < Math.min(2, mem.capacity)) {
    var siteD, siteErr;
    var siteFresh = liveSite;

    if (liveSite) {
      siteD = siteDistance0;
      siteErr = wrap(siteBearing0);
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteD = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteD > 0.05 ?
        wrap(Math.atan2(sdy, sdx) * DEG - trueHeading) : 0;
      siteFresh = tick - num(mem.siteLock.lastSeen, tick) < 50;
    }

    if (siteD <= 1.38) {
      var hc = holdCommands();
      var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.13;
      var shouldDrill = siteD <= 1.42 && still &&
                        (siteFresh || drillProgress > 0);
      return emit(hc[0], hc[1], shouldDrill, 0);
    }

    return navigateVector(siteErr, siteD, 1.02, 0.52, 0.68,
                          "SITE", mem.siteLock.x, mem.siteLock.y,
                          function() {
                            mem.siteLock = null;
                            var sc = activeCandidate();
                            if (sc) markCandidateDone(sc);
                          });
  }

  var cnow = activeCandidate();
  if (cnow) {
    if (cnow.phase === 0) {
      return navigatePoint(
        cnow.x, cnow.y, 2.35, 0.82, 0.60,
        "C" + mem.targetIdx + "T",
        function() { markCandidateDone(cnow); }
      );
    }

    var cpNow = candidatePoint(cnow);
    if (cpNow) {
      var candidateKey = "C" + mem.targetIdx + "S" + cnow.index;
      return navigatePoint(
        cpNow.x, cpNow.y, 1.8, 0.72, 0.60,
        candidateKey,
        function() {
          cnow.index++;
          if (cnow.index >= 20) markCandidateDone(cnow);
        }
      );
    }
  }

  if (mem.signal) {
    var spNow = signalPoint(mem.signal);
    if (spNow) {
      var sNow = mem.signal;
      return navigatePoint(
        spNow.x, spNow.y, 1.8, 0.68, 0.58,
        "S" + sNow.rounds + "I" + sNow.index,
        function() {
          sNow.index++;
          if (sNow.index >= 8) finishSignalRing(sNow);
        }
      );
    }
  }

  if (mem.exploreGoal) {
    var egNow = mem.exploreGoal;
    return navigatePoint(
      egNow.x, egNow.y, 2.2, 0.76, 0.60,
      "G" + egNow.index,
      function() {
        if (egNow.index >= 0) mem.gridVisited[egNow.index] = true;
        mem.exploreGoal = null;
      }
    );
  }

  return holdOutput(false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  var PI = Math.PI;
  var DEG = 180 / PI;
  var dt = 0.1;

  function num(v, d) {
    if (v === undefined || v === null) return d;
    var n = Number(v);
    return Number.isFinite(n) ? n : d;
  }
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }
  function wrap(a) {
    return ((a + 180) % 360 + 360) % 360 - 180;
  }
  function rad(d) {
    return d * PI / 180;
  }
  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1, dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function angleTo(x1, y1, x2, y2) {
    return Math.atan2(y2 - y1, x2 - x1) * DEG;
  }

  var rawX = num(obs.x, 200);
  var rawY = num(obs.y, 200);
  var rawHeading = wrap(num(obs.heading, 0));
  var wheelL = clamp(num(obs.wheelLeft, 0), -3, 3);
  var wheelR = clamp(num(obs.wheelRight, 0), -3, 3);
  var centerV = 0.5 * (wheelL + wheelR);
  var wheelTravel = Math.abs(centerV) * dt;
  var pitch = num(obs.pitch, 0);
  var battery = Math.max(0, num(obs.battery, 1));
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var timeLeft = Math.max(0, num(obs.timeLeft, 1200));
  var science = Math.max(0, num(obs.science, 0));
  var drillProgress = Math.max(0, num(obs.drilling, 0));
  var docked = !!obs.docked;

  if (!mem.initialized) {
    var mission = obs.mission || {};
    var sz = mission.size;
    var sx = 400, sy = 400;

    if (Array.isArray(sz)) {
      sx = num(sz[0], 400);
      sy = num(sz[1], 400);
    } else if (typeof sz === "number") {
      sx = sz;
      sy = sz;
    } else if (sz && typeof sz === "object") {
      sx = num(sz.width, num(sz.w, num(sz.x, 400)));
      sy = num(sz.height, num(sz.h, num(sz.y, 400)));
    }

    var base = mission.base || {};
    mem.sizeX = Math.max(30, sx);
    mem.sizeY = Math.max(30, sy);
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));
    mem.seconds = num(mission.seconds, 1200);

    mem.cands = [];
    var hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi] || {};
      var hx = num(h.x, NaN);
      var hy = num(h.y, NaN);
      if (!Number.isFinite(hx) || !Number.isFinite(hy)) continue;

      var hv = Math.max(0.05, num(h.estimate, num(h.value, 1)));
      var duplicate = -1;
      for (var hj = 0; hj < mem.cands.length; hj++) {
        if (dist(hx, hy, mem.cands[hj].x, mem.cands[hj].y) < 12) {
          duplicate = hj;
          break;
        }
      }

      if (duplicate >= 0) {
        var dc = mem.cands[duplicate];
        dc.x = 0.5 * (dc.x + hx);
        dc.y = 0.5 * (dc.y + hy);
        dc.value = Math.max(dc.value, hv);
      } else {
        mem.cands.push({
          x: clamp(hx, 3, mem.sizeX - 3),
          y: clamp(hy, 3, mem.sizeY - 3),
          value: hv,
          status: 0,
          startScience: 0,
          bestScience: 0,
          bestX: hx,
          bestY: hy
        });
      }
    }

    mem.gridNodes = [];
    mem.gridVisited = [];
    mem.gridBlocked = [];
    var nx = Math.max(4, Math.min(8, Math.ceil(mem.sizeX / 52)));
    var ny = Math.max(4, Math.min(8, Math.ceil(mem.sizeY / 52)));
    for (var gy = 0; gy < ny; gy++) {
      for (var gx = 0; gx < nx; gx++) {
        mem.gridNodes.push({
          x: (gx + 0.5) * mem.sizeX / nx,
          y: (gy + 0.5) * mem.sizeY / ny
        });
        mem.gridVisited.push(false);
        mem.gridBlocked.push(false);
      }
    }

    mem.target = null;
    mem.hunt = null;
    mem.siteLock = null;
    mem.drillXY = null;
    mem.returning = false;
    mem.samplesTrip = 0;

    mem.signalCenters = [];
    mem.tick = 0;

    mem.headingBias = 0;
    mem.yawScale = 1;
    mem.trueHeading = rawHeading;
    mem.compassStuck = false;
    mem.compassQuietYaw = 0;
    mem.prevRawHeading = undefined;
    mem.prevWheelL = undefined;
    mem.prevWheelR = undefined;
    mem.course = null;

    mem.px = rawX;
    mem.py = rawY;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = 0;
    mem.gpsAnchorTravel = 0;
    mem.gpsStale = false;

    mem.prevBattery = battery;
    mem.maxBattery = Math.max(0.2, battery);
    mem.ePerM = 0.0013;
    mem.energyWindowTick = 0;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.shockWindowTick = 0;
    mem.shockWindowBattery = battery;
    mem.energyShockTick = -10000;

    mem.motorGainL = 2.8;
    mem.motorGainR = 2.8;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastV = 0;
    mem.lastSteer = 0;

    mem.prevBump = false;
    mem.recoverTicks = 0;
    mem.recoverSign = 1;
    mem.nav = null;

    mem.holdIL = 0;
    mem.holdIR = 0;

    mem.rayLast = [];
    mem.raySame = [];
    mem.rayStartX = [];
    mem.rayStartY = [];
    mem.rayBad = [];

    mem.chargeWaitTick = -1;
    mem.chargeStartBattery = battery;
    mem.chargeWaitNeed = 0;
    mem.chargeLastBattery = battery;

    mem.lastCarried = carried;
    mem.initialized = true;
  }

  mem.tick = num(mem.tick, 0) + 1;
  var tick = mem.tick;

  /*
   * Blend wheel odometry with GPS. Detect a frozen GPS rather than letting
   * it pull the rover's estimated position back to its old location.
   */
  var oldTrueHeading = num(mem.trueHeading, rawHeading);
  var predictedYaw = 0;
  if (mem.prevWheelL !== undefined && mem.prevWheelR !== undefined) {
    var avgL = 0.5 * (wheelL + num(mem.prevWheelL, wheelL));
    var avgR = 0.5 * (wheelR + num(mem.prevWheelR, wheelR));
    predictedYaw = ((avgR - avgL) / 0.6) * dt * DEG;
  }

  var rawYaw = 0;
  var jumpThisTick = false;
  if (mem.prevRawHeading !== undefined) {
    rawYaw = wrap(rawHeading - num(mem.prevRawHeading, rawHeading));
    var scaledYaw = predictedYaw * num(mem.yawScale, 1);
    var residualYaw = wrap(rawYaw - scaledYaw);

    if (Math.abs(residualYaw) > 75 && Math.abs(predictedYaw) < 42) {
      mem.headingBias = wrap(oldTrueHeading + scaledYaw - rawHeading);
      mem.course = null;
      jumpThisTick = true;
    } else if (!mem.compassStuck &&
               Math.abs(predictedYaw) > 1.5 &&
               Math.abs(rawYaw) > 0.35 &&
               predictedYaw * rawYaw > 0) {
      var ratio = rawYaw / predictedYaw;
      if (ratio > 0.45 && ratio < 1.65) {
        mem.yawScale = clamp(0.97 * num(mem.yawScale, 1) + 0.03 * ratio,
                             0.55, 1.5);
      }
    }

    if (Math.abs(rawYaw) < 0.06 && Math.abs(predictedYaw) > 0.65) {
      mem.compassQuietYaw = num(mem.compassQuietYaw, 0) +
                            Math.abs(predictedYaw * num(mem.yawScale, 1));
      if (mem.compassQuietYaw > 75) mem.compassStuck = true;
    } else if (Math.abs(rawYaw) > 0.4) {
      mem.compassQuietYaw = 0;
      if (mem.compassStuck) {
        mem.headingBias = wrap(oldTrueHeading +
                               predictedYaw * num(mem.yawScale, 1) -
                               rawHeading);
        mem.compassStuck = false;
      }
    }
  }

  var trueHeading = mem.compassStuck ?
    wrap(oldTrueHeading + predictedYaw * num(mem.yawScale, 1)) :
    wrap(rawHeading + num(mem.headingBias, 0));

  var anchorMove = dist(rawX, rawY,
                        num(mem.gpsAnchorX, rawX),
                        num(mem.gpsAnchorY, rawY));
  mem.gpsAnchorTravel = num(mem.gpsAnchorTravel, 0) + wheelTravel;

  if (anchorMove > 1.25) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = tick;
    mem.gpsAnchorTravel = 0;
    mem.gpsStale = false;
  } else {
    if (tick - num(mem.gpsAnchorTick, tick) > 90 &&
        num(mem.gpsAnchorTravel, 0) > 4.5 &&
        anchorMove < 0.85) {
      mem.gpsStale = true;
    }
    if (mem.gpsStale && anchorMove > 2.5) {
      mem.gpsStale = false;
      mem.gpsAnchorX = rawX;
      mem.gpsAnchorY = rawY;
      mem.gpsAnchorTick = tick;
      mem.gpsAnchorTravel = 0;
    }
  }

  var midHeading = wrap(oldTrueHeading +
                        0.5 * predictedYaw * num(mem.yawScale, 1));
  var predX = num(mem.px, rawX) +
              centerV * dt * Math.cos(rad(midHeading));
  var predY = num(mem.py, rawY) +
              centerV * dt * Math.sin(rad(midHeading));

  if (!mem.gpsStale) {
    var ex = rawX - predX;
    var ey = rawY - predY;
    var errLen = Math.sqrt(ex * ex + ey * ey);
    if (errLen < 25) {
      if (errLen > 4) {
        ex *= 4 / errLen;
        ey *= 4 / errLen;
      }
      var alpha = Math.abs(centerV) > 0.25 ? 0.27 : 0.09;
      predX += alpha * ex;
      predY += alpha * ey;
    }
  }

  mem.px = predX;
  mem.py = predY;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  if (!mem.compassStuck && !mem.gpsStale && !jumpThisTick &&
      Math.abs(centerV) > 0.38 &&
      Math.abs(wheelR - wheelL) < 0.38) {
    if (!mem.course) {
      mem.course = {
        x: rawX,
        y: rawY,
        sin: Math.sin(rad(rawHeading)),
        cos: Math.cos(rad(rawHeading)),
        direction: centerV
      };
    } else {
      mem.course.sin += Math.sin(rad(rawHeading));
      mem.course.cos += Math.cos(rad(rawHeading));
      mem.course.direction += centerV;

      if (dist(rawX, rawY, mem.course.x, mem.course.y) > 6) {
        var courseAngle = angleTo(mem.course.x, mem.course.y, rawX, rawY);
        if (mem.course.direction < 0) courseAngle = wrap(courseAngle + 180);
        var meanHeading = Math.atan2(mem.course.sin, mem.course.cos) * DEG;
        var biasTarget = wrap(courseAngle - meanHeading);
        if (Math.abs(biasTarget) < 65) {
          mem.headingBias = wrap(num(mem.headingBias, 0) +
            0.045 * wrap(biasTarget - num(mem.headingBias, 0)));
          trueHeading = wrap(rawHeading + mem.headingBias);
        }
        mem.course = null;
      }
    }
  } else {
    mem.course = null;
  }

  mem.trueHeading = trueHeading;
  mem.prevRawHeading = rawHeading;
  mem.prevWheelL = wheelL;
  mem.prevWheelR = wheelR;

  /* Learn drive energy use and notice sudden battery faults. */
  var previousBattery = num(mem.prevBattery, battery);
  var immediateDrop = previousBattery - battery;
  if (immediateDrop > 0.07) {
    mem.energyShockTick = tick;
    mem.ePerM = Math.max(num(mem.ePerM, 0.0013), 0.0055);
    mem.maxBattery = Math.min(num(mem.maxBattery, battery), battery + 0.025);
  }

  if (docked) {
    mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);
    mem.energyWindowTick = tick;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.shockWindowTick = tick;
    mem.shockWindowBattery = battery;
  } else {
    mem.energyWindowDistance =
      num(mem.energyWindowDistance, 0) + wheelTravel;

    if (tick - num(mem.energyWindowTick, tick) >= 80) {
      var netLoss = num(mem.energyWindowBattery, battery) - battery;
      var moved = num(mem.energyWindowDistance, 0);
      if (moved > 3.5 && netLoss > 0.004) {
        var measured = clamp(netLoss / moved, 0.0003, 0.03);
        var aE = measured > num(mem.ePerM, 0.0013) ? 0.30 : 0.07;
        mem.ePerM = clamp(num(mem.ePerM, 0.0013) +
                          aE * (measured - num(mem.ePerM, 0.0013)),
                          0.0005, 0.025);
      }
      mem.energyWindowTick = tick;
      mem.energyWindowBattery = battery;
      mem.energyWindowDistance = 0;
    }

    if (tick - num(mem.shockWindowTick, tick) >= 50) {
      var shockLoss = num(mem.shockWindowBattery, battery) - battery;
      if (shockLoss > 0.16) {
        mem.energyShockTick = tick;
        mem.ePerM = Math.max(num(mem.ePerM, 0.0013), 0.0055);
        mem.maxBattery = Math.min(num(mem.maxBattery, battery), battery + 0.03);
      }
      mem.shockWindowTick = tick;
      mem.shockWindowBattery = battery;
    }
  }
  mem.prevBattery = battery;

  /* Adapt each wheel's command-to-speed scale. */
  function updateMotorGain(cmd, actual, oldGain) {
    if (Math.abs(cmd) < 0.16 || Math.abs(actual) < 0.10 || cmd * actual <= 0) {
      return oldGain;
    }
    var estimate = Math.abs(actual / cmd);
    if (estimate < 0.55 || estimate > 5.2) return oldGain;
    return clamp(0.985 * oldGain + 0.015 * estimate, 1.0, 5.2);
  }
  if (num(mem.lastV, 0) > 0.12) {
    mem.motorGainL = updateMotorGain(
      num(mem.lastCmdL, 0), wheelL, num(mem.motorGainL, 2.8));
    mem.motorGainR = updateMotorGain(
      num(mem.lastCmdR, 0), wheelR, num(mem.motorGainR, 2.8));
  }

  /* Reject range sensors that become stuck at a finite reading. */
  var rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  var rays = [];
  for (var ri = 0; ri < 9; ri++) {
    var rd = num(rawRays[ri], 15);
    if (rd < 0 || rd > 15.2) rd = 15;
    rd = clamp(rd, 0, 15);

    if (mem.rayLast[ri] === undefined) {
      mem.rayLast[ri] = rd;
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayBad[ri] = false;
    } else if (Math.abs(rd - mem.rayLast[ri]) < 0.02) {
      mem.raySame[ri] = num(mem.raySame[ri], 0) + 1;
      if (mem.raySame[ri] > 240 && rd < 14.8 &&
          dist(mem.px, mem.py, mem.rayStartX[ri],
               mem.rayStartY[ri]) > 4) {
        mem.rayBad[ri] = true;
      }
    } else {
      if (mem.rayBad[ri] && Math.abs(rd - mem.rayLast[ri]) > 0.8) {
        mem.rayBad[ri] = false;
      }
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
    }

    mem.rayLast[ri] = rd;
    rays[ri] = mem.rayBad[ri] ? 15 : rd;
  }

  function emit(left, right, drill, v) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastV = Math.abs(num(v, 0));
    return { left: left, right: right, drill: !!drill };
  }

  function wheelCommand(target, actual, gain) {
    gain = clamp(num(gain, 2.8), 1, 5.2);
    var cmd = target / gain + 0.34 * (target - actual);
    if (Math.abs(target) > 0.16 &&
        Math.abs(cmd) < 0.10 &&
        cmd * target >= 0) {
      cmd = target < 0 ? -0.10 : 0.10;
    }
    return clamp(cmd, -1, 1);
  }

  function drive(v, omega) {
    var lt = clamp(v - 0.3 * omega, -1.8, 1.8);
    var rt = clamp(v + 0.3 * omega, -1.8, 1.8);
    mem.holdIL = num(mem.holdIL, 0) * 0.88;
    mem.holdIR = num(mem.holdIR, 0) * 0.88;
    return emit(
      wheelCommand(lt, wheelL, mem.motorGainL),
      wheelCommand(rt, wheelR, mem.motorGainR),
      false,
      v
    );
  }

  function holdCommands() {
    var feed = clamp(0.34 * Math.sin(rad(pitch)), -0.32, 0.32);
    mem.holdIL = clamp(num(mem.holdIL, 0) - 0.10 * wheelL * dt,
                       -0.18, 0.18);
    mem.holdIR = clamp(num(mem.holdIR, 0) - 0.10 * wheelR * dt,
                       -0.18, 0.18);
    var l = clamp(feed + mem.holdIL - 0.62 * wheelL, -0.42, 0.42);
    var r = clamp(feed + mem.holdIR - 0.62 * wheelR, -0.42, 0.42);
    return [l, r];
  }

  function holdOutput(drill) {
    var h = holdCommands();
    return emit(h[0], h[1], drill, 0);
  }

  function edgeDistance(relAngle) {
    var a = rad(trueHeading + relAngle);
    var dx = Math.cos(a), dy = Math.sin(a);
    var best = 1e9;
    if (dx > 0.001) best = Math.min(best, (mem.sizeX - 3 - mem.px) / dx);
    if (dx < -0.001) best = Math.min(best, (3 - mem.px) / dx);
    if (dy > 0.001) best = Math.min(best, (mem.sizeY - 3 - mem.py) / dy);
    if (dy < -0.001) best = Math.min(best, (3 - mem.py) / dy);
    return Math.max(0, best);
  }

  function rayAt(a) {
    var q = clamp((a + 80) / 20, 0, 8);
    var i = Math.floor(q);
    var f = q - i;
    if (i >= 8) return rays[8];
    return Math.min(rays[i], rays[i + 1],
                    rays[i] * (1 - f) + rays[i + 1] * f);
  }

  function sideSign() {
    var right = 0, left = 0;
    for (var i = 0; i < 4; i++) right += rays[i];
    for (var j = 5; j < 9; j++) left += rays[j];
    right *= 0.25;
    left *= 0.25;
    if (left > right + 0.25) return 1;
    if (right > left + 0.25) return -1;
    return num(mem.recoverSign, 1) >= 0 ? 1 : -1;
  }

  function recoveryOutput() {
    var elapsed = 20 - num(mem.recoverTicks, 0);
    mem.recoverTicks = Math.max(0, num(mem.recoverTicks, 0) - 1);
    if (elapsed < 8) return drive(-0.28, 0);
    return drive(0, num(mem.recoverSign, 1) * 0.95);
  }

  function monitorNavigation(gx, gy, key, stopRadius, onSkip) {
    if (!key || !Number.isFinite(gx) || !Number.isFinite(gy)) return false;

    var mx = mem.gpsStale ? mem.px : rawX;
    var my = mem.gpsStale ? mem.py : rawY;

    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = {
        key: key,
        startTick: tick,
        startDist: dist(mx, my, gx, gy),
        cmd: 0,
        travel: 0,
        failures: 0
      };
    }

    var nav = mem.nav;
    if (num(mem.lastV, 0) > 0.12) {
      nav.cmd = num(nav.cmd, 0) + num(mem.lastV, 0) * dt;
    }
    nav.travel = num(nav.travel, 0) + wheelTravel;

    if (tick - num(nav.startTick, tick) >= 180) {
      var currentD = dist(mx, my, gx, gy);
      var improvement = num(nav.startDist, currentD) - currentD;
      var stalled = currentD > stopRadius + 2.5 &&
                    improvement < 0.9 &&
                    (num(nav.cmd, 0) > 1.3 ||
                     num(nav.travel, 0) > 1.3);

      if (stalled) {
        nav.failures = num(nav.failures, 0) + 1;
        mem.recoverTicks = Math.max(num(mem.recoverTicks, 0), 20);
        mem.recoverSign = sideSign();

        if (nav.failures >= 3 && typeof onSkip === "function") {
          onSkip();
          nav.failures = 0;
          mem.nav = null;
        }

        if (mem.nav) {
          mem.nav.startTick = tick;
          mem.nav.startDist = currentD;
          mem.nav.cmd = 0;
          mem.nav.travel = 0;
        }
        return true;
      }

      if (improvement > 1.5) {
        nav.failures = Math.max(0, num(nav.failures, 0) - 1);
      }
      nav.startTick = tick;
      nav.startDist = currentD;
      nav.cmd = 0;
      nav.travel = 0;
    }

    return false;
  }

  function chooseDirection(goalErr, speed) {
    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    var g = clamp(goalErr, -80, 80);
    candidates.push(g);
    candidates.push(clamp(g - 15, -80, 80));
    candidates.push(clamp(g + 15, -80, 80));
    candidates.push(clamp(g - 35, -80, 80));
    candidates.push(clamp(g + 35, -80, 80));

    var best = g;
    var bestCost = 1e30;

    for (var ci = 0; ci < candidates.length; ci++) {
      var c = candidates[ci];
      var duplicate = false;
      for (var cj = 0; cj < ci; cj++) {
        if (Math.abs(candidates[cj] - c) < 0.5) {
          duplicate = true;
          break;
        }
      }
      if (duplicate) continue;

      var diff = Math.abs(wrap(c - goalErr));
      var cost = 0.0022 * diff * diff;
      cost += 0.00012 *
        Math.pow(Math.abs(wrap(c - num(mem.lastSteer, 0))), 2);

      for (var rj = 0; rj < 9; rj++) {
        var d = rays[rj];
        if (d >= 14.95) continue;
        var alpha = -80 + 20 * rj;
        var da = Math.abs(wrap(c - alpha));
        if (da > 58) continue;

        var safe = 3.0 + 0.40 * clamp(Math.abs(speed), 0, 1.5);
        var p = clamp((safe - d) / safe, 0, 1);
        var influence = Math.exp(-0.5 * Math.pow(da / 25, 2));
        cost += 22 * p * p * influence;
        if (d < 1.25 && da < 21) cost += 90;
      }

      var e = edgeDistance(c);
      var edgeSafe = 4.8 + 0.5 * clamp(Math.abs(speed), 0, 1.5);
      if (e < edgeSafe) {
        var ep = (edgeSafe - e) / edgeSafe;
        cost += 24 * ep * ep;
        if (e < 1.7) cost += 75;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }

    mem.lastSteer = best;
    return best;
  }

  function navigateVector(err, d, stopRadius, cruise, gain,
                          key, gx, gy, onSkip) {
    if (!Number.isFinite(d) || d < 0) return holdOutput(false);
    err = wrap(err);

    if (d <= stopRadius + 0.08) return holdOutput(false);

    if (monitorNavigation(gx, gy, key, stopRadius, onSkip)) {
      return recoveryOutput();
    }

    if (Math.abs(err) > 118) {
      return drive(0, err >= 0 ? 1.12 : -1.12);
    }

    var dir = chooseDirection(err, centerV);
    var v = Math.min(cruise, Math.max(0.12, (d - stopRadius) * gain));

    if (Math.abs(dir) > 65) {
      v = 0;
    } else {
      v *= Math.max(0.08, Math.cos(rad(dir)));
    }

    var clear = rayAt(dir);
    if (clear < 5.0) {
      var cap = clamp((clear - 1.05) * 0.25, 0, cruise);
      v = Math.min(v, cap);
    }
    if (clear < 1.15) v = 0;

    var edge = edgeDistance(dir);
    if (edge < 7.5) {
      v = Math.min(v, clamp((edge - 1.0) * 0.22, 0, cruise));
    }
    if (edge < 1.15) v = 0;

    if (Math.abs(pitch) > 30) v = Math.min(v, 0.52);
    if (Math.abs(pitch) > 42) v = Math.min(v, 0.34);

    var omega = clamp(1.65 * rad(dir), -1.35, 1.35);
    return drive(v, omega);
  }

  function navigateTo(x, y, stopRadius, cruise, gain, key, onSkip) {
    var dx = x - mem.px;
    var dy = y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var err = d > 0.05 ?
      wrap(Math.atan2(dy, dx) * DEG - trueHeading) : 0;
    return navigateVector(err, d, stopRadius, cruise, gain,
                          key, x, y, onSkip);
  }

  function energyFor(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    var n = Math.max(0, load || 0);
    return 0.07 + Math.max(0, path) *
      num(mem.ePerM, 0.0013) * (1.55 + 0.08 * n) + 0.02 * n;
  }

  function markGridNear(x, y, radius) {
    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (dist(x, y, mem.gridNodes[i].x, mem.gridNodes[i].y) < radius) {
        mem.gridVisited[i] = true;
      }
    }
  }

  function rememberSignal(x, y, value) {
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    var centers = Array.isArray(mem.signalCenters) ? mem.signalCenters : [];
    var match = -1;
    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < 10) {
        match = i;
        break;
      }
    }
    if (match >= 0) {
      centers[match].value = Math.max(
        num(centers[match].value, 0), num(value, 0));
      centers[match].tick = tick;
    } else {
      centers.push({ x: x, y: y, value: num(value, 0), tick: tick });
      if (centers.length > 50) centers.shift();
    }
    mem.signalCenters = centers;
    markGridNear(x, y, 17);
  }

  function signalNear(x, y, value) {
    var centers = Array.isArray(mem.signalCenters) ? mem.signalCenters : [];
    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < 18 &&
          value <= num(centers[i].value, 0) +
                   Math.max(0.035, Math.abs(num(centers[i].value, 0)) * 0.12)) {
        return true;
      }
    }
    return false;
  }

  function beginFreeHunt(x, y, value) {
    mem.hunt = {
      kind: "free",
      centerX: x,
      centerY: y,
      originX: x,
      originY: y,
      baseScience: value,
      bestScience: value,
      bestX: x,
      bestY: y,
      index: 0,
      round: 0,
      maxRounds: 3,
      radius: 8,
      startAngle: ((tick * 17) % 360) * PI / 180
    };
    mem.target = null;
    mem.nav = null;
  }

  function beginCandidateHunt(c, idx) {
    if (!c) return;
    var threshold = Math.max(0.025, Math.abs(c.startScience) * 0.12);
    var useBest = c.bestScience > c.startScience + threshold;
    var cx = useBest ? c.bestX : mem.px;
    var cy = useBest ? c.bestY : mem.py;
    var baseValue = useBest ? c.bestScience : science;

    mem.hunt = {
      kind: "candidate",
      cidx: idx,
      centerX: cx,
      centerY: cy,
      originX: c.x,
      originY: c.y,
      baseScience: baseValue,
      bestScience: baseValue,
      bestX: cx,
      bestY: cy,
      index: 0,
      round: 0,
      maxRounds: 2,
      radius: useBest ? 8 : 18,
      startAngle: ((idx * 131 + tick * 0.7) % 360) * PI / 180
    };
    mem.nav = null;
  }

  function huntPoint(h) {
    if (!h || h.index >= 8) return null;
    var a = h.startAngle + h.index * 2 * PI / 8;
    return {
      x: clamp(h.centerX + h.radius * Math.cos(a), 3, mem.sizeX - 3),
      y: clamp(h.centerY + h.radius * Math.sin(a), 3, mem.sizeY - 3)
    };
  }

  function finishHuntRing() {
    var h = mem.hunt;
    if (!h) return;

    var gain = num(h.bestScience, 0) - num(h.baseScience, 0);
    var threshold = Math.max(0.008, Math.abs(num(h.baseScience, 0)) * 0.045);

    if (gain > threshold && h.round < h.maxRounds) {
      h.centerX = h.bestX;
      h.centerY = h.bestY;
      h.baseScience = h.bestScience;
      h.bestX = h.centerX;
      h.bestY = h.centerY;
      h.index = 0;
      h.round++;
      h.radius = 8;
      h.startAngle += 0.37;
      mem.nav = null;
      return;
    }

    rememberSignal(h.originX, h.originY, h.bestScience);
    rememberSignal(h.centerX, h.centerY, h.bestScience);

    if (h.kind === "candidate") {
      var c = mem.cands[h.cidx];
      if (c && c.status === 1) c.status = 3;
      if (mem.target &&
          mem.target.kind === "candidate" &&
          mem.target.idx === h.cidx) {
        mem.target = null;
      }
    }

    mem.hunt = null;
    mem.nav = null;
  }

  function markSampledAt(x, y, oldTarget, oldHunt) {
    var nearest = -1;
    var nearestD = 1e30;

    for (var i = 0; i < mem.cands.length; i++) {
      var d = dist(x, y, mem.cands[i].x, mem.cands[i].y);
      if (d < nearestD) {
        nearestD = d;
        nearest = i;
      }
      if (d < 8 && mem.cands[i].status !== 2) {
        mem.cands[i].status = 2;
      }
    }

    if (oldTarget && oldTarget.kind === "candidate" &&
        mem.cands[oldTarget.idx]) {
      mem.cands[oldTarget.idx].status = 2;
    }
    if (oldHunt && oldHunt.kind === "candidate" &&
        mem.cands[oldHunt.cidx]) {
      mem.cands[oldHunt.cidx].status = 2;
    }
    if (nearest >= 0 && nearestD < 22) {
      mem.cands[nearest].status = 2;
    }

    markGridNear(x, y, 17);
  }

  function candidateRouteLength(c, fromX, fromY) {
    if (!c) return Infinity;
    return dist(fromX, fromY, c.x, c.y) +
           150 + dist(c.x, c.y, mem.baseX, mem.baseY);
  }

  function pickCandidate() {
    if (carried >= mem.capacity) return null;
    if (carried > 0 && num(mem.samplesTrip, 0) >= 2) return null;

    var best = -1;
    var bestScore = -1;
    var available = docked ? num(mem.maxBattery, battery) : battery;

    for (var i = 0; i < mem.cands.length; i++) {
      var c = mem.cands[i];
      if (c.status !== 0) continue;

      var out = dist(mem.px, mem.py, c.x, c.y);
      var back = dist(c.x, c.y, mem.baseX, mem.baseY);
      if (carried > 0 && out > 30) continue;

      var route = out + 150 + back;
      var need = energyFor(route, carried);
      var margin = docked ? 0.025 : 0.075;
      if (need + margin > available) continue;

      var timeNeed = route / 0.58 + 20;
      if (timeNeed > timeLeft - 6) continue;

      var score = Math.max(0.05, c.value) /
                  (30 + out + 0.65 * back + 55);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return null;

    var chosen = mem.cands[best];
    chosen.status = 1;
    chosen.startScience = science;
    chosen.bestScience = science;
    chosen.bestX = mem.px;
    chosen.bestY = mem.py;
    mem.target = { kind: "candidate", idx: best };
    mem.hunt = null;
    mem.nav = null;
    return chosen;
  }

  function chooseExploreGoal() {
    if (carried > 0) return null;

    var best = -1;
    var bestScore = 1e30;
    var available = docked ? num(mem.maxBattery, battery) : battery;

    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (mem.gridVisited[i] || mem.gridBlocked[i]) continue;

      var node = mem.gridNodes[i];
      var out = dist(mem.px, mem.py, node.x, node.y);
      var back = dist(node.x, node.y, mem.baseX, mem.baseY);
      var route = out + 50 + back;
      var need = energyFor(route, carried);
      var margin = docked ? 0.025 : 0.075;
      if (need + margin > available) continue;
      if (route / 0.58 + 18 > timeLeft - 6) continue;

      var score = out + 0.30 * back;
      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return null;

    mem.target = {
      kind: "grid",
      idx: best,
      science0: science
    };
    mem.nav = null;
    return mem.gridNodes[best];
  }

  function ensureWork() {
    if (mem.returning || mem.siteLock || drillProgress > 0) return;
    if (mem.hunt) return;

    if (mem.target) {
      if (mem.target.kind === "candidate") {
        var tc = mem.cands[mem.target.idx];
        if (tc && tc.status === 1) return;
        mem.target = null;
      } else if (mem.target.kind === "grid") {
        if (!mem.gridVisited[mem.target.idx] &&
            !mem.gridBlocked[mem.target.idx]) return;
        mem.target = null;
      }
    }

    if (!mem.target) {
      for (var ai = 0; ai < mem.cands.length; ai++) {
        if (mem.cands[ai].status === 1) {
          mem.target = { kind: "candidate", idx: ai };
          return;
        }
      }
    }

    if (carried > 0 && num(mem.samplesTrip, 0) >= 2) return;

    var canSignal = science > 0.035 &&
      !signalNear(mem.px, mem.py, science) &&
      (carried === 0 ||
       (num(mem.samplesTrip, 0) < 2 && science > 0.12));

    if (canSignal) {
      beginFreeHunt(mem.px, mem.py, science);
      return;
    }

    if (pickCandidate()) return;
    if (carried === 0) chooseExploreGoal();
  }

  function updateWorkProgress() {
    if (mem.returning || mem.siteLock || drillProgress > 0) return;

    if (mem.hunt) {
      if (science > num(mem.hunt.bestScience, -1)) {
        mem.hunt.bestScience = science;
        mem.hunt.bestX = mem.px;
        mem.hunt.bestY = mem.py;
      }

      var hp = huntPoint(mem.hunt);
      if (!hp) {
        finishHuntRing();
        return;
      }
      if (dist(mem.px, mem.py, hp.x, hp.y) < 2.4) {
        mem.hunt.index++;
        if (mem.hunt.index >= 8) finishHuntRing();
      }
      return;
    }

    if (!mem.target) return;

    if (mem.target.kind === "candidate") {
      var idx = mem.target.idx;
      var c = mem.cands[idx];
      if (!c || c.status !== 1) {
        mem.target = null;
        return;
      }

      if (science > num(c.bestScience, -1)) {
        c.bestScience = science;
        c.bestX = mem.px;
        c.bestY = mem.py;
      }

      if (dist(mem.px, mem.py, c.x, c.y) < 4.5) {
        beginCandidateHunt(c, idx);
      }
      return;
    }

    if (mem.target.kind === "grid") {
      var gi = mem.target.idx;
      var node = mem.gridNodes[gi];
      if (!node) {
        mem.target = null;
        return;
      }

      var threshold = Math.max(0.025, Math.abs(mem.target.science0) * 0.18);
      if (science > num(mem.target.science0, 0) + threshold &&
          !signalNear(mem.px, mem.py, science)) {
        mem.gridVisited[gi] = true;
        mem.target = null;
        beginFreeHunt(mem.px, mem.py, science);
        return;
      }

      if (dist(mem.px, mem.py, node.x, node.y) < 2.8) {
        mem.gridVisited[gi] = true;
        mem.target = null;
        if (science > 0.025 &&
            !signalNear(mem.px, mem.py, science)) {
          beginFreeHunt(mem.px, mem.py, science);
        }
      }
    }
  }

  function huntRemainingDistance(h) {
    if (!h) return 0;
    var p = huntPoint(h);
    var remainingPoints = Math.max(0, 8 - h.index);
    var edge = 2 * h.radius * Math.sin(PI / 8);
    var d = p ? dist(mem.px, mem.py, p.x, p.y) : 0;
    d += Math.max(0, remainingPoints - 1) * edge;
    d += Math.max(0, h.maxRounds - h.round) * 50;
    return d;
  }

  function workDistance() {
    if (mem.siteLock) {
      var sd;
      if (liveSite && !mem.returning) {
        sd = siteDistance0;
      } else {
        sd = dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      }
      return sd + 8 +
        dist(mem.siteLock.x, mem.siteLock.y, mem.baseX, mem.baseY);
    }

    if (mem.hunt) {
      return huntRemainingDistance(mem.hunt) +
        dist(mem.hunt.centerX, mem.hunt.centerY, mem.baseX, mem.baseY);
    }

    if (mem.target && mem.target.kind === "candidate") {
      var c = mem.cands[mem.target.idx];
      if (!c) return Infinity;
      return dist(mem.px, mem.py, c.x, c.y) +
        155 + dist(c.x, c.y, mem.baseX, mem.baseY);
    }

    if (mem.target && mem.target.kind === "grid") {
      var n = mem.gridNodes[mem.target.idx];
      if (!n) return Infinity;
      return dist(mem.px, mem.py, n.x, n.y) +
        50 + dist(n.x, n.y, mem.baseX, mem.baseY);
    }

    return Infinity;
  }

  function discardCurrentPlan() {
    if (mem.siteLock) {
      mem.siteLock = null;
      mem.drillXY = null;
      mem.nav = null;
      return true;
    }

    if (mem.hunt) {
      var oldHunt = mem.hunt;
      rememberSignal(oldHunt.originX, oldHunt.originY,
                     oldHunt.bestScience);
      rememberSignal(oldHunt.centerX, oldHunt.centerY,
                     oldHunt.bestScience);

      if (oldHunt.kind === "candidate" &&
          mem.cands[oldHunt.cidx]) {
        mem.cands[oldHunt.cidx].status = 3;
      }
      mem.hunt = null;
      mem.target = null;
      mem.nav = null;
      return true;
    }

    if (mem.target && mem.target.kind === "candidate") {
      var ci = mem.target.idx;
      if (mem.cands[ci]) mem.cands[ci].status = 3;
      mem.target = null;
      mem.nav = null;
      return true;
    }

    if (mem.target && mem.target.kind === "grid") {
      var gi = mem.target.idx;
      if (gi >= 0 && gi < mem.gridBlocked.length) {
        mem.gridBlocked[gi] = true;
        mem.gridVisited[gi] = true;
      }
      mem.target = null;
      mem.nav = null;
      return true;
    }

    return false;
  }

  var siteObj = obs.site && typeof obs.site === "object" ? obs.site : null;
  var siteDistance0 = siteObj ? num(siteObj.distance, NaN) : NaN;
  var siteBearing0 = siteObj ? num(siteObj.bearing, NaN) : NaN;
  var liveSite = !!(siteObj &&
    Number.isFinite(siteDistance0) &&
    Number.isFinite(siteBearing0) &&
    siteDistance0 >= 0);

  var oldCarried = num(mem.lastCarried, carried);
  var sampleDone = carried > oldCarried;

  if (sampleDone) {
    var oldTarget = mem.target;
    var oldHunt = mem.hunt;
    var doneX = mem.drillXY ? mem.drillXY.x :
                (mem.siteLock ? mem.siteLock.x : mem.px);
    var doneY = mem.drillXY ? mem.drillXY.y :
                (mem.siteLock ? mem.siteLock.y : mem.py);

    markSampledAt(doneX, doneY, oldTarget, oldHunt);

    if (oldHunt) {
      rememberSignal(oldHunt.originX, oldHunt.originY,
                     oldHunt.bestScience);
      rememberSignal(oldHunt.centerX, oldHunt.centerY,
                     oldHunt.bestScience);
    }

    mem.target = null;
    mem.hunt = null;
    mem.siteLock = null;
    mem.drillXY = null;
    mem.nav = null;
    mem.samplesTrip = num(mem.samplesTrip, 0) + 1;
    mem.returning = false;
  }
  mem.lastCarried = carried;

  if (docked && carried === 0) {
    mem.returning = false;
    mem.samplesTrip = 0;
  }

  /* Update the global estimate of a live site's position from its bearing. */
  if (liveSite && !mem.returning && carried < mem.capacity) {
    var sg = rad(trueHeading + siteBearing0);
    var slx = mem.px + siteDistance0 * Math.cos(sg);
    var sly = mem.py + siteDistance0 * Math.sin(sg);

    var sameAsJustSampled = sampleDone &&
      dist(slx, sly,
           mem.drillXY ? mem.drillXY.x : rawX,
           mem.drillXY ? mem.drillXY.y : rawY) < 3;

    if (!sameAsJustSampled) {
      if (mem.siteLock &&
          dist(slx, sly, mem.siteLock.x, mem.siteLock.y) < 12) {
        mem.siteLock.x = 0.62 * mem.siteLock.x + 0.38 * slx;
        mem.siteLock.y = 0.62 * mem.siteLock.y + 0.38 * sly;
        mem.siteLock.value = num(siteObj.value, mem.siteLock.value);
        mem.siteLock.lastSeen = tick;
      } else {
        mem.siteLock = {
          x: slx,
          y: sly,
          value: num(siteObj.value, 1),
          lastSeen: tick
        };
      }

      var nearestHint = -1;
      var nearestHintD = 30;
      for (var hi2 = 0; hi2 < mem.cands.length; hi2++) {
        var hd2 = dist(slx, sly, mem.cands[hi2].x, mem.cands[hi2].y);
        if (hd2 < nearestHintD) {
          nearestHintD = hd2;
          nearestHint = hi2;
        }
      }
      if (nearestHint >= 0 && Number.isFinite(num(siteObj.value, NaN))) {
        mem.cands[nearestHint].value = Math.max(
          mem.cands[nearestHint].value, num(siteObj.value, 0));
      }
    }
  }

  if (mem.siteLock && drillProgress <= 0 &&
      tick - num(mem.siteLock.lastSeen, tick) > 140) {
    mem.siteLock = null;
    mem.drillXY = null;
    mem.nav = null;
  }

  if (drillProgress > 0 && !sampleDone) {
    var holdWhileDrilling = holdCommands();
    return emit(holdWhileDrilling[0], holdWhileDrilling[1], true, 0);
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.prevBump && !docked && drillProgress <= 0) {
    mem.recoverTicks = 20;
    mem.recoverSign = sideSign();
  }
  mem.prevBump = bumped;

  if (docked) {
    mem.recoverTicks = 0;
  } else if (mem.recoverTicks > 0 && drillProgress <= 0) {
    return recoveryOutput();
  }

  updateWorkProgress();
  ensureWork();

  var beacon = obs.beacon && typeof obs.beacon === "object" ?
               obs.beacon : null;
  var beaconDistance = beacon ? num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ? num(beacon.bearing, NaN) : NaN;
  var beaconValid = Number.isFinite(beaconDistance) &&
                    Number.isFinite(beaconBearing) &&
                    beaconDistance >= 0 && beaconDistance <= 24;

  var homeD = beaconValid ? beaconDistance :
    dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeTime = homeD / 0.55 * 1.35 + 12;
  var homeNeed = energyFor(homeD * 1.35 + 5, carried) + 0.035;

  if (docked && carried > 0) {
    mem.chargeWaitTick = -1;
    return emit(0, 0, false, 0);
  }

  if (docked && carried === 0) {
    mem.returning = false;

    var tries = 0;
    while (tries < 8) {
      var pathNow = workDistance();
      if (!Number.isFinite(pathNow)) break;

      var needNow = energyFor(pathNow, carried);
      var timeNow = pathNow / 0.55 + 15;
      var batteryImpossible =
        needNow + 0.025 > num(mem.maxBattery, battery);
      var timeImpossible = timeNow > timeLeft - 5;

      if (!batteryImpossible && !timeImpossible) break;
      if (!discardCurrentPlan()) break;
      ensureWork();
      tries++;
    }

    var dockPath = workDistance();
    if (!Number.isFinite(dockPath)) {
      mem.chargeWaitTick = -1;
      return emit(0, 0, false, 0);
    }

    var dockNeed = energyFor(dockPath, carried);
    var dockTime = dockPath / 0.55 + 15;
    if (dockTime > timeLeft - 5 ||
        dockNeed + 0.025 > num(mem.maxBattery, battery)) {
      mem.chargeWaitTick = -1;
      return emit(0, 0, false, 0);
    }

    if (battery + 0.01 < dockNeed + 0.015) {
      if (mem.chargeWaitTick < 0 ||
          Math.abs(dockNeed - num(mem.chargeWaitNeed, 0)) > 0.12) {
        mem.chargeWaitTick = tick;
        mem.chargeStartBattery = battery;
        mem.chargeWaitNeed = dockNeed;
      }

      if (battery > num(mem.chargeStartBattery, battery) + 0.025) {
        mem.chargeWaitTick = tick;
        mem.chargeStartBattery = battery;
      }

      mem.chargeLastBattery = battery;

      if (tick - num(mem.chargeWaitTick, tick) > 1800 &&
          battery - num(mem.chargeStartBattery, battery) < 0.02) {
        discardCurrentPlan();
        mem.chargeWaitTick = -1;
        return emit(0, 0, false, 0);
      }

      return emit(0, 0, false, 0);
    }

    mem.chargeWaitTick = -1;
  } else {
    var workD = workDistance();
    var mustReturn = !!mem.returning;

    if (carried >= mem.capacity) mustReturn = true;
    if (carried > 0 && num(mem.samplesTrip, 0) >= 2) mustReturn = true;
    if (carried > 0 && !mem.siteLock && !mem.hunt && !mem.target) {
      mustReturn = true;
    }

    if (battery < 0.025) mustReturn = true;
    if (homeD > 3 && battery < homeNeed + 0.08) mustReturn = true;

    if (Number.isFinite(workD)) {
      var remainingNeed = energyFor(workD, carried);
      var remainingTime = workD / 0.55 + 15;
      if (homeD > 3 && battery < remainingNeed + 0.04) {
        mustReturn = true;
      }
      if (homeD > 2 && timeLeft < remainingTime) {
        mustReturn = true;
      }
    } else if (homeD > 4) {
      mustReturn = true;
    }

    if (carried > 0 && timeLeft < homeTime + 8) {
      mustReturn = true;
    }
    if (carried > 0 &&
        tick - num(mem.energyShockTick, -10000) < 35 &&
        homeD > 4) {
      mustReturn = true;
    }

    var siteDForDecision = Infinity;
    if (mem.siteLock) {
      siteDForDecision = liveSite ?
        siteDistance0 :
        dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
    }

    if (!mem.returning &&
        mem.siteLock &&
        siteDForDecision <= 1.45 &&
        carried < mem.capacity &&
        battery > 0.06 &&
        timeLeft > homeTime + 8) {
      mustReturn = false;
    }

    mem.returning = mustReturn;
  }

  if (mem.returning) {
    if (beaconValid) {
      return navigateVector(beaconBearing, beaconDistance,
                            1.45, 0.76, 0.46,
                            "HOME", mem.baseX, mem.baseY, null);
    }
    return navigateTo(mem.baseX, mem.baseY,
                      1.45, 0.76, 0.46, "HOME", null);
  }

  if (mem.siteLock && carried < mem.capacity) {
    var siteD, siteErr;
    if (liveSite) {
      siteD = siteDistance0;
      siteErr = wrap(siteBearing0);
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteD = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteD > 0.05 ?
        wrap(Math.atan2(sdy, sdx) * DEG - trueHeading) : 0;
    }

    if (siteD <= 1.42) {
      var hc = holdCommands();
      var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.14;
      var fresh = tick - num(mem.siteLock.lastSeen, tick) < 120;
      var shouldDrill = siteD <= 1.40 && still && fresh;

      if (shouldDrill && !mem.drillXY) {
        mem.drillXY = { x: mem.siteLock.x, y: mem.siteLock.y };
      }
      return emit(hc[0], hc[1], shouldDrill, 0);
    }

    return navigateVector(siteErr, siteD, 1.28, 0.56, 0.62,
                          "SITE", mem.siteLock.x, mem.siteLock.y,
                          function() {
                            mem.siteLock = null;
                            mem.drillXY = null;
                            mem.nav = null;
                          });
  }

  if (mem.hunt) {
