        var dn = num(dc.n, 1);
        dc.x = (dc.x * dn + hx) / (dn + 1);
        dc.y = (dc.y * dn + hy) / (dn + 1);
        dc.n = dn + 1;
        dc.value = Math.max(dc.value, hv);
