    mem.gridVisited = [];
    mem.gridBlocked = [];
    var nx = Math.max(4, Math.min(12, Math.ceil(mem.sizeX / 48)));
    var ny = Math.max(4, Math.min(12, Math.ceil(mem.sizeY / 48)));
    for (var gy = 0; gy < ny; gy++) {
