    mem.siteRetryAfter = 0;
    mem.drillXY = null;
    mem.signalCenters = [];

    mem.tick = 0;
    mem.headingBias = 0;
    mem.yawScale = 1;
    mem.trueHeading = rawHeading;
    mem.compassStuck = false;
    mem.compassQuietYaw = 0;
    mem.prevRawHeading = undefined;
    mem.prevWheelL = wheelL;
    mem.prevWheelR = wheelR;
    mem.course = null;
    mem.headingCalibrated = false;

    mem.px = rawX;
    mem.py = rawY;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = 0;
    mem.gpsAnchorTravel = 0;
    mem.gpsStale = false;

    mem.prevBattery = battery;
    mem.maxBattery = Math.max(0.2, battery);
    mem.ePerM = 0.0016;
    mem.energyWindowTick = 0;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.shockWindowTick = 0;
    mem.shockWindowBattery = battery;
    mem.energyShockTick = -10000;

    mem.motorGainL = 3.2;
    mem.motorGainR = 3.2;
    mem.motorSamples = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastV = 0;
    mem.lastOmega = 0;

    mem.nav = null;
    mem.lastSteer = 0;
    mem.prevBump = false;
    mem.recoverTicks = 0;
    mem.recoverTotal = 18;
    mem.recoverSign = 1;

    mem.holdIL = 0;
    mem.holdIR = 0;

    mem.rayLast = [];
    mem.raySame = [];
    mem.rayStartX = [];
    mem.rayStartY = [];
    mem.rayStartHeading = [];
    mem.rayBad = [];

