  mem.tick = num(mem.tick, 0) + 1;
  var tick = mem.tick;

  /* Compass/gyro estimation from differential wheel motion. */
  var oldTrueHeading = num(mem.trueHeading, rawHeading);
  var predictedYaw = 0;
  if (mem.prevWheelL !== undefined && mem.prevWheelR !== undefined) {
    var avgL = 0.5 * (wheelL + num(mem.prevWheelL, wheelL));
    var avgR = 0.5 * (wheelR + num(mem.prevWheelR, wheelR));
    predictedYaw = ((avgR - avgL) / 0.6) * dt * DEG;
