    var scaledYaw = predictedYaw * num(mem.yawScale, 1);
    var residualYaw = wrap(rawYaw - scaledYaw);

    if (Math.abs(residualYaw) > 85 && Math.abs(predictedYaw) < 35) {
      mem.headingBias = wrap(oldTrueHeading + scaledYaw - rawHeading);
      mem.course = null;
      jumpThisTick = true;
    } else if (!mem.compassStuck &&
               Math.abs(predictedYaw) > 1.5 &&
               Math.abs(rawYaw) > 0.35 &&
               predictedYaw * rawYaw > 0) {
      var yawRatio = rawYaw / predictedYaw;
      if (yawRatio > 0.4 && yawRatio < 1.8) {
        mem.yawScale = clamp(0.96 * num(mem.yawScale, 1) +
                             0.04 * yawRatio, 0.4, 1.8);
      }
    }

    if (Math.abs(rawYaw) < 0.05 && Math.abs(predictedYaw) > 0.7) {
