  var anchorMove = dist(rawX, rawY,
                        num(mem.gpsAnchorX, rawX),
                        num(mem.gpsAnchorY, rawY));
  mem.gpsAnchorTravel = num(mem.gpsAnchorTravel, 0) + wheelTravel;

  if (anchorMove > 1.25) {
