    right = clamp(num(right, 0), -1, 1);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastV = Math.abs(num(v, 0));
    mem.lastOmega = num(omega, 0);
    return { left: left, right: right, drill: !!drill };
  }

  function wheelCommand(target, actual, gain) {
    gain = clamp(num(gain, 3.2), 0.65, 5.8);
    var cmd = target / gain + 0.16 * (target - actual);

