    var lt = clamp(v - 0.30 * omega, -1.15, 1.15);
    var rt = clamp(v + 0.30 * omega, -1.15, 1.15);
    mem.holdIL = num(mem.holdIL, 0) * 0.92;
    mem.holdIR = num(mem.holdIR, 0) * 0.92;
    return emit(wheelCommand(lt, wheelL, mem.motorGainL),
                wheelCommand(rt, wheelR, mem.motorGainR),
