  }

  function holdCommands() {
    var feed = clamp(0.42 * Math.sin(rad(pitch)), -0.36, 0.36);
    mem.holdIL = clamp(num(mem.holdIL, 0) -
                       0.15 * wheelL * dt, -0.35, 0.35);
    mem.holdIR = clamp(num(mem.holdIR, 0) -
                       0.15 * wheelR * dt, -0.35, 0.35);
    var l = clamp(feed + mem.holdIL - 0.76 * wheelL, -0.48, 0.48);
    var r = clamp(feed + mem.holdIR - 0.76 * wheelR, -0.48, 0.48);
    return [l, r];
  }

