    var h = holdCommands();
    return emit(h[0], h[1], drill, 0, 0);
  }

  function edgeDistance(relAngle) {
    var a = rad(trueHeading + relAngle);
    var dx = Math.cos(a), dy = Math.sin(a);
    var best = 1e9;

    if (dx > 0.001) best = Math.min(best,
      (mem.sizeX - 2 - mem.px) / dx);
    if (dx < -0.001) best = Math.min(best,
      (2 - mem.px) / dx);
    if (dy > 0.001) best = Math.min(best,
      (mem.sizeY - 2 - mem.py) / dy);
    if (dy < -0.001) best = Math.min(best,
      (2 - mem.py) / dy);

    return Math.max(0, best);
  }

  function rayAt(a) {
    var q = clamp((a + 80) / 20, 0, 8);
    var i = Math.floor(q);
    var f = q - i;
    if (i >= 8) return rays[8];
    return Math.min(rays[i], rays[i + 1],
                    rays[i] * (1 - f) + rays[i + 1] * f);
  }

  function sideSign() {
    var right = 0, left = 0;
    for (var i = 0; i < 4; i++) right += rays[i];
    for (var j = 5; j < 9; j++) left += rays[j];
    right *= 0.25;
    left *= 0.25;
    if (left > right + 0.25) return 1;
    if (right > left + 0.25) return -1;
    return num(mem.recoverSign, 1) >= 0 ? 1 : -1;
  }

  function recoveryOutput() {
    var total = num(mem.recoverTotal, 18);
    var elapsed = total - num(mem.recoverTicks, 0);
    mem.recoverTicks = Math.max(0, num(mem.recoverTicks, 0) - 1);

    if (elapsed < 7) {
      return drive(-0.25, 0);
    }
    var out = drive(0, num(mem.recoverSign, 1) * 0.85);
    if (mem.recoverTicks <= 0) mem.nav = null;
    return out;
  }

  function chooseSteering(goalErr, speed) {
    var g = clamp(wrap(goalErr), -80, 80);
    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80,
                      g,
                      clamp(g - 20, -80, 80),
                      clamp(g + 20, -80, 80),
                      clamp(g - 40, -80, 80),
                      clamp(g + 40, -80, 80)];

    var best = g;
    var bestCost = 1e30;

    for (var ci = 0; ci < candidates.length; ci++) {
      var c = candidates[ci];
      var duplicate = false;
      for (var cj = 0; cj < ci; cj++) {
        if (Math.abs(candidates[cj] - c) < 0.5) {
          duplicate = true;
          break;
        }
      }
      if (duplicate) continue;

      var diff = Math.abs(wrap(c - goalErr));
      var cost = 0.014 * diff * diff;
      cost += 0.0012 *
        Math.pow(Math.abs(wrap(c - num(mem.lastSteer, 0))), 2);

      for (var rj = 0; rj < 9; rj++) {
        var rd2 = rays[rj];
        if (rd2 >= 14.95) continue;
        var alpha = -80 + 20 * rj;
        var da = Math.abs(wrap(c - alpha));
        if (da > 48) continue;

        var safe = 2.8 + 0.55 * clamp(Math.abs(speed), 0, 1.3);
        var p = clamp((safe + 0.25 - rd2) / (safe + 0.25), 0, 1);
        var influence = Math.exp(-0.5 * Math.pow(da / 22, 2));
        cost += 36 * p * p * influence;
        if (rd2 < 1.25 && da < 20) cost += 75;
      }

      var edge = edgeDistance(c);
      var edgeSafe = 4.0 + 0.45 * clamp(Math.abs(speed), 0, 1.3);
      if (edge < edgeSafe) {
        var ep = (edgeSafe - edge) / edgeSafe;
        cost += 55 * ep * ep;
        if (edge < 1.2) cost += 100;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }

    mem.lastSteer = best;
    return best;
  }

  function monitorNavigation(gx, gy, key, stopRadius, onSkip) {
    if (!key || !Number.isFinite(gx) || !Number.isFinite(gy)) {
      return false;
    }

    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = {
        key: key,
        startTick: tick,
        startDist: dist(mem.px, mem.py, gx, gy),
        cmd: 0,
        travel: 0,
        failures: 0
      };
    }

    var nav = mem.nav;
    nav.cmd = num(nav.cmd, 0) +
              num(mem.lastV, 0) * dt;
    nav.travel = num(nav.travel, 0) + wheelTravel;

    if (tick - num(nav.startTick, tick) >= 220) {
      var currentD = dist(mem.px, mem.py, gx, gy);
      var improvement = num(nav.startDist, currentD) - currentD;
      var stalled = currentD > stopRadius + 2.5 &&
                    improvement < 1.1 &&
                    (num(nav.cmd, 0) > 1.8 ||
                     num(nav.travel, 0) > 1.8);

      if (stalled) {
        nav.failures = num(nav.failures, 0) + 1;
        mem.recoverTicks = 18;
        mem.recoverTotal = 18;
        mem.recoverSign = sideSign();

        if (nav.failures >= 3 && typeof onSkip === "function") {
          onSkip();
          mem.nav = null;
        } else if (mem.nav) {
          mem.nav.startTick = tick;
          mem.nav.startDist = currentD;
          mem.nav.cmd = 0;
          mem.nav.travel = 0;
        }
        return true;
      }

      if (improvement > 1.8) {
        nav.failures = Math.max(0, num(nav.failures, 0) - 1);
      }
      nav.startTick = tick;
      nav.startDist = currentD;
      nav.cmd = 0;
      nav.travel = 0;
    }

    return false;
  }

  function navigateVector(err, d, stopRadius, cruise,
                          key, gx, gy, onSkip) {
    if (!Number.isFinite(d) || d < 0) return holdOutput(false);
    err = wrap(err);

    if (d <= stopRadius + 0.05) return holdOutput(false);

    if (monitorNavigation(gx, gy, key, stopRadius, onSkip)) {
      return recoveryOutput();
    }

    var steer = chooseSteering(err, centerV);
    if (Math.abs(steer) > 55 || Math.abs(err) > 145) {
      var turnSign = Math.abs(steer) > 1 ? steer : err;
      return drive(0, turnSign >= 0 ? 0.85 : -0.85);
    }

    var v = Math.min(cruise,
                     Math.max(0.12, (d - stopRadius) * 0.45));
    v *= Math.max(0.18, Math.cos(rad(steer)));

    var clear = rayAt(steer);
    if (clear < 4.8) {
      var cap = clamp((clear - 1.1) * 0.23, 0, cruise);
      v = Math.min(v, cap);
    }
    if (clear < 1.1) v = 0;

    var edge = edgeDistance(steer);
    if (edge < 7) {
      v = Math.min(v, clamp((edge - 1.0) * 0.20, 0, cruise));
    }
    if (edge < 1.1) v = 0;

    if (Math.abs(steer) > 36) v = Math.min(v, 0.34);
    if (Math.abs(pitch) > 30) v = Math.min(v, 0.42);
    if (Math.abs(pitch) > 42) v = Math.min(v, 0.30);

    var omega = clamp(1.8 * rad(steer), -1.15, 1.15);
    return drive(v, omega);
  }

  function navigatePoint(x, y, stopRadius, cruise,
                         key, onSkip) {
    var dx = x - mem.px, dy = y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var err = d > 0.05 ?
      wrap(Math.atan2(dy, dx) * DEG - trueHeading) : 0;
    return navigateVector(err, d, stopRadius, cruise,
                          key, x, y, onSkip);
  }

  function energyNeed(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    var n = Math.max(0, load || 0);
    return 0.075 + Math.max(0, path) *
      num(mem.ePerM, 0.0016) * (1.72 + 0.20 * n) +
      0.025 * n;
  }

  function markGridNear(x, y, radius) {
    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (dist(x, y, mem.gridNodes[i].x, mem.gridNodes[i].y) <
          radius) {
        mem.gridVisited[i] = true;
      }
    }
  }

  function rememberSignal(x, y, value) {
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    var centers = Array.isArray(mem.signalCenters) ?
                  mem.signalCenters : [];
    var match = -1;

    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < 12) {
        match = i;
        break;
      }
    }

    if (match >= 0) {
      centers[match].value = Math.max(
        num(centers[match].value, 0), num(value, 0));
      centers[match].tick = tick;
    } else {
      centers.push({ x: x, y: y, value: num(value, 0), tick: tick });
      if (centers.length > 45) centers.shift();
    }
    mem.signalCenters = centers;
    markGridNear(x, y, 22);
  }

  function signalNear(x, y, value) {
    var centers = Array.isArray(mem.signalCenters) ?
                  mem.signalCenters : [];
    for (var i = 0; i < centers.length; i++) {
      var oldValue = num(centers[i].value, 0);
      if (dist(x, y, centers[i].x, centers[i].y) < 18 &&
          value <= oldValue +
                   Math.max(0.025, Math.abs(oldValue) * 0.12)) {
        return true;
      }
    }
    return false;
  }

  function beginGlobalHunt(x, y, value) {
    mem.hunt = {
      kind: "global",
      originX: x,
      originY: y,
      centerX: x,
      centerY: y,
      baseScience: value,
      bestScience: value,
      bestX: x,
      bestY: y,
      index: 0,
      count: 8,
      round: 0,
      maxRounds: 2,
      radius: 9.5,
      startAngle: ((tick * 17) % 360) * PI / 180
    };
    mem.work = null;
    mem.nav = null;
  }

  function beginCandidateHunt(c, idx) {
    if (!c) return;

    var startValue = Math.max(0, num(c.bestScience, 0), science);
    var bx = num(c.bestX, c.x);
    var by = num(c.bestY, c.y);
    if (science >= num(c.bestScience, -1)) {
      bx = mem.px;
      by = mem.py;
    }

    mem.hunt = {
      kind: "candidate",
      cidx: idx,
      originX: c.x,
      originY: c.y,
      centerX: c.x,
      centerY: c.y,
      baseScience: startValue,
      bestScience: startValue,
      bestX: bx,
      bestY: by,
      index: 0,
      count: 12,
      round: 0,
      maxRounds: 2,
      radius: 17.5,
      startAngle: ((tick * 17 + idx * 131) % 360) * PI / 180
    };
    mem.nav = null;
  }

  function huntPoint(h) {
    if (!h || h.index >= h.count) return null;
    var a = h.startAngle + h.index * 2 * PI / h.count;
    return {
      x: clamp(h.centerX + h.radius * Math.cos(a),
               2, mem.sizeX - 2),
      y: clamp(h.centerY + h.radius * Math.sin(a),
               2, mem.sizeY - 2)
    };
  }

  function finishHunt() {
    var h = mem.hunt;
    if (!h) return;

    var threshold = Math.max(0.008,
                             Math.abs(h.baseScience) * 0.05);
    if (h.round + 1 < h.maxRounds &&
        h.bestScience > h.baseScience + threshold) {
      h.round++;
      h.centerX = h.bestX;
      h.centerY = h.bestY;
      h.baseScience = h.bestScience;
      h.bestX = h.centerX;
      h.bestY = h.centerY;
      h.index = 0;
      h.count = 8;
      h.radius = h.kind === "candidate" ? 8 : 7;
      h.startAngle += 0.39;
      mem.nav = null;
      return;
    }

    rememberSignal(h.originX, h.originY, h.bestScience);
    rememberSignal(h.centerX, h.centerY, h.bestScience);

    if (h.kind === "candidate") {
      var c = mem.cands[h.cidx];
      if (c && c.status === 1) c.status = 3;
      markGridNear(h.originX, h.originY, 22);
      if (mem.work && mem.work.kind === "candidate" &&
          mem.work.idx === h.cidx) {
        mem.work = null;
      }
    } else {
      markGridNear(h.originX, h.originY, 22);
    }

    mem.hunt = null;
    mem.nav = null;
  }

  var siteObj = obs.site && typeof obs.site === "object" ?
                obs.site : null;
  var siteDistance0 = siteObj ?
    num(siteObj.distance, NaN) : NaN;
  var siteBearing0 = siteObj ?
    num(siteObj.bearing, NaN) : NaN;
  var liveSite = !!(siteObj &&
    Number.isFinite(siteDistance0) &&
    Number.isFinite(siteBearing0) &&
    siteDistance0 >= 0);

  function startCandidate(c, idx) {
    c.status = 1;
    c.bestScience = -1;
    c.bestX = c.x;
    c.bestY = c.y;
    if (dist(mem.px, mem.py, c.x, c.y) < 45) {
      c.bestScience = science;
      c.bestX = mem.px;
      c.bestY = mem.py;
    }
    mem.work = { kind: "candidate", idx: idx };
    mem.hunt = null;
    mem.nav = null;
  }

  function candidateInitialPath(c) {
    return dist(mem.px, mem.py, c.x, c.y) +
           135 + dist(c.x, c.y, mem.baseX, mem.baseY) + 12;
  }

  function pickCandidate() {
    if (carried > 0 || carried >= mem.capacity) return false;

    var available = docked ?
      num(mem.maxBattery, battery) : battery;
    var best = -1;
    var bestScore = -1;

    for (var i = 0; i < mem.cands.length; i++) {
      var c = mem.cands[i];
      if (c.status !== 0) continue;

      var route = candidateInitialPath(c);
      var need = energyNeed(route, 0);
      if (need + 0.035 > available) continue;
      if (route / 0.43 + 24 > timeLeft - 6) continue;

      var out = dist(mem.px, mem.py, c.x, c.y);
      var back = dist(c.x, c.y, mem.baseX, mem.baseY);
      var score = Math.max(0.05, c.value) /
                  (38 + out + 0.75 * back + 80);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return false;
    startCandidate(mem.cands[best], best);
    return true;
  }

  function chooseGridGoal() {
    if (carried > 0) return false;

    var available = docked ?
      num(mem.maxBattery, battery) : battery;
    var best = -1;
    var bestScore = 1e30;

    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (mem.gridVisited[i] || mem.gridBlocked[i]) continue;

      var node = mem.gridNodes[i];
      var out = dist(mem.px, mem.py, node.x, node.y);
      var back = dist(node.x, node.y, mem.baseX, mem.baseY);
      var route = out + 45 + back + 10;
      var need = energyNeed(route, 0);

      if (need + 0.03 > available) continue;
      if (route / 0.43 + 18 > timeLeft - 5) continue;

      var score = out + 0.42 * back;
      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return false;
    mem.work = {
      kind: "grid",
      idx: best,
      science0: science
    };
    mem.nav = null;
    return true;
  }

  function ensureWork() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0) return;
    if (mem.hunt) return;

    if (mem.work) {
      if (mem.work.kind === "candidate") {
        var wc = mem.cands[mem.work.idx];
        if (wc && wc.status === 1) return;
        mem.work = null;
      } else if (mem.work.kind === "grid") {
        var gi = mem.work.idx;
        if (gi >= 0 && gi < mem.gridNodes.length &&
            !mem.gridVisited[gi] && !mem.gridBlocked[gi]) {
          return;
        }
        mem.work = null;
      } else {
        mem.work = null;
      }
    }

    for (var ai = 0; ai < mem.cands.length; ai++) {
      if (mem.cands[ai].status === 1) {
        mem.work = { kind: "candidate", idx: ai };
        return;
      }
    }

    if (pickCandidate()) return;

    if (science > 0.012 &&
        !signalNear(mem.px, mem.py, science)) {
      beginGlobalHunt(mem.px, mem.py, science);
      return;
    }

    chooseGridGoal();
  }

  function huntRemainingDistance(h) {
    if (!h) return 0;
    var p = huntPoint(h);
    var remaining = Math.max(0, h.count - h.index);
    var d = p ? dist(mem.px, mem.py, p.x, p.y) : 0;
    var edge = 2 * h.radius * Math.sin(PI / h.count);
    d += Math.max(0, remaining - 1) * edge;

    if (h.round + 1 < h.maxRounds &&
        h.bestScience > h.baseScience + 0.004) {
      d += 58;
    }
    return d;
  }

  function currentPlanPath() {
    if (mem.siteLock && !mem.returning) {
      var sd = liveSite ? siteDistance0 :
        dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      return sd +
        dist(mem.siteLock.x, mem.siteLock.y,
             mem.baseX, mem.baseY) + 14;
    }

    if (mem.hunt) {
      return huntRemainingDistance(mem.hunt) +
        dist(mem.hunt.centerX, mem.hunt.centerY,
             mem.baseX, mem.baseY) + 12;
    }

    if (mem.work && mem.work.kind === "candidate") {
      var c = mem.cands[mem.work.idx];
      if (!c) return Infinity;
      return candidateInitialPath(c);
    }

    if (mem.work && mem.work.kind === "grid") {
      var n = mem.gridNodes[mem.work.idx];
      if (!n) return Infinity;
      return dist(mem.px, mem.py, n.x, n.y) +
             45 + dist(n.x, n.y, mem.baseX, mem.baseY) + 10;
    }

    return Infinity;
  }

  function abandonPlan() {
    if (mem.siteLock) {
      mem.siteLock = null;
      mem.siteRetryAfter = tick + 90;
      mem.nav = null;
      return;
    }

    if (mem.hunt) {
      var oldHunt = mem.hunt;
      rememberSignal(oldHunt.originX, oldHunt.originY,
                     oldHunt.bestScience);
      if (oldHunt.kind === "candidate" &&
          mem.cands[oldHunt.cidx]) {
        mem.cands[oldHunt.cidx].status = 3;
      }
      mem.hunt = null;
    }

    if (mem.work && mem.work.kind === "candidate") {
      var ci = mem.work.idx;
      if (mem.cands[ci]) mem.cands[ci].status = 3;
    } else if (mem.work && mem.work.kind === "grid") {
      var gi = mem.work.idx;
      if (gi >= 0 && gi < mem.gridNodes.length) {
        mem.gridBlocked[gi] = true;
        mem.gridVisited[gi] = true;
      }
    }

    mem.work = null;
    mem.nav = null;
  }

  function failWork() {
    if (mem.hunt) {
      var h = mem.hunt;
      if (h.kind === "candidate" && mem.cands[h.cidx]) {
        mem.cands[h.cidx].status = 3;
      }
      rememberSignal(h.originX, h.originY, h.bestScience);
      mem.hunt = null;
    }

    if (mem.work && mem.work.kind === "candidate") {
      var ci = mem.work.idx;
      if (mem.cands[ci]) {
        mem.cands[ci].status = 3;
        markGridNear(mem.cands[ci].x, mem.cands[ci].y, 20);
      }
    } else if (mem.work && mem.work.kind === "grid") {
      var gi = mem.work.idx;
      if (gi >= 0 && gi < mem.gridNodes.length) {
        mem.gridBlocked[gi] = true;
        mem.gridVisited[gi] = true;
      }
    }
    mem.work = null;
    mem.nav = null;
  }

  function updateWorkProgress() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0) return;

    if (mem.hunt) {
      var h = mem.hunt;
      if (science > num(h.bestScience, -1) + 0.003) {
        h.bestScience = science;
        h.bestX = mem.px;
        h.bestY = mem.py;
      }

      var hp = huntPoint(h);
      if (!hp) {
        finishHunt();
        return;
      }
      if (dist(mem.px, mem.py, hp.x, hp.y) < 1.85) {
        h.index++;
        if (h.index >= h.count) finishHunt();
      }
      return;
    }

    if (!mem.work) return;

    if (mem.work.kind === "candidate") {
      var idx = mem.work.idx;
      var c = mem.cands[idx];
      if (!c || c.status !== 1) {
        mem.work = null;
        return;
      }

      var cd = dist(mem.px, mem.py, c.x, c.y);
      if (cd < 48 && science > num(c.bestScience, -1) + 0.003) {
        c.bestScience = science;
        c.bestX = mem.px;
        c.bestY = mem.py;
      }

      if (cd < 4.2) beginCandidateHunt(c, idx);
      return;
    }

    if (mem.work.kind === "grid") {
      var gi = mem.work.idx;
      var node = mem.gridNodes[gi];
      if (!node) {
        mem.work = null;
        return;
      }

      var threshold = Math.max(0.02,
                              Math.abs(num(mem.work.science0, 0)) *
                              0.18);
      if (science > num(mem.work.science0, 0) + threshold &&
          science > 0.012 &&
          !signalNear(mem.px, mem.py, science)) {
        mem.gridVisited[gi] = true;
        mem.work = null;
        beginGlobalHunt(mem.px, mem.py, science);
        return;
      }

      if (dist(mem.px, mem.py, node.x, node.y) < 2.5) {
        mem.gridVisited[gi] = true;
        mem.work = null;
        if (science > 0.012 &&
            !signalNear(mem.px, mem.py, science)) {
          beginGlobalHunt(mem.px, mem.py, science);
        }
      }
    }
  }

  var oldCarried = num(mem.lastCarried, carried);
  var sampleDone = carried > oldCarried;

  if (sampleDone) {
    var sampleX = mem.px, sampleY = mem.py;

    for (var mi = 0; mi < mem.cands.length; mi++) {
      if (dist(sampleX, sampleY,
               mem.cands[mi].x, mem.cands[mi].y) < 30) {
        mem.cands[mi].status = 2;
      }
    }

    if (mem.work && mem.work.kind === "candidate") {
      var sampledIdx = mem.work.idx;
      var sampledCand = mem.cands[sampledIdx];
      if (sampledCand) {
        sampledCand.status =
          dist(sampleX, sampleY,
               sampledCand.x, sampledCand.y) < 35 ? 2 : 3;
      }
    }
    if (mem.hunt && mem.hunt.kind === "candidate" &&
        mem.cands[mem.hunt.cidx]) {
      var hcand = mem.cands[mem.hunt.cidx];
      hcand.status =
        dist(sampleX, sampleY, hcand.x, hcand.y) < 35 ? 2 : 3;
    }

    markGridNear(sampleX, sampleY, 24);
    mem.work = null;
    mem.hunt = null;
    mem.siteLock = null;
    mem.drillXY = null;
    mem.nav = null;
    mem.returning = true;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered);

  if (docked && carried === 0) {
    mem.returning = false;
    mem.recoverTicks = 0;
  }
  if (carried > 0) mem.returning = true;

  /* Maintain a global fallback estimate for a directly sensed site. */
  if (liveSite && carried === 0 && !mem.returning &&
      drillProgress <= 0 && tick >= num(mem.siteRetryAfter, 0)) {
    var sa = rad(trueHeading + siteBearing0);
    var sxSite = mem.px + siteDistance0 * Math.cos(sa);
    var sySite = mem.py + siteDistance0 * Math.sin(sa);

    if (mem.siteLock &&
        dist(sxSite, sySite, mem.siteLock.x, mem.siteLock.y) < 11) {
      mem.siteLock.x = 0.58 * mem.siteLock.x + 0.42 * sxSite;
      mem.siteLock.y = 0.58 * mem.siteLock.y + 0.42 * sySite;
      mem.siteLock.value = num(siteObj.value, mem.siteLock.value);
      mem.siteLock.lastSeen = tick;
    } else {
      mem.siteLock = {
        x: sxSite,
        y: sySite,
        value: num(siteObj.value, 1),
        lastSeen: tick
      };
    }

    var siteValue = num(siteObj.value, NaN);
    if (Number.isFinite(siteValue)) {
      for (var vi = 0; vi < mem.cands.length; vi++) {
        if (dist(sxSite, sySite, mem.cands[vi].x,
                 mem.cands[vi].y) < 30) {
          mem.cands[vi].value =
            Math.max(mem.cands[vi].value, siteValue);
        }
      }
    }
  }

  if (mem.siteLock && drillProgress <= 0 &&
      tick - num(mem.siteLock.lastSeen, tick) > 110) {
    mem.siteLock = null;
    mem.nav = null;
  }

  if (carried === 0 && drillProgress > 0) {
    return holdOutput(true);
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.prevBump && !docked && drillProgress <= 0) {
    mem.recoverTicks = 18;
    mem.recoverTotal = 18;
    mem.recoverSign = sideSign();
  }
  mem.prevBump = bumped;

  if (docked) {
    mem.recoverTicks = 0;
  } else if (mem.recoverTicks > 0 && drillProgress <= 0) {
    return recoveryOutput();
  }

  updateWorkProgress();
  ensureWork();

  var beacon = obs.beacon && typeof obs.beacon === "object" ?
               obs.beacon : null;
  var beaconDistance = beacon ?
    num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ?
    num(beacon.bearing, NaN) : NaN;
  var beaconValid = Number.isFinite(beaconDistance) &&
                    Number.isFinite(beaconBearing) &&
                    beaconDistance >= 0 && beaconDistance <= 22;

  var homeD = beaconValid ? beaconDistance :
    dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homePath = homeD * 1.25 + 8;
  var homeNeed = energyNeed(homePath, carried);

  if (docked && carried > 0) {
    return emit(0, 0, false, 0, 0);
  }

  /* Charge at the base if this sortie is feasible but not yet charged. */
  if (docked && carried === 0) {
    mem.returning = false;
    var tries = 0;

    while (tries < 8) {
      var dockPath = currentPlanPath();
      if (!Number.isFinite(dockPath)) break;

      var dockNeed = energyNeed(dockPath, 0);
      var dockTime = dockPath / 0.42 + 16;
      var capacityBad =
        dockNeed + 0.025 > num(mem.maxBattery, battery);
      var timeBad = dockTime > timeLeft - 5;

      if (!capacityBad && !timeBad) break;
      abandonPlan();
      ensureWork();
      tries++;
    }

    var finalPath = currentPlanPath();
    if (!Number.isFinite(finalPath)) {
      return holdOutput(false);
    }

    var finalNeed = energyNeed(finalPath, 0);
    var finalTime = finalPath / 0.42 + 16;
    if (finalNeed + 0.025 > num(mem.maxBattery, battery) ||
        finalTime > timeLeft - 5) {
      return holdOutput(false);
    }
    if (battery + 0.01 < finalNeed + 0.015) {
      return emit(0, 0, false, 0, 0);
    }
  } else if (!docked) {
    var mustReturn = !!mem.returning;

    if (carried > 0) mustReturn = true;
    if (battery < 0.018) mustReturn = true;

    if (homeD > 3) {
      if (battery < homeNeed + 0.065) mustReturn = true;
      if (timeLeft < homeD / 0.38 + 12) mustReturn = true;

      var pathNow = currentPlanPath();
      if (Number.isFinite(pathNow)) {
        var needNow = energyNeed(pathNow, carried);
        if (battery < needNow + 0.04) mustReturn = true;
        if (timeLeft < pathNow / 0.42 + 12) mustReturn = true;
      } else {
        mustReturn = true;
      }
    }

    mem.returning = mustReturn;
  }

  function skipSite() {
    mem.siteLock = null;
    mem.siteRetryAfter = tick + 100;
    mem.nav = null;
    mem.returning = true;
  }

  if (mem.returning) {
    if (beaconValid) {
      return navigateVector(beaconBearing, beaconDistance,
                            2.15, 0.58, "HOME",
                            mem.baseX, mem.baseY, null);
    }
    return navigatePoint(mem.baseX, mem.baseY,
                         2.15, 0.58, "HOME", null);
  }

  if (mem.siteLock && carried === 0) {
    var siteD, siteErr;
    if (liveSite) {
      siteD = siteDistance0;
      siteErr = wrap(siteBearing0);
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteD = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteD > 0.05 ?
        wrap(Math.atan2(sdy, sdx) * DEG - trueHeading) : 0;
    }

    if (siteD <= 1.38) {
      var hc = holdCommands();
      var still = Math.max(Math.abs(wheelL),
                           Math.abs(wheelR)) < 0.15;
      var fresh = liveSite ||
        tick - num(mem.siteLock.lastSeen, tick) < 32;
      var drillNow = siteD <= 1.42 && fresh && still;

      if (drillNow && !mem.drillXY) {
        mem.drillXY = { x: mem.px, y: mem.py };
      }
      return emit(hc[0], hc[1], drillNow, 0, 0);
    }

    if (liveSite) {
      return navigateVector(siteErr, siteD, 1.08, 0.40,
                            "SITE", mem.siteLock.x, mem.siteLock.y,
                            skipSite);
    }

    return navigatePoint(mem.siteLock.x, mem.siteLock.y,
                         1.08, 0.40, "SITE", skipSite);
  }

  if (mem.hunt) {
    var hpNow = huntPoint(mem.hunt);
    if (hpNow) {
      var hNow = mem.hunt;
      var hKey = "H" + hNow.kind + "_" +
                 num(hNow.cidx, -1) + "_" +
                 hNow.round + "_" + hNow.index;
      return navigatePoint(hpNow.x, hpNow.y, 1.25, 0.50,
                           hKey, failWork);
    }
  }

  if (mem.work && mem.work.kind === "candidate") {
    var cnow = mem.cands[mem.work.idx];
    if (cnow && cnow.status === 1) {
      var cidxNow = mem.work.idx;
      return navigatePoint(cnow.x, cnow.y, 3.0, 0.56,
                           "C" + cidxNow, failWork);
    }
  }

  if (mem.work && mem.work.kind === "grid") {
    var gidx = mem.work.idx;
    var gnow = mem.gridNodes[gidx];
    if (gnow) {
      return navigatePoint(gnow.x, gnow.y, 2.2, 0.54,
                           "G" + gidx, failWork);
    }
  }

  if (!docked && homeD > 3) {
    mem.returning = true;
    if (beaconValid) {
      return navigateVector(beaconBearing, beaconDistance,
                            2.15, 0.58, "HOME",
                            mem.baseX, mem.baseY, null);
    }
    return navigatePoint(mem.baseX, mem.baseY,
                         2.15, 0.58, "HOME", null);
  }

  return holdOutput(false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  var PI = Math.PI;
  var DEG = 180 / PI;
  var DT = 0.1;

  function num(v, d) {
    if (v === undefined || v === null) return d;
    var n = Number(v);
    return Number.isFinite(n) ? n : d;
  }
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }
  function wrap(a) {
    return ((a + 180) % 360 + 360) % 360 - 180;
  }
  function rad(d) {
    return d * PI / 180;
  }
  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1, dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var rawX = num(obs.x, 200);
  var rawY = num(obs.y, 200);
  var rawHeading = wrap(num(obs.heading, 0));
  var wheelL = clamp(num(obs.wheelLeft, 0), -3, 3);
  var wheelR = clamp(num(obs.wheelRight, 0), -3, 3);
  var centerV = 0.5 * (wheelL + wheelR);
  var wheelTravel = Math.abs(centerV) * DT;
  var pitch = num(obs.pitch, 0);
  var battery = Math.max(0, num(obs.battery, 1));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var timeLeft = Math.max(0, num(obs.timeLeft, 1200));
  var science = Math.max(0, num(obs.science, 0));
  var drillProgress = Math.max(0, num(obs.drilling, 0));
  var docked = !!obs.docked;

  if (!mem.initialized) {
    var mission = obs.mission || {};
    var size = mission.size;
    var sx = 400, sy = 400;

    if (Array.isArray(size)) {
      sx = num(size[0], 400);
      sy = num(size[1], 400);
    } else if (typeof size === "number") {
      sx = size;
      sy = size;
    } else if (size && typeof size === "object") {
      sx = num(size.width, num(size.w, num(size.x, 400)));
      sy = num(size.height, num(size.h, num(size.y, 400)));
    }

    var base = mission.base || {};
    mem.sizeX = Math.max(30, sx);
    mem.sizeY = Math.max(30, sy);
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));

    mem.cands = [];
    var hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi] || {};
      var hx = num(h.x, NaN);
      var hy = num(h.y, NaN);
      if (!Number.isFinite(hx) || !Number.isFinite(hy)) continue;

      var hv = Math.max(0.05, num(h.estimate, num(h.value, 1)));
      var duplicate = -1;
      for (var hj = 0; hj < mem.cands.length; hj++) {
        if (dist(hx, hy, mem.cands[hj].x, mem.cands[hj].y) < 10) {
          duplicate = hj;
          break;
        }
      }

      if (duplicate >= 0) {
        var dc = mem.cands[duplicate];
        dc.x = 0.5 * (dc.x + hx);
        dc.y = 0.5 * (dc.y + hy);
        dc.value = Math.max(dc.value, hv);
      } else {
        mem.cands.push({
          x: clamp(hx, 3, mem.sizeX - 3),
          y: clamp(hy, 3, mem.sizeY - 3),
          value: hv,
          status: 0
        });
      }
    }

    mem.gridNodes = [];
    mem.gridVisited = [];
    mem.gridBlocked = [];
    var nx = Math.max(4, Math.min(10, Math.ceil(mem.sizeX / 50)));
    var ny = Math.max(4, Math.min(10, Math.ceil(mem.sizeY / 50)));
    for (var gy = 0; gy < ny; gy++) {
      for (var gx = 0; gx < nx; gx++) {
        mem.gridNodes.push({
          x: (gx + 0.5) * mem.sizeX / nx,
          y: (gy + 0.5) * mem.sizeY / ny
        });
        mem.gridVisited.push(false);
        mem.gridBlocked.push(false);
      }
    }

    mem.work = null;
    mem.scan = null;
    mem.siteLock = null;
    mem.returning = false;
    mem.signalCenters = [];

    mem.tick = 0;
    mem.trueHeading = rawHeading;
    mem.headingBias = 0;
    mem.yawScale = 1;
    mem.compassStuck = false;
    mem.compassQuietYaw = 0;
    mem.prevRawHeading = rawHeading;
    mem.prevWheelL = wheelL;
    mem.prevWheelR = wheelR;
    mem.course = null;
    mem.headingCalibrated = false;

    mem.px = rawX;
    mem.py = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = 0;
    mem.gpsAnchorTravel = 0;
    mem.gpsStale = false;

    mem.prevBattery = battery;
    mem.maxBattery = Math.max(0.2, battery);
    mem.ePerM = 0.0011;
    mem.energyWindowTick = 0;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.energyShockTick = -10000;

    mem.motorGainL = 2.8;
    mem.motorGainR = 2.8;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastDrive = false;
    mem.lastV = 0;
    mem.lastOmega = 0;
    mem.lastAim = 0;
    mem.lastAimHeading = rawHeading;

    mem.nav = null;
    mem.prevBump = false;
    mem.recoverTicks = 0;
    mem.recoverTotal = 16;
    mem.recoverSign = 1;

    mem.holdIL = 0;
    mem.holdIR = 0;

    mem.rayLast = [];
    mem.raySame = [];
    mem.rayStartX = [];
    mem.rayStartY = [];
    mem.rayStartHeading = [];
    mem.rayBad = [];

    mem.lastCarried = carried;
    mem.lastDelivered = num(obs.delivered, 0);
    mem.initialized = true;
  }

  mem.tick = num(mem.tick, 0) + 1;
  var tick = mem.tick;

  /* Blend wheel odometry with GPS and reject a GPS position that freezes. */
  var oldTrueHeading = num(mem.trueHeading, rawHeading);
  var predictedYaw = 0;
  if (mem.prevWheelL !== undefined && mem.prevWheelR !== undefined) {
    var avgL = 0.5 * (wheelL + num(mem.prevWheelL, wheelL));
    var avgR = 0.5 * (wheelR + num(mem.prevWheelR, wheelR));
    predictedYaw = ((avgR - avgL) / 0.6) * DT * DEG;
  }

  var rawYaw = wrap(rawHeading - num(mem.prevRawHeading, rawHeading));
  var scaledYaw = predictedYaw * num(mem.yawScale, 1);
  var jumpThisTick = false;

  if (Math.abs(wrap(rawYaw - scaledYaw)) > 105 &&
      Math.abs(predictedYaw) < 25) {
    mem.headingBias = wrap(oldTrueHeading + scaledYaw - rawHeading);
    jumpThisTick = true;
    mem.course = null;
  } else if (!mem.compassStuck &&
             Math.abs(predictedYaw) > 1 &&
             Math.abs(rawYaw) > 0.25 &&
             predictedYaw * rawYaw > 0) {
    var yr = rawYaw / predictedYaw;
    if (yr > 0.4 && yr < 1.8) {
      mem.yawScale = clamp(0.985 * num(mem.yawScale, 1) + 0.015 * yr,
                           0.45, 1.8);
    }
  }

  if (Math.abs(rawYaw) < 0.04 && Math.abs(predictedYaw) > 0.8) {
    mem.compassQuietYaw = num(mem.compassQuietYaw, 0) +
                          Math.abs(predictedYaw * num(mem.yawScale, 1));
    if (mem.compassQuietYaw > 55) mem.compassStuck = true;
  } else if (Math.abs(rawYaw) > 0.35) {
    mem.compassQuietYaw = 0;
    if (mem.compassStuck) {
      mem.headingBias = wrap(oldTrueHeading +
                             scaledYaw -
                             rawHeading);
      mem.compassStuck = false;
    }
