  mem.trueHeading = trueHeading;
  mem.prevRawHeading = rawHeading;
  mem.prevWheelL = wheelL;
  mem.prevWheelR = wheelR;

  /* Adapt the drive-energy estimate and detect battery shocks. */
  var prevBattery = num(mem.prevBattery, battery);
  var batteryDrop = prevBattery - battery;
  if (batteryDrop > 0.16) {
    mem.energyShockTick = tick;
    mem.maxBattery = Math.min(num(mem.maxBattery, battery), battery + 0.05);
    mem.ePerM = Math.max(num(mem.ePerM, 0.0011), 0.0022);
  }

  if (battery > num(mem.maxBattery, battery)) mem.maxBattery = battery;

  if (docked) {
    mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);
    mem.energyWindowTick = tick;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
  } else {
    mem.energyWindowDistance =
      num(mem.energyWindowDistance, 0) + wheelTravel;

    if (tick - num(mem.energyWindowTick, tick) >= 90) {
      var netLoss = num(mem.energyWindowBattery, battery) - battery;
      var moved = num(mem.energyWindowDistance, 0);
      if (moved > 2.5 && netLoss > 0.004) {
        var measuredE = clamp(netLoss / moved, 0.0003, 0.025);
        var alphaE = measuredE > num(mem.ePerM, 0.0011) ? 0.24 : 0.06;
