    rd = clamp(rd, 0, 15);

    if (mem.rayLast[ri] === undefined) {
      mem.rayLast[ri] = rd;
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayStartHeading[ri] = trueHeading;
      mem.rayBad[ri] = false;
    } else if (Math.abs(rd - mem.rayLast[ri]) < 0.015) {
      mem.raySame[ri] = num(mem.raySame[ri], 0) + 1;
      if (mem.raySame[ri] > 280 && rd < 14.8 &&
          dist(mem.px, mem.py, mem.rayStartX[ri],
               mem.rayStartY[ri]) > 6 &&
          Math.abs(wrap(trueHeading -
                        num(mem.rayStartHeading[ri], trueHeading))) > 22) {
        mem.rayBad[ri] = true;
      }
    } else {
      if (mem.rayBad[ri] && Math.abs(rd - mem.rayLast[ri]) > 0.7) {
        mem.rayBad[ri] = false;
      }
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayStartHeading[ri] = trueHeading;
    }

    mem.rayLast[ri] = rd;
    rays[ri] = mem.rayBad[ri] ? 15 : rd;
