  var siteObj = obs.site && typeof obs.site === "object" ? obs.site : null;
  var siteDistance = siteObj ? num(siteObj.distance, NaN) : NaN;
  var siteBearing = siteObj ? num(siteObj.bearing, NaN) : NaN;
  var liveSite = !!(siteObj &&
    Number.isFinite(siteDistance) &&
    Number.isFinite(siteBearing) &&
    siteDistance >= 0);

  function emit(left, right, drill, v, omega, isDrive) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastDrive = !!isDrive;
    mem.lastV = Math.abs(num(v, 0));
    mem.lastOmega = num(omega, 0);
    return { left: left, right: right, drill: !!drill };
  }

  function wheelCommand(target, actual, gain) {
    gain = clamp(num(gain, 2.8), 0.55, 7);
    var cmd = target / gain + 0.20 * (target - actual);
    if (Math.abs(target) > 0.07 &&
        Math.abs(cmd) < 0.085 &&
        cmd * target >= 0) {
      cmd = target < 0 ? -0.085 : 0.085;
    }
    return clamp(cmd, -0.85, 0.85);
  }

  function drive(v, omega) {
    var leftTarget = clamp(v - 0.30 * omega, -1.25, 1.25);
    var rightTarget = clamp(v + 0.30 * omega, -1.25, 1.25);
    mem.holdIL = num(mem.holdIL, 0) * 0.92;
    mem.holdIR = num(mem.holdIR, 0) * 0.92;
    return emit(
      wheelCommand(leftTarget, wheelL, mem.motorGainL),
      wheelCommand(rightTarget, wheelR, mem.motorGainR),
      false, v, omega, true
    );
  }

  function holdCommands() {
    var feed = clamp(0.34 * Math.sin(rad(pitch)), -0.30, 0.30);
    mem.holdIL = clamp(num(mem.holdIL, 0) - 0.08 * wheelL * DT,
                       -0.28, 0.28);
    mem.holdIR = clamp(num(mem.holdIR, 0) - 0.08 * wheelR * DT,
                       -0.28, 0.28);
    return [
      clamp(feed + mem.holdIL - 0.72 * wheelL, -0.48, 0.48),
      clamp(feed + mem.holdIR - 0.72 * wheelR, -0.48, 0.48)
    ];
  }

  function holdOutput(drill) {
    var h = holdCommands();
    return emit(h[0], h[1], drill, 0, 0, false);
  }

  function rayAt(angle) {
    var a = clamp(angle, -80, 80);
    var q = (a + 80) / 20;
    var i = Math.floor(q);
    var f = q - i;
    if (i >= 8) return rays[8];
    return Math.min(rays[i], rays[i + 1],
                    rays[i] * (1 - f) + rays[i + 1] * f);
  }

  function edgeDistance(relativeAngle) {
    var a = rad(trueHeading + relativeAngle);
    var dx = Math.cos(a), dy = Math.sin(a);
    var best = 1e9;
    if (dx > 0.001) best = Math.min(best, (mem.sizeX - 3 - mem.px) / dx);
    if (dx < -0.001) best = Math.min(best, (3 - mem.px) / dx);
    if (dy > 0.001) best = Math.min(best, (mem.sizeY - 3 - mem.py) / dy);
    if (dy < -0.001) best = Math.min(best, (3 - mem.py) / dy);
    return Math.max(0, best);
  }

  function chooseAim(goalErr, speed) {
    var g = clamp(wrap(goalErr), -80, 80);
    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80,
                      g, clamp(g - 15, -80, 80),
                      clamp(g + 15, -80, 80),
                      clamp(g - 35, -80, 80),
                      clamp(g + 35, -80, 80)];

    var prevRel = wrap(num(mem.lastAim, 0) -
                       wrap(trueHeading - num(mem.lastAimHeading, trueHeading)));
    var best = g;
    var bestCost = 1e30;

    for (var ci = 0; ci < candidates.length; ci++) {
      var c = candidates[ci];
      var duplicate = false;
      for (var cj = 0; cj < ci; cj++) {
        if (Math.abs(candidates[cj] - c) < 0.5) {
          duplicate = true;
          break;
        }
      }
      if (duplicate) continue;

      var diff = Math.abs(wrap(c - goalErr));
      var cost = 0.006 * diff * diff;
      cost += 0.0015 * Math.pow(Math.abs(wrap(c - prevRel)), 2);

      for (var rj = 0; rj < 9; rj++) {
        var d = rays[rj];
        if (d >= 14.95) continue;
        var alpha = -80 + 20 * rj;
        var da = Math.abs(wrap(c - alpha));
        if (da > 62) continue;

        var safe = 2.8 + 0.40 * clamp(Math.abs(speed), 0, 0.9);
        var p = clamp((safe - d) / safe, 0, 1);
        var influence = Math.exp(-0.5 * Math.pow(da / 23, 2));
        cost += 32 * p * p * influence;
        if (d < 1.15 && da < 18) cost += 30;
      }

      var edge = edgeDistance(c);
      var edgeSafe = 5.2;
      if (edge < edgeSafe) {
        var ep = (edgeSafe - edge) / edgeSafe;
        cost += 32 * ep * ep;
        if (edge < 1.8) cost += 65;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }

    mem.lastAim = best;
    mem.lastAimHeading = trueHeading;
    return best;
  }

  function sideSign() {
    var right = 0, left = 0;
    for (var i = 0; i < 4; i++) right += rays[i];
    for (var j = 5; j < 9; j++) left += rays[j];
    right *= 0.25;
    left *= 0.25;
    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    return num(mem.recoverSign, 1) >= 0 ? 1 : -1;
  }

  function setRecovery() {
    mem.recoverTotal = 16;
    mem.recoverTicks = 16;
    mem.recoverSign = sideSign();
  }

  function recoveryOutput() {
    var total = num(mem.recoverTotal, 16);
    var elapsed = total - num(mem.recoverTicks, 0);
    mem.recoverTicks = Math.max(0, num(mem.recoverTicks, 0) - 1);

    if (elapsed < 6) return drive(-0.24, 0);
    var out = drive(0, num(mem.recoverSign, 1) * 0.82);
    if (mem.recoverTicks <= 0) mem.nav = null;
    return out;
  }

  function monitorNavigation(gx, gy, key, stopRadius, onSkip) {
    if (!key || !Number.isFinite(gx) || !Number.isFinite(gy)) return false;

    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = {
        key: key,
        startTick: tick,
        startDist: dist(mem.px, mem.py, gx, gy),
        commanded: 0,
        travel: 0,
        failures: 0
      };
    }

    var nav = mem.nav;
    nav.commanded = num(nav.commanded, 0) +
                    num(mem.lastV, 0) * DT;
    nav.travel = num(nav.travel, 0) + wheelTravel;

    if (tick - num(nav.startTick, tick) >= 120) {
      var currentD = dist(mem.px, mem.py, gx, gy);
      var improvement = num(nav.startDist, currentD) - currentD;
      var stalled = currentD > stopRadius + 2 &&
                    improvement < 0.9 &&
                    (num(nav.commanded, 0) > 1.5 ||
                     num(nav.travel, 0) > 1.5);

      if (stalled) {
        nav.failures = num(nav.failures, 0) + 1;
        setRecovery();

        if (nav.failures >= 3 && typeof onSkip === "function") {
          onSkip();
          mem.nav = null;
        } else {
          nav.startTick = tick;
          nav.startDist = currentD;
          nav.commanded = 0;
          nav.travel = 0;
        }
        return true;
      }

      if (improvement > 1.7) {
        nav.failures = Math.max(0, num(nav.failures, 0) - 1);
      }
      nav.startTick = tick;
      nav.startDist = currentD;
      nav.commanded = 0;
      nav.travel = 0;
    }

    return false;
  }

  function navigateRelative(err, d, stopRadius, cruise,
                             key, gx, gy, onSkip) {
    if (!Number.isFinite(d) || d < 0) return holdOutput(false);
    err = wrap(err);

    if (d <= stopRadius) return holdOutput(false);

    if (monitorNavigation(gx, gy, key, stopRadius, onSkip)) {
      return recoveryOutput();
    }

    if (Math.abs(err) > 125) {
      return drive(0, err > 0 ? 0.88 : -0.88);
    }

    var aim = chooseAim(err, centerV);
    var e = wrap(aim);
    var ae = Math.abs(e);
    var omega = clamp(1.55 * rad(e), -0.95, 0.95);
    if (ae < 1.2) omega = 0;

    var v = Math.min(cruise, Math.max(0.055, (d - stopRadius) * 0.32));
    if (ae > 72) {
      v = 0;
    } else {
      v *= Math.max(0.12, Math.cos(rad(e)));
      if (ae > 42) v *= 0.58;
    }

    var clear = rayAt(e);
    if (clear < 3.5) {
      v *= clamp((clear - 0.85) / 2.65, 0, 1);
    }
    if (clear < 1.05) v = 0;

    var directClear = rayAt(clamp(err, -80, 80));
    if (directClear < 2.0 &&
        Math.abs(wrap(aim - err)) > 16) {
      v = Math.min(v, 0.14);
    }

    var edge = edgeDistance(e);
    if (edge < 5.5) {
      v = Math.min(v, clamp((edge - 1.0) * 0.17, 0, cruise));
    }
    if (edge < 1.2) v = 0;

    if (Math.abs(pitch) > 32) v = Math.min(v, 0.42);
    if (Math.abs(pitch) > 43) v = Math.min(v, 0.30);

    return drive(v, omega);
  }

  function navigatePoint(x, y, stopRadius, cruise, key, onSkip) {
    var dx = x - mem.px;
    var dy = y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var err = d > 0.04
      ? wrap(Math.atan2(dy, dx) * DEG - trueHeading)
      : 0;
    return navigateRelative(err, d, stopRadius, cruise,
                            key, x, y, onSkip);
  }

  function energyNeed(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    var n = Math.max(0, load || 0);
    return 0.10 + Math.max(0, path) *
      num(mem.ePerM, 0.0011) * (1.75 + 0.18 * n) +
      0.025 * n;
  }

  function markGridNear(x, y, radius) {
    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (dist(x, y, mem.gridNodes[i].x, mem.gridNodes[i].y) < radius) {
        mem.gridVisited[i] = true;
      }
    }
  }

  function signalNear(x, y, value) {
    var centers = Array.isArray(mem.signalCenters) ? mem.signalCenters : [];
    for (var i = 0; i < centers.length; i++) {
      var old = num(centers[i].value, 0);
      if (dist(x, y, centers[i].x, centers[i].y) < 20 &&
          value <= old + Math.max(0.04, Math.abs(old) * 0.22)) {
        return true;
      }
    }
    return false;
  }

  function rememberSignal(x, y, value) {
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    var centers = Array.isArray(mem.signalCenters) ? mem.signalCenters : [];
    var match = -1;
    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < 14) {
        match = i;
        break;
      }
    }
    if (match >= 0) {
      centers[match].value = Math.max(num(centers[match].value, 0),
                                      num(value, 0));
      centers[match].tick = tick;
    } else {
      centers.push({ x: x, y: y, value: num(value, 0), tick: tick });
      if (centers.length > 50) centers.shift();
    }
    mem.signalCenters = centers;
    markGridNear(x, y, 18);
  }

  function scanParams(phase) {
    if (phase === 0) return { radius: 7.5, count: 8 };
    if (phase === 1) return { radius: 16, count: 12 };
    return { radius: 6, count: 8 };
  }

  function scanPointAt(s, phase, index) {
    var p = scanParams(phase);
    var cx = phase === 2 ? num(s.refineX, s.bestX) : s.centerX;
    var cy = phase === 2 ? num(s.refineY, s.bestY) : s.centerY;
    var a = s.startAngle + phase * 0.31 +
            index * 2 * PI / p.count;
    return {
      x: clamp(cx + p.radius * Math.cos(a), 3, mem.sizeX - 3),
      y: clamp(cy + p.radius * Math.sin(a), 3, mem.sizeY - 3)
    };
  }

  function beginScan(kind, x, y, idx, value) {
    var startValue = Math.max(0, num(value, science));
    mem.scan = {
      kind: kind,
      idx: idx,
      originX: x,
      originY: y,
      centerX: x,
      centerY: y,
      refineX: x,
      refineY: y,
      phase: 0,
      index: 0,
      startAngle: ((tick * 37 + Math.max(0, num(idx, 0)) * 83) % 360) *
                  PI / 180,
      baseScience: startValue,
      bestScience: startValue,
      bestX: mem.px,
      bestY: mem.py
    };
    if (kind === "free") mem.work = null;
    mem.nav = null;
  }

  function currentScanPoint() {
    if (!mem.scan) return null;
    var p = scanParams(mem.scan.phase);
    if (mem.scan.index >= p.count) return null;
    return scanPointAt(mem.scan, mem.scan.phase, mem.scan.index);
  }

  function finishScan() {
    var s = mem.scan;
    if (!s) return;

    rememberSignal(s.originX, s.originY, s.bestScience);
    rememberSignal(s.bestX, s.bestY, s.bestScience);
    markGridNear(s.originX, s.originY, 18);
    markGridNear(s.bestX, s.bestY, 18);

    if (s.kind === "cand" &&
        mem.cands[s.idx] &&
        mem.cands[s.idx].status === 1) {
      mem.cands[s.idx].status = 3;
    }
    if (mem.work && mem.work.kind === "cand" &&
        mem.work.idx === s.idx && s.kind === "cand") {
      mem.work = null;
    }

    mem.scan = null;
    mem.nav = null;
  }

  function advanceScanPhase() {
    var s = mem.scan;
    if (!s) return;

    if (s.phase === 0) {
      s.phase = 1;
      s.index = 0;
      mem.nav = null;
      return;
    }

    if (s.phase === 1) {
      var threshold = Math.max(0.025, Math.abs(s.baseScience) * 0.16);
      if (s.bestScience > s.baseScience + threshold) {
        s.phase = 2;
        s.index = 0;
        s.refineX = s.bestX;
        s.refineY = s.bestY;
        mem.nav = null;
        return;
      }
    }

    finishScan();
  }

  function scanRemainingDistance() {
    if (!mem.scan) return Infinity;
    var s = mem.scan;
    var p = currentScanPoint();
    if (!p) return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 20;

    var total = dist(mem.px, mem.py, p.x, p.y);
    var prevX = p.x, prevY = p.y;
    var params = scanParams(s.phase);

    for (var i = s.index + 1; i < params.count; i++) {
      var q = scanPointAt(s, s.phase, i);
      total += dist(prevX, prevY, q.x, q.y);
      prevX = q.x;
      prevY = q.y;
    }

    if (s.phase === 0) total += 125;
    else if (s.phase === 1) total += 48;

    total += dist(s.centerX, s.centerY, mem.baseX, mem.baseY) + 22;
    return total;
  }

  function currentPlanPath() {
    if (mem.siteLock && !mem.returning) {
      var sd = liveSite
        ? siteDistance
        : dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      return sd + dist(mem.siteLock.x, mem.siteLock.y,
                       mem.baseX, mem.baseY) + 16;
    }

    if (mem.scan) return scanRemainingDistance();

    if (mem.work && mem.work.kind === "cand") {
      var c = mem.cands[mem.work.idx];
      if (!c) return Infinity;
      return dist(mem.px, mem.py, c.x, c.y) +
             145 + dist(c.x, c.y, mem.baseX, mem.baseY) + 24;
    }

    if (mem.work && mem.work.kind === "grid") {
      var n = mem.gridNodes[mem.work.idx];
      if (!n) return Infinity;
      return dist(mem.px, mem.py, n.x, n.y) +
             dist(n.x, n.y, mem.baseX, mem.baseY) + 30;
    }

    return Infinity;
  }

  function startCandidate(idx) {
    var c = mem.cands[idx];
    if (!c) return false;
    c.status = 1;
    mem.work = { kind: "cand", idx: idx };
    mem.scan = null;
    mem.nav = null;
    return true;
  }

  function pickCandidate() {
    if (carried > 0 || carried >= mem.capacity) return false;

    var available = docked ? num(mem.maxBattery, battery) : battery;
    var best = -1;
    var bestScore = -1;

    for (var i = 0; i < mem.cands.length; i++) {
      var c = mem.cands[i];
      if (c.status !== 0) continue;

      var out = dist(mem.px, mem.py, c.x, c.y);
      var back = dist(c.x, c.y, mem.baseX, mem.baseY);
      var route = out + 145 + back + 24;
      if (energyNeed(route, 0) + 0.07 > available) continue;
      if (route / 0.45 + 28 > timeLeft - 5) continue;

      var score = Math.max(0.05, c.value) /
                  (85 + out + back + 120);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return false;
    return startCandidate(best);
  }

  function chooseGridGoal() {
    if (carried > 0) return false;

    var available = docked ? num(mem.maxBattery, battery) : battery;
    var best = -1;
    var bestScore = 1e30;

    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (mem.gridVisited[i] || mem.gridBlocked[i]) continue;

      var n = mem.gridNodes[i];
      var out = dist(mem.px, mem.py, n.x, n.y);
      var back = dist(n.x, n.y, mem.baseX, mem.baseY);
      var searchAllowance = science > 0.03 ? 105 : 15;
      var route = out + back + searchAllowance + 20;

      if (energyNeed(route, 0) + 0.06 > available) continue;
      if (route / 0.45 + 22 > timeLeft - 5) continue;

      var score = out + 0.38 * back;
      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return false;
    mem.work = { kind: "grid", idx: best, science0: science };
    mem.nav = null;
    return true;
  }

  function ensureWork() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0 || mem.scan) return;

    if (mem.work) {
      if (mem.work.kind === "cand") {
        var c = mem.cands[mem.work.idx];
        if (c && c.status === 1) return;
        mem.work = null;
      } else if (mem.work.kind === "grid") {
        var gi = mem.work.idx;
        if (gi >= 0 && gi < mem.gridNodes.length &&
            !mem.gridVisited[gi] && !mem.gridBlocked[gi]) return;
        mem.work = null;
      } else {
        mem.work = null;
      }
    }

    for (var ai = 0; ai < mem.cands.length; ai++) {
      if (mem.cands[ai].status === 1) {
        mem.work = { kind: "cand", idx: ai };
        return;
      }
    }

    if (science > 0.045 &&
        !signalNear(mem.px, mem.py, science)) {
      beginScan("free", mem.px, mem.py, -1, science);
      return;
    }

    if (pickCandidate()) return;
    chooseGridGoal();
  }

  function failScanPoint() {
    if (!mem.scan) return;
    mem.scan.index++;
    if (mem.scan.index >= scanParams(mem.scan.phase).count) {
      advanceScanPhase();
    }
    mem.nav = null;
  }

  function failCandidate() {
    if (mem.work && mem.work.kind === "cand" &&
        mem.cands[mem.work.idx]) {
      mem.cands[mem.work.idx].status = 3;
    }
    if (mem.scan && mem.scan.kind === "cand" &&
        mem.cands[mem.scan.idx]) {
      mem.cands[mem.scan.idx].status = 3;
    }
    mem.work = null;
    mem.scan = null;
    mem.nav = null;
  }

  function failGrid() {
    if (mem.work && mem.work.kind === "grid") {
      var gi = mem.work.idx;
      if (gi >= 0 && gi < mem.gridNodes.length) {
        mem.gridBlocked[gi] = true;
        mem.gridVisited[gi] = true;
      }
    }
    mem.work = null;
    mem.nav = null;
  }

  function updateWorkProgress() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0) return;

    if (mem.scan) {
      if (science > num(mem.scan.bestScience, -1) + 0.003) {
        mem.scan.bestScience = science;
        mem.scan.bestX = mem.px;
        mem.scan.bestY = mem.py;
      }

      var sp = currentScanPoint();
      if (!sp) {
        advanceScanPhase();
        return;
      }

      if (dist(mem.px, mem.py, sp.x, sp.y) < 2.5) {
        mem.scan.index++;
        if (mem.scan.index >= scanParams(mem.scan.phase).count) {
          advanceScanPhase();
        }
      }
      return;
    }

    if (!mem.work) return;

    if (mem.work.kind === "cand") {
      var c = mem.cands[mem.work.idx];
      if (!c || c.status !== 1) {
        mem.work = null;
        return;
      }

      if (dist(mem.px, mem.py, c.x, c.y) < 3.0) {
        beginScan("cand", c.x, c.y, mem.work.idx, science);
      }
      return;
    }

    if (mem.work.kind === "grid") {
      var gi = mem.work.idx;
      var n = mem.gridNodes[gi];
      if (!n) {
        mem.work = null;
        return;
      }

      var rise = Math.max(0.025, Math.abs(num(mem.work.science0, 0)) * 0.22);
      if (science > num(mem.work.science0, 0) + rise &&
          science > 0.025 &&
          !signalNear(mem.px, mem.py, science)) {
        mem.gridVisited[gi] = true;
        mem.work = null;
        beginScan("free", mem.px, mem.py, -1, science);
        return;
      }

      if (dist(mem.px, mem.py, n.x, n.y) < 2.5) {
        mem.gridVisited[gi] = true;
        mem.work = null;
        if (science > 0.035 &&
            !signalNear(mem.px, mem.py, science)) {
          beginScan("free", mem.px, mem.py, -1, science);
        }
      }
    }
  }

  function abandonPlan() {
    var had = false;

    if (mem.scan) {
      had = true;
      if (mem.scan.kind === "cand" &&
          mem.cands[mem.scan.idx]) {
        mem.cands[mem.scan.idx].status = 3;
      } else if (mem.scan.kind === "free") {
        rememberSignal(mem.scan.originX, mem.scan.originY,
                       mem.scan.bestScience);
      }
      mem.scan = null;
    }

    if (mem.work) {
      had = true;
      if (mem.work.kind === "cand" &&
          mem.cands[mem.work.idx]) {
        mem.cands[mem.work.idx].status = 3;
      } else if (mem.work.kind === "grid") {
        var gi = mem.work.idx;
        if (gi >= 0 && gi < mem.gridBlocked.length) {
          mem.gridBlocked[gi] = true;
          mem.gridVisited[gi] = true;
        }
      }
      mem.work = null;
    }

    if (mem.siteLock) {
      had = true;
      mem.siteLock = null;
    }
    mem.nav = null;
    return had;
  }

  var oldCarried = num(mem.lastCarried, carried);
  var sampleDone = carried > oldCarried;

  if (sampleDone) {
    var sampleX = mem.px, sampleY = mem.py;
    var nearest = -1, nearestD = 1e30;

    for (var mi = 0; mi < mem.cands.length; mi++) {
      var md = dist(sampleX, sampleY, mem.cands[mi].x, mem.cands[mi].y);
      if (md < nearestD) {
        nearestD = md;
        nearest = mi;
      }
      if (md < 11) mem.cands[mi].status = 2;
    }

    if (nearest >= 0 && nearestD < 27) {
      mem.cands[nearest].status = 2;
    }
    if (mem.work && mem.work.kind === "cand" &&
        mem.cands[mem.work.idx]) {
      mem.cands[mem.work.idx].status =
        dist(sampleX, sampleY,
             mem.cands[mem.work.idx].x,
             mem.cands[mem.work.idx].y) < 30 ? 2 : 3;
    }
    if (mem.scan && mem.scan.kind === "cand" &&
        mem.cands[mem.scan.idx]) {
      mem.cands[mem.scan.idx].status =
        dist(sampleX, sampleY,
             mem.cands[mem.scan.idx].x,
             mem.cands[mem.scan.idx].y) < 30 ? 2 : 3;
    }

    markGridNear(sampleX, sampleY, 17);
    mem.work = null;
    mem.scan = null;
    mem.siteLock = null;
    mem.nav = null;
    mem.returning = true;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered);

  if (docked && carried === 0) {
    mem.returning = false;
    mem.recoverTicks = 0;
  }
  if (carried > 0) mem.returning = true;

  /* Convert a direct site bearing into a persistent local position estimate. */
  if (liveSite && carried === 0 && !mem.returning && drillProgress <= 0) {
    var sa = rad(trueHeading + siteBearing);
    var sxSite = mem.px + siteDistance * Math.cos(sa);
    var sySite = mem.py + siteDistance * Math.sin(sa);

    if (mem.siteLock &&
        dist(sxSite, sySite, mem.siteLock.x, mem.siteLock.y) < 10) {
      mem.siteLock.x = 0.55 * mem.siteLock.x + 0.45 * sxSite;
      mem.siteLock.y = 0.55 * mem.siteLock.y + 0.45 * sySite;
      mem.siteLock.value = num(siteObj.value, mem.siteLock.value);
      mem.siteLock.lastSeen = tick;
    } else {
      mem.siteLock = {
        x: sxSite,
        y: sySite,
        value: num(siteObj.value, 1),
        lastSeen: tick
      };
    }

    var valueNow = num(siteObj.value, NaN);
    if (Number.isFinite(valueNow)) {
      var nearestHint = -1;
      var nearestHintD = 30;
      for (var vh = 0; vh < mem.cands.length; vh++) {
        var vhd = dist(sxSite, sySite, mem.cands[vh].x, mem.cands[vh].y);
        if (vhd < nearestHintD) {
          nearestHintD = vhd;
          nearestHint = vh;
        }
      }
      if (nearestHint >= 0) {
        mem.cands[nearestHint].value =
          Math.max(mem.cands[nearestHint].value, valueNow);
      }
    }
  }

  if (mem.siteLock && drillProgress <= 0 &&
      tick - num(mem.siteLock.lastSeen, tick) > 240) {
    mem.siteLock = null;
    mem.nav = null;
  }

  if (drillProgress > 0 && !sampleDone) {
    return holdOutput(true);
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.prevBump && !docked && drillProgress <= 0) {
    setRecovery();
  }
  mem.prevBump = bumped;

  if (docked) {
    mem.recoverTicks = 0;
  } else if (mem.recoverTicks > 0 && drillProgress <= 0) {
    return recoveryOutput();
  }

  updateWorkProgress();
  ensureWork();

  var beacon = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
  var beaconDistance = beacon ? num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ? num(beacon.bearing, NaN) : NaN;
  var beaconValid = Number.isFinite(beaconDistance) &&
                    Number.isFinite(beaconBearing) &&
                    beaconDistance >= 0 && beaconDistance <= 24;

  var homeD = beaconValid
    ? beaconDistance
    : dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeNeed = energyNeed(homeD * 1.28 + 12, carried);
  var homeTime = homeD / 0.38 + 22;

  if (docked && carried > 0) {
    return emit(0, 0, false, 0, 0, false);
  }

  if (docked && carried === 0) {
    mem.returning = false;

    var attempts = 0;
    while (attempts < 14) {
      var path = currentPlanPath();
      if (!Number.isFinite(path)) {
        ensureWork();
        path = currentPlanPath();
      }
      if (!Number.isFinite(path)) break;

      var need = energyNeed(path, 0);
      var tooMuchTime = path / 0.45 + 25 > timeLeft - 4;
      var impossibleBattery =
        need + 0.035 > num(mem.maxBattery, battery);

      if (!tooMuchTime && !impossibleBattery) {
        if (battery + 0.01 < need + 0.015) {
          return emit(0, 0, false, 0, 0, false);
        }
        break;
      }

      if (!abandonPlan()) break;
      ensureWork();
      attempts++;
    }

    if (!Number.isFinite(currentPlanPath())) {
      return holdOutput(false);
    }
  } else if (!docked) {
    var mustReturn = !!mem.returning;

    if (carried > 0) mustReturn = true;
    if (battery < 0.02) mustReturn = true;

    if (homeD > 2.5) {
      if (battery < homeNeed + 0.085) mustReturn = true;
      if (timeLeft < homeTime + 5) mustReturn = true;

      var workPath = currentPlanPath();
      if (Number.isFinite(workPath)) {
        if (battery < energyNeed(workPath, 0) + 0.055) {
          mustReturn = true;
        }
        if (timeLeft < workPath / 0.40 + 18) {
          mustReturn = true;
        }
      } else {
        mustReturn = true;
      }
    }

    if (mem.siteLock && !mem.returning) {
      var nearSiteD = liveSite
        ? siteDistance
        : dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      if (nearSiteD <= 1.42 &&
          battery > homeNeed + 0.10 &&
          timeLeft > homeTime + 10) {
        mustReturn = false;
      }
    }

    mem.returning = mustReturn;
  }

  function failSite() {
    mem.siteLock = null;
    if (mem.work && mem.work.kind === "cand" &&
        mem.cands[mem.work.idx]) {
      mem.cands[mem.work.idx].status = 3;
      mem.work = null;
      mem.scan = null;
    }
    mem.nav = null;
  }

  if (mem.returning) {
    var homeCruise = timeLeft < homeTime + 80 ? 0.72 : 0.66;
    if (beaconValid) {
      return navigateRelative(beaconBearing, beaconDistance,
                              1.15, homeCruise, "HOME",
                              mem.baseX, mem.baseY, null);
    }
    return navigatePoint(mem.baseX, mem.baseY,
                         1.15, homeCruise, "HOME", null);
  }

  if (mem.siteLock && carried < mem.capacity) {
    var siteD, siteErr;
    if (liveSite) {
      siteD = siteDistance;
      siteErr = wrap(siteBearing);
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteD = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteD > 0.04
        ? wrap(Math.atan2(sdy, sdx) * DEG - trueHeading)
        : 0;
    }

    if (siteD <= 1.42) {
      var hc = holdCommands();
      var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.14;
      var drillNow = siteD <= 1.39 && still;
      return emit(hc[0], hc[1], drillNow, 0, 0, false);
    }

    return navigateRelative(siteErr, siteD, 1.02, 0.40,
                            "SITE", mem.siteLock.x, mem.siteLock.y,
                            failSite);
  }

  if (mem.scan) {
    var spNow = currentScanPoint();
    if (spNow) {
      var scanKey = "S" + mem.scan.kind + "_" +
                    num(mem.scan.idx, -1) + "_" +
                    mem.scan.phase + "_" + mem.scan.index;
      return navigatePoint(spNow.x, spNow.y, 1.8, 0.52,
                           scanKey, failScanPoint);
    }
  }

  if (mem.work && mem.work.kind === "cand") {
    var cnow = mem.cands[mem.work.idx];
    if (cnow && cnow.status === 1) {
      var cidx = mem.work.idx;
      return navigatePoint(cnow.x, cnow.y, 2.4, 0.56,
                           "C" + cidx, failCandidate);
    }
  }

  if (mem.work && mem.work.kind === "grid") {
    var gidx = mem.work.idx;
    var gnow = mem.gridNodes[gidx];
    if (gnow) {
      return navigatePoint(gnow.x, gnow.y, 1.9, 0.54,
                           "G" + gidx, failGrid);
    }
  }

  if (!docked && homeD > 2.5) {
    mem.returning = true;
    if (beaconValid) {
      return navigateRelative(beaconBearing, beaconDistance,
                              1.15, 0.66, "HOME",
                              mem.baseX, mem.baseY, null);
    }
    return navigatePoint(mem.baseX, mem.baseY,
                         1.15, 0.66, "HOME", null);
  }

  return holdOutput(false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  var PI = Math.PI;
  var DEG = 180 / PI;
  var DT = 0.1;

  function num(v, d) {
    if (v === undefined || v === null) return d;
    var n = Number(v);
    return Number.isFinite(n) ? n : d;
  }
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }
  function wrap(a) {
    return ((a + 180) % 360 + 360) % 360 - 180;
  }
  function rad(d) {
    return d * PI / 180;
  }
  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1, dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var rawX = num(obs.x, 200);
  var rawY = num(obs.y, 200);
  var rawHeading = wrap(num(obs.heading, 0));
  var wheelL = clamp(num(obs.wheelLeft, 0), -3, 3);
  var wheelR = clamp(num(obs.wheelRight, 0), -3, 3);
  var centerV = 0.5 * (wheelL + wheelR);
  var wheelTravel = Math.abs(centerV) * DT;
  var pitch = num(obs.pitch, 0);
  var battery = Math.max(0, num(obs.battery, 1));
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var delivered = num(obs.delivered, 0);
  var timeLeft = Math.max(0, num(obs.timeLeft, 1200));
  var science = Math.max(0, num(obs.science, 0));
  var drillProgress = Math.max(0, num(obs.drilling, 0));
  var docked = !!obs.docked;

  if (!mem.initialized) {
    var mission = obs.mission || {};
    var size = mission.size;
    var sx = 400, sy = 400;

    if (Array.isArray(size)) {
      sx = num(size[0], 400);
      sy = num(size[1], 400);
    } else if (typeof size === "number") {
      sx = size;
      sy = size;
    } else if (size && typeof size === "object") {
      sx = num(size.width, num(size.w, num(size.x, 400)));
      sy = num(size.height, num(size.h, num(size.y, 400)));
    }

    var base = mission.base || {};
    mem.sizeX = Math.max(40, sx);
    mem.sizeY = Math.max(40, sy);
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));

    mem.cands = [];
    var hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi] || {};
      var hx = num(h.x, NaN);
      var hy = num(h.y, NaN);
      if (!Number.isFinite(hx) || !Number.isFinite(hy)) continue;

      hx = clamp(hx, 3, mem.sizeX - 3);
      hy = clamp(hy, 3, mem.sizeY - 3);
      var hv = Math.max(0.05, num(h.estimate, num(h.value, 1)));
      var duplicate = -1;

      for (var hj = 0; hj < mem.cands.length; hj++) {
        if (dist(hx, hy, mem.cands[hj].x, mem.cands[hj].y) < 8) {
          duplicate = hj;
          break;
        }
      }

      if (duplicate >= 0) {
        var dc = mem.cands[duplicate];
        dc.x = 0.5 * (dc.x + hx);
        dc.y = 0.5 * (dc.y + hy);
        dc.value = Math.max(dc.value, hv);
      } else {
        mem.cands.push({
          x: hx,
          y: hy,
          value: hv,
          status: 0,
          minMode: 0
        });
      }
    }

    mem.gridNodes = [];
    mem.gridVisited = [];
    mem.gridBlocked = [];
    var nx = Math.max(5, Math.min(10, Math.ceil(mem.sizeX / 52)));
    var ny = Math.max(5, Math.min(10, Math.ceil(mem.sizeY / 52)));

    for (var gy = 0; gy < ny; gy++) {
      for (var gx = 0; gx < nx; gx++) {
        mem.gridNodes.push({
          x: (gx + 0.5) * mem.sizeX / nx,
          y: (gy + 0.5) * mem.sizeY / ny
