        mem.gridVisited.push(false);
        mem.gridBlocked.push(false);
      }
    }

    mem.task = null;
    mem.taskSerial = 0;
    mem.initialFreeDone = false;
    mem.siteLock = null;
    mem.siteIgnoreUntil = 0;
    mem.returning = false;

    mem.tick = 0;
    mem.trueHeading = rawHeading;
    mem.headingBias = 0;
    mem.yawScale = 1;
    mem.compassStuck = false;
    mem.compassQuietYaw = 0;
    mem.prevRawHeading = rawHeading;
    mem.prevWheelL = wheelL;
    mem.prevWheelR = wheelR;
    mem.course = null;
    mem.headingCalibrated = false;

    mem.px = rawX;
    mem.py = rawY;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = 0;
    mem.gpsAnchorTravel = 0;
    mem.gpsSame = 0;
    mem.gpsStale = false;

    mem.prevBattery = battery;
    mem.maxBattery = Math.max(0.15, battery);
    mem.ePerM = 0.00115;
    mem.energyWindowTick = 0;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.energyWindowSolar = 0;

    mem.motorGainL = 3.2;
    mem.motorGainR = 3.2;
    mem.motorSamples = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastDrive = false;
    mem.lastV = 0;
    mem.lastOmega = 0;
    mem.lastAim = 0;
    mem.lastAimHeading = rawHeading;

    mem.nav = null;
    mem.prevBump = false;
    mem.recoverTicks = 0;
    mem.recoverTotal = 15;
    mem.recoverSign = 1;

    mem.holdIL = 0;
    mem.holdIR = 0;

    mem.rayLast = [];
    mem.raySame = [];
    mem.rayStartX = [];
    mem.rayStartY = [];
    mem.rayStartHeading = [];
    mem.rayBad = [];

    mem.lastCarried = carried;
    mem.lastDelivered = delivered;
    mem.initialized = true;
  }

  mem.tick = num(mem.tick, 0) + 1;
  var tick = mem.tick;

  /* Estimate heading from compass and wheel odometry, and learn compass bias. */
  var oldTrueHeading = num(mem.trueHeading, rawHeading);
  var predictedYaw = 0;
  var avgL = 0.5 * (wheelL + num(mem.prevWheelL, wheelL));
  var avgR = 0.5 * (wheelR + num(mem.prevWheelR, wheelR));
  predictedYaw = ((avgR - avgL) / 0.6) * DT * DEG;

  var rawYaw = wrap(rawHeading - num(mem.prevRawHeading, rawHeading));
  var scaledYaw = predictedYaw * num(mem.yawScale, 1);
  var jumpThisTick = false;

  if (Math.abs(wrap(rawYaw - scaledYaw)) > 95 &&
      Math.abs(predictedYaw) < 30) {
    mem.headingBias = wrap(oldTrueHeading + scaledYaw - rawHeading);
    jumpThisTick = true;
    mem.course = null;
  } else if (!mem.compassStuck &&
             Math.abs(predictedYaw) > 1 &&
             Math.abs(rawYaw) > 0.25 &&
             predictedYaw * rawYaw > 0) {
    var yawRatio = rawYaw / predictedYaw;
    if (yawRatio > 0.4 && yawRatio < 1.8) {
      mem.yawScale = clamp(0.98 * num(mem.yawScale, 1) +
                           0.02 * yawRatio, 0.45, 1.8);
    }
  }

  if (Math.abs(rawYaw) < 0.04 && Math.abs(predictedYaw) > 0.8) {
    mem.compassQuietYaw = num(mem.compassQuietYaw, 0) +
                          Math.abs(predictedYaw *
                                   num(mem.yawScale, 1));
    if (mem.compassQuietYaw > 55) mem.compassStuck = true;
  } else if (Math.abs(rawYaw) > 0.35) {
    mem.compassQuietYaw = 0;
    if (mem.compassStuck) {
      mem.headingBias = wrap(oldTrueHeading + scaledYaw - rawHeading);
      mem.compassStuck = false;
    }
  }

  var trueHeading = mem.compassStuck
    ? wrap(oldTrueHeading + scaledYaw)
    : wrap(rawHeading + num(mem.headingBias, 0));

  /* Blend GPS with odometry; detect a GPS reading that is genuinely frozen. */
  var rawStep = dist(rawX, rawY,
                     num(mem.lastRawX, rawX),
                     num(mem.lastRawY, rawY));
  if (rawStep < 0.008) {
    mem.gpsSame = num(mem.gpsSame, 0) + 1;
  } else {
    mem.gpsSame = 0;
  }

  var anchorMove = dist(rawX, rawY,
                        num(mem.gpsAnchorX, rawX),
                        num(mem.gpsAnchorY, rawY));
  mem.gpsAnchorTravel = num(mem.gpsAnchorTravel, 0) + wheelTravel;

  if (anchorMove > 1.3) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = tick;
    mem.gpsAnchorTravel = 0;
    mem.gpsStale = false;
  } else if (tick - num(mem.gpsAnchorTick, tick) > 85 &&
             num(mem.gpsAnchorTravel, 0) > 6 &&
             num(mem.gpsSame, 0) > 65) {
    mem.gpsStale = true;
  }

  if (mem.gpsStale && anchorMove > 2.5) {
    mem.gpsStale = false;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorTick = tick;
    mem.gpsAnchorTravel = 0;
    mem.gpsSame = 0;
