  var midHeading = wrap(oldTrueHeading +
                        0.5 * predictedYaw *
                        num(mem.yawScale, 1));
  var predX = num(mem.px, rawX) +
              centerV * DT * Math.cos(rad(midHeading));
  var predY = num(mem.py, rawY) +
              centerV * DT * Math.sin(rad(midHeading));

  if (!mem.gpsStale) {
    var ex = rawX - predX;
    var ey = rawY - predY;
    var errLen = Math.sqrt(ex * ex + ey * ey);

    if (errLen < 25) {
      if (errLen > 5) {
        ex *= 5 / errLen;
        ey *= 5 / errLen;
      }
      var poseAlpha = Math.abs(centerV) > 0.2 ? 0.30 : 0.09;
      predX += poseAlpha * ex;
      predY += poseAlpha * ey;
