  mem.px = predX;
  mem.py = predY;

  /* Calibrate heading bias from long, straight GPS tracks. */
  if (!mem.compassStuck && !mem.gpsStale && !jumpThisTick &&
      Math.abs(centerV) > 0.24 &&
      Math.abs(wheelR - wheelL) < 0.24 &&
      Math.abs(num(mem.lastOmega, 0)) < 0.25 &&
      Math.abs(pitch) < 25) {
    if (!mem.course) {
      mem.course = {
        x: rawX,
        y: rawY,
        sin: Math.sin(rad(rawHeading)),
        cos: Math.cos(rad(rawHeading)),
        direction: centerV * DT
      };
    } else {
      mem.course.sin += Math.sin(rad(rawHeading));
      mem.course.cos += Math.cos(rad(rawHeading));
      mem.course.direction += centerV * DT;

      if (dist(rawX, rawY, mem.course.x, mem.course.y) > 7) {
        var trackAngle = Math.atan2(rawY - mem.course.y,
                                    rawX - mem.course.x) * DEG;
        if (mem.course.direction < 0) {
          trackAngle = wrap(trackAngle + 180);
        }

        var meanRaw = Math.atan2(mem.course.sin,
                                 mem.course.cos) * DEG;
        var biasTarget = wrap(trackAngle - meanRaw);

        if (Math.abs(biasTarget) < 85) {
          if (!mem.headingCalibrated) {
            mem.headingBias = biasTarget;
            mem.headingCalibrated = true;
          } else {
            mem.headingBias = wrap(num(mem.headingBias, 0) +
              0.07 * wrap(biasTarget - num(mem.headingBias, 0)));
          }
          trueHeading = wrap(rawHeading + mem.headingBias);
        }
        mem.course = null;
      }
    }
  } else {
    mem.course = null;
  }

  mem.trueHeading = trueHeading;
  mem.prevRawHeading = rawHeading;
  mem.prevWheelL = wheelL;
  mem.prevWheelR = wheelR;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  /* Learn energy use and respond conservatively to sudden battery changes. */
  var previousBattery = num(mem.prevBattery, battery);
  var immediateDrop = previousBattery - battery;

  if (immediateDrop > 0.10) {
    mem.maxBattery = Math.min(num(mem.maxBattery, battery), battery + 0.08);
    mem.ePerM = Math.max(num(mem.ePerM, 0.00115), 0.0018);
    mem.energyWindowTick = tick;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.energyWindowSolar = 0;
  }

  if (battery > num(mem.maxBattery, battery)) {
    mem.maxBattery = battery;
  }

  if (docked) {
    mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);
    mem.energyWindowTick = tick;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;
    mem.energyWindowSolar = 0;
