      var netLoss = num(mem.energyWindowBattery, battery) - battery +
                    0.22 * num(mem.energyWindowSolar, 0);
      var moved = num(mem.energyWindowDistance, 0);

      if (moved > 5 && netLoss > 0.005) {
        var measuredE = clamp(netLoss / moved, 0.00035, 0.025);
        var energyAlpha = measuredE > num(mem.ePerM, 0.00115)
          ? 0.22 : 0.035;
        mem.ePerM = clamp(num(mem.ePerM, 0.00115) +
                          energyAlpha *
                          (measuredE - num(mem.ePerM, 0.00115)),
                          0.0004, 0.025);
