  /* Adapt the two motor gains independently. */
  function learnGain(cmd, actual, oldGain) {
    if (!mem.lastDrive || Math.abs(cmd) < 0.14 ||
        Math.abs(actual) < 0.08 || cmd * actual <= 0) {
      return oldGain;
    }
    var ratio = Math.abs(actual / cmd);
    if (ratio < 0.45 || ratio > 7.5) return oldGain;
    mem.motorSamples = num(mem.motorSamples, 0) + 1;
    return clamp(0.94 * oldGain + 0.06 * ratio, 0.55, 7.5);
  }

  mem.motorGainL = learnGain(num(mem.lastCmdL, 0), wheelL,
                             num(mem.motorGainL, 3.2));
  mem.motorGainR = learnGain(num(mem.lastCmdR, 0), wheelR,
                             num(mem.motorGainR, 3.2));

  /* Ignore range sensors that become stuck at a finite reading. */
  var rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  var rays = [];

  for (var ri = 0; ri < 9; ri++) {
    var rd = num(rawRays[ri], 15);
    if (rd < 0 || rd > 15.2) rd = 15;
    rd = clamp(rd, 0, 15);

    if (mem.rayLast[ri] === undefined) {
      mem.rayLast[ri] = rd;
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayStartHeading[ri] = trueHeading;
      mem.rayBad[ri] = false;
    } else if (Math.abs(rd - mem.rayLast[ri]) < 0.015) {
      mem.raySame[ri] = num(mem.raySame[ri], 0) + 1;
      if (mem.raySame[ri] > 300 && rd < 14.8 &&
          dist(mem.px, mem.py,
               mem.rayStartX[ri], mem.rayStartY[ri]) > 6 &&
          Math.abs(wrap(trueHeading -
                        num(mem.rayStartHeading[ri], trueHeading))) > 22) {
        mem.rayBad[ri] = true;
      }
    } else {
      if (mem.rayBad[ri] &&
          Math.abs(rd - mem.rayLast[ri]) > 0.8) {
        mem.rayBad[ri] = false;
      }
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayStartHeading[ri] = trueHeading;
    }

    mem.rayLast[ri] = rd;
    rays[ri] = mem.rayBad[ri] ? 15 : rd;
  }

  var siteObj = obs.site && typeof obs.site === "object"
    ? obs.site : null;
  var siteDistance = siteObj ? num(siteObj.distance, NaN) : NaN;
  var siteBearing = siteObj ? num(siteObj.bearing, NaN) : NaN;
  var liveSite = !!(siteObj &&
    Number.isFinite(siteDistance) &&
    Number.isFinite(siteBearing) &&
    siteDistance >= 0);

  var beacon = obs.beacon && typeof obs.beacon === "object"
    ? obs.beacon : null;
  var beaconDistance = beacon ? num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ? num(beacon.bearing, NaN) : NaN;
  var beaconValid = !!(beacon &&
    Number.isFinite(beaconDistance) &&
    Number.isFinite(beaconBearing) &&
    beaconDistance >= 0 && beaconDistance <= 24);

  function emit(left, right, drill, v, omega, isDrive) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastDrive = !!isDrive;
    mem.lastV = Math.abs(num(v, 0));
    mem.lastOmega = num(omega, 0);
    return { left: left, right: right, drill: !!drill };
  }

  function zeroOutput() {
    mem.holdIL = 0;
    mem.holdIR = 0;
    return emit(0, 0, false, 0, 0, false);
  }

  function wheelCommand(target, actual, gain) {
    gain = clamp(num(gain, 3.2), 0.55, 7.5);
    var cmd = target / gain + 0.18 * (target - actual);

    if (Math.abs(target) > 0.12 &&
        Math.abs(cmd) < 0.085 &&
        cmd * target >= 0) {
      cmd = target < 0 ? -0.085 : 0.085;
    }

    var limit = num(mem.motorSamples, 0) < 8 ? 0.24 : 0.84;
    return clamp(cmd, -limit, limit);
  }

  function drive(v, omega) {
    var leftTarget = clamp(v - 0.30 * omega, -1.0, 1.0);
    var rightTarget = clamp(v + 0.30 * omega, -1.0, 1.0);
    mem.holdIL = num(mem.holdIL, 0) * 0.92;
    mem.holdIR = num(mem.holdIR, 0) * 0.92;

    return emit(
      wheelCommand(leftTarget, wheelL, mem.motorGainL),
      wheelCommand(rightTarget, wheelR, mem.motorGainR),
      false, v, omega, true
    );
  }

  function holdCommands() {
    var feed = clamp(0.32 * Math.sin(rad(pitch)), -0.28, 0.28);
    mem.holdIL = clamp(num(mem.holdIL, 0) -
                       0.10 * wheelL * DT, -0.25, 0.25);
    mem.holdIR = clamp(num(mem.holdIR, 0) -
                       0.10 * wheelR * DT, -0.25, 0.25);

    return [
      clamp(feed + mem.holdIL - 0.78 * wheelL, -0.48, 0.48),
      clamp(feed + mem.holdIR - 0.78 * wheelR, -0.48, 0.48)
    ];
  }

  function holdOutput(drill) {
    var h = holdCommands();
    return emit(h[0], h[1], drill, 0, 0, false);
  }

  function rayAt(angle) {
    var a = clamp(angle, -80, 80);
    var q = (a + 80) / 20;
    var i = Math.floor(q);
    var f = q - i;
    if (i >= 8) return rays[8];
    return Math.min(rays[i], rays[i + 1],
                    rays[i] * (1 - f) + rays[i + 1] * f);
  }

  function edgeDistance(relativeAngle) {
    var a = rad(trueHeading + relativeAngle);
    var dx = Math.cos(a), dy = Math.sin(a);
    var best = 1e9;

    if (dx > 0.001) {
      best = Math.min(best, (mem.sizeX - 3 - mem.px) / dx);
    }
    if (dx < -0.001) {
      best = Math.min(best, (3 - mem.px) / dx);
    }
    if (dy > 0.001) {
      best = Math.min(best, (mem.sizeY - 3 - mem.py) / dy);
    }
    if (dy < -0.001) {
      best = Math.min(best, (3 - mem.py) / dy);
    }

    return Math.max(0, best);
  }

  function chooseAim(goalErr, speed) {
    var g = clamp(wrap(goalErr), -80, 80);
    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80,
                      g, clamp(g - 20, -80, 80),
                      clamp(g + 20, -80, 80),
                      clamp(g - 40, -80, 80),
                      clamp(g + 40, -80, 80)];

    var prevRel = wrap(num(mem.lastAim, 0) -
      wrap(trueHeading - num(mem.lastAimHeading, trueHeading)));
    var best = g;
    var bestCost = 1e30;

    for (var ci = 0; ci < candidates.length; ci++) {
      var c = candidates[ci];
      var duplicate = false;

      for (var cj = 0; cj < ci; cj++) {
        if (Math.abs(candidates[cj] - c) < 0.5) {
          duplicate = true;
          break;
        }
      }
      if (duplicate) continue;

      var diff = Math.abs(wrap(c - goalErr));
      var cost = 0.008 * diff * diff;
      cost += 0.0010 *
        Math.pow(Math.abs(wrap(c - prevRel)), 2);

      for (var rj = 0; rj < 9; rj++) {
        var rd2 = rays[rj];
        if (rd2 >= 14.95) continue;

        var rayAngle = -80 + 20 * rj;
        var da = Math.abs(wrap(c - rayAngle));
        if (da > 58) continue;

        var safe = 3.1 + 0.40 * clamp(Math.abs(speed), 0, 1.0);
        var p = clamp((safe - rd2) / safe, 0, 1);
        var influence = Math.exp(-0.5 * Math.pow(da / 25, 2));
        cost += 38 * p * p * influence;
        if (rd2 < 1.25 && da < 18) cost += 60;
      }

      var edge = edgeDistance(c);
      var edgeSafe = 5.5;
      if (edge < edgeSafe) {
        var ep = (edgeSafe - edge) / edgeSafe;
        cost += 40 * ep * ep;
        if (edge < 1.5) cost += 90;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }

    mem.lastAim = best;
    mem.lastAimHeading = trueHeading;
    return best;
  }

  function sideSign() {
    var right = 0, left = 0;
    for (var i = 0; i < 4; i++) right += rays[i];
    for (var j = 5; j < 9; j++) left += rays[j];
    right *= 0.25;
    left *= 0.25;

    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    return tick % 2 === 0 ? 1 : -1;
  }

  function setRecovery() {
    mem.recoverTotal = 15;
    mem.recoverTicks = 15;
    mem.recoverSign = sideSign();
  }

  function recoveryOutput() {
    var total = num(mem.recoverTotal, 15);
    var elapsed = total - num(mem.recoverTicks, 0);
    mem.recoverTicks = Math.max(0, num(mem.recoverTicks, 0) - 1);

    if (elapsed < 6) return drive(-0.23, 0);

    var out = drive(0, num(mem.recoverSign, 1) * 0.82);
    if (mem.recoverTicks <= 0 && mem.nav) {
      mem.nav.startTick = tick;
      mem.nav.startDist = num(mem.nav.lastDist, mem.nav.startDist);
      mem.nav.commanded = 0;
      mem.nav.travel = 0;
    }
    return out;
  }

  function monitorNavigation(key, d, stopRadius, onSkip) {
    if (!key || !Number.isFinite(d)) return false;

    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = {
        key: key,
        startTick: tick,
        startDist: d,
        lastDist: d,
        commanded: 0,
        travel: 0,
        failures: 0
      };
    }

    var nav = mem.nav;
    nav.commanded = num(nav.commanded, 0) +
                    num(mem.lastV, 0) * DT;
    nav.travel = num(nav.travel, 0) + wheelTravel;
    nav.lastDist = d;

    if (tick - num(nav.startTick, tick) >= 200) {
      var improvement = num(nav.startDist, d) - d;
      var stalled = d > stopRadius + 2 &&
                    improvement < 1.2 &&
                    (num(nav.commanded, 0) > 2 ||
                     num(nav.travel, 0) > 2);

      if (stalled) {
        nav.failures = num(nav.failures, 0) + 1;
        nav.startTick = tick;
        nav.startDist = d;
        nav.commanded = 0;
        nav.travel = 0;
        setRecovery();

        if (nav.failures >= 3 && typeof onSkip === "function") {
          onSkip();
          mem.nav = null;
        }
        return true;
      }

      if (improvement > 2) {
        nav.failures = Math.max(0, num(nav.failures, 0) - 1);
      }
      nav.startTick = tick;
      nav.startDist = d;
      nav.commanded = 0;
      nav.travel = 0;
    }

    return false;
  }

  function navigateRelative(err, d, stopRadius, cruise,
                             key, onSkip) {
    if (!Number.isFinite(d) || d < 0) return holdOutput(false);
    err = wrap(err);

    if (d <= stopRadius) return holdOutput(false);
    if (monitorNavigation(key, d, stopRadius, onSkip)) {
      return recoveryOutput();
    }

    if (Math.abs(err) > 112) {
      return drive(0, err > 0 ? 0.92 : -0.92);
    }

    var aim = chooseAim(err, centerV);
    var absAim = Math.abs(aim);
    var omega = clamp(1.75 * rad(aim), -1.15, 1.15);
    if (absAim < 1.1) omega = 0;

    var v = Math.min(cruise,
                     Math.max(0.09, (d - stopRadius) * 0.42));
    v *= Math.max(0.12, Math.cos(rad(aim)));

    if (absAim > 62) v = Math.min(v, 0.16);

    var clear = rayAt(aim);
    if (clear < 4.2) {
      v *= clamp((clear - 0.85) / 3.35, 0, 1);
    }
    if (clear < 1.05) v = 0;

    var directClear = rayAt(clamp(err, -80, 80));
    if (directClear < 1.7 &&
        Math.abs(wrap(aim - err)) < 14) {
      v = 0;
    }

    var edge = edgeDistance(aim);
    if (edge < 5.2) {
      v = Math.min(v, clamp((edge - 1.0) * 0.18, 0, cruise));
    }
    if (edge < 1.1) v = 0;

    if (Math.abs(pitch) > 32) v = Math.min(v, 0.40);
    if (Math.abs(pitch) > 43) v = Math.min(v, 0.28);

    return drive(v, omega);
  }

  function navigatePoint(x, y, stopRadius, cruise, key, onSkip) {
    var dx = x - mem.px;
    var dy = y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var err = d > 0.04
      ? wrap(Math.atan2(dy, dx) * DEG - trueHeading)
      : 0;

    return navigateRelative(err, d, stopRadius, cruise, key, onSkip);
  }

  function markGridNear(x, y, radius) {
    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (dist(x, y, mem.gridNodes[i].x, mem.gridNodes[i].y) < radius) {
        mem.gridVisited[i] = true;
      }
    }
  }

  function makeRing(cx, cy, radius, count, startAngle) {
    var points = [];
    for (var i = 0; i < count; i++) {
      var a = startAngle + i * 2 * PI / count;
      var x = clamp(cx + radius * Math.cos(a), 3, mem.sizeX - 3);
      var y = clamp(cy + radius * Math.sin(a), 3, mem.sizeY - 3);

      if (points.length === 0 ||
          dist(x, y, points[points.length - 1].x,
               points[points.length - 1].y) > 2.2) {
        points.push({ x: x, y: y });
      }
    }
    return points;
  }

  function modeRadius(mode) {
    if (mode === 1) return 12;
    if (mode === 2) return 8;
    return 14;
  }

  function modeCount(mode) {
    if (mode === 1) return 10;
    if (mode === 2) return 6;
    return 18;
  }

  function modeLength(mode) {
    if (mode === 1) return 86;
    if (mode === 2) return 60;
    return 105;
  }

  function energyNeed(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    var n = Math.max(0, load || 0);
    var e = Math.max(0.0004, num(mem.ePerM, 0.00115));
    return 0.065 + Math.max(0, path) * e *
           (1.68 + 0.16 * n) + 0.022 * n;
  }

  function planNeed(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    return energyNeed(path * 1.18 + 8, load) + 0.035;
  }

  function startCandidate(idx, mode) {
    var c = mem.cands[idx];
    if (!c) return false;

    c.status = 1;
    mem.taskSerial = num(mem.taskSerial, 0) + 1;
    mem.task = {
      kind: "candidate",
      id: mem.taskSerial,
      idx: idx,
      mode: mode,
      stage: 0,
      centerX: c.x,
      centerY: c.y,
      points: [{ x: c.x, y: c.y }],
      pointIndex: 0,
      baseScience: -1,
      bestScience: -1,
      bestX: c.x,
      bestY: c.y
    };
    mem.nav = null;
    return true;
  }

  function startFreeSearch(x, y, gridIndex, baseline) {
    mem.taskSerial = num(mem.taskSerial, 0) + 1;
    var angle = ((tick * 29 + Math.max(0, gridIndex + 1) * 71) % 360) *
                PI / 180;

    mem.task = {
      kind: "free",
      id: mem.taskSerial,
      gridIndex: gridIndex,
      centerX: x,
      centerY: y,
      stage: 1,
      points: makeRing(x, y, 8, 8, angle),
      pointIndex: 0,
      baseScience: Math.max(0, num(baseline, science)),
      bestScience: Math.max(0, num(baseline, science)),
      bestX: mem.px,
      bestY: mem.py
    };
    mem.nav = null;
  }

  function startGrid(idx, scan) {
    var node = mem.gridNodes[idx];
    if (!node) return false;

    mem.taskSerial = num(mem.taskSerial, 0) + 1;
    mem.task = {
      kind: "grid",
      id: mem.taskSerial,
      idx: idx,
      point: { x: node.x, y: node.y },
      scan: !!scan,
      baseScience: science
    };
    mem.nav = null;
    return true;
  }

  function finishTask() {
    var t = mem.task;
    if (!t) return;

    if (t.kind === "candidate") {
      var c = mem.cands[t.idx];
      if (c && c.status === 1) c.status = 3;
      markGridNear(t.centerX, t.centerY, 14);
    } else if (t.kind === "grid") {
      if (t.idx >= 0 && t.idx < mem.gridVisited.length) {
        mem.gridVisited[t.idx] = true;
      }
    } else if (t.kind === "free" && t.gridIndex >= 0) {
      if (t.gridIndex < mem.gridVisited.length) {
        mem.gridVisited[t.gridIndex] = true;
      }
    }

    mem.task = null;
    mem.nav = null;
  }

  function skipTaskTarget() {
    var t = mem.task;
    if (!t) return;

    if (t.kind === "candidate") {
      var c = mem.cands[t.idx];
      if (t.stage === 0) {
        if (c) c.status = 3;
        markGridNear(t.centerX, t.centerY, 14);
        mem.task = null;
        mem.nav = null;
        return;
      }

      t.pointIndex++;
      if (t.pointIndex >= t.points.length) finishTask();
      return;
    }

    if (t.kind === "grid") {
      if (t.idx >= 0 && t.idx < mem.gridBlocked.length) {
        mem.gridBlocked[t.idx] = true;
        mem.gridVisited[t.idx] = true;
      }
      mem.task = null;
      mem.nav = null;
      return;
    }

    if (t.kind === "free") {
      t.pointIndex++;
      if (t.pointIndex >= t.points.length) finishTask();
    }
  }

  function updateTaskProgress() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0 || !mem.task) return;

    var t = mem.task;

    if (t.kind === "candidate") {
      var c = mem.cands[t.idx];
      if (!c || c.status !== 1) {
        mem.task = null;
        mem.nav = null;
        return;
      }

      if (t.stage > 0 &&
          dist(mem.px, mem.py, t.centerX, t.centerY) < 30 &&
          science > num(t.bestScience, -1) + 0.004) {
        t.bestScience = science;
        t.bestX = mem.px;
        t.bestY = mem.py;
      }

      if (t.stage === 0) {
        if (dist(mem.px, mem.py, t.centerX, t.centerY) < 1.75) {
          t.stage = 1;
          t.baseScience = science;
          t.bestScience = science;
          t.bestX = mem.px;
          t.bestY = mem.py;

          var angle = ((tick * 31 + t.idx * 97) % 360) * PI / 180;
          t.points = makeRing(t.centerX, t.centerY,
                              modeRadius(t.mode),
                              modeCount(t.mode), angle);
          t.pointIndex = 0;
          mem.nav = null;

          if (t.points.length === 0) finishTask();
        }
        return;
      }

      var cp = t.points[t.pointIndex];
      if (!cp || dist(mem.px, mem.py, cp.x, cp.y) < 1.65) {
        if (cp) t.pointIndex++;

        if (t.pointIndex >= t.points.length) {
          var rise = Math.max(0.025,
                              Math.abs(num(t.baseScience, 0)) * 0.16);

          if (t.mode === 0 && t.stage === 1 &&
              t.bestScience > t.baseScience + rise) {
            t.stage = 2;
            t.points = makeRing(t.bestX, t.bestY, 5, 8,
                                ((tick * 19 + t.idx * 43) % 360) *
                                PI / 180);
            t.pointIndex = 0;
            mem.nav = null;
            if (t.points.length === 0) finishTask();
          } else {
            finishTask();
          }
        } else if (cp) {
          mem.nav = null;
        }
      }
      return;
    }

    if (t.kind === "grid") {
      if (dist(mem.px, mem.py, t.point.x, t.point.y) < 1.8) {
        var riseGrid = Math.max(0.035,
          Math.abs(num(t.baseScience, 0)) * 0.22);

        if (t.scan &&
            science > num(t.baseScience, 0) + riseGrid &&
            science > 0.025) {
          var gx = t.point.x, gy = t.point.y, gi = t.idx;
          startFreeSearch(gx, gy, gi, science);
        } else {
          if (t.idx >= 0 && t.idx < mem.gridVisited.length) {
            mem.gridVisited[t.idx] = true;
          }
          mem.task = null;
          mem.nav = null;
        }
      }
      return;
    }

    if (t.kind === "free") {
      if (science > num(t.bestScience, -1) + 0.004) {
        t.bestScience = science;
        t.bestX = mem.px;
        t.bestY = mem.py;
      }

      var fp = t.points[t.pointIndex];
      if (!fp || dist(mem.px, mem.py, fp.x, fp.y) < 1.65) {
        if (fp) t.pointIndex++;
        if (t.pointIndex >= t.points.length) {
          finishTask();
        } else if (fp) {
          mem.nav = null;
        }
      }
    }
  }

  function searchLength(mode) {
    return modeLength(mode);
  }

  function chooseCandidate() {
    if (carried > 0 || carried >= mem.capacity) return false;

    var available = docked
      ? num(mem.maxBattery, battery)
      : battery;

    for (var mode = 0; mode <= 2; mode++) {
      var best = -1;
      var bestScore = -1;

      for (var i = 0; i < mem.cands.length; i++) {
        var c = mem.cands[i];
        if (c.status !== 0 || num(c.minMode, 0) > mode) continue;

        var out = dist(mem.px, mem.py, c.x, c.y);
        var back = dist(c.x, c.y, mem.baseX, mem.baseY);
        var route = out + searchLength(mode) + back + 18;

        if (planNeed(route, 0) + 0.02 > available) continue;
        if (route / 0.45 + 38 > timeLeft - 6) continue;

        var score = Math.pow(Math.max(0.05, c.value), 0.85) /
                    (70 + out + 0.72 * back + searchLength(mode));

        if (score > bestScore) {
          bestScore = score;
          best = i;
        }
      }

      if (best >= 0) return startCandidate(best, mode);
    }

    return false;
  }

  function chooseGridGoal() {
    if (carried > 0) return false;

    var available = docked
      ? num(mem.maxBattery, battery)
      : battery;

    for (var scanPass = 0; scanPass < 2; scanPass++) {
      var scan = scanPass === 0;
      var best = -1;
      var bestScore = 1e30;

      for (var i = 0; i < mem.gridNodes.length; i++) {
        if (mem.gridVisited[i] || mem.gridBlocked[i]) continue;

        var node = mem.gridNodes[i];
        var out = dist(mem.px, mem.py, node.x, node.y);
        var back = dist(node.x, node.y, mem.baseX, mem.baseY);
        var route = out + back + (scan ? 52 : 15) + 16;

        if (planNeed(route, 0) + 0.02 > available) continue;
        if (route / 0.45 + 30 > timeLeft - 5) continue;

        var score = out + 0.40 * back + (scan ? 0 : 4);
        if (score < bestScore) {
          bestScore = score;
          best = i;
        }
      }

      if (best >= 0) return startGrid(best, scan);
    }

    return false;
  }

  function ensureTask() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0) return;

    if (mem.task) {
      if (mem.task.kind === "candidate") {
        var c = mem.cands[mem.task.idx];
        if (c && c.status === 1) return;
        mem.task = null;
      } else if (mem.task.kind === "grid") {
        var gi = mem.task.idx;
        if (gi >= 0 && gi < mem.gridVisited.length &&
            !mem.gridVisited[gi] && !mem.gridBlocked[gi]) return;
        mem.task = null;
      } else if (mem.task.kind === "free") {
        return;
      } else {
        mem.task = null;
      }
    }

    if (chooseCandidate()) return;

    if (!mem.initialFreeDone && science > 0.06) {
      mem.initialFreeDone = true;
      startFreeSearch(mem.px, mem.py, -1, science);
      return;
    }

    chooseGridGoal();
  }

  function currentTaskPath() {
    var t = mem.task;
    if (!t) return Infinity;

    if (t.kind === "candidate") {
      if (t.stage === 0) {
        return dist(mem.px, mem.py, t.centerX, t.centerY) +
               searchLength(t.mode) +
               dist(t.centerX, t.centerY, mem.baseX, mem.baseY) + 14;
      }

      if (!t.points || t.points.length === 0) {
        return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 10;
      }

      var ti = clamp(t.pointIndex, 0, t.points.length);
      if (ti >= t.points.length) {
        return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 10;
      }

      var route = dist(mem.px, mem.py,
                       t.points[ti].x, t.points[ti].y);
      for (var k = ti + 1; k < t.points.length; k++) {
        route += dist(t.points[k - 1].x, t.points[k - 1].y,
                      t.points[k].x, t.points[k].y);
      }
      var last = t.points[t.points.length - 1];
      return route + dist(last.x, last.y, mem.baseX, mem.baseY) + 14;
    }

    if (t.kind === "grid") {
      return dist(mem.px, mem.py, t.point.x, t.point.y) +
             dist(t.point.x, t.point.y, mem.baseX, mem.baseY) +
             (t.scan ? 48 : 12);
    }

    if (t.kind === "free") {
      if (!t.points || t.points.length === 0) {
        return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 10;
      }

      var fi = clamp(t.pointIndex, 0, t.points.length);
      if (fi >= t.points.length) {
        return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 10;
      }

      var freeRoute = dist(mem.px, mem.py,
                           t.points[fi].x, t.points[fi].y);
      for (var q = fi + 1; q < t.points.length; q++) {
        freeRoute += dist(t.points[q - 1].x, t.points[q - 1].y,
                          t.points[q].x, t.points[q].y);
      }
      var finalPoint = t.points[t.points.length - 1];
      return freeRoute +
             dist(finalPoint.x, finalPoint.y, mem.baseX, mem.baseY) + 12;
    }

    return Infinity;
  }

  function currentPlanPath() {
    if (mem.siteLock) {
      var sd = liveSite
        ? siteDistance
        : dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      return sd + dist(mem.px, mem.py, mem.baseX, mem.baseY) + 14;
    }
    return currentTaskPath();
  }

  function abandonTaskForReplan() {
    if (mem.siteLock) {
      mem.siteLock = null;
      mem.siteIgnoreUntil = tick + 70;
      mem.nav = null;
      return true;
    }

    if (!mem.task) return false;

    var t = mem.task;
    if (t.kind === "candidate") {
      var c = mem.cands[t.idx];
      if (c) {
        c.status = 0;
        c.minMode = Math.min(3, Math.max(num(c.minMode, 0),
                                         num(t.mode, 0) + 1));
      }
    } else if (t.kind === "grid") {
      if (t.idx >= 0 && t.idx < mem.gridBlocked.length) {
        mem.gridBlocked[t.idx] = true;
        mem.gridVisited[t.idx] = true;
      }
    } else if (t.kind === "free") {
      if (t.gridIndex >= 0 &&
          t.gridIndex < mem.gridVisited.length) {
        mem.gridVisited[t.gridIndex] = true;
      }
      mem.initialFreeDone = true;
    }

    mem.task = null;
    mem.nav = null;
    return true;
  }

  /* Handle a completed sample and choose whether to deliver it now. */
  var oldCarried = num(mem.lastCarried, carried);
  var sampleDone = carried > oldCarried;

  if (sampleDone) {
    var sampleX = mem.px, sampleY = mem.py;

    for (var mi = 0; mi < mem.cands.length; mi++) {
      var md = dist(sampleX, sampleY, mem.cands[mi].x, mem.cands[mi].y);
      if (md < 9) mem.cands[mi].status = 2;
    }

    if (mem.task && mem.task.kind === "candidate") {
      var sampledCandidate = mem.cands[mem.task.idx];
      if (sampledCandidate) {
        sampledCandidate.status =
          dist(sampleX, sampleY,
               sampledCandidate.x, sampledCandidate.y) < 32 ? 2 : 0;
      }
    }

    markGridNear(sampleX, sampleY, 14);
    mem.task = null;
    mem.siteLock = null;
    mem.nav = null;

