      tick - num(mem.siteLock.lastSeen, tick) > 45) {
    mem.siteLock = null;
    mem.nav = null;
  }

  if (docked) {
    mem.recoverTicks = 0;
  } else if (!!obs.bumped && !mem.prevBump &&
             drillProgress <= 0) {
    setRecovery();
    mem.nav = null;
  }
  mem.prevBump = !!obs.bumped;

  if (drillProgress > 0 && carried === 0) {
    return holdOutput(true);
  }

  if (!docked && mem.recoverTicks > 0) {
    return recoveryOutput();
  }

  updateTaskProgress();
  ensureTask();

  var homeD = beaconValid
    ? beaconDistance
    : dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeNeed = planNeed(homeD * 1.25 + 10, carried);

  if (docked && carried > 0) {
    return zeroOutput();
  }

  /* At the base, wait for enough charge, but replan infeasible sorties. */
  if (docked && carried === 0) {
    mem.returning = false;
    var canDepart = false;

    for (var attempt = 0; attempt < 10; attempt++) {
      ensureTask();
      var dockPath = currentPlanPath();

      if (!Number.isFinite(dockPath)) break;

      var dockNeed = planNeed(dockPath, 0);
      var timeBad = dockPath / 0.44 + 32 > timeLeft - 4;
      var energyBad = dockNeed + 0.02 >
                      num(mem.maxBattery, battery);

      if (timeBad || energyBad) {
        if (!abandonTaskForReplan()) break;
        continue;
      }

      if (battery + 0.005 < dockNeed + 0.02) {
        return zeroOutput();
      }

      canDepart = true;
      break;
    }

    if (!canDepart) return zeroOutput();
  } else if (!docked) {
    var mustReturn = !!mem.returning;

    if (carried > 0 &&
        !(liveSite && siteDistance < 3.5 &&
          carried < mem.capacity)) {
      mustReturn = true;
    }
    if (battery < 0.018) mustReturn = true;

    if (homeD > 2.7) {
      if (battery < homeNeed + 0.05) mustReturn = true;
      if (timeLeft < homeD / 0.40 + 14) mustReturn = true;

      if (!mustReturn) {
        var workPath = currentPlanPath();
        if (!Number.isFinite(workPath)) {
          mustReturn = true;
        } else {
          if (battery < planNeed(workPath, carried) + 0.045) {
            mustReturn = true;
          }
          if (timeLeft < workPath / 0.43 + 24) {
            mustReturn = true;
          }
        }
      }
    }

    if (mustReturn) {
      mem.returning = true;
      if (carried === 0 && mem.siteLock) {
        mem.siteLock = null;
        mem.nav = null;
      }
    } else {
      mem.returning = false;
    }
  }

  function skipSite() {
    mem.siteLock = null;
    mem.siteIgnoreUntil = tick + 85;
    mem.nav = null;
  }

  if (mem.returning) {
    if (beaconValid) {
      return navigateRelative(beaconBearing, beaconDistance,
                              1.75, 0.58, "HOME", null);
    }
    return navigatePoint(mem.baseX, mem.baseY,
                         1.75, 0.58, "HOME", null);
  }

  if (mem.siteLock && carried < mem.capacity) {
    var siteD, siteErr;

    if (liveSite) {
      siteD = siteDistance;
      siteErr = wrap(siteBearing);
    } else {
      var sdx = mem.siteLock.x - mem.px;
      var sdy = mem.siteLock.y - mem.py;
      siteD = Math.sqrt(sdx * sdx + sdy * sdy);
      siteErr = siteD > 0.04
        ? wrap(Math.atan2(sdy, sdx) * DEG - trueHeading)
        : 0;
    }

    if (siteD <= 1.32) {
      var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.14;
      var fresh = liveSite ||
        tick - num(mem.siteLock.lastSeen, tick) < 28;
      return holdOutput(!!(still && fresh && siteD <= 1.35));
    }

    return navigateRelative(siteErr, siteD, 1.12, 0.36,
                            "SITE", skipSite);
  }

  if (mem.task) {
    var t = mem.task;
    var tx, ty, stopRadius, key;

    if (t.kind === "grid") {
      tx = t.point.x;
      ty = t.point.y;
      stopRadius = 1.65;
      key = "T" + t.id + "_G";
    } else if (t.points && t.points[t.pointIndex]) {
      tx = t.points[t.pointIndex].x;
      ty = t.points[t.pointIndex].y;
      stopRadius = t.kind === "candidate" && t.stage === 0
        ? 1.55 : 1.30;
      key = "T" + t.id + "_" + t.kind + "_" +
            num(t.stage, 0) + "_" + num(t.pointIndex, 0);
    } else {
      finishTask();
      return docked ? zeroOutput() : holdOutput(false);
    }

    return navigatePoint(tx, ty, stopRadius, 0.53,
                         key, skipTaskTarget);
  }

  if (!docked && homeD > 2.7) {
    mem.returning = true;
    if (beaconValid) {
      return navigateRelative(beaconBearing, beaconDistance,
                              1.75, 0.58, "HOME", null);
    }
    return navigatePoint(mem.baseX, mem.baseY,
                         1.75, 0.58, "HOME", null);
  }

  return docked ? zeroOutput() : holdOutput(false);
