  var rawY = num(obs && obs.y, 200);
  var rawHeading = wrap(num(obs && obs.heading, 0));
  var wheelL = clamp(num(obs && obs.wheelLeft, 0), -3, 3);
  var wheelR = clamp(num(obs && obs.wheelRight, 0), -3, 3);
  var centerV = 0.5 * (wheelL + wheelR);
  var wheelTravel = 0.5 * (Math.abs(wheelL) + Math.abs(wheelR)) * DT;
