  var battery = Math.max(0, num(obs && obs.battery, 1));
  var solar = Math.max(0, num(obs && obs.solar, 0));
  var carried = Math.max(0, Math.floor(num(obs && obs.carried, 0)));
  var delivered = num(obs && obs.delivered, 0);
  var timeLeft = Math.max(0, num(obs && obs.timeLeft, 1200));
  var science = Math.max(0, num(obs && obs.science, 0));
