    mem.hEst = rawHeading;
    mem.headingBias = 0;
    mem.yawScale = 1;
    mem.compassStuck = false;
    mem.compassQuietYaw = 0;
    mem.compassBad = 0;
    mem.prevRawHeading = rawHeading;
    mem.prevWheelL = wheelL;
    mem.prevWheelR = wheelR;
    mem.track = null;

    mem.px = rawX;
    mem.py = rawY;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.gpsSame = 0;
    mem.gpsStale = false;
    mem.gpsStaleTravel = 0;

