    mem.maxBattery = Math.max(0.15, battery);
    mem.ePerM = 0.00065;
    mem.energyWindowTick = 0;
    mem.energyWindowBattery = battery;
    mem.energyWindowDistance = 0;

    mem.dockCheckTick = 0;
    mem.dockCheckBattery = battery;
    mem.wasDocked = false;

    mem.motorGainL = 3.0;
    mem.motorGainR = 3.0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastDrive = false;
    mem.lastV = 0;
    mem.lastOmega = 0;
    mem.lastAimAbs = rawHeading;

    mem.nav = null;
    mem.prevBump = false;
    mem.recoverTicks = 0;
    mem.recoverTotal = 24;
    mem.recoverSign = 1;

    mem.rayLast = [];
    mem.raySame = [];
    mem.rayStartX = [];
    mem.rayStartY = [];
    mem.rayStartHeading = [];
    mem.rayBad = [];

