      }

      mem.energyWindowTick = tick;
      mem.energyWindowBattery = battery;
      mem.energyWindowDistance = 0;
    }
  }
  mem.wasDocked = docked;
  mem.prevBattery = battery;

  /* Adapt inverse motor gains so weakened motors still receive useful commands. */
  function learnGain(cmd, actual, oldGain) {
    if (!mem.lastDrive ||
        Math.abs(cmd) < 0.12 ||
        Math.abs(actual) < 0.06 ||
        cmd * actual <= 0) {
      return oldGain;
    }

    var ratio = Math.abs(actual / cmd);
    if (ratio < 0.25 || ratio > 9) return oldGain;

    var alpha = ratio < oldGain ? 0.075 : 0.025;
    return clamp(oldGain + alpha * (ratio - oldGain), 0.55, 8);
  }

  mem.motorGainL = learnGain(num(mem.lastCmdL, 0), wheelL,
                             num(mem.motorGainL, 3.0));
  mem.motorGainR = learnGain(num(mem.lastCmdR, 0), wheelR,
                             num(mem.motorGainR, 3.0));

  /* Ignore range sensors that remain stuck at one finite reading. */
  var rawRays = Array.isArray(obs && obs.rays) ? obs.rays : [];
  var rays = [];

  for (var ri = 0; ri < 9; ri++) {
    var rd = num(rawRays[ri], 15);
    if (rd < 0 || rd > 15.2) rd = 15;
    rd = clamp(rd, 0, 15);

    if (mem.rayLast[ri] === undefined) {
      mem.rayLast[ri] = rd;
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayStartHeading[ri] = trueHeading;
      mem.rayBad[ri] = false;
    } else if (Math.abs(rd - mem.rayLast[ri]) < 0.015) {
      mem.raySame[ri] = num(mem.raySame[ri], 0) + 1;
      if (mem.raySame[ri] > 280 &&
          rd < 14.8 &&
          dist(mem.px, mem.py, mem.rayStartX[ri], mem.rayStartY[ri]) > 6 &&
          Math.abs(wrap(trueHeading -
                        num(mem.rayStartHeading[ri], trueHeading))) > 24) {
        mem.rayBad[ri] = true;
      }
    } else {
      if (mem.rayBad[ri] && Math.abs(rd - mem.rayLast[ri]) > 0.8) {
        mem.rayBad[ri] = false;
      }
      mem.raySame[ri] = 0;
      mem.rayStartX[ri] = mem.px;
      mem.rayStartY[ri] = mem.py;
      mem.rayStartHeading[ri] = trueHeading;
    }

    mem.rayLast[ri] = rd;
    rays[ri] = mem.rayBad[ri] ? 15 : rd;
  }

  var siteObj = obs && obs.site && typeof obs.site === "object"
    ? obs.site : null;
  var siteDistance = siteObj ? num(siteObj.distance, NaN) : NaN;
  var siteBearing = siteObj ? num(siteObj.bearing, NaN) : NaN;
  var liveSite = !!(siteObj &&
    Number.isFinite(siteDistance) &&
    Number.isFinite(siteBearing) &&
    siteDistance >= 0);

  var beacon = obs && obs.beacon && typeof obs.beacon === "object"
    ? obs.beacon : null;
  var beaconDistance = beacon ? num(beacon.distance, NaN) : NaN;
  var beaconBearing = beacon ? num(beacon.bearing, NaN) : NaN;
  var beaconValid = !!(beacon &&
    Number.isFinite(beaconDistance) &&
    Number.isFinite(beaconBearing) &&
    beaconDistance >= 0 &&
    beaconDistance <= 24);

  function emit(left, right, drill, v, omega, isDrive) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastDrive = !!isDrive;
    mem.lastV = Math.abs(num(v, 0));
    mem.lastOmega = num(omega, 0);
    return { left: left, right: right, drill: !!drill };
  }

  function wheelCommand(target, actual, gain) {
    gain = clamp(num(gain, 3.0), 0.55, 8);
    var cmd = target / gain + 0.16 * (target - actual);

    if (Math.abs(target) > 0.09 &&
        Math.abs(cmd) < 0.075 &&
        cmd * target >= 0) {
      cmd = target < 0 ? -0.075 : 0.075;
    }

    return clamp(cmd, -0.90, 0.90);
  }

  function drive(v, omega) {
    var leftTarget = clamp(v - 0.30 * omega, -1.15, 1.15);
    var rightTarget = clamp(v + 0.30 * omega, -1.15, 1.15);

    return emit(
      wheelCommand(leftTarget, wheelL, mem.motorGainL),
      wheelCommand(rightTarget, wheelR, mem.motorGainR),
      false, v, omega, true
    );
  }

  function zeroOutput() {
    return emit(0, 0, false, 0, 0, false);
  }

  function holdOutput(drill) {
    var slope = clamp(0.10 * Math.sin(rad(pitch)), -0.10, 0.10);
    var l = wheelCommand(0, wheelL, mem.motorGainL) + slope;
    var r = wheelCommand(0, wheelR, mem.motorGainR) + slope;

    return emit(clamp(l, -0.36, 0.36),
                clamp(r, -0.36, 0.36),
                !!drill, 0, 0, false);
  }

  function rayAt(angle) {
    var a = clamp(angle, -80, 80);
    var q = (a + 80) / 20;
    var i = Math.floor(q);
    var f = q - i;

    if (i >= 8) return rays[8];
    return Math.min(rays[i], rays[i + 1],
                    rays[i] * (1 - f) + rays[i + 1] * f);
  }

  function edgeDistance(relativeAngle) {
    var a = rad(trueHeading + relativeAngle);
    var dx = Math.cos(a);
    var dy = Math.sin(a);
    var best = 1e9;

    if (dx > 0.001) {
      best = Math.min(best, (mem.sizeX - 3 - mem.px) / dx);
    }
    if (dx < -0.001) {
      best = Math.min(best, (3 - mem.px) / dx);
    }
    if (dy > 0.001) {
      best = Math.min(best, (mem.sizeY - 3 - mem.py) / dy);
    }
    if (dy < -0.001) {
      best = Math.min(best, (3 - mem.py) / dy);
    }

    return Math.max(0, best);
  }

  function chooseAim(goalErr, speed) {
    var g = clamp(wrap(goalErr), -80, 80);
    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80,
                      g, clamp(g - 18, -80, 80),
                      clamp(g + 18, -80, 80),
                      clamp(g - 36, -80, 80),
                      clamp(g + 36, -80, 80)];
    var previousRel = wrap(num(mem.lastAimAbs, trueHeading) - trueHeading);
    var best = g;
    var bestCost = 1e30;

    for (var ci = 0; ci < candidates.length; ci++) {
      var c = candidates[ci];
      var duplicate = false;

      for (var cj = 0; cj < ci; cj++) {
        if (Math.abs(candidates[cj] - c) < 0.5) {
          duplicate = true;
          break;
        }
      }
      if (duplicate) continue;

      var goalDiff = Math.abs(wrap(c - goalErr));
      var cost = 0.008 * goalDiff * goalDiff;
      cost += 0.001 * Math.pow(Math.abs(wrap(c - previousRel)), 2);

      var clear = rayAt(c);
      var safe = 3.1 + 0.65 * clamp(Math.abs(speed), 0, 1);
      if (clear < safe) {
        var risk = (safe - clear) / safe;
        cost += 48 * risk * risk;
        if (clear < 1.35) cost += 60;
      }

      var edge = edgeDistance(c);
      if (edge < 5.0) {
        var edgeRisk = (5.0 - edge) / 5.0;
        cost += 34 * edgeRisk * edgeRisk;
        if (edge < 1.4) cost += 80;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = c;
      }
    }

    mem.lastAimAbs = wrap(trueHeading + best);
    return best;
  }

  function sideSign() {
    var right = 0;
    var left = 0;

    for (var i = 0; i < 4; i++) right += rays[i];
    for (var j = 5; j < 9; j++) left += rays[j];

    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    return tick % 2 === 0 ? 1 : -1;
  }

  function setRecovery() {
    mem.recoverTotal = 24;
    mem.recoverTicks = 24;
    mem.recoverSign = sideSign();
  }

  function recoveryOutput() {
    var total = num(mem.recoverTotal, 24);
    var remain = num(mem.recoverTicks, 0);
    var elapsed = total - remain;
    mem.recoverTicks = Math.max(0, remain - 1);

    if (elapsed < 9) return drive(-0.24, 0);

    var out = drive(0, num(mem.recoverSign, 1) * 0.72);

    if (mem.recoverTicks <= 0) {
      if (mem.nav) {
        mem.nav.startTick = tick;
        mem.nav.startDist = num(mem.nav.lastDist, mem.nav.startDist);
        mem.nav.commanded = 0;
        mem.nav.travel = 0;
      }
      mem.nav = null;
    }

    return out;
  }

  function monitorNavigation(key, d, stopRadius, onSkip) {
    if (!key || !Number.isFinite(d)) return false;

    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = {
        key: key,
        startTick: tick,
        startDist: d,
        lastDist: d,
        commanded: 0,
        travel: 0,
        failures: 0
      };
    }

    var nav = mem.nav;
    nav.commanded = num(nav.commanded, 0) + num(mem.lastV, 0) * DT;
    nav.travel = num(nav.travel, 0) + wheelTravel;
    nav.lastDist = d;

    if (tick - num(nav.startTick, tick) >= 240) {
      var improvement = num(nav.startDist, d) - d;
      var stalled = d > stopRadius + 2.2 &&
        improvement < 0.8 &&
        (num(nav.commanded, 0) > 3.5 || num(nav.travel, 0) > 3.5);

      if (stalled) {
        nav.failures = num(nav.failures, 0) + 1;
        nav.startTick = tick;
        nav.startDist = d;
        nav.commanded = 0;
        nav.travel = 0;
        setRecovery();

        if (nav.failures >= 3 && typeof onSkip === "function") {
          onSkip();
          mem.nav = null;
        }
        return true;
      }

      if (improvement > 1.6) {
        nav.failures = Math.max(0, num(nav.failures, 0) - 1);
      }

      nav.startTick = tick;
      nav.startDist = d;
      nav.commanded = 0;
      nav.travel = 0;
    }

    return false;
  }

  function navigateRelative(err, d, stopRadius, cruise, key, onSkip) {
    if (!Number.isFinite(d) || d < 0) return holdOutput(false);
    err = wrap(err);

    if (d <= stopRadius) return holdOutput(false);

    if (monitorNavigation(key, d, stopRadius, onSkip)) {
      return recoveryOutput();
    }

    if (Math.abs(err) > 100) {
      return drive(0, err > 0 ? 0.78 : -0.78);
    }

    var aim = chooseAim(err, centerV);
    var absAim = Math.abs(aim);
    var omega = clamp(1.30 * rad(aim), -0.78, 0.78);
    if (absAim < 1.0) omega = 0;

    var v = Math.min(cruise, Math.max(0.08, (d - stopRadius) * 0.34));

    if (absAim > 56) {
      v = 0;
    } else if (absAim > 34) {
      v *= 0.48;
    } else {
      v *= Math.max(0.22, Math.cos(rad(aim)));
    }

    var clear = rayAt(aim);
    if (clear < 3.6) {
      v *= clamp((clear - 0.95) / 2.65, 0, 1);
    }
    if (clear < 1.1) v = 0;

    var edge = edgeDistance(aim);
    if (edge < 4.8) {
      v = Math.min(v, clamp((edge - 0.9) * 0.18, 0, cruise));
    }
    if (edge < 1.0) v = 0;

    if (Math.abs(pitch) > 32) v = Math.min(v, 0.38);
    if (Math.abs(pitch) > 43) v = Math.min(v, 0.28);

    return drive(v, omega);
  }

  function navigatePoint(x, y, stopRadius, cruise, key, onSkip) {
    var dx = x - mem.px;
    var dy = y - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var err = d > 0.04
      ? wrap(Math.atan2(dy, dx) * DEG - trueHeading)
      : 0;

    return navigateRelative(err, d, stopRadius, cruise, key, onSkip);
  }

  function markGridNear(x, y, radius) {
    for (var i = 0; i < mem.gridNodes.length; i++) {
      if (dist(x, y, mem.gridNodes[i].x, mem.gridNodes[i].y) < radius) {
        mem.gridVisited[i] = true;
      }
    }
  }

  function rememberScan(x, y) {
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    var centers = Array.isArray(mem.scannedCenters) ? mem.scannedCenters : [];

    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < 18) {
        centers[i].x = 0.5 * (centers[i].x + x);
        centers[i].y = 0.5 * (centers[i].y + y);
        centers[i].tick = tick;
        mem.scannedCenters = centers;
        return;
      }
    }

    centers.push({ x: x, y: y, tick: tick });
    if (centers.length > 60) centers.shift();
    mem.scannedCenters = centers;
  }

  function scanNear(x, y, radius) {
    var centers = Array.isArray(mem.scannedCenters) ? mem.scannedCenters : [];
    for (var i = 0; i < centers.length; i++) {
      if (dist(x, y, centers[i].x, centers[i].y) < radius) return true;
    }
    return false;
  }

  function makeRing(cx, cy, radius, count, startAngle) {
    var pts = [];

    for (var i = 0; i < count; i++) {
      var a = startAngle + i * 2 * PI / count;
      var x = clamp(cx + radius * Math.cos(a), 3, mem.sizeX - 3);
      var y = clamp(cy + radius * Math.sin(a), 3, mem.sizeY - 3);

      if (pts.length === 0 ||
          dist(x, y, pts[pts.length - 1].x, pts[pts.length - 1].y) > 2.0) {
        pts.push({ x: x, y: y });
      }
    }

    return pts;
  }

  function startFreeSearch(x, y, gridIndex, baseline, radius, count) {
    mem.taskSerial = num(mem.taskSerial, 0) + 1;
    var startAngle = ((tick * 29 + Math.max(0, gridIndex + 1) * 71 +
                       Math.floor(x * 3 + y * 7)) % 360) * PI / 180;

    mem.task = {
      kind: "free",
      id: mem.taskSerial,
      gridIndex: gridIndex,
      centerX: x,
      centerY: y,
      points: makeRing(x, y, radius, count, startAngle),
      pointIndex: 0,
      baseScience: Math.max(0, num(baseline, science)),
      bestScience: Math.max(0, num(baseline, science)),
      bestX: mem.px,
      bestY: mem.py,
      depth: 0
    };

    if (gridIndex < 0) mem.initialFreeDone = true;
    rememberScan(x, y);
    mem.nav = null;
  }

  function startCandidate(idx) {
    var c = mem.cands[idx];
    if (!c) return false;

    c.status = 1;
    mem.taskSerial = num(mem.taskSerial, 0) + 1;
    mem.task = {
      kind: "cand",
      id: mem.taskSerial,
      idx: idx,
      stage: 0,
      centerX: c.x,
      centerY: c.y,
      points: [{ x: c.x, y: c.y }],
      pointIndex: 0,
      baseScience: 0,
      bestScience: 0,
      bestX: c.x,
      bestY: c.y,
      depth: 0
    };

    rememberScan(c.x, c.y);
    mem.nav = null;
    return true;
  }

  function startGrid(idx) {
    var n = mem.gridNodes[idx];
    if (!n) return false;

    mem.taskSerial = num(mem.taskSerial, 0) + 1;
    mem.task = {
      kind: "grid",
      id: mem.taskSerial,
      idx: idx,
      point: { x: n.x, y: n.y },
      baseScience: science
    };
    mem.nav = null;
    return true;
  }

  function finishTask() {
    var t = mem.task;
    if (!t) return;

    if (t.kind === "cand") {
      var c = mem.cands[t.idx];
      if (c && c.status === 1) c.status = 3;
      markGridNear(t.centerX, t.centerY, 12);
    } else if (t.kind === "grid") {
      if (t.idx >= 0 && t.idx < mem.gridVisited.length) {
        mem.gridVisited[t.idx] = true;
      }
    } else if (t.kind === "free" && t.gridIndex >= 0) {
      if (t.gridIndex < mem.gridVisited.length) {
        mem.gridVisited[t.gridIndex] = true;
      }
    }

    mem.task = null;
    mem.nav = null;
  }

  function continueSearchOrFinish(t) {
    var threshold = Math.max(0.025, Math.abs(num(t.baseScience, 0)) * 0.14);

    if (num(t.depth, 0) < 1 &&
        num(t.bestScience, 0) > num(t.baseScience, 0) + threshold) {
      t.depth = num(t.depth, 0) + 1;
      t.centerX = t.bestX;
      t.centerY = t.bestY;
      t.baseScience = t.bestScience;
      t.bestScience = t.baseScience;
      t.points = makeRing(t.centerX, t.centerY, 8, 8,
                          ((tick * 19 + t.id * 43) % 360) * PI / 180);
      t.pointIndex = 0;
      rememberScan(t.centerX, t.centerY);
      mem.nav = null;

      if (t.points.length > 0) return;
    }

    finishTask();
  }

  function skipTaskTarget() {
    var t = mem.task;
    if (!t) return;

    if (t.kind === "cand") {
      if (t.stage === 0) {
        var c = mem.cands[t.idx];
        if (c) c.status = 3;
        mem.task = null;
        mem.nav = null;
        return;
      }

      t.pointIndex++;
      if (t.pointIndex >= t.points.length) continueSearchOrFinish(t);
      else mem.nav = null;
      return;
    }

    if (t.kind === "grid") {
      if (t.idx >= 0 && t.idx < mem.gridBlocked.length) {
        mem.gridBlocked[t.idx] = true;
        mem.gridVisited[t.idx] = true;
      }
      mem.task = null;
      mem.nav = null;
      return;
    }

    if (t.kind === "free") {
      t.pointIndex++;
      if (t.pointIndex >= t.points.length) continueSearchOrFinish(t);
      else mem.nav = null;
    }
  }

  function updateTaskProgress() {
    if (mem.returning || carried > 0 || mem.siteLock ||
        drillProgress > 0 || !mem.task) return;

    var t = mem.task;

    if (t.kind === "cand") {
      var c = mem.cands[t.idx];
      if (!c || c.status !== 1) {
        mem.task = null;
        mem.nav = null;
        return;
      }

      if (t.stage === 0) {
        if (dist(mem.px, mem.py, t.centerX, t.centerY) < 2.4) {
          t.stage = 1;
          t.baseScience = science;
          t.bestScience = science;
          t.bestX = mem.px;
          t.bestY = mem.py;
          t.points = makeRing(t.centerX, t.centerY, 14, 12,
                              ((tick * 31 + t.idx * 97) % 360) *
                              PI / 180);
          t.pointIndex = 0;
          mem.nav = null;
          if (t.points.length === 0) finishTask();
        }
        return;
      }

      if (science > num(t.bestScience, -1) + 0.004) {
        t.bestScience = science;
        t.bestX = mem.px;
        t.bestY = mem.py;
      }

      var cp = t.points[t.pointIndex];
      if (!cp || dist(mem.px, mem.py, cp.x, cp.y) < 2.2) {
        if (cp) t.pointIndex++;
        if (t.pointIndex >= t.points.length) {
          continueSearchOrFinish(t);
        } else if (cp) {
          mem.nav = null;
        }
      }
      return;
    }

    if (t.kind === "grid") {
      if (dist(mem.px, mem.py, t.point.x, t.point.y) < 2.2) {
        if (t.idx >= 0 && t.idx < mem.gridVisited.length) {
          mem.gridVisited[t.idx] = true;
        }

        var gx = t.point.x;
        var gy = t.point.y;
        var gi = t.idx;
        var usefulSignal = science > 0.07 &&
                           !scanNear(gx, gy, 28);

        if (usefulSignal) {
          startFreeSearch(gx, gy, gi, science, 12, 8);
        } else {
          mem.task = null;
          mem.nav = null;
        }
      }
      return;
    }

    if (t.kind === "free") {
      if (science > num(t.bestScience, -1) + 0.004) {
        t.bestScience = science;
        t.bestX = mem.px;
        t.bestY = mem.py;
      }

      var fp = t.points[t.pointIndex];
      if (!fp || dist(mem.px, mem.py, fp.x, fp.y) < 2.1) {
        if (fp) t.pointIndex++;
        if (t.pointIndex >= t.points.length) {
          continueSearchOrFinish(t);
        } else if (fp) {
          mem.nav = null;
        }
      }
    }
  }

  function pointRoute(points, index) {
    if (!points || points.length === 0) {
      return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 12;
    }

    if (index >= points.length) {
      return dist(mem.px, mem.py, mem.baseX, mem.baseY) + 12;
    }

    var total = dist(mem.px, mem.py, points[index].x, points[index].y);
    var prevX = points[index].x;
    var prevY = points[index].y;

    for (var i = index + 1; i < points.length; i++) {
      total += dist(prevX, prevY, points[i].x, points[i].y);
      prevX = points[i].x;
      prevY = points[i].y;
    }

    var last = points[points.length - 1];
    return total + dist(last.x, last.y, mem.baseX, mem.baseY) + 18;
  }

  function currentTaskPath() {
    var t = mem.task;
    if (!t) return Infinity;

    if (t.kind === "cand") {
      if (t.stage === 0) {
        return dist(mem.px, mem.py, t.centerX, t.centerY) +
               100 +
               dist(t.centerX, t.centerY, mem.baseX, mem.baseY) + 20;
      }
      return pointRoute(t.points, t.pointIndex);
    }

    if (t.kind === "grid") {
      return dist(mem.px, mem.py, t.point.x, t.point.y) +
             dist(t.point.x, t.point.y, mem.baseX, mem.baseY) + 28;
    }

    if (t.kind === "free") {
      return pointRoute(t.points, t.pointIndex);
    }

    return Infinity;
  }

  function currentPlanPath() {
    if (mem.siteLock) {
      var siteD = liveSite
        ? siteDistance
        : dist(mem.px, mem.py, mem.siteLock.x, mem.siteLock.y);
      return siteD +
             dist(mem.siteLock.x, mem.siteLock.y, mem.baseX, mem.baseY) + 20;
    }

    return currentTaskPath();
  }

  function energyNeed(path, load) {
    if (!Number.isFinite(path)) return Infinity;
    var n = Math.max(0, load || 0);
    var e = Math.max(0.0004, num(mem.ePerM, 0.00065));
    return 0.10 + Math.max(0, path) * e * (1.72 + 0.20 * n) +
           0.025 * n;
  }

  function timeNeed(path) {
    if (!Number.isFinite(path)) return Infinity;
    return path / 0.48 + 38;
  }

  function chooseCandidate() {
    if (carried > 0) return false;

    var available = docked
      ? num(mem.maxBattery, battery)
      : battery;

    var best = -1;
    var bestScore = -1;

    for (var i = 0; i < mem.cands.length; i++) {
      var c = mem.cands[i];
      if (c.status !== 0) continue;

      var out = dist(mem.px, mem.py, c.x, c.y);
      var back = dist(c.x, c.y, mem.baseX, mem.baseY);
