  if (dt > 0) {
    var avgL = (mem.prevVL + vL) * 0.5;
    var avgR = (mem.prevVR + vR) * 0.5;
    dsNow = (avgL + avgR) * 0.5 * dt;
    yawNow = (avgR - avgL) / WB * dt * DEG;
    var midAng = (mem.head + yawNow * 0.5) * RAD;
    mem.x += dsNow * Math.cos(midAng);
    mem.y += dsNow * Math.sin(midAng);
    mem.head = wrap(mem.head + yawNow);
    mem.turnSinceCal += Math.abs(yawNow);
    if (Math.abs(dsNow) > 0.005) {
      mem.driveDist += Math.abs(dsNow);
      mem.driveTime += dt;
    }
  }

  var rawHead = +obs.heading;
  if (!isFinite(rawHead)) rawHead = mem.lastRaw;
  var rawDelta = wrap(rawHead - mem.lastRaw);
  if (dt > 0) {
    if (Math.abs(wrap(rawDelta - yawNow)) > 42 && Math.abs(yawNow) < 25) {
      mem.compassFaultT = t;
    }
    var compHead = wrap(rawHead - mem.bias);
    var headErr = wrap(compHead - mem.head);
    if (Math.abs(headErr) < 38) {
      mem.head = wrap(mem.head + clamp(headErr, -8, 8) * 0.07);
    } else if (Math.abs(headErr) < 70 && Math.abs(vL) + Math.abs(vR) < 0.15) {
      mem.head = wrap(mem.head + clamp(headErr, -5, 5) * 0.04);
    }
  }
  mem.lastRaw = rawHead;

  var gx = +obs.x, gy = +obs.y;
  if (isFinite(gx) && isFinite(gy)) {
    var sameGps = Math.abs(gx - mem.lastGpsX) < 0.0001 && Math.abs(gy - mem.lastGpsY) < 0.0001;
    if (!sameGps) {
      var gerrX = gx - mem.x, gerrY = gy - mem.y;
      var gerr = hyp(gerrX, gerrY);
      if (gerr > 50) {
        mem.x = gx;
        mem.y = gy;
      } else {
        var ga = gerr < 0.8 ? 0.30 : (gerr < 5 ? 0.72 : 0.92);
        mem.x += gerrX * ga;
        mem.y += gerrY * ga;
      }

      var cdx = gx - mem.calX, cdy = gy - mem.calY;
      var cd = hyp(cdx, cdy);
      if (cd > 1.2 && cd < 50 && mem.turnSinceCal < 28) {
        var course = Math.atan2(cdy, cdx) * DEG;
        var hCorr = wrap(course - mem.head);
        if (Math.abs(hCorr) < 55) {
          mem.head = wrap(mem.head + hCorr * 0.55);
          if (t - mem.compassFaultT > 2.0) mem.bias = wrap(rawHead - mem.head);
        }
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      } else if (cd > 50 || mem.turnSinceCal > 65) {
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      }

      mem.lastGpsX = gx;
      mem.lastGpsY = gy;
      mem.lastGpsT = t;
      if (mem.gpsFrozen) {
        mem.gpsFrozen = false;
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      }
    } else {
      if (speedAbs > 0.25 && t - mem.lastGpsT > 1.8) mem.gpsFrozen = true;
    }
  }

  if (dt > 0 && mem.lastBatt != null && isFinite(+obs.battery)) {
    var drain = mem.lastBatt - (+obs.battery);
    if (Math.abs(dsNow) > 0.02 && drain > -0.001 && drain < 0.5 && !obs.docked) {
      var gross = drain + (isFinite(+obs.solar) ? +obs.solar : 0) * dt;
      if (gross > 0.000001) {
        var per = gross / Math.abs(dsNow);
        if (per > 0.00005 && per < 0.05) {
          mem.perM = mem.perM * 0.985 + per * 0.015;
        }
      }
    }
  }
  if (isFinite(+obs.battery)) mem.lastBatt = +obs.battery;
  if (mem.driveTime > 12) mem.avgSpeed = clamp(mem.driveDist / mem.driveTime, 0.4, 2.5);

  var rawRays = obs.rays || [];
  var rays = [];
  for (var ri = 0; ri < 9; ri++) {
    var rr = +rawRays[ri];
    if (!isFinite(rr) || rr < 0) rr = 15;
    if (rr > 15) rr = 15;

    if (rr < 0.25) mem.rayLowT[ri] += dt;
    else mem.rayLowT[ri] = 0;

    if (mem.rayIgnoreUntil[ri] > t && rr > 2.0) {
      mem.rayIgnoreUntil[ri] = -999;
      mem.rayLowT[ri] = 0;
    }
    if (mem.rayLowT[ri] > 5.5 && Math.abs(speedF) > 0.25 && !obs.bumped && t > mem.recoverUntil + 0.5) {
      if (ri >= 2 && ri <= 6) mem.rayIgnoreUntil[ri] = t + 15;
    }

    if (mem.rayIgnoreUntil[ri] > t) rr = 15;
    rays.push(rr);
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    var pos = (a + 80) / 20;
    var i0 = Math.floor(pos);
    if (i0 < 0) i0 = 0;
    if (i0 > 7) i0 = 7;
    var f = pos - i0;
    return rays[i0] * (1 - f) + rays[i0 + 1] * f;
  }

  var dBase = hyp(mem.x - mem.base.x, mem.y - mem.base.y);
  var carried = obs.carried || 0;
  var cap = mem.cap || 5;
  var perM = Math.max(0.00045, mem.perM || 0.001);
  var avgSp = clamp(mem.avgSpeed || 1.0, 0.45, 2.5);
  var timeToBase = dBase / Math.max(0.62, avgSp * 0.85) + 14;
  var battNeed = 0.06 + dBase * perM * 1.85 * (1 + 0.15 * carried) + carried * 0.008;
  var mustReturn = false;
  if (carried >= cap) mustReturn = true;
  if (carried > 0) {
    if (obs.timeLeft < timeToBase * 1.28 + 16) mustReturn = true;
    if (obs.battery < battNeed) mustReturn = true;
  } else {
    if (obs.battery < 0.085 && dBase > 12) mustReturn = true;
    if (obs.battery < 0.03) mustReturn = true;
  }
  var drillingNow = !!(mem.mode === "sample" && mem.sample && mem.sample.drilling);

  function motorCmd(tL, tR, hold) {
    var maxW = 2.8;
    tL = clamp(tL, -maxW, maxW);
    tR = clamp(tR, -maxW, maxW);

    var cm = hold ? 1 : 0;
    if (mem.ctrlHold !== cm) {
      mem.intL = 0;
      mem.intR = 0;
      mem.ctrlHold = cm;
    }

    var eL = tL - vL;
    var eR = tR - vR;
    var kp = hold ? 1.10 : 0.58;
    var ki = hold ? 1.75 : 0.80;

    if (dt > 0) {
      mem.intL = clamp((mem.intL || 0) * 0.985 + eL * dt * ki, -0.8, 0.8);
      mem.intR = clamp((mem.intR || 0) * 0.985 + eR * dt * ki, -0.8, 0.8);
    }

    var pitch = +obs.pitch || 0;
    var slope = (hold ? 0.34 : 0.075) * Math.sin(pitch * RAD);

    var uL = tL / maxW + kp * eL + mem.intL + slope;
    var uR = tR / maxW + kp * eR + mem.intR + slope;

    if (tL > 0.03 && uL < 0.035) uL = 0.035;
    if (tL < -0.03 && uL > -0.035) uL = -0.035;
    if (tR > 0.03 && uR < 0.035) uR = 0.035;
    if (tR < -0.03 && uR > -0.035) uR = -0.035;

    return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1) };
  }

  function holdPoint(hx, hy, drillFlag) {
    var ex = hx - mem.x, ey = hy - mem.y;
    var err = hyp(ex, ey);
    var vx = 0, vy = 0;
    if (err > 0.045) {
      vx = clamp(ex * 0.85, -0.12, 0.12);
      vy = clamp(ey * 0.85, -0.12, 0.12);
    }
    var ch = Math.cos(mem.head * RAD), sh = Math.sin(mem.head * RAD);
    var fwd = vx * ch + vy * sh;
    var lat = -vx * sh + vy * ch;
    var vCmd = clamp(fwd, -0.10, 0.10);
    var yawCmd = clamp(lat * 1.55, -0.55, 0.55);
    var tL = vCmd - yawCmd * 0.3;
    var tR = vCmd + yawCmd * 0.3;
    var cmd = motorCmd(tL, tR, true);
    return { left: cmd.left, right: cmd.right, drill: !!drillFlag, speed: Math.abs(vCmd) + Math.abs(yawCmd) * 0.3 };
  }

  function navRel(relIn, dist, vmax, arrive) {
    var desiredRel = wrap(relIn);
    var speedNow = (vL + vR) * 0.5;
    var absSpeedNow = Math.abs(speedNow);

    if (dist <= arrive) {
      mem.lastDesired = 0;
      var hc0 = motorCmd(0, 0, true);
      return { left: hc0.left, right: hc0.right, speed: 0, c: 0, clear: 15, dist: dist };
    }

    var emClear = Math.min(rays[3], rays[4], rays[5]);
    if (speedNow > 0.22 && emClear < 0.90 + 0.68 * absSpeedNow) {
      var leftClearE = rays[6] + rays[7] + rays[8];
      var rightClearE = rays[0] + rays[1] + rays[2];
      var dirE = leftClearE >= rightClearE ? 1 : -1;
      var vB = -Math.min(0.85, 0.16 + 0.46 * absSpeedNow);
      var omegaB = dirE * 1.8;
      var cmdB = motorCmd(vB - omegaB * 0.3, vB + omegaB * 0.3, false);
      mem.lastDesired = Math.max(Math.abs(vB), 0.45);
      return { left: cmdB.left, right: cmdB.right, speed: vB, c: dirE * 80, clear: emClear, dist: dist };
    }

    var bestC = 0, bestScore = -1e12, bestClear = 0;
    for (var c = -80; c <= 80; c += 10) {
      var r0 = rayAt(c);
      var r1 = rayAt(c - 18);
      var r2 = rayAt(c + 18);
      var cl = Math.min(r0, r1 * 0.92, r2 * 0.92);
      if (cl < 0) cl = 0;

      var align = Math.abs(wrap(c - desiredRel));
      var score = Math.min(Math.max(cl - 0.15, 0), 10) * 2.3 - align * 0.11;
      if (cl < 0.8) score -= 70;
      else if (cl < 1.3) score -= 22;
      else if (cl < 2.2) score -= 6;
      else if (cl < 3.2) score -= 1;

      var aa = (mem.head + c) * RAD;
      var look = Math.min(3.2, Math.max(0.6, cl));
      var px = mem.x + Math.cos(aa) * look;
      var py = mem.y + Math.sin(aa) * look;
      if (px < 1.2 || px > mem.sizeX - 1.2 || py < 1.2 || py > mem.sizeY - 1.2) score -= 100;

      if (t < mem.avoidUntil) {
        if (c * mem.avoidDir > 0) score += 2.5;
        else if (c * mem.avoidDir < 0) score -= 0.5;
      }

      if (score > bestScore) {
        bestScore = score;
        bestC = c;
        bestClear = cl;
      }
    }

    var c2 = bestC;
    var absC = Math.abs(c2);
    var v = vmax;
    var remain = dist - arrive;
    if (remain < 6) v = Math.min(v, Math.max(0.04, remain * 0.65));
    else if (remain < 10) v = Math.min(v, 1.2);

    if (absC > 72) v = Math.min(v, 0.18);
    else if (absC > 55) v = Math.min(v, 0.55);
    else if (absC > 35) v = Math.min(v, 0.95);
    else if (absC > 20) v = Math.min(v, 1.55);

    var clearAhead = Math.min(rayAt(c2), rayAt(c2 - 20), rayAt(c2 + 20));
    var allowed;
    if (clearAhead < 0.7) allowed = 0;
    else if (clearAhead < 1.2) allowed = (clearAhead - 0.7) * 0.28;
    else if (clearAhead < 2.2) allowed = 0.14 + (clearAhead - 1.2) * 0.55;
    else if (clearAhead < 3.5) allowed = 0.69 + (clearAhead - 2.2) * 0.65;
    else if (clearAhead < 5.0) allowed = 1.535 + (clearAhead - 3.5) * 0.50;
    else allowed = vmax;
    v = Math.min(v, allowed);

    if (absSpeedNow > 0.35 && clearAhead < 1.1 + 0.55 * absSpeedNow) {
      v = Math.min(v, -0.05);
    }
    if (Math.abs(desiredRel) > 105) v = Math.min(v, 0);

    var omega = clamp(c2 * 0.030, -1.9, 1.9);
    if (Math.abs(c2) < 2) omega = 0;

    if (v < -0.01) {
      var cmdB2 = motorCmd(v - omega * 0.3, v + omega * 0.3, false);
      mem.lastDesired = Math.max(Math.abs(v), Math.abs(omega) * 0.3);
      return { left: cmdB2.left, right: cmdB2.right, speed: v, c: c2, clear: clearAhead, dist: dist };
    }

    if (v < 0.03 && Math.abs(desiredRel) > 10) {
      var turnC = c2;
      if (Math.abs(turnC) < 8) turnC = desiredRel >= 0 ? 18 : -18;
      var omegaP = clamp(turnC * 0.025, -1.5, 1.5);
      var tLp = -omegaP * 0.3;
      var tRp = omegaP * 0.3;
      var cmdP = motorCmd(tLp, tRp, true);
      mem.lastDesired = Math.abs(omegaP) * 0.3;
      if (bestClear < 2.5 && absC > 10) {
        mem.avoidDir = c2 > 0 ? 1 : -1;
        mem.avoidUntil = Math.max(mem.avoidUntil, t + 1.2);
      }
      return { left: cmdP.left, right: cmdP.right, speed: 0, c: c2, clear: clearAhead, dist: dist };
    }

    var tL = v - omega * 0.3;
    var tR = v + omega * 0.3;
    var cmd = motorCmd(tL, tR, v < 0.12);
    mem.lastDesired = Math.max(Math.abs(v), Math.abs(omega) * 0.3);

    if (bestClear < 2.5 && absC > 10) {
      mem.avoidDir = c2 > 0 ? 1 : -1;
      mem.avoidUntil = Math.max(mem.avoidUntil, t + 1.2);
    } else if (bestClear > 4.5 && Math.abs(desiredRel) < 25) {
      mem.avoidUntil = -999;
    }

    return { left: cmd.left, right: cmd.right, speed: v, c: c2, clear: clearAhead, dist: dist };
  }

  function navTo(tx, ty, vmax, arrive) {
    var dx = tx - mem.x, dy = ty - mem.y;
    var d = hyp(dx, dy);
    if (d < arrive) {
      mem.lastDesired = 0;
      var h0 = motorCmd(0, 0, true);
      return { left: h0.left, right: h0.right, speed: 0, c: 0, clear: 15, dist: d };
    }
    var desired = Math.atan2(dy, dx) * DEG;
    return navRel(wrap(desired - mem.head), d, vmax, arrive);
  }

  function navBase(vmax) {
    if (obs.beacon && isFinite(+obs.beacon.distance) && isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
      return navRel(+obs.beacon.bearing, +obs.beacon.distance, vmax, 0.55);
    }
    return navTo(mem.base.x, mem.base.y, vmax, 0.55);
  }

  function markHintsNear(px, py) {
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status === 2) continue;
      if (hyp(h.x - px, h.y - py) < 35) h.status = 2;
    }
  }

  function clearActiveToZero() {
    if (mem.activeHint && !mem.activeHint.temp && mem.activeHint.status === 1) mem.activeHint.status = 0;
    mem.activeHint = null;
    mem.search = null;
  }

  function startReturn() {
    if (mem.sample && mem.sample.drilling) return;
    if (mem.activeHint && !mem.activeHint.temp && mem.activeHint.status === 1) mem.activeHint.status = 0;
    mem.activeHint = null;
    mem.search = null;
    if (mem.sample && !mem.sample.drilling) mem.sample = null;
    mem.mode = "return";
  }

  function beginSample(siteObs) {
    var dist = +siteObs.distance || 0;
    var rel = +siteObs.bearing || 0;
    var aa = (mem.head + rel) * RAD;
    var sx = mem.x + Math.cos(aa) * dist;
    var sy = mem.y + Math.sin(aa) * dist;
    mem.sample = {
      x: sx,
      y: sy,
      value: +siteObs.value || 0,
      startCarried: obs.carried || 0,
      startT: t,
      lastSeen: t,
      drilling: false,
      drillStart: 0,
      holdX: mem.x,
      holdY: mem.y,
      fails: 0
    };
    mem.mode = "sample";
    return { left: 0, right: 0, drill: false };
  }

  if (obs.bumped && t > mem.bumpAck && !drillingNow) {
    mem.bumpAck = t + 1.5;
    mem.recoverUntil = t + 1.0;
    var leftC0 = rays[6] + rays[7] + rays[8];
    var rightC0 = rays[0] + rays[1] + rays[2];
    mem.recoverTurn = leftC0 >= rightC0 ? 1 : -1;
    mem.lastProgressX = mem.x;
    mem.lastProgressY = mem.y;
    mem.lastProgressT = t;
    mem.avoidUntil = -999;
  }

  if (t < mem.recoverUntil && !drillingNow) {
    var dirR = mem.recoverTurn || 1;
    var vR0 = -0.38;
    var omR = dirR * 1.3;
    var cmdRec = motorCmd(vR0 - omR * 0.3, vR0 + omR * 0.3, false);
    mem.lastDesired = Math.abs(vR0) + Math.abs(omR) * 0.3;
    return { left: cmdRec.left, right: cmdRec.right, drill: false };
  }

  var progMoved = hyp(mem.x - mem.lastProgressX, mem.y - mem.lastProgressY);
  if (progMoved > 0.8) {
    mem.lastProgressX = mem.x;
    mem.lastProgressY = mem.y;
    mem.lastProgressT = t;
  }
  if (!drillingNow && mem.mode !== "dock" &&
      t - mem.lastProgressT > 5.0 &&
      Math.abs(vL) + Math.abs(vR) < 0.18 &&
      mem.lastDesired > 0.25 &&
      t > mem.recoverUntil + 1.0) {
    mem.recoverUntil = t + 1.0;
    mem.recoverTurn = -(mem.recoverTurn || 1);
    mem.lastProgressX = mem.x;
    mem.lastProgressY = mem.y;
    mem.lastProgressT = t;
    var cmdStuck = motorCmd(-0.42 - mem.recoverTurn * 0.36, -0.42 + mem.recoverTurn * 0.36, false);
    mem.lastDesired = 0.8;
    return { left: cmdStuck.left, right: cmdStuck.right, drill: false };
  }

  if (mem.mode === "return") {
    if (dBase <= 2.85) {
      mem.mode = "dock";
      mem.dockStart = null;
      mem.dockLastBatt = obs.battery;
      mem.dockLastT = t;
      mem.dockPlateau = false;
      var hR0 = motorCmd(0, 0, true);
      mem.lastDesired = 0;
      return { left: hR0.left, right: hR0.right, drill: false };
    }
    var vRet = carried > 0 ? 1.8 : 2.0;
    if (dBase < 10) vRet = Math.min(vRet, 0.95);
    var navRet = navBase(vRet);
    return { left: navRet.left, right: navRet.right, drill: false };
  }

  if (mem.mode === "dock") {
    if (dBase > 3.35) {
      mem.mode = "return";
      var hOut = motorCmd(0, 0, true);
      mem.lastDesired = 0;
      return { left: hOut.left, right: hOut.right, drill: false };
    }

    if (mem.dockStart == null) {
      mem.dockStart = t;
      mem.dockLastBatt = obs.battery;
      mem.dockLastT = t;
      mem.dockPlateau = false;
    }

    if (dBase > 2.75) {
      var navD0 = navBase(0.55);
      return { left: navD0.left, right: navD0.right, drill: false };
    }

    if (carried > 0) {
      var hUnload = holdPoint(mem.base.x, mem.base.y, false);
      mem.lastDesired = 0;
      return { left: hUnload.left, right: hUnload.right, drill: false };
    }

    if (t - mem.dockLastT > 2.2) {
      if (obs.battery - mem.dockLastBatt < 0.0012) mem.dockPlateau = true;
      else mem.dockPlateau = false;
      mem.dockLastBatt = obs.battery;
      mem.dockLastT = t;
    }

    var targetB = 0.92;
    if (obs.timeLeft < 300) targetB = 0.75;
    if (obs.timeLeft < 130) targetB = 0.50;
    if (obs.timeLeft < 45) targetB = 0.0;

    var waitCharge = (obs.battery < targetB &&
                      obs.timeLeft > 28 &&
                      !mem.dockPlateau &&
                      (t - mem.dockStart < 65));

    if (waitCharge) {
      var hWait = holdPoint(mem.x, mem.y, false);
      mem.lastDesired = 0;
      return { left: hWait.left, right: hWait.right, drill: false };
    }

    mem.mode = "choose";
    mem.dockStart = null;
    clearActiveToZero();
    var hLeave = holdPoint(mem.x, mem.y, false);
    mem.lastDesired = 0;
    return { left: hLeave.left, right: hLeave.right, drill: false };
  }

  if (mem.mode === "sample" && mem.sample) {
    var S = mem.sample;

    if ((obs.carried || 0) > S.startCarried) {
      markHintsNear(mem.x, mem.y);
      if (mem.activeHint && !mem.activeHint.temp && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.activeHint = null;
      mem.search = null;
      mem.sample = null;
      var newCarried = obs.carried || 0;
      if (newCarried >= cap || mustReturn) {
        mem.mode = "return";
      } else {
        mem.mode = "choose";
      }
      var hDone0 = motorCmd(0, 0, true);
      mem.lastDesired = 0;
      return { left: hDone0.left, right: hDone0.right, drill: false };
    }

    if (mustReturn && !S.drilling) {
      startReturn();
      var hAbort0 = motorCmd(0, 0, true);
      mem.lastDesired = 0;
      return { left: hAbort0.left, right: hAbort0.right, drill: false };
    }

    if (S.drilling) {
      var urgentDrill = (obs.timeLeft < dBase / 0.55 + 5 + 6) ||
                        (obs.battery < 0.035 + dBase * perM + 0.015);
      if (urgentDrill) {
        S.drilling = false;
        startReturn();
        var hUrg = motorCmd(0, 0, true);
        mem.lastDesired = 0;
        return { left: hUrg.left, right: hUrg.right, drill: false };
      }
    }

    var visible = !!(obs.site && isFinite(+obs.site.distance));
    var distS = hyp(S.x - mem.x, S.y - mem.y);

    if (visible) {
      var wAng = (mem.head + (+obs.site.bearing || 0)) * RAD;
      var wx = mem.x + Math.cos(wAng) * (+obs.site.distance || 0);
      var wy = mem.y + Math.sin(wAng) * (+obs.site.distance || 0);
      var wdd = hyp(wx - S.x, wy - S.y);
      if (wdd < 12 || t - S.lastSeen > 2.0) {
        S.x = S.x * 0.58 + wx * 0.42;
        S.y = S.y * 0.58 + wy * 0.42;
      }
      S.lastSeen = t;
      S.value = +obs.site.value || S.value;
      distS = +obs.site.distance || distS;
    }

    var wheelMag = Math.max(Math.abs(vL), Math.abs(vR));

    if (S.drilling) {
      var progress = obs.drilling || 0;
      if (distS > 1.78 && progress < 5.4) {
        S.drilling = false;
      } else {
        if (t - S.drillStart > 10.5 && progress < 0.4) {
