    if (bestH) {
      bestH.status = 1;
      mem.activeHint = bestH;
      mem.target = {
        type: "hint",
        hint: bestH,
        x: bestH.x,
        y: bestH.y
      };
      mem.mode = "goto";
      mem.targetStart = t;
      mem.lastProgressX = mem.x;
      mem.lastProgressY = mem.y;
      mem.lastProgressT = t;
      var cmdPick = drive(0, 0, true);
      return { left: cmdPick.left, right: cmdPick.right, drill: false };
    }

    if (carried > 0) {
      mem.mode = "return";
      mem.dockStart = null;
