        }
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      } else if (cd > 28 || mem.turnSinceCal > 65) {
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      }

