    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  if (t < mem.recoverUntil && mem.mode !== "drill") {
    var rec = drive(-0.23, (mem.recoverDir || 1) * 0.92, false);
    return { left: rec.left, right: rec.right, drill: false };
  }

  // Progress / stuck detection.
  if (dt > 0) {
    var prog = hyp(mem.x - mem.lastProgX, mem.y - mem.lastProgY);
    if (prog > 0.45) {
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      mem.stuckCount = 0;
    }
  }

  var movingMode = (mem.mode === "goto" || mem.mode === "search" ||
                    mem.mode === "return" || mem.mode === "explore" ||
                    mem.mode === "approach");
  if (mem.mode !== "drill" && mem.mode !== "dock" && movingMode &&
      t - mem.lastProgT > 4.5 && mem.lastCmdSpeed > 0.12 &&
      maxWheel < 0.08 && t > mem.recoverUntil + 0.6) {
    mem.stuckCount++;
    mem.recoverUntil = t + 0.90;
    mem.recoverDir = -mem.recoverDir || 1;
    mem.lastProgT = t;
    if (mem.stuckCount >= 3) {
      if (mem.mode === "goto" || mem.mode === "search") {
        if (mem.activeHint) mem.activeHint.status = 3;
        mem.activeHint = null;
        mem.search = null;
      } else if (mem.mode === "explore" && mem.target && mem.target.point) {
        mem.target.point.done = true;
      } else if (mem.mode === "approach") {
        mem.cooldownUntil = t + 2.0;
        if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      }
      mem.mode = "choose";
      mem.target = null;
      mem.stuckCount = 0;
    }
    var rec2 = drive(-0.24, (mem.recoverDir || 1) * 0.95, false);
    return { left: rec2.left, right: rec2.right, drill: false };
  }

  var carried = +obs.carried || 0;
  var cap = mem.cap || 5;
  var dBase = getBaseDist();
  var batteryNow = isFinite(+obs.battery) ? +obs.battery : 1;
  var perNow = Math.max(0.0008, mem.perM || 0.0018);

  // Drill mode must be handled before anything else, except recovery (which is skipped for drill).
  if (mem.mode === "drill") {
    var S = mem.sample;
    if (!S) {
      mem.mode = "choose";
      var oNo = brakeCmd();
      return { left: oNo.left, right: oNo.right, drill: false };
    }

    if (carried > S.startCarried) {
      markSampleSuccess();
      var oSucc = brakeCmd();
      return { left: oSucc.left, right: oSucc.right, drill: false };
    }

    var p = isFinite(+obs.drilling) ? +obs.drilling : 0;
    if (p > S.maxProg + 0.02) {
      S.maxProg = p;
      S.lastProgT = t;
    }

    var reserveDrill = 0.035 + dBase * perNow * 2.25 + 0.018;
    var urgentDrill = (obs.timeLeft < dBase / 0.35 + 8) ||
                      (p < 5.75 && batteryNow < reserveDrill);

    if (urgentDrill && p < 5.75) {
      mem.sample = null;
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.mode = "return";
      var oUrg = brakeCmd();
      return { left: oUrg.left, right: oUrg.right, drill: false };
    }

    var dNow = 99;
    if (obs.site && isFinite(+obs.site.distance)) {
      dNow = +obs.site.distance;
      S.lastSeen = t;
      S.lastDist = dNow;
    } else {
      dNow = S.lastDist != null ? S.lastDist : 99;
    }

    if (!obs.site && t - S.lastSeen > 1.8 && p < 5.75) {
      mem.sample = null;
      mem.mode = "approach";
      mem.cooldownUntil = t + 0.7;
      var oLostD = brakeCmd();
      return { left: oLostD.left, right: oLostD.right, drill: false };
    }

    if (p < 5.55 && dNow > 1.56) {
      mem.sample = null;
      mem.mode = "approach";
      mem.cooldownUntil = t + 0.7;
      var oFarD = brakeCmd();
      return { left: oFarD.left, right: oFarD.right, drill: false };
    }

    var stall = t - S.lastProgT;
    if (p < 5.55 && t - S.startT > 2.0 && stall > 2.0) {
      mem.sample = null;
      mem.mode = "approach";
      mem.cooldownUntil = t + 1.2;
      var oFailD = brakeCmd();
      return { left: oFailD.left, right: oFailD.right, drill: false };
    }

    if (p < 5.55 && t - S.startT > 16.0) {
      mem.sample = null;
      mem.mode = "approach";
      mem.cooldownUntil = t + 1.5;
      var oLongD = brakeCmd();
      return { left: oLongD.left, right: oLongD.right, drill: false };
    }

    var outD;
    if (obs.site && p < 5.80 && dNow > 1.36) {
      var relD = +obs.site.bearing || 0;
      var creepV = Math.min(0.052, Math.max(0.0, (dNow - 1.24) * 0.12));
      var creepW = clamp(relD * 0.016, -0.18, 0.18);
      outD = drive(creepV, creepW, true);
