      outD = drive(0, 0, true);
    }
    return { left: outD.left, right: outD.right, drill: true };
  }

  // If carrying anything, go bank it immediately.
  if (carried > 0 && mem.mode !== "return" && mem.mode !== "dock") {
    mem.mode = "return";
    mem.sample = null;
    mem.search = null;
    mem.target = null;
    if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
    mem.activeHint = null;
    var oForceRet = brakeCmd();
    return { left: oForceRet.left, right: oForceRet.right, drill: false };
  }

  if (mem.mode === "return") {
    if (dBase <= 2.90) {
      mem.mode = "dock";
      mem.dockStart = null;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
      var oArr = brakeCmd();
      return { left: oArr.left, right: oArr.right, drill: false };
    }

    var vRet = carried > 0 ? 0.82 : 0.92;
    if (dBase < 10) vRet = Math.min(vRet, 0.52);
    if (dBase < 5) vRet = Math.min(vRet, 0.30);

    var outR;
    if (obs.beacon && isFinite(+obs.beacon.distance) &&
        isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
      outR = navRel(+obs.beacon.bearing, +obs.beacon.distance, vRet, 0.65);
    } else {
      outR = navTo(mem.base.x, mem.base.y, vRet, 0.65);
    }
    return { left: outR.left, right: outR.right, drill: false };
  }

  if (mem.mode === "dock") {
    var dD = getBaseDist();
    if (mem.dockStart == null) {
      mem.dockStart = t;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
    }

    if (dD > 3.35) {
      mem.mode = "return";
      var oOutD = brakeCmd();
      return { left: oOutD.left, right: oOutD.right, drill: false };
    }

    if (carried > 0) {
      if (dD > 2.65 && t - mem.dockStart > 0.8) {
        var outCreeper;
        if (obs.beacon && isFinite(+obs.beacon.distance) &&
            isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
          outCreeper = navRel(+obs.beacon.bearing, +obs.beacon.distance, 0.22, 0.45);
        } else {
          outCreeper = navTo(mem.base.x, mem.base.y, 0.22, 0.45);
        }
        return { left: outCreeper.left, right: outCreeper.right, drill: false };
      }
      var oWaitUnload = brakeCmd();
      return { left: oWaitUnload.left, right: oWaitUnload.right, drill: false };
    }

    if (t - mem.dockCheckT > 2.2) {
      if (batteryNow - mem.dockLastBatt < 0.0015) mem.dockPlateau = true;
      else mem.dockPlateau = false;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
    }

    var targetB = 0.84;
    if (obs.timeLeft < 240) targetB = 0.64;
    if (obs.timeLeft < 110) targetB = 0.44;
    if (obs.timeLeft < 55) targetB = 0.22;

    var wantCharge = (batteryNow < targetB) &&
                     (obs.timeLeft > 35) &&
                     !mem.dockPlateau &&
