    if (wantCharge) {
      var oChg = brakeCmd();
      return { left: oChg.left, right: oChg.right, drill: false };
    }

    if (obs.timeLeft < 25) {
      var oEnd = brakeCmd();
      return { left: oEnd.left, right: oEnd.right, drill: false };
    }

    mem.mode = "choose";
    mem.dockStart = null;
    mem.target = null;
    mem.search = null;
