        if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
        mem.activeHint = null;
        mem.search = null;
      }
      var oNoSite = brakeCmd();
      return { left: oNoSite.left, right: oNoSite.right, drill: false };
