    var timeNeedApp = dBase / 0.35 + 22 + dSite / 0.15;
    var battNeedApp = 0.055 + dBase * perNow * 2.7 + 0.020;
    if (obs.timeLeft < timeNeedApp || batteryNow < battNeedApp) {
