      } else {
        outApp = drive(0, 0, true);
      }
    } else {
      var vApp;
      if (dSite > 5.0) vApp = 0.50;
      else if (dSite > 3.0) vApp = 0.32;
      else if (dSite > 2.0) vApp = 0.18;
      else vApp = 0.10;
      outApp = navRel(relSite, dSite, vApp, 1.05);
    }

    if (t - mem.approachStart > 50 && dSite > 1.45) {
      mem.mode = "choose";
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.activeHint = null;
      mem.cooldownUntil = t + 2.0;
      var oAppTimeout = brakeCmd();
      return { left: oAppTimeout.left, right: oAppTimeout.right, drill: false };
    }

    return { left: outApp.left, right: outApp.right, drill: false };
  }

  if (mem.mode === "goto") {
    var T = mem.target;
    var H = mem.activeHint;
    if (!T || !H || H.status !== 1) {
      mem.mode = "choose";
      var oG0 = brakeCmd();
      return { left: oG0.left, right: oG0.right, drill: false };
    }

    var dH = hyp(H.x - mem.x, H.y - mem.y);
    if (dH < 3.0) {
      mem.search = {
        h: H,
        cx: H.x,
        cy: H.y,
        idx: 0,
        points: 8,
        startT: t,
        wpT: t,
        angle0: Math.atan2(mem.y - H.y, mem.x - H.x)
      };
      mem.mode = "search";
      var oGS = brakeCmd();
      return { left: oGS.left, right: oGS.right, drill: false };
    }

    if (t - mem.targetStart > 165) {
      H.status = 3;
      mem.activeHint = null;
      mem.target = null;
      mem.mode = "choose";
      var oGTimeout = brakeCmd();
      return { left: oGTimeout.left, right: oGTimeout.right, drill: false };
    }

    var vG = 0.82;
    if (dH < 12) vG = 0.52;
    if (dH < 6) vG = 0.32;

    var outG = navTo(H.x, H.y, vG, 0.95);
    return { left: outG.left, right: outG.right, drill: false };
  }

  if (mem.mode === "search") {
    var SS = mem.search;
    if (!SS || !SS.h || SS.h.status !== 1) {
      mem.mode = "choose";
      mem.search = null;
      mem.activeHint = null;
      var oS0 = brakeCmd();
      return { left: oS0.left, right: oS0.right, drill: false };
    }

    if (SS.idx >= 16 || t - SS.startT > 105) {
      SS.h.status = 3;
      mem.activeHint = null;
      mem.search = null;
      mem.mode = "choose";
      var oSFail = brakeCmd();
      return { left: oSFail.left, right: oSFail.right, drill: false };
    }

    var ring = SS.idx < 8 ? 0 : 1;
    var rrWay = ring === 0 ? 7.0 : 13.0;
    var ii = SS.idx % 8;
    var angW = SS.angle0 + ii * (2 * PI / SS.points) +
               (ring === 1 ? PI / 8 : 0);
    var wx = SS.cx + Math.cos(angW) * rrWay;
    var wy = SS.cy + Math.sin(angW) * rrWay;
    var dW = hyp(wx - mem.x, wy - mem.y);

    if (dW < 1.8 || t - SS.wpT > 14.0) {
      SS.idx++;
      SS.wpT = t;
      if (SS.idx >= 16) {
        SS.h.status = 3;
        mem.activeHint = null;
        mem.search = null;
        mem.mode = "choose";
        var oSEnd = brakeCmd();
        return { left: oSEnd.left, right: oSEnd.right, drill: false };
      }
      ring = SS.idx < 8 ? 0 : 1;
      rrWay = ring === 0 ? 7.0 : 13.0;
      ii = SS.idx % 8;
      angW = SS.angle0 + ii * (2 * PI / SS.points) +
             (ring === 1 ? PI / 8 : 0);
      wx = SS.cx + Math.cos(angW) * rrWay;
      wy = SS.cy + Math.sin(angW) * rrWay;
      dW = hyp(wx - mem.x, wy - mem.y);
    }

    var vS = dW < 5 ? 0.52 : 0.78;
    var outS = navTo(wx, wy, vS, 1.15);
    return { left: outS.left, right: outS.right, drill: false };
  }

  if (mem.mode === "explore") {
    var ET = mem.target;
    if (!ET || !ET.point) {
      mem.mode = "choose";
      var oE0 = brakeCmd();
      return { left: oE0.left, right: oE0.right, drill: false };
    }

    var de = hyp(ET.x - mem.x, ET.y - mem.y);
    if (de < 3.0 || t - mem.targetStart > 85) {
      ET.point.done = true;
      mem.target = null;
      mem.mode = "choose";
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      var oEDone = brakeCmd();
      return { left: oEDone.left, right: oEDone.right, drill: false };
    }

    var vE = de < 8 ? 0.52 : 0.76;
    var outE = navTo(ET.x, ET.y, vE, 1.4);
    return { left: outE.left, right: outE.right, drill: false };
  }

  // Choose mode / idle.
  if (mem.activeHint && mem.activeHint.status === 1) {
    mem.activeHint.status = 0;
    mem.activeHint = null;
  }
  mem.target = null;
  mem.search = null;

  if (carried > 0) {
    mem.mode = "return";
    var oChCarry = brakeCmd();
    return { left: oChCarry.left, right: oChCarry.right, drill: false };
  }

  var chargeTargetChoose = 0.82;
  if (obs.timeLeft < 240) chargeTargetChoose = 0.62;
  if (obs.timeLeft < 110) chargeTargetChoose = 0.42;

  if (dBase < 3.2 && batteryNow < chargeTargetChoose &&
      obs.timeLeft > 55 && !mem.dockPlateau) {
    mem.mode = "dock";
    mem.dockStart = null;
    var oChooseDock = brakeCmd();
    return { left: oChooseDock.left, right: oChooseDock.right, drill: false };
  }

  if (batteryNow < 0.20 && dBase > 7 && obs.timeLeft > 40) {
    mem.mode = "return";
    var oLowB = brakeCmd();
    return { left: oLowB.left, right: oLowB.right, drill: false };
  }

  if (obs.timeLeft < 40) {
    mem.mode = "idle";
    var oIdle0 = brakeCmd();
    return { left: oIdle0.left, right: oIdle0.right, drill: false };
  }

  // If by any chance a site is visible now, take it.
  if (obs.site && canSampleSite(obs.site)) {
    startApproach(obs.site);
    var oChooseSite = brakeCmd();
    return { left: oChooseSite.left, right: oChooseSite.right, drill: false };
  }

  var bestH = null;
  var bestScore = -1e15;

  for (var bi = 0; bi < mem.hints.length; bi++) {
    var hC = mem.hints[bi];
    if (hC.status !== 0) continue;

    var dhC = hyp(hC.x - mem.x, hC.y - mem.y);
    var hbC = hyp(hC.x - mem.base.x, hC.y - mem.base.y);

    var totalTrip = dhC + hbC + 30;
    var estTime = totalTrip / 0.50 + 28;
    if (obs.timeLeft < estTime) continue;

    var estBatt = 0.13 + totalTrip * perNow * 2.7 + 0.025;
    if (batteryNow < estBatt) continue;

    var val = Math.max(0.05, hC.v || 0.1);
    var score = val / (dhC + 0.55 * hbC + 45);

    if (hbC > 150) score *= 0.55;
    if (hbC > 95) score *= 0.75;
    if (dhC < 8) score *= 1.15;

    if (score > bestScore) {
      bestScore = score;
      bestH = hC;
    }
  }

  if (bestH) {
    bestH.status = 1;
    mem.activeHint = bestH;
    mem.target = { x: bestH.x, y: bestH.y, hint: bestH };
    mem.mode = "goto";
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oPick = brakeCmd();
    return { left: oPick.left, right: oPick.right, drill: false };
  }

  // No suitable hint: do conservative exploration from map grid.
  var bestP = null, bestPD = 1e15;
  for (var ei = 0; ei < mem.explorePts.length; ei++) {
    var ep = mem.explorePts[ei];
    if (ep.done) continue;
    var dp = hyp(ep.x - mem.x, ep.y - mem.y);
    var pb = hyp(ep.x - mem.base.x, ep.y - mem.base.y);
    if (obs.timeLeft < (dp + pb) / 0.50 + 35) continue;
    if (batteryNow < 0.13 + (dp + pb) * perNow * 2.8) continue;
    if (pb > 125) continue;
    if (dp < bestPD) {
      bestPD = dp;
      bestP = ep;
    }
  }

  if (bestP) {
    mem.mode = "explore";
    mem.target = { x: bestP.x, y: bestP.y, point: bestP };
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oExplore = brakeCmd();
    return { left: oExplore.left, right: oExplore.right, drill: false };
  }

  mem.mode = "idle";
  var oFinalIdle = brakeCmd();
  return { left: oFinalIdle.left, right: oFinalIdle.right, drill: false };
}

function act(obs, mem) {
  var PI = Math.PI, RAD = PI / 180, DEG = 180 / PI, WB = 0.6;
  function wrap(a) { a = ((a + 180) % 360 + 360) % 360 - 180; return a; }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function hyp(a, b) { return Math.sqrt(a * a + b * b); }

  var t = (typeof obs.t === "number" && isFinite(obs.t)) ? +obs.t : 0;
  var vL = +obs.wheelLeft || 0;
  var vR = +obs.wheelRight || 0;
  var speedF = (vL + vR) * 0.5;
  var speedAbs = Math.abs(speedF);
  var maxWheel = Math.max(Math.abs(vL), Math.abs(vR));

  if (!mem.init) {
    mem.init = true;

    var mission = obs.mission || {};
    var sz = mission.size, sx = 400, sy = 400;
    if (Array.isArray(sz)) {
      sx = +sz[0] || 400;
      sy = +sz[1] || sx;
    } else if (sz && typeof sz === "object") {
      sx = +(sz.w || sz.x || sz.width || 400);
      sy = +(sz.h || sz.y || sz.height || sx);
    } else if (typeof sz === "number") {
      sx = sy = sz;
    }
    mem.sizeX = sx;
    mem.sizeY = sy;

    var mb = mission.base || {};
    mem.base = {
      x: isFinite(+mb.x) ? +mb.x : (+obs.x || 0),
      y: isFinite(+mb.y) ? +mb.y : (+obs.y || 0)
    };
    mem.cap = +(mission.capacity || 5);
    mem.seconds = +(mission.seconds || 1200);

    mem.hints = [];
    var hs = mission.hints || [];
    for (var hi = 0; hi < hs.length; hi++) {
      var hh = hs[hi] || {};
      var hx = +hh.x, hy = +hh.y;
      var hv = +hh.estimate;
      if (!isFinite(hv) || hv <= 0) hv = +hh.value;
      if (!isFinite(hv) || hv <= 0) hv = 0.15;
      if (isFinite(hx) && isFinite(hy)) {
        mem.hints.push({ x: hx, y: hy, v: Math.max(0.001, hv), status: 0 });
      }
    }

    mem.x = isFinite(+obs.x) ? +obs.x : mem.base.x;
    mem.y = isFinite(+obs.y) ? +obs.y : mem.base.y;
    mem.head = isFinite(+obs.heading) ? +obs.heading : 0;

    mem.lastT = t;
    mem.lastBatt = isFinite(+obs.battery) ? +obs.battery : 1;
    mem.perM = 0.0018;

    mem.intL = 0;
    mem.intR = 0;
    mem.ctrlHold = -1;
    mem.lastCmdSpeed = 0;

    mem.mode = "choose";
    mem.activeHint = null;
    mem.target = null;
    mem.search = null;
    mem.sample = null;

    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    mem.recoverUntil = -999;
    mem.recoverDir = 1;
    mem.bumpAck = -999;
    mem.cooldownUntil = -999;

    mem.lastGpsX = mem.x;
    mem.lastGpsY = mem.y;
    mem.lastGpsT = t;
    mem.gpsFrozen = false;
    mem.calX = mem.x;
    mem.calY = mem.y;
    mem.turnSinceCal = 0;

    mem.dockStart = null;
    mem.dockLastBatt = mem.lastBatt;
    mem.dockCheckT = t;
    mem.dockPlateau = false;

    mem.approachStart = -999;
    mem.approachLastSeen = -999;
    mem.approachX = null;
    mem.approachY = null;
    mem.approachValue = 0;

    mem.rayLow = [0,0,0,0,0,0,0,0,0];
    mem.rayIgnore = [-999,-999,-999,-999,-999,-999,-999,-999,-999];

    mem.sampleRadius = 1.45;
    mem.nudgeUntil = -999;
    mem.nextNudgeT = 0;

    mem.lastSciSearchX = -9999;
    mem.lastSciSearchY = -9999;
    mem.sciCooldown = 0;

    mem.explorePts = [];
    var stepE = 50;
    for (var xx = 25; xx < mem.sizeX - 15; xx += stepE) {
      for (var yy = 25; yy < mem.sizeY - 15; yy += stepE) {
        if (hyp(xx - mem.base.x, yy - mem.base.y) > 22) {
          mem.explorePts.push({ x: xx, y: yy, done: false });
        }
      }
    }
  }

  var timeLeft = isFinite(+obs.timeLeft) ? +obs.timeLeft : Math.max(0, mem.seconds - t);
  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.55) dt = 0;
  else dt = Math.min(dt, 0.20);
  mem.lastT = t;

  // Rough battery-use-per-metre estimate.
  if (dt > 0 && isFinite(+obs.battery) && !obs.docked) {
    var drain = mem.lastBatt - (+obs.battery);
    var solarNow = isFinite(+obs.solar) ? +obs.solar : 0;
    var gross = drain + solarNow * dt;
    var distNow = Math.abs(speedF) * dt;
    if (distNow > 0.004 && gross > 0.0000002 && gross < 0.02) {
      var per = gross / distNow;
      if (per > 0.00004 && per < 0.030) {
        mem.perM = mem.perM * 0.985 + per * 0.015;
      }
    }
  }
  if (isFinite(+obs.battery)) mem.lastBatt = +obs.battery;

  // Odometry prediction.
  if (dt > 0) {
    var dYawDeg = (vR - vL) / WB * dt * DEG;
    var ds = speedF * dt;
    var mid = (mem.head + dYawDeg * 0.5) * RAD;
    mem.x += ds * Math.cos(mid);
    mem.y += ds * Math.sin(mid);
    mem.head = wrap(mem.head + dYawDeg);
    mem.turnSinceCal += Math.abs(dYawDeg);
  }

  // GPS and heading correction from displacement.
  var gx = +obs.x, gy = +obs.y;
  if (isFinite(gx) && isFinite(gy)) {
    var movedGps = Math.abs(gx - mem.lastGpsX) > 0.002 ||
                   Math.abs(gy - mem.lastGpsY) > 0.002;
    if (movedGps) {
      mem.lastGpsT = t;
      if (mem.gpsFrozen) {
        mem.gpsFrozen = false;
        mem.x = gx;
        mem.y = gy;
      }
      mem.lastGpsX = gx;
      mem.lastGpsY = gy;

      var cdx = gx - mem.calX, cdy = gy - mem.calY;
      var cd = hyp(cdx, cdy);
      if (cd > 1.6 && cd < 40 && mem.turnSinceCal < 26 && speedAbs > 0.10) {
        var course = Math.atan2(cdy, cdx) * DEG;
        var herr = wrap(course - mem.head);
        if (Math.abs(herr) < 60) {
          mem.head = wrap(mem.head + herr * 0.55);
        }
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      } else if (cd > 28 || mem.turnSinceCal > 65) {
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      }

      var ex = gx - mem.x, ey = gy - mem.y;
      var ed = hyp(ex, ey);
      if (ed > 18) {
        mem.x = gx;
        mem.y = gy;
      } else if (ed > 0.0005) {
        mem.x += ex * 0.72;
        mem.y += ey * 0.72;
      }
    } else {
      if (speedAbs > 0.16 && t - mem.lastGpsT > 1.8) mem.gpsFrozen = true;
    }
  }

  // Range sensors with very simple stuck-sensor suppression.
  var rawRays = obs.rays || [];
  var rays = [];
  for (var ri = 0; ri < 9; ri++) {
    var rr = +rawRays[ri];
    if (!isFinite(rr) || rr < 0) rr = 15;
    if (rr > 15) rr = 15;

    if (rr < 0.30) mem.rayLow[ri] += dt;
    else mem.rayLow[ri] = 0;

    if (mem.rayIgnore[ri] > t && rr > 2.0) {
      mem.rayIgnore[ri] = -999;
      mem.rayLow[ri] = 0;
    }

    if (mem.rayLow[ri] > 7.0 && !obs.bumped &&
        speedAbs < 0.25 && t > mem.recoverUntil + 1.0) {
      mem.rayIgnore[ri] = t + 8.0;
      mem.rayLow[ri] = 0;
    }

    if (mem.rayIgnore[ri] > t) rr = 15;
    rays.push(rr);
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    var pos = (a + 80) / 20;
    var i0 = Math.floor(pos);
    if (i0 < 0) i0 = 0;
    if (i0 > 7) i0 = 7;
    var f = pos - i0;
    return rays[i0] * (1 - f) + rays[i0 + 1] * f;
  }

  function getBaseDist() {
    if (obs.beacon && isFinite(+obs.beacon.distance) && +obs.beacon.distance < 30) {
      return Math.max(0, +obs.beacon.distance);
    }
    return hyp(mem.x - mem.base.x, mem.y - mem.base.y);
  }

  function drive(v, omega, hold) {
    var targetL = clamp(v - omega * 0.3, -2.35, 2.35);
    var targetR = clamp(v + omega * 0.3, -2.35, 2.35);

    var hf = hold ? 1 : 0;
    if (mem.ctrlHold !== hf) {
      mem.intL = 0;
      mem.intR = 0;
      mem.ctrlHold = hf;
    }

    var eL = targetL - vL;
    var eR = targetR - vR;
    var kp = hold ? 0.98 : 0.58;
    var ki = hold ? 1.25 : 0.74;

    if (dt > 0) {
      mem.intL = clamp((mem.intL || 0) * 0.991 + eL * dt * ki, -0.75, 0.75);
      mem.intR = clamp((mem.intR || 0) * 0.991 + eR * dt * ki, -0.75, 0.75);
    }

    var pitch = isFinite(+obs.pitch) ? +obs.pitch : 0;
    var slope = (hold ? 0.30 : 0.055) * Math.sin(pitch * RAD);

    var uL = targetL / 2.8 + kp * eL + (mem.intL || 0) + slope;
    var uR = targetR / 2.8 + kp * eR + (mem.intR || 0) + slope;

    if (targetL > 0.025 && uL < 0.035) uL = 0.035;
    if (targetL > 0.10 && uL < 0.052) uL = 0.052;
    if (targetL < -0.025 && uL > -0.035) uL = -0.035;
    if (targetL < -0.10 && uL > -0.052) uL = -0.052;
    if (targetR > 0.025 && uR < 0.035) uR = 0.035;
    if (targetR > 0.10 && uR < 0.052) uR = 0.052;
    if (targetR < -0.025 && uR > -0.035) uR = -0.035;
    if (targetR < -0.10 && uR > -0.052) uR = -0.052;

    return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1) };
  }

  function navRel(relIn, dist, vmax, arrive) {
    var rel = wrap(relIn);
    if (!isFinite(dist)) dist = 100;
    if (dist <= arrive) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }

    if (Math.abs(rel) > 110 && speedAbs < 0.30) {
      var dir0 = rel >= 0 ? 1 : -1;
      mem.lastCmdSpeed = 0.9 * 0.3;
      return drive(0, dir0 * 0.90, false);
    }

    var bestC = 0, bestClear = 0, bestScore = -1e15;
    for (var c = -80; c <= 80; c += 10) {
      var r0 = rayAt(c);
      var r1 = Math.min(rayAt(c - 20), rayAt(c + 20));
      var r2 = Math.min(rayAt(c - 40), rayAt(c + 40));
      var clear = Math.min(r0, r1 * 0.92, r2 * 0.78);
      if (!isFinite(clear) || clear < 0) clear = 0;

      var align = Math.abs(wrap(c - rel));
      var score = Math.min(clear, 6.0) * 2.40 - align * 0.072;

      if (clear < 0.55) score -= 65;
      else if (clear < 1.00) score -= 18;
      else if (clear < 1.60) score -= 3.5;

      var aa = (mem.head + c) * RAD;
      var look = Math.min(3.0, Math.max(0.55, clear));
      var px = mem.x + Math.cos(aa) * look;
      var py = mem.y + Math.sin(aa) * look;
      if (px < 1.2 || px > mem.sizeX - 1.2 ||
          py < 1.2 || py > mem.sizeY - 1.2) {
        score -= 95;
      }

      score -= Math.abs(c) * 0.0025;

      if (score > bestScore) {
        bestScore = score;
        bestC = c;
        bestClear = clear;
      }
    }

    var c2 = bestC;
    var ar = Math.abs(c2);
    var v = vmax;

    if (bestClear < 0.55) v = 0;
    else if (bestClear < 0.95) v = Math.min(v, 0.055);
    else if (bestClear < 1.50) v = Math.min(v, 0.16);
    else if (bestClear < 2.40) v = Math.min(v, 0.36);
    else if (bestClear < 4.00) v = Math.min(v, 0.62);
    else v = Math.min(v, 0.95);

    if (ar > 70) v = Math.min(v, 0.04);
    else if (ar > 50) v = Math.min(v, 0.12);
    else if (ar > 30) v = Math.min(v, 0.30);
    else if (ar > 15) v = Math.min(v, 0.55);

    var remain = dist - arrive;
    if (remain < 0.7) v = Math.min(v, 0.04);
    else if (remain < 2.0) v = Math.min(v, 0.13);
    else if (remain < 5.0) v = Math.min(v, 0.34);
    else if (remain < 10.0) v = Math.min(v, 0.64);

    if (speedAbs > 0.28 &&
        bestClear < 0.65 + 0.38 * Math.abs(speedAbs)) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }

    var omega = clamp(c2 * 0.024, -1.25, 1.25);
    if (Math.abs(c2) < 2) omega = 0;
    if (v < 0.025 && Math.abs(c2) > 8) {
      omega = clamp(c2 * 0.018, -1.00, 1.00);
    }

    var hold = (Math.abs(v) < 0.035 && Math.abs(omega) < 0.07);
    mem.lastCmdSpeed = Math.abs(v) + Math.abs(omega) * 0.3;
    return drive(v, omega, hold);
  }

  function navTo(tx, ty, vmax, arrive) {
    var dx = tx - mem.x, dy = ty - mem.y;
    var d = hyp(dx, dy);
    if (d <= arrive) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }
    var desired = Math.atan2(dy, dx) * DEG;
    return navRel(wrap(desired - mem.head), d, vmax, arrive);
  }

  function brakeCmd() {
    mem.lastCmdSpeed = 0;
    return drive(0, 0, true);
  }

  function holdStation(hx, hy) {
    var ex = hx - mem.x, ey = hy - mem.y;
    var err = hyp(ex, ey);
    if (err > 0.055) {
      var desired = Math.atan2(ey, ex) * DEG;
      var rel = wrap(desired - mem.head);
      var v = clamp(err * 0.55, 0.025, 0.115);
      var omega = clamp(rel * 0.022, -0.60, 0.60);
      if (Math.abs(rel) > 80) {
        v = 0;
        omega = clamp(rel * 0.022, -0.50, 0.50);
      }
      mem.lastCmdSpeed = Math.abs(v) + Math.abs(omega) * 0.3;
      return drive(v, omega, true);
    }
    mem.lastCmdSpeed = 0;
    return drive(0, 0, true);
  }

  var carriedNow = +obs.carried || 0;
  var cap = mem.cap || 5;
  var dBase = getBaseDist();
  var batteryNow = isFinite(+obs.battery) ? +obs.battery : 1;
  var perNow = Math.max(0.0008, mem.perM || 0.0018);
  var dockedNow = !!obs.docked;

  function startApproach(siteObs) {
    var sr = +siteObs.bearing || 0;
    var sd = +siteObs.distance || 0;
    var ang = (mem.head + sr) * RAD;
    mem.approachX = mem.x + Math.cos(ang) * sd;
    mem.approachY = mem.y + Math.sin(ang) * sd;
    mem.approachValue = +siteObs.value || 0;
    mem.mode = "approach";
    mem.approachStart = t;
    mem.approachLastSeen = t;
    mem.search = null;
    mem.target = null;
  }

  function startDrill(dd, rr, vv) {
    var ang = (mem.head + rr) * RAD;
    mem.sample = {
      startCarried: carriedNow,
      startT: t,
      maxProg: 0,
      lastProgT: t,
      lastSeen: t,
      lastDist: dd,
      value: vv || 0,
      holdX: mem.x,
      holdY: mem.y,
      sx: mem.x + Math.cos(ang) * dd,
      sy: mem.y + Math.sin(ang) * dd
    };
    mem.mode = "drill";
  }

  function markSampleSuccess() {
    var px = mem.x, py = mem.y;
    if (mem.activeHint) {
      if (hyp(mem.activeHint.x - px, mem.activeHint.y - py) < 35) {
        mem.activeHint.status = 2;
      } else if (mem.activeHint.status === 1) {
        mem.activeHint.status = 0;
      }
      mem.activeHint = null;
    }
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status !== 2 && hyp(h.x - px, h.y - py) < 16) {
        h.status = 2;
      }
    }
    mem.search = null;
    mem.sample = null;
    mem.target = null;
    mem.mode = "return";
    mem.stuckCount = 0;
  }

  function canSampleSite(siteObs) {
    if (!siteObs || !isFinite(+siteObs.distance)) return false;
    var dS = +siteObs.distance;
    if (dS < 0 || dS > 7.9) return false;
    var dB = getBaseDist();
    var per = Math.max(0.0008, mem.perM || 0.0018);
    var timeNeed = dB / 0.33 + 20 + dS / 0.12;
    var battNeed = 0.045 + dB * per * 2.4 + 0.020;
    return timeLeft > timeNeed && batteryNow > battNeed;
  }

  function approachMove(d, rel) {
    var relN = wrap(rel);
    var ar = Math.abs(relN);
    var v;
    if (d > 5.0) v = 0.45;
    else if (d > 3.0) v = 0.28;
    else if (d > 2.2) v = 0.20;
    else if (d > 1.8) v = 0.16;
    else v = 0.13;

    var front = rayAt(relN);
    if (d > 1.58 && front < 0.45) {
      return navRel(relN, d, 0.28, 0.0);
    }

    if (front < 0.35) v = 0;
    else if (front < 0.70) v = Math.min(v, 0.06);

    if (ar > 70) v = Math.min(v, 0.04);
    else if (ar > 45) v = Math.min(v, 0.10);

    var omega = clamp(relN * 0.028, -1.10, 1.10);
    if (ar < 2) omega = 0;

    if (d <= 1.58) {
      if (t > mem.nextNudgeT && speedAbs < 0.045 && ar < 30 && front > 0.45) {
        mem.nudgeUntil = t + 0.35;
        mem.nextNudgeT = t + 1.10;
      }
      if (t < mem.nudgeUntil && ar < 30 && front > 0.45) v = 0.36;
      else v = Math.min(v, 0.14);
    }

    if (d > mem.sampleRadius && d < 1.75 && speedAbs > 0.25) v = 0;
    return drive(v, omega, false);
  }

  function startSearch(cx, cy, hintObj, tempFlag) {
    var ang0 = Math.atan2(mem.y - cy, mem.x - cx);
    if (hyp(mem.x - cx, mem.y - cy) < 0.7) ang0 = mem.head * RAD;
    var pts = [];
    var nPts = tempFlag ? 8 : 12;
    var rr = tempFlag ? 10.5 : 13.2;
    for (var si = 0; si < nPts; si++) {
      var aa = ang0 + si * (2 * PI / nPts) + (tempFlag ? 0 : PI / nPts);
      pts.push({ x: cx + Math.cos(aa) * rr, y: cy + Math.sin(aa) * rr });
    }
    mem.search = {
      h: hintObj,
      cx: cx,
      cy: cy,
      pts: pts,
      idx: 0,
      startT: t,
      wpT: t,
      temp: !!tempFlag
    };
    mem.mode = "search";
    mem.target = null;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
  }

  // Bump and recovery.
  if (obs.bumped && mem.mode !== "drill" && t > mem.bumpAck) {
    mem.bumpAck = t + 1.3;
    mem.recoverUntil = t + 0.95;
    var leftB = rays[6] + rays[7] + rays[8];
    var rightB = rays[0] + rays[1] + rays[2];
    mem.recoverDir = leftB >= rightB ? 1 : -1;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  if (t < mem.recoverUntil && mem.mode !== "drill") {
    var rec = drive(-0.23, (mem.recoverDir || 1) * 0.92, false);
    return { left: rec.left, right: rec.right, drill: false };
  }

  // Progress / stuck detection.
  if (dt > 0) {
    var prog = hyp(mem.x - mem.lastProgX, mem.y - mem.lastProgY);
    if (prog > 0.45) {
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      mem.stuckCount = 0;
    }
  }

  var nearSiteApproach = false;
  if (mem.mode === "approach") {
    if (obs.site && isFinite(+obs.site.distance) && +obs.site.distance < 2.3) {
      nearSiteApproach = true;
    } else if (mem.approachX != null &&
               hyp(mem.approachX - mem.x, mem.approachY - mem.y) < 2.3) {
      nearSiteApproach = true;
    }
  }

  var movingMode = (mem.mode === "goto" || mem.mode === "search" ||
                    mem.mode === "return" || mem.mode === "explore" ||
                    mem.mode === "approach");
  if (mem.mode !== "drill" && mem.mode !== "dock" && !nearSiteApproach &&
      movingMode && t - mem.lastProgT > 5.0 && mem.lastCmdSpeed > 0.12 &&
      maxWheel < 0.08 && t > mem.recoverUntil + 0.6) {
    mem.stuckCount++;
    mem.recoverUntil = t + 0.90;
    mem.recoverDir = -mem.recoverDir || 1;
    mem.lastProgT = t;
    if (mem.stuckCount >= 3) {
      if (mem.mode === "goto" || mem.mode === "search") {
        if (mem.activeHint) mem.activeHint.status = 3;
        mem.activeHint = null;
        mem.search = null;
      } else if (mem.mode === "explore" && mem.target && mem.target.point) {
        mem.target.point.done = true;
      } else if (mem.mode === "approach") {
        mem.cooldownUntil = t + 2.0;
        if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      }
      mem.mode = "choose";
      mem.target = null;
      mem.stuckCount = 0;
    }
    var rec2 = drive(-0.24, (mem.recoverDir || 1) * 0.95, false);
    return { left: rec2.left, right: rec2.right, drill: false };
  }

  // Drill mode: hold station and insist on completing a real site.
  if (mem.mode === "drill") {
    var S = mem.sample;
    if (!S) {
      mem.mode = "choose";
      var oNo = brakeCmd();
      return { left: oNo.left, right: oNo.right, drill: false };
    }

    if (carriedNow > S.startCarried) {
      markSampleSuccess();
      var oSucc = brakeCmd();
      return { left: oSucc.left, right: oSucc.right, drill: false };
    }

    var p = isFinite(+obs.drilling) ? +obs.drilling : 0;
    var visD = !!(obs.site && isFinite(+obs.site.distance));
    var dNow, relNow = 0;
    if (visD) {
      dNow = +obs.site.distance;
      relNow = +obs.site.bearing || 0;
      S.lastSeen = t;
      S.lastDist = dNow;
      var angS = (mem.head + relNow) * RAD;
      S.sx = mem.x + Math.cos(angS) * dNow;
      S.sy = mem.y + Math.sin(angS) * dNow;
    } else {
      if (S.sx != null) {
        dNow = hyp(S.sx - mem.x, S.sy - mem.y);
        relNow = wrap(Math.atan2(S.sy - mem.y, S.sx - mem.x) * DEG - mem.head);
      } else {
        dNow = S.lastDist != null ? S.lastDist : 99;
      }
    }

    if (p > S.maxProg + 0.005) {
      S.maxProg = p;
      S.lastProgT = t;
    }
    if (p + 0.40 < S.maxProg) {
      S.maxProg = p;
      S.lastProgT = t;
    }

    var reserveB = 0.030 + dBase * perNow * 1.6 + 0.010;
    var reserveT = dBase / 0.30 + 10;
    if (timeLeft < reserveT || (p < 5.6 && batteryNow < reserveB)) {
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.sample = null;
      mem.mode = (carriedNow > 0 ? "return" : "choose");
      var oAb = brakeCmd();
      return { left: oAb.left, right: oAb.right, drill: false };
    }

    var age = t - S.startT;
    var noProg = t - S.lastProgT;
    if (age > 28 && p < 5.65) {
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.sample = null;
      mem.mode = (carriedNow > 0 ? "return" : "choose");
      mem.cooldownUntil = t + 2.0;
      var oAge = brakeCmd();
      return { left: oAge.left, right: oAge.right, drill: false };
    }

    if (noProg > 12 && p < 5.55) {
      if (!visD && t - S.lastSeen > 5) {
        mem.sample = null;
        mem.mode = (carriedNow > 0 ? "return" : "choose");
        mem.cooldownUntil = t + 2.0;
        var oLost = brakeCmd();
        return { left: oLost.left, right: oLost.right, drill: false };
      }
      if (dNow > 1.62) {
        mem.sample = null;
        mem.mode = "approach";
        mem.approachStart = t;
        mem.approachLastSeen = S.lastSeen;
        mem.approachX = S.sx;
        mem.approachY = S.sy;
        mem.cooldownUntil = t + 0.5;
        var oFar = brakeCmd();
        return { left: oFar.left, right: oFar.right, drill: false };
      }
      S.lastProgT = t;
    }

    var outD;
    if (dNow > 1.58 && p < 5.6) {
