      mem.dockStart = null;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
      var oArr = brakeCmd();
      return { left: oArr.left, right: oArr.right, drill: false };
    }

    var vRet = carriedNow > 0 ? 0.78 : 0.86;
    if (dBase < 10) vRet = Math.min(vRet, 0.52);
    if (dBase < 5) vRet = Math.min(vRet, 0.30);

