        H.status = 3;
        mem.activeHint = null;
        mem.mode = "choose";
        var oGskip = brakeCmd();
        return { left: oGskip.left, right: oGskip.right, drill: false };
      }
      startSearch(H.x, H.y, H, false);
      var oGS = brakeCmd();
      return { left: oGS.left, right: oGS.right, drill: false };
    }

    if (t - mem.targetStart > 205) {
      H.status = 3;
      mem.activeHint = null;
      mem.target = null;
      mem.mode = "choose";
      var oGTimeout = brakeCmd();
      return { left: oGTimeout.left, right: oGTimeout.right, drill: false };
    }

    var vG = 0.82;
    if (dH < 12) vG = 0.52;
    if (dH < 6) vG = 0.32;

