      mem.search = null;
      mem.activeHint = null;
      var oS0 = brakeCmd();
      return { left: oS0.left, right: oS0.right, drill: false };
    }

    var maxSearchT = SS.temp ? 72 : 170;
    if (SS.idx >= SS.pts.length || t - SS.startT > maxSearchT) {
