      ET.point.done = true;
      mem.target = null;
      mem.mode = "choose";
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      var oEDone = brakeCmd();
      return { left: oEDone.left, right: oEDone.right, drill: false };
    }

    var vE = de < 8 ? 0.52 : 0.76;
