      mem.mode = "dock";
      mem.dockStart = null;
      var oChooseDock = brakeCmd();
      return { left: oChooseDock.left, right: oChooseDock.right, drill: false };
    }

    if (batteryNow < 0.18 && dBase > 7 && timeLeft > 40) {
      mem.mode = "return";
      var oLowB = brakeCmd();
      return { left: oLowB.left, right: oLowB.right, drill: false };
    }

    if (timeLeft < 35) {
      mem.mode = "idle";
      var oIdle0 = brakeCmd();
      return { left: oIdle0.left, right: oIdle0.right, drill: false };
    }

    if (obs.site && canSampleSite(obs.site) && t > mem.cooldownUntil) {
