      mem.target = { x: bestH.x, y: bestH.y, hint: bestH };
      mem.mode = "goto";
      mem.targetStart = t;
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      mem.stuckCount = 0;
      var oPick = brakeCmd();
      return { left: oPick.left, right: oPick.right, drill: false };
    }

    var bestP = null, bestPD = 1e15;
    for (var ei = 0; ei < mem.explorePts.length; ei++) {
      var ep = mem.explorePts[ei];
      if (ep.done) continue;
      var dp = hyp(ep.x - mem.x, ep.y - mem.y);
      var pb = hyp(ep.x - mem.base.x, ep.y - mem.base.y);
      if (timeLeft < (dp + pb) / 0.50 + 35) continue;
      if (batteryNow < 0.13 + (dp + pb) * perNow * 2.8) continue;
      if (pb > 125) continue;
      if (dp < bestPD) {
