        bestP = ep;
      }
    }

    if (bestP) {
      mem.mode = "explore";
      mem.target = { x: bestP.x, y: bestP.y, point: bestP };
      mem.targetStart = t;
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      mem.stuckCount = 0;
      var oExplore = brakeCmd();
      return { left: oExplore.left, right: oExplore.right, drill: false };
    }

    mem.mode = "idle";
    var oFinalIdle = brakeCmd();
    return { left: oFinalIdle.left, right: oFinalIdle.right, drill: false };
  }

  mem.mode = "choose";
  mem.target = null;
  mem.search = null;
  mem.activeHint = null;
  var cmdFinal = drive(0, 0, true);
  return { left: cmdFinal.left, right: cmdFinal.right, drill: false };
}

