      mem.lastGpsY = gy;

      var cdx = gx - mem.calX, cdy = gy - mem.calY;
      var cd = hyp(cdx, cdy);
      if (cd > 1.8 && cd < 50 && mem.turnSinceCal < 30 && speedAbs > 0.10) {
        var course = Math.atan2(cdy, cdx) * DEG;
        var herr = wrap(course - mem.head);
        if (Math.abs(herr) < 70) {
          mem.head = wrap(mem.head + herr * 0.50);
        }
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      } else if (cd > 45 || mem.turnSinceCal > 90) {
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      }

      var ex = gx - mem.x, ey = gy - mem.y;
      var ed = hyp(ex, ey);
      if (ed > 15) {
        mem.x = gx;
        mem.y = gy;
      } else if (ed > 0.0004) {
        mem.x += ex * 0.62;
        mem.y += ey * 0.62;
      }
    } else {
      if (speedAbs > 0.13 && t - mem.lastGpsT > 2.0) mem.gpsFrozen = true;
    }
  }

  // Range sensors, with simple stuck/blocked sensor suppression.
  var rawRays = obs.rays || [];
  var rays = [];
  for (var ri = 0; ri < 9; ri++) {
    var rr = +rawRays[ri];
    if (!isFinite(rr) || rr < 0) rr = 15;
    if (rr > 15) rr = 15;

    if (rr < 0.30) mem.rayLow[ri] += dt;
    else mem.rayLow[ri] = 0;

    if (mem.rayIgnore[ri] > t && rr > 2.0) {
      mem.rayIgnore[ri] = -999;
      mem.rayLow[ri] = 0;
    }

    if (mem.rayLow[ri] > 7.0 && !obs.bumped &&
        speedAbs < 0.25 && t > mem.recoverUntil + 1.0) {
      mem.rayIgnore[ri] = t + 8.0;
      mem.rayLow[ri] = 0;
    }

    if (mem.rayIgnore[ri] > t) rr = 15;
    rays.push(rr);
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    var pos = (a + 80) / 20;
    var i0 = Math.floor(pos);
    if (i0 < 0) i0 = 0;
    if (i0 > 7) i0 = 7;
    var f = pos - i0;
    return rays[i0] * (1 - f) + rays[i0 + 1] * f;
  }

  function getBaseDist() {
    if (obs.docked) return 0;
    if (obs.beacon && isFinite(+obs.beacon.distance) && +obs.beacon.distance < 30) {
      return Math.max(0, +obs.beacon.distance);
    }
    return hyp(mem.x - mem.base.x, mem.y - mem.base.y);
  }

  function drive(v, omega, hold) {
    var targetL = clamp(v - omega * 0.3, -2.35, 2.35);
    var targetR = clamp(v + omega * 0.3, -2.35, 2.35);

    var hf = hold ? 1 : 0;
    if (mem.ctrlHold !== hf) {
      mem.intL = 0;
      mem.intR = 0;
      mem.ctrlHold = hf;
    }

    var eL = targetL - vL;
    var eR = targetR - vR;
    var kp = hold ? 0.98 : 0.58;
    var ki = hold ? 1.25 : 0.74;

    if (dt > 0) {
      mem.intL = clamp((mem.intL || 0) * 0.991 + eL * dt * ki, -0.75, 0.75);
      mem.intR = clamp((mem.intR || 0) * 0.991 + eR * dt * ki, -0.75, 0.75);
    }

    var pitch = isFinite(+obs.pitch) ? +obs.pitch : 0;
    var slope = (hold ? 0.30 : 0.055) * Math.sin(pitch * RAD);

    var uL = targetL / 2.8 + kp * eL + (mem.intL || 0) + slope;
    var uR = targetR / 2.8 + kp * eR + (mem.intR || 0) + slope;

    if (targetL > 0.025 && uL < 0.035) uL = 0.035;
    if (targetL > 0.10 && uL < 0.052) uL = 0.052;
    if (targetL < -0.025 && uL > -0.035) uL = -0.035;
    if (targetL < -0.10 && uL > -0.052) uL = -0.052;
    if (targetR > 0.025 && uR < 0.035) uR = 0.035;
    if (targetR > 0.10 && uR < 0.052) uR = 0.052;
    if (targetR < -0.025 && uR > -0.035) uR = -0.035;
    if (targetR < -0.10 && uR > -0.052) uR = -0.052;

    return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1) };
  }

  function navRel(relIn, dist, vmax, arrive) {
    var rel = wrap(relIn);
    if (!isFinite(dist)) dist = 100;
    if (dist <= arrive) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }

    if (Math.abs(rel) > 110 && speedAbs < 0.30) {
      var dir0 = rel >= 0 ? 1 : -1;
      mem.lastCmdSpeed = 0.30;
      return drive(0, dir0 * 0.90, false);
    }

    var bestC = 0, bestClear = 0, bestScore = -1e15;
    for (var c = -80; c <= 80; c += 10) {
      var r0 = rayAt(c);
      var r1 = Math.min(rayAt(c - 20), rayAt(c + 20));
      var r2 = Math.min(rayAt(c - 40), rayAt(c + 40));
      var clear = Math.min(r0, r1 * 0.92, r2 * 0.78);
      if (!isFinite(clear) || clear < 0) clear = 0;

      var align = Math.abs(wrap(c - rel));
      var score = Math.min(clear, 6.0) * 2.40 - align * 0.072;

      if (clear < 0.55) score -= 65;
      else if (clear < 1.00) score -= 18;
      else if (clear < 1.60) score -= 3.5;

      var aa = (mem.head + c) * RAD;
      var look = Math.min(3.0, Math.max(0.55, clear));
      var px = mem.x + Math.cos(aa) * look;
      var py = mem.y + Math.sin(aa) * look;
      if (px < 1.2 || px > mem.sizeX - 1.2 ||
          py < 1.2 || py > mem.sizeY - 1.2) {
        score -= 95;
      }

      score -= Math.abs(c) * 0.0025;

      if (score > bestScore) {
        bestScore = score;
        bestC = c;
        bestClear = clear;
      }
    }

    var c2 = bestC;
    var ar = Math.abs(c2);
    var v = vmax;

    if (bestClear < 0.55) v = 0;
    else if (bestClear < 0.95) v = Math.min(v, 0.055);
    else if (bestClear < 1.50) v = Math.min(v, 0.16);
    else if (bestClear < 2.40) v = Math.min(v, 0.36);
    else if (bestClear < 4.00) v = Math.min(v, 0.62);
    else v = Math.min(v, 0.95);

    if (ar > 70) v = Math.min(v, 0.04);
    else if (ar > 50) v = Math.min(v, 0.12);
    else if (ar > 30) v = Math.min(v, 0.30);
    else if (ar > 15) v = Math.min(v, 0.55);

    var remain = dist - arrive;
    if (remain < 0.7) v = Math.min(v, 0.04);
    else if (remain < 2.0) v = Math.min(v, 0.13);
    else if (remain < 5.0) v = Math.min(v, 0.34);
    else if (remain < 10.0) v = Math.min(v, 0.64);

    if (speedAbs > 0.28 &&
        bestClear < 0.65 + 0.38 * Math.abs(speedAbs)) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }

    var omega = clamp(c2 * 0.024, -1.25, 1.25);
    if (Math.abs(c2) < 2) omega = 0;
    if (v < 0.025 && Math.abs(c2) > 8) {
      omega = clamp(c2 * 0.018, -1.00, 1.00);
    }

    var hold = (Math.abs(v) < 0.035 && Math.abs(omega) < 0.07);
    mem.lastCmdSpeed = Math.abs(v) + Math.abs(omega) * 0.3;
    return drive(v, omega, hold);
  }

  function navTo(tx, ty, vmax, arrive) {
    var dx = tx - mem.x, dy = ty - mem.y;
    var d = hyp(dx, dy);
    if (d <= arrive) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }
    var desired = Math.atan2(dy, dx) * DEG;
    return navRel(wrap(desired - mem.head), d, vmax, arrive);
  }

  function brakeCmd() {
    mem.lastCmdSpeed = 0;
    return drive(0, 0, true);
  }

  function canAffordSample(dS) {
    var dB = getBaseDist();
    var per = clamp(mem.perM, 0.0006, 0.0022);
    var battNeed = 0.10 + dB * per * 1.8 + (carriedNow + 1) * 0.015 + 0.030;
    var timeNeed = dB / 0.32 + 18 + (carriedNow + 1) * 4;
    return batteryNow > battNeed && timeLeft > timeNeed;
  }

  function startApproach(siteObs) {
    var sr = +siteObs.bearing || 0;
    var sd = +siteObs.distance || 0;
    var ang = (mem.head + sr) * RAD;
    mem.approachX = mem.x + Math.cos(ang) * sd;
    mem.approachY = mem.y + Math.sin(ang) * sd;
    mem.approachValue = +siteObs.value || 0;
    mem.mode = "approach";
    mem.approachStart = t;
    mem.approachLastSeen = t;
    mem.search = null;
    mem.target = null;
    mem.sample = null;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
  }

  function startDrill(dd, rr, vv) {
    var ang = (mem.head + rr) * RAD;
    mem.sample = {
      startCarried: carriedNow,
      startT: t,
      maxProg: 0,
      lastProgT: t,
      lastSeen: t,
      lastDist: dd,
      value: vv || 0,
      holdX: mem.x,
      holdY: mem.y,
      sx: mem.x + Math.cos(ang) * dd,
      sy: mem.y + Math.sin(ang) * dd
    };
    mem.mode = "drill";
  }

  function finishSample() {
    var px = mem.x, py = mem.y;
    if (mem.activeHint) {
      if (hyp(mem.activeHint.x - px, mem.activeHint.y - py) < 40) {
        mem.activeHint.status = 2;
      } else if (mem.activeHint.status === 1) {
        mem.activeHint.status = 0;
      }
      mem.activeHint = null;
    }
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status !== 2 && hyp(h.x - px, h.y - py) < 18) {
        h.status = 2;
      }
    }

    mem.sample = null;
    mem.search = null;
    mem.target = null;
    mem.cooldownUntil = t + 0.8;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;

    var dB = getBaseDist();
    var needReturn = carriedNow >= mem.batch ||
                     carriedNow >= mem.cap ||
                     timeLeft < dB / 0.32 + 18 + carriedNow * 4 ||
                     batteryNow < 0.10 + dB * 0.0016 + carriedNow * 0.015;
    mem.mode = needReturn ? "return" : "choose";
  }

  function abortApproach() {
    if (mem.activeHint && mem.activeHint.status === 1) {
      if (hyp(mem.activeHint.x - mem.x, mem.activeHint.y - mem.y) < 15) {
        mem.activeHint.status = 3;
      } else {
        mem.activeHint.status = 0;
      }
    }
    mem.activeHint = null;
    mem.sample = null;
    mem.search = null;
    mem.cooldownUntil = t + 1.5;
    mem.mode = carriedNow > 0 ? "return" : "choose";
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  function makeSpiral(cx, cy, spacing, maxR) {
    var pts = [];
    var x = cx, y = cy;
    pts.push({ x: cx, y: cy, r: 0 });
    var dx = [1, 0, -1, 0], dy = [0, 1, 0, -1];
    var d = 0, len = 1;
    for (var outer = 0; outer < 80; outer++) {
      for (var side = 0; side < 2; side++) {
        for (var k = 0; k < len; k++) {
          x += dx[d] * spacing;
          y += dy[d] * spacing;
          var rr = hyp(x - cx, y - cy);
          if (rr <= maxR + spacing * 0.70) {
            pts.push({ x: x, y: y, r: rr });
          }
        }
        d = (d + 1) % 4;
      }
      len++;
      if (len * spacing / 2 > maxR + spacing) break;
    }
    return pts;
  }

  function startSearch(cx, cy, hintObj, type, maxR, maxDur) {
    var spacing = type === "science" ? 10.5 : 11.0;
    var pts = makeSpiral(cx, cy, spacing, maxR);
    mem.search = {
      h: hintObj,
      cx: cx,
      cy: cy,
      pts: pts,
      idx: 0,
      wpT: t,
      startT: t,
      type: type,
      maxR: maxR,
      maxDur: maxDur,
      maxSci: 0,
      bestX: cx,
      bestY: cy
    };
    mem.mode = "search";
    mem.target = null;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    if (hintObj) {
      hintObj.status = 1;
      mem.activeHint = hintObj;
    } else {
      mem.activeHint = null;
    }
  }

  function finishSearch(failed) {
    if (mem.search && mem.search.h) {
      if (mem.search.h.status === 1) {
        mem.search.h.status = failed ? 3 : 2;
      }
    }
    mem.search = null;
    mem.activeHint = null;
    mem.target = null;
    mem.mode = "choose";
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  // Bump recovery.
  if (obs.bumped && mem.mode !== "drill" && t > mem.bumpAck) {
    mem.bumpAck = t + 1.3;
    mem.recoverUntil = t + 0.95;
    var leftB = rays[6] + rays[7] + rays[8];
    var rightB = rays[0] + rays[1] + rays[2];
    mem.recoverDir = leftB >= rightB ? 1 : -1;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  if (t < mem.recoverUntil && mem.mode !== "drill") {
    var rec = drive(-0.23, (mem.recoverDir || 1) * 0.90, false);
    return { left: rec.left, right: rec.right, drill: false };
  }

  // Progress and stuck recovery.
  if (dt > 0) {
    var prog = hyp(mem.x - mem.lastProgX, mem.y - mem.lastProgY);
    if (prog > 0.38) {
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      mem.stuckCount = 0;
    }
  }

  var dBaseNow = getBaseDist();
  var movingMode = (mem.mode === "goto" || mem.mode === "search" ||
                    mem.mode === "return" || mem.mode === "explore" ||
                    mem.mode === "approach");
  var nearSite = !!(obs.site && isFinite(+obs.site.distance) && +obs.site.distance < 2.6);

  if (mem.mode !== "drill" && mem.mode !== "dock" && movingMode && !nearSite &&
      t - mem.lastProgT > 5.0 && mem.lastCmdSpeed > 0.12 &&
      maxWheel < 0.10 && t > mem.recoverUntil + 0.6) {
    mem.stuckCount++;
    mem.recoverUntil = t + 0.90;
    mem.recoverDir = -mem.recoverDir || 1;
    mem.lastProgT = t;

    if (mem.stuckCount >= 3) {
      mem.stuckCount = 0;
      if (mem.mode === "goto" || mem.mode === "search") {
        if (mem.activeHint) mem.activeHint.status = 3;
        mem.activeHint = null;
        mem.search = null;
        mem.mode = "choose";
      } else if (mem.mode === "explore" && mem.target && mem.target.point) {
        mem.target.point.done = true;
        mem.target = null;
        mem.mode = "choose";
      } else if (mem.mode === "approach") {
        abortApproach();
      } else if (mem.mode === "return") {
        // Keep returning; try another reverse/turn direction.
        mem.recoverUntil = t + 1.2;
      }
    }

    var rec2 = drive(-0.24, (mem.recoverDir || 1) * 0.94, false);
    return { left: rec2.left, right: rec2.right, drill: false };
  }

  // Drill mode is handled first: keep drill on through small disturbances.
  if (mem.mode === "drill") {
    var S = mem.sample;
    if (!S) {
      mem.mode = "choose";
      var oNoS = brakeCmd();
      return { left: oNoS.left, right: oNoS.right, drill: false };
    }

    if (carriedNow > S.startCarried) {
      finishSample();
      var oSuc = brakeCmd();
      return { left: oSuc.left, right: oSuc.right, drill: false };
    }

    var p = isFinite(+obs.drilling) ? +obs.drilling : 0;
    if (p > S.maxProg + 0.005) {
      S.maxProg = p;
      S.lastProgT = t;
    }
    if (p < S.maxProg - 0.50) {
      S.maxProg = p;
      S.lastProgT = t;
    }

    var dS = S.lastDist != null ? S.lastDist : 99;
    var visS = false;
    if (obs.site && isFinite(+obs.site.distance)) {
      dS = +obs.site.distance;
      visS = true;
      S.lastSeen = t;
      S.lastDist = dS;
      var relS = +obs.site.bearing || 0;
      var angS = (mem.head + relS) * RAD;
      S.sx = mem.x + Math.cos(angS) * dS;
      S.sy = mem.y + Math.sin(angS) * dS;
    } else if (S.sx != null && S.sy != null) {
      dS = hyp(S.sx - mem.x, S.sy - mem.y);
    }

    if (visS && dS > 1.55 && p < 0.60) {
      mem.sample = null;
      mem.mode = "approach";
      mem.approachStart = t;
      mem.approachLastSeen = t;
      mem.approachX = S.sx;
      mem.approachY = S.sy;
      mem.cooldownUntil = t + 0.5;
      var oFarStart = brakeCmd();
      return { left: oFarStart.left, right: oFarStart.right, drill: false };
    }

    var dB = getBaseDist();
    var battReserve = 0.045 + dB * 0.0015 + carriedNow * 0.010;
    var timeReserve = dB / 0.30 + 8;

    if ((p < 5.8 && batteryNow < battReserve) || timeLeft < timeReserve) {
      mem.sample = null;
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.mode = carriedNow > 0 ? "return" : "choose";
      mem.cooldownUntil = t + 1.5;
      var oAbortD = brakeCmd();
      return { left: oAbortD.left, right: oAbortD.right, drill: false };
    }

    var noProg = t - S.lastProgT;

    if (p < 5.7 && noProg > 4.0) {
      if (visS && dS > 1.38 && dS < 1.70 && speedAbs < 0.10) {
        var relD = +obs.site.bearing || 0;
        var creepD = drive(0.045, clamp(relD * 0.018, -0.10, 0.10), true);
        return { left: creepD.left, right: creepD.right, drill: true };
      }

      if (t - S.startT > 11.0 || dS > 1.55) {
        mem.sample = null;
        if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
        mem.mode = carriedNow > 0 ? "return" : "choose";
        mem.cooldownUntil = t + 2.0;
        var oFailD = brakeCmd();
        return { left: oFailD.left, right: oFailD.right, drill: false };
      }

      S.lastProgT = t - 1.0;
    }

    if (p < 5.7 && t - S.startT > 22.0) {
      mem.sample = null;
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.mode = carriedNow > 0 ? "return" : "choose";
      mem.cooldownUntil = t + 2.0;
      var oLongD = brakeCmd();
      return { left: oLongD.left, right: oLongD.right, drill: false };
    }

    var outD;
    if (visS && dS > 1.36 && dS < 1.52 && p < 0.45 && speedAbs < 0.085) {
      var relC = +obs.site.bearing || 0;
      outD = drive(0.035, clamp(relC * 0.018, -0.08, 0.08), true);
    } else {
      // Equal-wheel active brake. Do not rotate during drilling.
      outD = drive(0, 0, true);
    }
    return { left: outD.left, right: outD.right, drill: true };
  }

  // Safety-based return request.
  var needReturn = false;
  if (carriedNow >= mem.cap) needReturn = true;
  if (carriedNow > 0 && carriedNow >= mem.batch) needReturn = true;
  if (carriedNow > 0) {
    var battReturn = 0.10 + dBaseNow * 0.0016 + carriedNow * 0.015;
    var timeReturn = dBaseNow / 0.32 + 18 + carriedNow * 4;
    if (batteryNow < battReturn || timeLeft < timeReturn) needReturn = true;
  }
  if (batteryNow < 0.08 && dBaseNow > 10) needReturn = true;
  if (timeLeft < dBaseNow / 0.28 + 12) needReturn = true;

  if (needReturn && mem.mode !== "return" && mem.mode !== "dock") {
    mem.mode = "return";
    mem.sample = null;
    mem.search = null;
    mem.target = null;
    if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
    mem.activeHint = null;
  }

  // Opportunistic sampling whenever a real site is close enough.
  if (mem.mode !== "return" && mem.mode !== "dock" &&
      mem.mode !== "drill" && mem.mode !== "approach" &&
      carriedNow < mem.cap && carriedNow < mem.batch &&
      t > mem.cooldownUntil &&
      obs.site && isFinite(+obs.site.distance) &&
      +obs.site.distance < 7.9 &&
      canAffordSample(+obs.site.distance)) {
    startApproach(obs.site);
    var oOpp = brakeCmd();
    return { left: oOpp.left, right: oOpp.right, drill: false };
  }

  if (mem.mode === "return") {
    if (dBaseNow <= 2.90 || obs.docked) {
      mem.mode = "dock";
      mem.dockStart = null;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
      var oArrR = brakeCmd();
      return { left: oArrR.left, right: oArrR.right, drill: false };
    }

    var vRet = carriedNow > 0 ? 0.80 : 0.88;
    if (dBaseNow < 10) vRet = Math.min(vRet, 0.52);
    if (dBaseNow < 5) vRet = Math.min(vRet, 0.30);

    var outR;
    if (obs.beacon && isFinite(+obs.beacon.distance) &&
        isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
      outR = navRel(+obs.beacon.bearing, +obs.beacon.distance, vRet, 0.55);
    } else {
      outR = navTo(mem.base.x, mem.base.y, vRet, 0.55);
    }
    return { left: outR.left, right: outR.right, drill: false };
  }

  if (mem.mode === "dock") {
    var dD = getBaseDist();
    if (!obs.docked && dD > 3.25) {
      mem.mode = "return";
      var oLeaveDock = brakeCmd();
      return { left: oLeaveDock.left, right: oLeaveDock.right, drill: false };
    }

    if (mem.dockStart == null) {
      mem.dockStart = t;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
    }

    if (carriedNow > 0) {
      if (!obs.docked && dD > 2.55 && t - mem.dockStart > 0.7) {
        var outCreep;
        if (obs.beacon && isFinite(+obs.beacon.distance) &&
            isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
          outCreep = navRel(+obs.beacon.bearing, +obs.beacon.distance, 0.20, 0.35);
        } else {
          outCreep = navTo(mem.base.x, mem.base.y, 0.20, 0.35);
        }
        return { left: outCreep.left, right: outCreep.right, drill: false };
      }
      var oWaitUnload = brakeCmd();
      return { left: oWaitUnload.left, right: oWaitUnload.right, drill: false };
    }

    var delivNow = isFinite(+obs.delivered) ? +obs.delivered : mem.lastDelivered;
    if (delivNow > mem.lastDelivered) {
      mem.lastDelivered = delivNow;
      mem.firstDeliveryDone = true;
      if (timeLeft > 520) mem.batch = 4;
      else if (timeLeft > 260) mem.batch = 3;
      else mem.batch = 2;
      if (mem.batch > mem.cap) mem.batch = mem.cap;
    }

    if (t - mem.dockCheckT > 2.0) {
      if (batteryNow - mem.dockLastBatt < 0.0015) mem.dockPlateau = true;
      else mem.dockPlateau = false;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
    }

    var targetB = 0.84;
    if (timeLeft < 360) targetB = 0.64;
    if (timeLeft < 180) targetB = 0.46;
    if (timeLeft < 80) targetB = 0.28;

    var wantCharge = batteryNow < targetB &&
                     timeLeft > 35 &&
                     !mem.dockPlateau &&
                     (t - mem.dockStart < 75);

    if (wantCharge) {
      var oCharge = brakeCmd();
      return { left: oCharge.left, right: oCharge.right, drill: false };
    }

    mem.mode = "choose";
    mem.dockStart = null;
    mem.target = null;
    mem.search = null;
    mem.activeHint = null;
    var oLeaveCharge = brakeCmd();
    return { left: oLeaveCharge.left, right: oLeaveCharge.right, drill: false };
  }

  if (mem.mode === "approach") {
    var dApp, relApp, visible = false, valApp = mem.approachValue || 0;

    if (obs.site && isFinite(+obs.site.distance)) {
      dApp = +obs.site.distance;
      relApp = +obs.site.bearing || 0;
      visible = true;
      valApp = +obs.site.value || 0;
      mem.approachLastSeen = t;
      mem.approachValue = valApp;
      var angA = (mem.head + relApp) * RAD;
      mem.approachX = mem.x + Math.cos(angA) * dApp;
      mem.approachY = mem.y + Math.sin(angA) * dApp;
    } else {
      if (mem.approachX == null || t - mem.approachLastSeen > 3.2) {
        abortApproach();
        var oLostA = brakeCmd();
        return { left: oLostA.left, right: oLostA.right, drill: false };
      }
      var dxA = mem.approachX - mem.x;
      var dyA = mem.approachY - mem.y;
      dApp = hyp(dxA, dyA);
      relApp = wrap(Math.atan2(dyA, dxA) * DEG - mem.head);
    }

    if (carriedNow >= mem.cap || carriedNow >= mem.batch) {
      mem.mode = carriedNow > 0 ? "return" : "choose";
      var oCarA = brakeCmd();
      return { left: oCarA.left, right: oCarA.right, drill: false };
    }

    if (!canAffordSample(dApp)) {
      abortApproach();
      var oAbA = brakeCmd();
      return { left: oAbA.left, right: oAbA.right, drill: false };
    }

    if (dApp <= 1.36 && speedAbs < 0.125) {
      startDrill(dApp, relApp, valApp);
      var oStartD = drive(0, 0, true);
      return { left: oStartD.left, right: oStartD.right, drill: true };
    }

    if (dApp <= 1.24 && speedAbs < 0.145) {
      startDrill(dApp, relApp, valApp);
      var oStartD2 = drive(0, 0, true);
      return { left: oStartD2.left, right: oStartD2.right, drill: true };
    }

    if (dApp <= 1.70 && speedAbs > 0.10) {
      var oBrakeA = drive(0, 0, true);
      return { left: oBrakeA.left, right: oBrakeA.right, drill: false };
    }

    if (t - mem.approachStart > 55 && dApp > 1.35) {
      abortApproach();
      var oTimeA = brakeCmd();
      return { left: oTimeA.left, right: oTimeA.right, drill: false };
    }

    if (!visible && dApp < 1.45) {
      abortApproach();
      var oNearLost = brakeCmd();
      return { left: oNearLost.left, right: oNearLost.right, drill: false };
    }

    var frontA = rayAt(relApp);
    if (frontA < 0.45 && dApp > 1.45) {
      var outAvoidA = navTo(mem.approachX, mem.approachY, 0.28, 0.45);
      return { left: outAvoidA.left, right: outAvoidA.right, drill: false };
    }

    var vA;
    if (dApp > 5.0) vA = 0.44;
    else if (dApp > 3.0) vA = 0.29;
    else if (dApp > 2.0) vA = 0.19;
    else if (dApp > 1.5) vA = 0.13;
    else vA = 0.085;

    if (frontA < 0.35) vA = 0;
    else if (frontA < 0.70) vA = Math.min(vA, 0.065);

    var omegaA = clamp(relApp * 0.026, -1.00, 1.00);
    if (Math.abs(relApp) < 2) omegaA = 0;
    if (Math.abs(relApp) > 70) {
      vA = Math.min(vA, 0.040);
      omegaA = clamp(relApp * 0.030, -0.80, 0.80);
    }

    if (dApp <= 1.55) vA = Math.min(vA, 0.10);
    if (dApp <= 1.40) vA = Math.min(vA, 0.075);

    var outA = drive(vA, omegaA, false);
    return { left: outA.left, right: outA.right, drill: false };
  }

  if (mem.mode === "goto") {
    var H = mem.activeHint;
    if (!H || H.status !== 1) {
      mem.mode = "choose";
      var oG0 = brakeCmd();
      return { left: oG0.left, right: oG0.right, drill: false };
    }

    var dH = hyp(H.x - mem.x, H.y - mem.y);
    if (dH < 3.2) {
      startSearch(H.x, H.y, H, "hint", 21.0, 145);
      var oGS = brakeCmd();
      return { left: oGS.left, right: oGS.right, drill: false };
    }

    if (t - mem.targetStart > 205) {
      H.status = 3;
      mem.activeHint = null;
      mem.target = null;
      mem.mode = "choose";
      var oGTimeout = brakeCmd();
      return { left: oGTimeout.left, right: oGTimeout.right, drill: false };
    }

    var vG = 0.86;
    if (dH < 12) vG = 0.54;
    if (dH < 6) vG = 0.34;

    var outG = navTo(H.x, H.y, vG, 0.85);
    return { left: outG.left, right: outG.right, drill: false };
  }

  if (mem.mode === "search") {
    var SS = mem.search;
    if (!SS) {
      mem.mode = "choose";
      var oS0 = brakeCmd();
      return { left: oS0.left, right: oS0.right, drill: false };
    }

    var sciNow = isFinite(+obs.science) ? +obs.science : 0;
    if (sciNow > SS.maxSci + 0.001) {
      SS.maxSci = sciNow;
      SS.bestX = mem.x;
      SS.bestY = mem.y;
    }

    if (SS.idx >= SS.pts.length || t - SS.startT > SS.maxDur) {
      finishSearch(true);
      var oSFail = brakeCmd();
      return { left: oSFail.left, right: oSFail.right, drill: false };
    }

    if (SS.type === "hint" && t - SS.startT > 34 && SS.maxSci < 0.015) {
      finishSearch(true);
      var oSQuiet = brakeCmd();
      return { left: oSQuiet.left, right: oSQuiet.right, drill: false };
    }
    if (SS.type === "science" && t - SS.startT > 42 && SS.maxSci < 0.018) {
      finishSearch(true);
      var oSQuiet2 = brakeCmd();
      return { left: oSQuiet2.left, right: oSQuiet2.right, drill: false };
    }

    var wp = SS.pts[SS.idx];
    var dW = hyp(wp.x - mem.x, wp.y - mem.y);

    if (dW < 1.55 || t - SS.wpT > 16.0) {
      SS.idx++;
      SS.wpT = t;
      if (SS.idx >= SS.pts.length) {
        finishSearch(true);
        var oSEnd = brakeCmd();
        return { left: oSEnd.left, right: oSEnd.right, drill: false };
      }
      wp = SS.pts[SS.idx];
      dW = hyp(wp.x - mem.x, wp.y - mem.y);
    }

    var vS = dW < 5 ? 0.54 : 0.82;
    if (SS.type === "science" && SS.maxSci > 0.30) vS = Math.min(vS, 0.50);

    var outS = navTo(wp.x, wp.y, vS, 0.80);
    return { left: outS.left, right: outS.right, drill: false };
  }

  if (mem.mode === "explore") {
    var ET = mem.target;
    if (!ET || !ET.point) {
      mem.mode = "choose";
      var oE0 = brakeCmd();
      return { left: oE0.left, right: oE0.right, drill: false };
    }

    var de = hyp(ET.x - mem.x, ET.y - mem.y);
    if (de < 3.2 || t - mem.targetStart > 95) {
      ET.point.done = true;
      mem.target = null;
      mem.mode = "choose";
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      var oEDone = brakeCmd();
      return { left: oEDone.left, right: oEDone.right, drill: false };
    }

    var vE = de < 8 ? 0.52 : 0.78;
    var outE = navTo(ET.x, ET.y, vE, 1.20);
    return { left: outE.left, right: outE.right, drill: false };
  }

  if (mem.mode === "idle") {
    if (timeLeft < 25 || batteryNow < 0.05) {
      var oIdleStay = brakeCmd();
      return { left: oIdleStay.left, right: oIdleStay.right, drill: false };
    }
    mem.mode = "choose";
  }

  // Choose mode.
  mem.target = null;
  mem.search = null;
  if (mem.activeHint && mem.activeHint.status === 1) {
    mem.activeHint.status = 0;
    mem.activeHint = null;
  }

  if (timeLeft < 24) {
    mem.mode = "idle";
    var oFinal = brakeCmd();
    return { left: oFinal.left, right: oFinal.right, drill: false };
  }

  if (carriedNow >= mem.batch || carriedNow >= mem.cap) {
    mem.mode = "return";
    var oCarryRet = brakeCmd();
    return { left: oCarryRet.left, right: oCarryRet.right, drill: false };
  }

  if (carriedNow > 0) {
    var battRetC = 0.10 + dBaseNow * 0.0016 + carriedNow * 0.015;
    var timeRetC = dBaseNow / 0.32 + 18 + carriedNow * 4;
    if (batteryNow < battRetC || timeLeft < timeRetC) {
      mem.mode = "return";
      var oCarrySafety = brakeCmd();
      return { left: oCarrySafety.left, right: oCarrySafety.right, drill: false };
    }
  }

  if (dBaseNow < 3.2 && carriedNow === 0) {
    var chargeTargetChoose = 0.82;
    if (timeLeft < 360) chargeTargetChoose = 0.62;
    if (timeLeft < 180) chargeTargetChoose = 0.44;
    if (batteryNow < chargeTargetChoose && timeLeft > 50 && !mem.dockPlateau) {
      mem.mode = "dock";
      mem.dockStart = null;
      var oChooseDock = brakeCmd();
      return { left: oChooseDock.left, right: oChooseDock.right, drill: false };
    }
  }

  // Local science search, especially once at the start or after a failed hint.
  if (carriedNow < mem.batch && t > mem.cooldownUntil) {
    var sci = isFinite(+obs.science) ? +obs.science : 0;
    var doSci = false;

    if (!mem.initialScienceSearchDone && sci > 0.10 &&
        batteryNow > 0.34 && timeLeft > 650) {
      doSci = true;
      mem.initialScienceSearchDone = true;
    } else if (sci > 0.20 && timeLeft > 150 && batteryNow > 0.26 &&
               mem.sciSearchCount < 2 && t > mem.sciCooldown &&
               hyp(mem.x - mem.lastSciX, mem.y - mem.lastSciY) > 25) {
      doSci = true;
    }

    if (doSci) {
      mem.sciSearchCount++;
      mem.sciCooldown = t + 105;
      mem.lastSciX = mem.x;
      mem.lastSciY = mem.y;
      startSearch(mem.x, mem.y, null, "science", 19.0, 145);
      var oSciStart = brakeCmd();
      return { left: oSciStart.left, right: oSciStart.right, drill: false };
    }
  }

  var planPer = clamp(mem.perM || 0.0012, 0.0006, 0.0022);
  var bestH = null;
  var bestScore = -1e18;

  for (var bi = 0; bi < mem.hints.length; bi++) {
    var hC = mem.hints[bi];
    if (hC.status !== 0) continue;

    var dhC = hyp(hC.x - mem.x, hC.y - mem.y);
    var hbC = hyp(hC.x - mem.base.x, hC.y - mem.base.y);

    var timeCost = (dhC + hbC + 30) / 0.35 + 30;
    if (timeLeft < timeCost) continue;

    var battNeed = 0.08 + (dhC + hbC + 30) * planPer * 1.6 +
                   (carriedNow + 1) * 0.012;
    if (batteryNow < battNeed && batteryNow < 0.30) continue;

    var valH = Math.max(0.005, hC.v || 0.05);
    var scoreH;
    if (!mem.firstDeliveryDone) {
      scoreH = valH / (dhC + 0.72 * hbC + 36);
    } else {
      scoreH = valH / (dhC + 0.55 * hbC + 30);
    }

    if (dhC < 10) scoreH *= 1.22;
    if (dhC > 220) scoreH *= 0.55;
    if (carriedNow > 0) scoreH *= (1 - 0.015 * carriedNow);

    if (scoreH > bestScore) {
      bestScore = scoreH;
      bestH = hC;
    }
  }

  // Relaxed fallback: if all hints were rejected by strict margins, take nearest.
  if (!bestH && timeLeft > 60 && batteryNow > 0.14) {
    var nearestH = null, nearestHD = 1e18;
    for (var bj = 0; bj < mem.hints.length; bj++) {
      var hN = mem.hints[bj];
      if (hN.status !== 0) continue;
      var dN = hyp(hN.x - mem.x, hN.y - mem.y);
      if (dN < nearestHD) {
        nearestHD = dN;
        nearestH = hN;
      }
    }
    if (nearestH) bestH = nearestH;
  }

  if (bestH) {
    bestH.status = 1;
    mem.activeHint = bestH;
    mem.target = { x: bestH.x, y: bestH.y, hint: bestH };
    mem.mode = "goto";
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oPick = brakeCmd();
    return { left: oPick.left, right: oPick.right, drill: false };
  }

  if (carriedNow > 0) {
    mem.mode = "return";
    var oCarryRet2 = brakeCmd();
    return { left: oCarryRet2.left, right: oCarryRet2.right, drill: false };
  }

  var bestP = null, bestPD = 1e18;
  for (var ei = 0; ei < mem.explorePts.length; ei++) {
    var ep = mem.explorePts[ei];
    if (ep.done) continue;
    var dp = hyp(ep.x - mem.x, ep.y - mem.y);
    var pb = hyp(ep.x - mem.base.x, ep.y - mem.base.y);
    if (timeLeft < (dp + pb) / 0.35 + 30) continue;
    if (batteryNow < 0.12 + (dp + pb) * planPer * 1.7) continue;
    if (dp < bestPD) {
      bestPD = dp;
      bestP = ep;
    }
  }

  if (bestP) {
    mem.mode = "explore";
    mem.target = { x: bestP.x, y: bestP.y, point: bestP };
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oExplore = brakeCmd();
    return { left: oExplore.left, right: oExplore.right, drill: false };
  }

  // Last-resort wandering: never sit still while there is mission time and charge.
  if (timeLeft > 35 && batteryNow > 0.16) {
    mem.wanderIndex = (mem.wanderIndex || 0) + 1;
    var wa = (mem.wanderIndex * 137.5) * RAD;
    var wr = 45 + (mem.wanderIndex % 3) * 25;
    var wx = clamp(mem.x + Math.cos(wa) * wr, 8, mem.sizeX - 8);
    var wy = clamp(mem.y + Math.sin(wa) * wr, 8, mem.sizeY - 8);
    mem.mode = "explore";
    mem.target = { x: wx, y: wy, point: { x: wx, y: wy, done: false } };
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oWander = brakeCmd();
    return { left: oWander.left, right: oWander.right, drill: false };
  }

  mem.mode = "idle";
  var oFinalIdle = brakeCmd();
  return { left: oFinalIdle.left, right: oFinalIdle.right, drill: false };
}

function act(obs, mem) {
  var PI = Math.PI, RAD = PI / 180, DEG = 180 / PI, WB = 0.6;
  function wrap(a) { a = ((a + 180) % 360 + 360) % 360 - 180; return a; }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function hyp(a, b) { return Math.sqrt(a * a + b * b); }

  var t = (typeof obs.t === "number" && isFinite(obs.t)) ? +obs.t : 0;
  var vL = +obs.wheelLeft || 0;
  var vR = +obs.wheelRight || 0;
  var speedF = (vL + vR) * 0.5;
  var speedAbs = Math.abs(speedF);
  var maxWheel = Math.max(Math.abs(vL), Math.abs(vR));
  var batteryNow = isFinite(+obs.battery) ? +obs.battery : 1;
  var timeLeft = isFinite(+obs.timeLeft) ? +obs.timeLeft : 1200;
  var carriedNow = +obs.carried || 0;

  if (!mem.init) {
    mem.init = true;

    var mission = obs.mission || {};
    var sz = mission.size, sx = 400, sy = 400;
    if (Array.isArray(sz)) {
      sx = +sz[0] || 400;
      sy = +sz[1] || sx;
    } else if (sz && typeof sz === "object") {
      sx = +(sz.w || sz.x || sz.width || 400);
      sy = +(sz.h || sz.y || sz.height || sx);
    } else if (typeof sz === "number") {
      sx = sy = sz;
    }
    mem.sizeX = sx;
    mem.sizeY = sy;

    var mb = mission.base || {};
    mem.base = {
      x: isFinite(+mb.x) ? +mb.x : (+obs.x || 0),
      y: isFinite(+mb.y) ? +mb.y : (+obs.y || 0)
    };
    mem.cap = +(mission.capacity || 5);
    mem.seconds = +(mission.seconds || 1200);

    mem.hints = [];
    var hs = mission.hints || [];
    for (var hi = 0; hi < hs.length; hi++) {
      var hh = hs[hi] || {};
      var hx = +hh.x, hy = +hh.y;
      var hv = +hh.estimate;
      if (!isFinite(hv) || hv <= 0) hv = +hh.value;
      if (!isFinite(hv) || hv <= 0) hv = 0.1;
      if (isFinite(hx) && isFinite(hy)) {
        mem.hints.push({
          x: hx, y: hy,
          v: Math.max(0.005, hv),
          status: 0
        });
      }
    }

    mem.x = isFinite(+obs.x) ? +obs.x : mem.base.x;
    mem.y = isFinite(+obs.y) ? +obs.y : mem.base.y;
    mem.head = isFinite(+obs.heading) ? +obs.heading : 0;

    mem.lastT = t;
    mem.lastBatt = batteryNow;
    mem.perM = 0.0012;

    mem.intL = 0;
    mem.intR = 0;
    mem.ctrlHold = -1;
    mem.lastCmdSpeed = 0;

    mem.mode = "choose";
    mem.activeHint = null;
    mem.target = null;
    mem.search = null;
    mem.sample = null;

    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    mem.recoverUntil = -999;
    mem.recoverDir = 1;
    mem.bumpAck = -999;
    mem.cooldownUntil = -999;

    mem.lastGpsX = mem.x;
    mem.lastGpsY = mem.y;
    mem.lastGpsT = t;
    mem.gpsFrozen = false;
    mem.calX = mem.x;
    mem.calY = mem.y;
    mem.turnSinceCal = 0;

    mem.dockStart = null;
    mem.dockLastBatt = batteryNow;
    mem.dockCheckT = t;
    mem.dockPlateau = false;

    mem.approachStart = -999;
    mem.approachLastSeen = -999;
    mem.approachX = null;
    mem.approachY = null;
    mem.approachValue = 0;

    mem.rayLow = [0,0,0,0,0,0,0,0,0];
    mem.rayIgnore = [-999,-999,-999,-999,-999,-999,-999,-999,-999];

    mem.lastDelivered = isFinite(+obs.delivered) ? +obs.delivered : 0;
    mem.firstDeliveryDone = false;
    mem.batch = 1;

    mem.initialScienceSearchDone = true;
    mem.sciSearchCount = 0;
    mem.sciCooldown = -999;
    mem.lastSciX = -9999;
    mem.lastSciY = -9999;

    mem.explorePts = [];
    var stepE = 45;
    for (var xx = 22; xx < mem.sizeX - 15; xx += stepE) {
      for (var yy = 22; yy < mem.sizeY - 15; yy += stepE) {
        if (hyp(xx - mem.base.x, yy - mem.base.y) > 18) {
          mem.explorePts.push({ x: xx, y: yy, done: false });
        }
      }
    }
    mem.wanderIndex = 0;
  }

  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.55) dt = 0;
  else dt = Math.min(dt, 0.20);
  mem.lastT = t;

  if (dt > 0 && isFinite(mem.lastBatt) && !obs.docked) {
    var dBatt = mem.lastBatt - batteryNow;
    var solarNow = isFinite(+obs.solar) ? +obs.solar : 0;
    var distNow = Math.abs(speedF) * dt;

    if (Math.abs(dBatt) > 0.035) {
      // Capacity/fault reset or docking transition.
    } else if (distNow > 0.002 && dBatt > -0.004 && dBatt < 0.02) {
      var gross = dBatt + Math.max(0, solarNow) * dt;
      if (gross > 0.0000001 && gross < 0.012) {
        var per = gross / distNow;
        if (per > 0.00002 && per < 0.009) {
          mem.perM = mem.perM * 0.97 + per * 0.03;
        }
      }
    }
  }
  mem.perM = clamp(mem.perM, 0.00020, 0.00400);
  mem.lastBatt = batteryNow;

  if (dt > 0) {
    var dYawDeg = (vR - vL) / WB * dt * DEG;
    var ds = speedF * dt;
    var mid = (mem.head + dYawDeg * 0.5) * RAD;
    mem.x += ds * Math.cos(mid);
    mem.y += ds * Math.sin(mid);
    mem.head = wrap(mem.head + dYawDeg);
    mem.turnSinceCal += Math.abs(dYawDeg);
  }

  var gx = +obs.x, gy = +obs.y;
  if (isFinite(gx) && isFinite(gy)) {
    var movedGps = Math.abs(gx - mem.lastGpsX) > 0.002 ||
                   Math.abs(gy - mem.lastGpsY) > 0.002;
    if (movedGps) {
      mem.lastGpsT = t;
      if (mem.gpsFrozen) {
        mem.gpsFrozen = false;
        mem.x = gx;
        mem.y = gy;
      }
      mem.lastGpsX = gx;
      mem.lastGpsY = gy;

      var cdx = gx - mem.calX, cdy = gy - mem.calY;
      var cd = hyp(cdx, cdy);
      if (cd > 1.8 && cd < 50 && mem.turnSinceCal < 30 && speedAbs > 0.10) {
        var course = Math.atan2(cdy, cdx) * DEG;
        var herr = wrap(course - mem.head);
        if (Math.abs(herr) < 70) {
          mem.head = wrap(mem.head + herr * 0.50);
        }
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      } else if (cd > 45 || mem.turnSinceCal > 90) {
        mem.calX = gx;
        mem.calY = gy;
        mem.turnSinceCal = 0;
      }

      var ex = gx - mem.x, ey = gy - mem.y;
      var ed = hyp(ex, ey);
      if (ed > 15) {
        mem.x = gx;
        mem.y = gy;
      } else if (ed > 0.0004) {
        mem.x += ex * 0.62;
        mem.y += ey * 0.62;
      }
    } else {
      if (speedAbs > 0.13 && t - mem.lastGpsT > 2.0) mem.gpsFrozen = true;
    }
  }

  var rawRays = obs.rays || [];
  var rays = [];
  for (var ri = 0; ri < 9; ri++) {
    var rr = +rawRays[ri];
    if (!isFinite(rr) || rr < 0) rr = 15;
    if (rr > 15) rr = 15;

    if (rr < 0.30) mem.rayLow[ri] += dt;
    else mem.rayLow[ri] = 0;

    if (mem.rayIgnore[ri] > t && rr > 2.0) {
      mem.rayIgnore[ri] = -999;
      mem.rayLow[ri] = 0;
    }

    if (mem.rayLow[ri] > 7.0 && !obs.bumped &&
        speedAbs < 0.25 && t > mem.recoverUntil + 1.0) {
      mem.rayIgnore[ri] = t + 8.0;
      mem.rayLow[ri] = 0;
    }

    if (mem.rayIgnore[ri] > t) rr = 15;
    rays.push(rr);
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    var pos = (a + 80) / 20;
    var i0 = Math.floor(pos);
    if (i0 < 0) i0 = 0;
    if (i0 > 7) i0 = 7;
    var f = pos - i0;
    return rays[i0] * (1 - f) + rays[i0 + 1] * f;
  }

  function getBaseDist() {
    if (obs.docked) return 0;
    if (obs.beacon && isFinite(+obs.beacon.distance) && +obs.beacon.distance < 30) {
      return Math.max(0, +obs.beacon.distance);
    }
    return hyp(mem.x - mem.base.x, mem.y - mem.base.y);
  }

  function drive(v, omega, hold) {
    var targetL = clamp(v - omega * 0.3, -2.35, 2.35);
    var targetR = clamp(v + omega * 0.3, -2.35, 2.35);

    var hf = hold ? 1 : 0;
    if (mem.ctrlHold !== hf) {
      mem.intL = 0;
      mem.intR = 0;
      mem.ctrlHold = hf;
    }

    var eL = targetL - vL;
    var eR = targetR - vR;
    var kp = hold ? 0.98 : 0.58;
    var ki = hold ? 1.25 : 0.74;

    if (dt > 0) {
      mem.intL = clamp((mem.intL || 0) * 0.991 + eL * dt * ki, -0.75, 0.75);
      mem.intR = clamp((mem.intR || 0) * 0.991 + eR * dt * ki, -0.75, 0.75);
    }

    var pitch = isFinite(+obs.pitch) ? +obs.pitch : 0;
    var slope = (hold ? 0.30 : 0.055) * Math.sin(pitch * RAD);

    var uL = targetL / 2.8 + kp * eL + (mem.intL || 0) + slope;
    var uR = targetR / 2.8 + kp * eR + (mem.intR || 0) + slope;

    if (targetL > 0.025 && uL < 0.035) uL = 0.035;
    if (targetL > 0.10 && uL < 0.052) uL = 0.052;
    if (targetL < -0.025 && uL > -0.035) uL = -0.035;
    if (targetL < -0.10 && uL > -0.052) uL = -0.052;
    if (targetR > 0.025 && uR < 0.035) uR = 0.035;
    if (targetR > 0.10 && uR < 0.052) uR = 0.052;
    if (targetR < -0.025 && uR > -0.035) uR = -0.035;
    if (targetR < -0.10 && uR > -0.052) uR = -0.052;

    return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1) };
  }

  function navRel(relIn, dist, vmax, arrive) {
    var rel = wrap(relIn);
    if (!isFinite(dist)) dist = 100;
    if (dist <= arrive) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }

    if (Math.abs(rel) > 110 && speedAbs < 0.30) {
      var dir0 = rel >= 0 ? 1 : -1;
      mem.lastCmdSpeed = 0.30;
      return drive(0, dir0 * 0.90, false);
    }

    var bestC = 0, bestClear = 0, bestScore = -1e15;
    for (var c = -80; c <= 80; c += 10) {
      var r0 = rayAt(c);
      var r1 = Math.min(rayAt(c - 20), rayAt(c + 20));
      var r2 = Math.min(rayAt(c - 40), rayAt(c + 40));
      var clear = Math.min(r0, r1 * 0.92, r2 * 0.78);
      if (!isFinite(clear) || clear < 0) clear = 0;

      var align = Math.abs(wrap(c - rel));
      var score = Math.min(clear, 6.0) * 2.40 - align * 0.072;

      if (clear < 0.55) score -= 65;
      else if (clear < 1.00) score -= 18;
      else if (clear < 1.60) score -= 3.5;

      var aa = (mem.head + c) * RAD;
      var look = Math.min(3.0, Math.max(0.55, clear));
      var px = mem.x + Math.cos(aa) * look;
      var py = mem.y + Math.sin(aa) * look;
      if (px < 1.2 || px > mem.sizeX - 1.2 ||
          py < 1.2 || py > mem.sizeY - 1.2) {
        score -= 95;
      }

      score -= Math.abs(c) * 0.0025;

      if (score > bestScore) {
        bestScore = score;
        bestC = c;
        bestClear = clear;
      }
    }

    var c2 = bestC;
    var ar = Math.abs(c2);
    var v = vmax;

    if (bestClear < 0.55) v = 0;
    else if (bestClear < 0.95) v = Math.min(v, 0.055);
    else if (bestClear < 1.50) v = Math.min(v, 0.16);
    else if (bestClear < 2.40) v = Math.min(v, 0.36);
    else if (bestClear < 4.00) v = Math.min(v, 0.62);
    else v = Math.min(v, 0.95);

    if (ar > 70) v = Math.min(v, 0.04);
    else if (ar > 50) v = Math.min(v, 0.12);
    else if (ar > 30) v = Math.min(v, 0.30);
    else if (ar > 15) v = Math.min(v, 0.55);

    var remain = dist - arrive;
    if (remain < 0.7) v = Math.min(v, 0.04);
    else if (remain < 2.0) v = Math.min(v, 0.13);
    else if (remain < 5.0) v = Math.min(v, 0.34);
    else if (remain < 10.0) v = Math.min(v, 0.64);

    if (speedAbs > 0.28 &&
        bestClear < 0.65 + 0.38 * Math.abs(speedAbs)) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }

    var omega = clamp(c2 * 0.024, -1.25, 1.25);
    if (Math.abs(c2) < 2) omega = 0;
    if (v < 0.025 && Math.abs(c2) > 8) {
      omega = clamp(c2 * 0.018, -1.00, 1.00);
    }

    var hold = (Math.abs(v) < 0.035 && Math.abs(omega) < 0.07);
    mem.lastCmdSpeed = Math.abs(v) + Math.abs(omega) * 0.3;
    return drive(v, omega, hold);
  }

  function navTo(tx, ty, vmax, arrive) {
    var dx = tx - mem.x, dy = ty - mem.y;
    var d = hyp(dx, dy);
    if (d <= arrive) {
      mem.lastCmdSpeed = 0;
      return drive(0, 0, true);
    }
    var desired = Math.atan2(dy, dx) * DEG;
    return navRel(wrap(desired - mem.head), d, vmax, arrive);
  }

  function brakeCmd() {
    mem.lastCmdSpeed = 0;
    return drive(0, 0, true);
  }

  function canAffordSample(dS) {
    var dB = getBaseDist();
    var per = clamp(mem.perM, 0.0006, 0.0022);
    var battNeed = 0.09 + dB * per * 1.7 + (carriedNow + 1) * 0.012 + 0.025;
    var timeNeed = dB / 0.34 + 16 + (carriedNow + 1) * 4;
    return batteryNow > battNeed && timeLeft > timeNeed;
  }

  function startApproach(siteObs) {
    var sr = +siteObs.bearing || 0;
    var sd = +siteObs.distance || 0;
    var ang = (mem.head + sr) * RAD;
    mem.approachX = mem.x + Math.cos(ang) * sd;
    mem.approachY = mem.y + Math.sin(ang) * sd;
    mem.approachValue = +siteObs.value || 0;
    mem.mode = "approach";
    mem.approachStart = t;
    mem.approachLastSeen = t;
    mem.search = null;
    mem.target = null;
    mem.sample = null;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
  }

  function startDrill(dd, rr, vv) {
    var ang = (mem.head + rr) * RAD;
    mem.sample = {
      startCarried: carriedNow,
      startT: t,
      maxProg: 0,
      lastProgT: t,
      lastSeen: t,
      lastDist: dd,
      value: vv || 0,
      holdX: mem.x,
      holdY: mem.y,
      sx: mem.x + Math.cos(ang) * dd,
      sy: mem.y + Math.sin(ang) * dd
    };
    mem.mode = "drill";
  }

  function finishSample() {
    var px = mem.x, py = mem.y;
    if (mem.activeHint) {
      if (hyp(mem.activeHint.x - px, mem.activeHint.y - py) < 40) {
        mem.activeHint.status = 2;
      } else if (mem.activeHint.status === 1) {
        mem.activeHint.status = 0;
      }
      mem.activeHint = null;
    }
    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.status !== 2 && hyp(h.x - px, h.y - py) < 18) {
        h.status = 2;
      }
    }

    mem.sample = null;
    mem.search = null;
    mem.target = null;
    mem.cooldownUntil = t + 0.8;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    mem.mode = carriedNow > 0 ? "return" : "choose";
  }

  function abortApproach() {
    if (mem.activeHint && mem.activeHint.status === 1) {
      if (hyp(mem.activeHint.x - mem.x, mem.activeHint.y - mem.y) < 15) {
        mem.activeHint.status = 3;
      } else {
        mem.activeHint.status = 0;
      }
    }
    mem.activeHint = null;
    mem.sample = null;
    mem.search = null;
    mem.cooldownUntil = t + 1.5;
    mem.mode = carriedNow > 0 ? "return" : "choose";
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  function makeSpiral(cx, cy, spacing, maxR) {
    var pts = [];
    var x = cx, y = cy;
    pts.push({ x: cx, y: cy, r: 0 });
    var dx = [1, 0, -1, 0], dy = [0, 1, 0, -1];
    var d = 0, len = 1;
    for (var outer = 0; outer < 80; outer++) {
      for (var side = 0; side < 2; side++) {
        for (var k = 0; k < len; k++) {
          x += dx[d] * spacing;
          y += dy[d] * spacing;
          var rr = hyp(x - cx, y - cy);
          if (rr <= maxR + spacing * 0.70) {
            pts.push({ x: x, y: y, r: rr });
          }
        }
        d = (d + 1) % 4;
      }
      len++;
      if (len * spacing / 2 > maxR + spacing) break;
    }
    return pts;
  }

  function startSearch(cx, cy, hintObj, type, maxR, maxDur) {
    var spacing = type === "science" ? 10.0 : 10.5;
    var pts = makeSpiral(cx, cy, spacing, maxR);
    mem.search = {
      h: hintObj,
      cx: cx,
      cy: cy,
      pts: pts,
      idx: 0,
      wpT: t,
      startT: t,
      type: type,
      maxR: maxR,
      maxDur: maxDur,
      maxSci: 0,
      bestX: cx,
      bestY: cy
    };
    mem.mode = "search";
    mem.target = null;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    if (hintObj) {
      hintObj.status = 1;
      mem.activeHint = hintObj;
    } else {
      mem.activeHint = null;
    }
  }

  function finishSearch(failed) {
    if (mem.search && mem.search.h) {
      if (mem.search.h.status === 1) {
        mem.search.h.status = failed ? 3 : 2;
      }
    }
    mem.search = null;
    mem.activeHint = null;
    mem.target = null;
    mem.mode = "choose";
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  if (obs.bumped && mem.mode !== "drill" && t > mem.bumpAck) {
    mem.bumpAck = t + 1.3;
    mem.recoverUntil = t + 0.95;
    var leftB = rays[6] + rays[7] + rays[8];
    var rightB = rays[0] + rays[1] + rays[2];
    mem.recoverDir = leftB >= rightB ? 1 : -1;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
  }

  if (t < mem.recoverUntil && mem.mode !== "drill") {
    var rec = drive(-0.23, (mem.recoverDir || 1) * 0.90, false);
    return { left: rec.left, right: rec.right, drill: false };
  }

  if (dt > 0) {
    var prog = hyp(mem.x - mem.lastProgX, mem.y - mem.lastProgY);
    if (prog > 0.38) {
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      mem.stuckCount = 0;
    }
  }

  var dBaseNow = getBaseDist();
  var movingMode = (mem.mode === "goto" || mem.mode === "search" ||
                    mem.mode === "return" || mem.mode === "explore" ||
