      if (t - S.startT > 11.0 || dS > 1.55) {
        mem.sample = null;
        if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
        mem.mode = carriedNow > 0 ? "return" : "choose";
        mem.cooldownUntil = t + 2.0;
        var oFailD = brakeCmd();
        return { left: oFailD.left, right: oFailD.right, drill: false };
      }

      S.lastProgT = t - 1.0;
    }

    if (p < 5.7 && t - S.startT > 22.0) {
      mem.sample = null;
      if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
      mem.mode = carriedNow > 0 ? "return" : "choose";
      mem.cooldownUntil = t + 2.0;
      var oLongD = brakeCmd();
      return { left: oLongD.left, right: oLongD.right, drill: false };
    }

    var outD;
    if (visS && dS > 1.36 && dS < 1.52 && p < 0.45 && speedAbs < 0.085) {
      var relC = +obs.site.bearing || 0;
      outD = drive(0.035, clamp(relC * 0.018, -0.08, 0.08), true);
    } else {
      outD = drive(0, 0, true);
    }
    return { left: outD.left, right: outD.right, drill: true };
  }

  if (carriedNow > 0 && mem.mode !== "return" && mem.mode !== "dock" && mem.mode !== "drill") {
    mem.mode = "return";
    mem.sample = null;
    mem.search = null;
    mem.target = null;
    if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
    mem.activeHint = null;
  }

  var needReturn = false;
  if (carriedNow >= mem.cap) needReturn = true;
  if (carriedNow > 0 && carriedNow >= mem.batch) needReturn = true;
  if (carriedNow > 0) {
    var battReturn = 0.09 + dBaseNow * 0.0016 + carriedNow * 0.014;
    var timeReturn = dBaseNow / 0.32 + 16 + carriedNow * 4;
    if (batteryNow < battReturn || timeLeft < timeReturn) needReturn = true;
  }
  if (batteryNow < 0.075 && dBaseNow > 8) needReturn = true;
  if (timeLeft < dBaseNow / 0.28 + 10) needReturn = true;

  if (needReturn && mem.mode !== "return" && mem.mode !== "dock") {
    mem.mode = "return";
    mem.sample = null;
    mem.search = null;
    mem.target = null;
    if (mem.activeHint && mem.activeHint.status === 1) mem.activeHint.status = 0;
    mem.activeHint = null;
  }

  if (mem.mode !== "return" && mem.mode !== "dock" &&
      mem.mode !== "drill" && mem.mode !== "approach" &&
      carriedNow < mem.cap && carriedNow < mem.batch &&
      t > mem.cooldownUntil &&
      obs.site && isFinite(+obs.site.distance) &&
      +obs.site.distance < 7.9 &&
      canAffordSample(+obs.site.distance)) {
    startApproach(obs.site);
    var oOpp = brakeCmd();
    return { left: oOpp.left, right: oOpp.right, drill: false };
  }

  if (mem.mode === "return") {
    if (dBaseNow <= 2.90 || obs.docked) {
      mem.mode = "dock";
      mem.dockStart = null;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
      var oArrR = brakeCmd();
      return { left: oArrR.left, right: oArrR.right, drill: false };
    }

    var vRet = carriedNow > 0 ? 0.80 : 0.88;
    if (dBaseNow < 10) vRet = Math.min(vRet, 0.52);
    if (dBaseNow < 5) vRet = Math.min(vRet, 0.30);

    var outR;
    if (obs.beacon && isFinite(+obs.beacon.distance) &&
        isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
      outR = navRel(+obs.beacon.bearing, +obs.beacon.distance, vRet, 0.55);
    } else {
      outR = navTo(mem.base.x, mem.base.y, vRet, 0.55);
    }
    return { left: outR.left, right: outR.right, drill: false };
  }

  if (mem.mode === "dock") {
    var dD = getBaseDist();
    if (!obs.docked && dD > 3.25) {
      mem.mode = "return";
      var oLeaveDock = brakeCmd();
      return { left: oLeaveDock.left, right: oLeaveDock.right, drill: false };
    }

    if (mem.dockStart == null) {
      mem.dockStart = t;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
      mem.dockPlateau = false;
    }

    if (carriedNow > 0) {
      if (!obs.docked && dD > 2.55 && t - mem.dockStart > 0.7) {
        var outCreep;
        if (obs.beacon && isFinite(+obs.beacon.distance) &&
            isFinite(+obs.beacon.bearing) && +obs.beacon.distance < 20) {
          outCreep = navRel(+obs.beacon.bearing, +obs.beacon.distance, 0.20, 0.35);
        } else {
          outCreep = navTo(mem.base.x, mem.base.y, 0.20, 0.35);
        }
        return { left: outCreep.left, right: outCreep.right, drill: false };
      }
      var oWaitUnload = brakeCmd();
      return { left: oWaitUnload.left, right: oWaitUnload.right, drill: false };
    }

    var delivNow = isFinite(+obs.delivered) ? +obs.delivered : mem.lastDelivered;
    if (delivNow > mem.lastDelivered) {
      mem.lastDelivered = delivNow;
      mem.firstDeliveryDone = true;
      mem.batch = 1;
    }

    if (t - mem.dockCheckT > 2.0) {
      if (batteryNow - mem.dockLastBatt < 0.0015) mem.dockPlateau = true;
      else mem.dockPlateau = false;
      mem.dockLastBatt = batteryNow;
      mem.dockCheckT = t;
    }

    var targetB = 0.86;
    if (timeLeft < 360) targetB = 0.68;
    if (timeLeft < 180) targetB = 0.48;
    if (timeLeft < 80) targetB = 0.30;

    var wantCharge = batteryNow < targetB &&
                     timeLeft > 35 &&
                     !mem.dockPlateau &&
                     (t - mem.dockStart < 75);

    if (wantCharge) {
      var oCharge = brakeCmd();
      return { left: oCharge.left, right: oCharge.right, drill: false };
    }

    mem.mode = "choose";
    mem.dockStart = null;
    mem.target = null;
    mem.search = null;
    mem.activeHint = null;
    var oLeaveCharge = brakeCmd();
    return { left: oLeaveCharge.left, right: oLeaveCharge.right, drill: false };
  }

  if (mem.mode === "approach") {
    var dApp, relApp, visible = false, valApp = mem.approachValue || 0;

    if (obs.site && isFinite(+obs.site.distance)) {
      dApp = +obs.site.distance;
      relApp = +obs.site.bearing || 0;
      visible = true;
      valApp = +obs.site.value || 0;
      mem.approachLastSeen = t;
      mem.approachValue = valApp;
      var angA = (mem.head + relApp) * RAD;
      mem.approachX = mem.x + Math.cos(angA) * dApp;
      mem.approachY = mem.y + Math.sin(angA) * dApp;
    } else {
      if (mem.approachX == null || t - mem.approachLastSeen > 3.2) {
        abortApproach();
        var oLostA = brakeCmd();
        return { left: oLostA.left, right: oLostA.right, drill: false };
      }
      var dxA = mem.approachX - mem.x;
      var dyA = mem.approachY - mem.y;
      dApp = hyp(dxA, dyA);
      relApp = wrap(Math.atan2(dyA, dxA) * DEG - mem.head);
    }

    if (carriedNow >= mem.cap || carriedNow >= mem.batch) {
      mem.mode = carriedNow > 0 ? "return" : "choose";
      var oCarA = brakeCmd();
      return { left: oCarA.left, right: oCarA.right, drill: false };
    }

    if (!canAffordSample(dApp)) {
      abortApproach();
      var oAbA = brakeCmd();
      return { left: oAbA.left, right: oAbA.right, drill: false };
    }

    if (dApp <= 1.36 && speedAbs < 0.125) {
      startDrill(dApp, relApp, valApp);
      var oStartD = drive(0, 0, true);
      return { left: oStartD.left, right: oStartD.right, drill: true };
    }

    if (dApp <= 1.45 && speedAbs < 0.075) {
      startDrill(dApp, relApp, valApp);
      var oStartD2 = drive(0, 0, true);
      return { left: oStartD2.left, right: oStartD2.right, drill: true };
    }

    if (dApp <= 1.70 && speedAbs > 0.10) {
      var oBrakeA = drive(0, 0, true);
      return { left: oBrakeA.left, right: oBrakeA.right, drill: false };
    }

    if (t - mem.approachStart > 55 && dApp > 1.35) {
      abortApproach();
      var oTimeA = brakeCmd();
      return { left: oTimeA.left, right: oTimeA.right, drill: false };
    }

    if (!visible && dApp < 1.45) {
      abortApproach();
      var oNearLost = brakeCmd();
      return { left: oNearLost.left, right: oNearLost.right, drill: false };
    }

    var frontA = rayAt(relApp);
    if (frontA < 0.45 && dApp > 1.45) {
      var outAvoidA = navTo(mem.approachX, mem.approachY, 0.28, 0.45);
      return { left: outAvoidA.left, right: outAvoidA.right, drill: false };
    }

    var vA;
    if (dApp > 5.0) vA = 0.44;
    else if (dApp > 3.0) vA = 0.29;
    else if (dApp > 2.0) vA = 0.19;
    else if (dApp > 1.5) vA = 0.13;
    else vA = 0.085;

    if (frontA < 0.35) vA = 0;
    else if (frontA < 0.70) vA = Math.min(vA, 0.065);

    var omegaA = clamp(relApp * 0.026, -1.00, 1.00);
    if (Math.abs(relApp) < 2) omegaA = 0;
    if (Math.abs(relApp) > 70) {
      vA = Math.min(vA, 0.040);
      omegaA = clamp(relApp * 0.030, -0.80, 0.80);
    }

    if (dApp <= 1.55) vA = Math.min(vA, 0.10);
    if (dApp <= 1.40) vA = Math.min(vA, 0.075);

    var outA = drive(vA, omegaA, false);
    return { left: outA.left, right: outA.right, drill: false };
  }

  if (mem.mode === "goto") {
    var H = mem.activeHint;
    if (!H || H.status !== 1) {
      mem.mode = "choose";
      var oG0 = brakeCmd();
      return { left: oG0.left, right: oG0.right, drill: false };
    }

    var dH = hyp(H.x - mem.x, H.y - mem.y);
    if (dH < 3.2) {
      startSearch(H.x, H.y, H, "hint", 22.0, 100);
      var oGS = brakeCmd();
      return { left: oGS.left, right: oGS.right, drill: false };
    }

    if (t - mem.targetStart > 205) {
      H.status = 3;
      mem.activeHint = null;
      mem.target = null;
      mem.mode = "choose";
      var oGTimeout = brakeCmd();
      return { left: oGTimeout.left, right: oGTimeout.right, drill: false };
    }

    var vG = 0.86;
    if (dH < 12) vG = 0.54;
    if (dH < 6) vG = 0.34;

    var outG = navTo(H.x, H.y, vG, 0.85);
    return { left: outG.left, right: outG.right, drill: false };
  }

  if (mem.mode === "search") {
    var SS = mem.search;
    if (!SS) {
      mem.mode = "choose";
      var oS0 = brakeCmd();
      return { left: oS0.left, right: oS0.right, drill: false };
    }

    var sciNow = isFinite(+obs.science) ? +obs.science : 0;
    if (sciNow > SS.maxSci + 0.001) {
      SS.maxSci = sciNow;
      SS.bestX = mem.x;
      SS.bestY = mem.y;
    }

    if (SS.idx >= SS.pts.length || t - SS.startT > SS.maxDur) {
      finishSearch(true);
      var oSFail = brakeCmd();
      return { left: oSFail.left, right: oSFail.right, drill: false };
    }

    if (SS.type === "hint" && t - SS.startT > 34 && SS.maxSci < 0.015) {
      finishSearch(true);
      var oSQuiet = brakeCmd();
      return { left: oSQuiet.left, right: oSQuiet.right, drill: false };
    }
    if (SS.type === "science" && t - SS.startT > 40 && SS.maxSci < 0.018) {
      finishSearch(true);
      var oSQuiet2 = brakeCmd();
      return { left: oSQuiet2.left, right: oSQuiet2.right, drill: false };
    }

    var wp = SS.pts[SS.idx];
    var dW = hyp(wp.x - mem.x, wp.y - mem.y);

    if (dW < 1.55 || t - SS.wpT > 16.0) {
      SS.idx++;
      SS.wpT = t;
      if (SS.idx >= SS.pts.length) {
        finishSearch(true);
        var oSEnd = brakeCmd();
        return { left: oSEnd.left, right: oSEnd.right, drill: false };
      }
      wp = SS.pts[SS.idx];
      dW = hyp(wp.x - mem.x, wp.y - mem.y);
    }

    var vS = dW < 5 ? 0.54 : 0.82;
    if (SS.type === "science" && SS.maxSci > 0.30) vS = Math.min(vS, 0.50);

    var outS = navTo(wp.x, wp.y, vS, 0.80);
    return { left: outS.left, right: outS.right, drill: false };
  }

  if (mem.mode === "explore") {
    var ET = mem.target;
    if (!ET || !ET.point) {
      mem.mode = "choose";
      var oE0 = brakeCmd();
      return { left: oE0.left, right: oE0.right, drill: false };
    }

    var de = hyp(ET.x - mem.x, ET.y - mem.y);
    if (de < 3.2 || t - mem.targetStart > 95) {
      ET.point.done = true;
      mem.target = null;
      mem.mode = "choose";
      mem.lastProgX = mem.x;
      mem.lastProgY = mem.y;
      mem.lastProgT = t;
      var oEDone = brakeCmd();
      return { left: oEDone.left, right: oEDone.right, drill: false };
    }

    var vE = de < 8 ? 0.52 : 0.78;
    var outE = navTo(ET.x, ET.y, vE, 1.20);
    return { left: outE.left, right: outE.right, drill: false };
  }

  if (mem.mode === "idle") {
    if (timeLeft < 25 || batteryNow < 0.05) {
      var oIdleStay = brakeCmd();
      return { left: oIdleStay.left, right: oIdleStay.right, drill: false };
    }
    mem.mode = "choose";
  }

  mem.target = null;
  mem.search = null;
  if (mem.activeHint && mem.activeHint.status === 1) {
    mem.activeHint.status = 0;
    mem.activeHint = null;
  }

  if (timeLeft < 24) {
    mem.mode = "idle";
    var oFinal = brakeCmd();
    return { left: oFinal.left, right: oFinal.right, drill: false };
  }

  if (carriedNow >= mem.batch || carriedNow >= mem.cap) {
    mem.mode = carriedNow > 0 ? "return" : "choose";
    var oCarryRet = brakeCmd();
    return { left: oCarryRet.left, right: oCarryRet.right, drill: false };
  }

  if (carriedNow > 0) {
    var battRetC = 0.09 + dBaseNow * 0.0016 + carriedNow * 0.014;
    var timeRetC = dBaseNow / 0.32 + 16 + carriedNow * 4;
    if (batteryNow < battRetC || timeLeft < timeRetC) {
      mem.mode = "return";
      var oCarrySafety = brakeCmd();
      return { left: oCarrySafety.left, right: oCarrySafety.right, drill: false };
    }
  }

  if (dBaseNow < 3.2 && carriedNow === 0) {
    var chargeTargetChoose = 0.84;
    if (timeLeft < 360) chargeTargetChoose = 0.64;
    if (timeLeft < 180) chargeTargetChoose = 0.46;
    if (batteryNow < chargeTargetChoose && timeLeft > 45 && !mem.dockPlateau) {
      mem.mode = "dock";
      mem.dockStart = null;
      var oChooseDock = brakeCmd();
      return { left: oChooseDock.left, right: oChooseDock.right, drill: false };
    }
  }

  var planPer = clamp(mem.perM || 0.0012, 0.0006, 0.0022);
  var bestH = null;
  var bestScore = -1e18;

  for (var bi = 0; bi < mem.hints.length; bi++) {
    var hC = mem.hints[bi];
    if (hC.status !== 0) continue;

    var dhC = hyp(hC.x - mem.x, hC.y - mem.y);
    var hbC = hyp(hC.x - mem.base.x, hC.y - mem.base.y);

    var timeCost = (dhC + hbC + 25) / 0.50 + 34;
    if (timeLeft < timeCost) continue;

    var battNeed = 0.075 + (dhC + hbC + 30) * planPer * 1.45 +
                   (carriedNow + 1) * 0.012;
    if (batteryNow < battNeed) continue;

    var valH = Math.max(0.005, hC.v || 0.05);
    var scoreH;
    if (!mem.firstDeliveryDone) {
      scoreH = valH / (dhC + 0.72 * hbC + 34);
    } else {
      scoreH = valH / (dhC + 0.55 * hbC + 28);
    }

    if (dhC < 10) scoreH *= 1.22;
    if (dhC > 220) scoreH *= 0.55;
    if (carriedNow > 0) scoreH *= (1 - 0.015 * carriedNow);

    if (scoreH > bestScore) {
      bestScore = scoreH;
      bestH = hC;
    }
  }

  if (!bestH && timeLeft > 45 && batteryNow > 0.16) {
    var nearestH = null, nearestHD = 1e18;
    for (var bj = 0; bj < mem.hints.length; bj++) {
      var hN = mem.hints[bj];
      if (hN.status !== 0) continue;
      var dN = hyp(hN.x - mem.x, hN.y - mem.y);
      var bN = hyp(hN.x - mem.base.x, hN.y - mem.base.y);
      var estT = (dN + bN + 20) / 0.45 + 28;
      var estB = 0.06 + (dN + bN + 20) * planPer * 1.25;
      if (timeLeft < estT) continue;
      if (batteryNow < estB * 0.85) continue;
      if (dN < nearestHD) {
        nearestHD = dN;
        nearestH = hN;
      }
    }
    if (nearestH) bestH = nearestH;
  }

  if (bestH) {
    bestH.status = 1;
    mem.activeHint = bestH;
    mem.target = { x: bestH.x, y: bestH.y, hint: bestH };
    mem.mode = "goto";
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oPick = brakeCmd();
    return { left: oPick.left, right: oPick.right, drill: false };
  }

  if (carriedNow > 0) {
    mem.mode = "return";
    var oCarryRet2 = brakeCmd();
    return { left: oCarryRet2.left, right: oCarryRet2.right, drill: false };
  }

  var sciFallback = isFinite(+obs.science) ? +obs.science : 0;
  if (sciFallback > 0.15 && timeLeft > 110 && batteryNow > 0.24 &&
      mem.sciSearchCount < 2 && t > mem.sciCooldown &&
      hyp(mem.x - mem.lastSciX, mem.y - mem.lastSciY) > 22) {
    mem.sciSearchCount++;
    mem.sciCooldown = t + 105;
    mem.lastSciX = mem.x;
    mem.lastSciY = mem.y;
    startSearch(mem.x, mem.y, null, "science", 18.0, 75);
    var oSciFallback = brakeCmd();
    return { left: oSciFallback.left, right: oSciFallback.right, drill: false };
  }

  var bestP = null, bestPD = 1e18;
  for (var ei = 0; ei < mem.explorePts.length; ei++) {
    var ep = mem.explorePts[ei];
    if (ep.done) continue;
    var dp = hyp(ep.x - mem.x, ep.y - mem.y);
    var pb = hyp(ep.x - mem.base.x, ep.y - mem.base.y);
    if (timeLeft < (dp + pb) / 0.35 + 28) continue;
    if (batteryNow < 0.12 + (dp + pb) * planPer * 1.45) continue;
    if (dp < bestPD) {
      bestPD = dp;
      bestP = ep;
    }
  }

  if (bestP) {
    mem.mode = "explore";
    mem.target = { x: bestP.x, y: bestP.y, point: bestP };
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oExplore = brakeCmd();
    return { left: oExplore.left, right: oExplore.right, drill: false };
  }

  if (timeLeft > 35 && batteryNow > 0.16) {
    mem.wanderIndex = (mem.wanderIndex || 0) + 1;
    var wa = (mem.wanderIndex * 137.5) * RAD;
    var wr = 45 + (mem.wanderIndex % 3) * 25;
    var wx = clamp(mem.x + Math.cos(wa) * wr, 8, mem.sizeX - 8);
    var wy = clamp(mem.y + Math.sin(wa) * wr, 8, mem.sizeY - 8);
    mem.mode = "explore";
    mem.target = { x: wx, y: wy, point: { x: wx, y: wy, done: false } };
    mem.targetStart = t;
    mem.lastProgX = mem.x;
    mem.lastProgY = mem.y;
    mem.lastProgT = t;
    mem.stuckCount = 0;
    var oWander = brakeCmd();
    return { left: oWander.left, right: oWander.right, drill: false };
  }

  mem.mode = "idle";
  var oFinalIdle = brakeCmd();
  return { left: oFinalIdle.left, right: oFinalIdle.right, drill: false };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function init(obs, mem) {
  const m = obs.mission || {};
  const b = m.base || { x: 0, y: 0 };
  mem.base = { x: b.x, y: b.y };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map(h => ({
    x: h.x, y: h.y,
    est: typeof h.estimate === 'number' ? h.estimate : 1,
    done: false, fails: 0
  }));
  mem.seed = 12345;
  mem.tick = 0;
  mem.ref = null; mem.off = 0; mem.offInit = false;
  mem.mode = 'pick'; mem.tgt = null; mem.tgtT = 0; mem.search = null;
  mem.back = 0; mem.backTurn = 1;
  mem.drilling = false; mem.dT = 0; mem.dPos = null; mem.carried0 = 0;
  mem.dockT = 0; mem.chargeT = 0; mem.siteT = 0;
  mem.visited = []; mem.explored = [];
  mem.ignoreUntil = 0; mem.noTargets = false;
  mem.sp = null; mem.cmdAcc = 0; mem.cmdN = 0; mem.stuck = 0;
  mem.hd = 0;
  mem.init = true;
}

function sanitize(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    let v = (r && typeof r[i] === 'number') ? r[i] : 15;
    if (!isFinite(v)) v = 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function brake(obs) {
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  const c = clamp(-avg * 1.5, -0.3, 0.3);
  return { left: c, right: c };
}

// Heading = compass + offset; offset is learned from GPS track when driving straight.
function updateHeading(obs, mem) {
  const h = obs.heading || 0;
  const x = obs.x, y = obs.y;
  if (!mem.ref) { mem.ref = { x: x, y: y }; return wrap(h + mem.off); }
  const dx = x - mem.ref.x, dy = y - mem.ref.y, d = Math.hypot(dx, dy);
  if (d > 2.0) {
    const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
    if (d < 6 && Math.abs(wl - wr) < 0.12 && (wl + wr) > 0.3) {
      const gh = Math.atan2(dy, dx) * R2D;
      const off = wrap(gh - h);
      if (!mem.offInit) { mem.off = off; mem.offInit = true; }
      else mem.off = wrap(mem.off + 0.15 * wrap(off - mem.off));
    }
    mem.ref = { x: x, y: y };
  }
  return wrap(h + mem.off);
}

// Steering with obstacle avoidance. e = bearing error (deg, positive = target to the left).
function drive(e, spd, rays) {
  const minF = Math.min(rays[3], rays[4], rays[5]);
  let adj = 0;
  for (let i = 0; i < 9; i++) {
    const r = rays[i];
    if (r >= 3) continue;
    const ang = -80 + 20 * i;
    adj += -((3 - r) / 3) * ang * 0.4;
  }
  if (rays[4] < 4) {
    const L = (rays[5] + rays[6] + rays[7]) / 3;
    const R = (rays[1] + rays[2] + rays[3]) / 3;
    adj += (L > R ? 1 : -1) * 25 * (4 - rays[4]) / 4;
  }
  const ee = clamp(e + adj, -180, 180);
  let s = spd;
  if (minF < 1.5) s = Math.min(s, 0.15);
  else if (minF < 3) s = Math.min(s, 0.3);
  else if (minF < 5) s = Math.min(s, 0.5);
  const fwd = s * clamp(1 - Math.abs(ee) / 60, 0, 1);
  let turn = clamp(ee / 30, -1, 1) * 0.6;
  if (Math.abs(ee) > 10 && Math.abs(turn) < 0.25) turn = Math.sign(ee) * 0.25;
  return { left: clamp(fwd - turn, -1, 1), right: clamp(fwd + turn, -1, 1) };
}

function pickHint(mem, me, tl) {
  let best = null, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.8 > tl - 40) continue;
    const sc = (Math.max(h.est, 0) + 0.1) / (d1 + 0.8 * d2 + 25);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function wanderPoint(mem, me) {
  let best = null, bs = -Infinity;
  const pts = mem.visited.concat(mem.explored);
  for (let k = 0; k < 8; k++) {
    const c = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
    let md = 300;
    for (const v of pts) md = Math.min(md, dist(c.x, c.y, v.x, v.y));
    const sc = Math.min(md, 150) - 0.25 * dist(c.x, c.y, me.x, me.y);
    if (sc > bs) { bs = sc; best = c; }
  }
  return best;
}

function markNearestHint(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function startDrill(mem, me, carried) {
  mem.drilling = true; mem.dT = 0;
  mem.dPos = { x: me.x, y: me.y };
  mem.carried0 = carried; mem.siteT = 0;
}

function drillStep(obs, mem, out, carried) {
  mem.dT++;
  out.drill = true;
  const b = brake(obs); out.left = b.left; out.right = b.right;
  const got = carried > mem.carried0;
  const sec = obs.drilling || 0;
  let finish = false;
  if (got) finish = true;
  else if (sec >= 6.5 && !obs.site) finish = true;
  else if (sec >= 10) finish = true;
  else if (mem.dT > 250) finish = true;
  if (finish) {
    out.drill = false;
    mem.drilling = false;
    if (got || !obs.site) markNearestHint(mem, mem.dPos, 25);
    if (got) {
      mem.visited.push({ x: mem.dPos.x, y: mem.dPos.y });
      mem.search = null; mem.tgt = null;
    } else {
      mem.ignoreUntil = mem.tick + 150;
    }
  }
  return out;
}

function core(obs, mem) {
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  const me = { x: obs.x, y: obs.y };
  const hd = updateHeading(obs, mem);
  mem.hd = hd;
  const rays = sanitize(obs.rays);
  const carried = obs.carried || 0;
  const absSp = Math.abs((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  const dBase = dist(me.x, me.y, mem.base.x, mem.base.y);
  const site = obs.site;
  const docked = !!obs.docked || dBase < 2.8;

  // Stuck monitor every 3 s: commanded forward but not moving.
  if (!mem.sp) mem.sp = { x: me.x, y: me.y };
  if (mem.tick % 30 === 0) {
    const moved = dist(me.x, me.y, mem.sp.x, mem.sp.y);
    const cmd = mem.cmdN > 0 ? mem.cmdAcc / mem.cmdN : 0;
    if (cmd > 0.3 && moved < 0.25 && !mem.drilling && mem.back === 0 && !docked) {
      mem.stuck++;
      mem.back = 15;
      mem.backTurn = rnd(mem) < 0.5 ? -1 : 1;
    }
    mem.sp = { x: me.x, y: me.y };
    mem.cmdAcc = 0; mem.cmdN = 0;
  }

  if (mem.drilling) return drillStep(obs, mem, out, carried);

  if (mem.back > 0) {
    mem.back--;
    const t = mem.backTurn * 0.3;
    out.left = clamp(-0.4 - t, -1, 1);
    out.right = clamp(-0.4 + t, -1, 1);
    return out;
  }
  if (obs.bumped) {
    mem.back = 12;
    mem.backTurn = rnd(mem) < 0.5 ? -1 : 1;
    out.left = -0.3; out.right = -0.3;
    return out;
  }

  // Delivery decision
  const wantDeliver = carried > 0 && (carried >= mem.cap || obs.battery < 0.25 ||
    obs.timeLeft < dBase / 0.9 + 40 || mem.noTargets);
  if (wantDeliver && mem.mode !== 'deliver') { mem.mode = 'deliver'; mem.dockT = 0; }
  if (mem.mode === 'deliver') {
    if (carried === 0) {
      mem.mode = 'pick'; mem.dockT = 0;
    } else if (docked) {
      mem.dockT++;
      const b = brake(obs); out.left = b.left; out.right = b.right;
      if (mem.dockT > 300) { mem.mode = 'pick'; mem.dockT = 0; mem.noTargets = false; }
      return out;
    } else {
      const e = wrap(brg(me.x, me.y, mem.base.x, mem.base.y) - hd);
      return drive(e, dBase > 8 ? 0.5 : 0.3, rays);
    }
  }

  // Charge while docked with empty-ish battery and no samples
  if (docked && carried === 0) {
    if (obs.battery < 0.4 && obs.timeLeft > 250 && mem.chargeT < 120) {
      mem.chargeT++;
      const b = brake(obs); out.left = b.left; out.right = b.right;
      return out;
    }
  } else if (!docked) {
    mem.chargeT = 0;
  }

  // Site visible nearby: approach and drill
  if (site && carried < mem.cap && mem.tick >= mem.ignoreUntil) {
    mem.siteT++;
    if (mem.siteT > 400) {
      mem.ignoreUntil = mem.tick + 300; mem.siteT = 0;
    } else if (site.distance <= 1.3) {
      if (absSp < 0.12) {
        startDrill(mem, me, carried);
        return drillStep(obs, mem, out, carried);
      }
      const b = brake(obs); out.left = b.left; out.right = b.right;
      return out;
    } else {
      return drive(site.bearing, clamp(site.distance * 0.3, 0.15, 0.4), rays);
    }
  } else {
    mem.siteT = 0;
  }

  // Navigation: search pattern around a hint, else hint target, else wander
  let tgt = null;
  if (mem.search) {
    const S = mem.search;
    S.t = (S.t || 0) + 1;
    while (S.i < S.pts.length && dist(me.x, me.y, S.pts[S.i].x, S.pts[S.i].y) < 2.5) S.i++;
    if (S.i >= S.pts.length || S.t > 600) {
      mem.hints[S.h].done = true;
      mem.search = null; mem.tgt = null;
    } else {
      tgt = S.pts[S.i];
    }
  }
  if (!tgt && mem.tgt) {
    mem.tgtT++;
    const T = mem.tgt;
    const d = dist(me.x, me.y, T.x, T.y);
    const limit = (T.h !== undefined) ? 1500 : 600;
    if (mem.tgtT > limit) {
      if (T.h !== undefined) { mem.hints[T.h].fails++; mem.hints[T.h].done = true; }
      mem.tgt = null; mem.search = null;
    } else if (d < 2.5) {
      if (T.h !== undefined) {
        mem.search = {
          h: T.h, i: 0, t: 0,
          pts: [{ x: T.x + 10, y: T.y }, { x: T.x, y: T.y + 10 },
                { x: T.x - 10, y: T.y }, { x: T.x, y: T.y - 10 }]
        };
        tgt = mem.search.pts[0];
      } else {
        mem.explored.push({ x: T.x, y: T.y });
        mem.tgt = null;
      }
    } else {
      tgt = T;
    }
  }

  // Front very close and not moving: back off
  const minF = Math.min(rays[3], rays[4], rays[5]);
  if (!tgt && minF < 0.9 && absSp < 0.2 && !docked) {
    mem.back = 8; mem.backTurn = rnd(mem) < 0.5 ? -1 : 1;
    out.left = -0.3; out.right = -0.3;
    return out;
  }

  if (!tgt) {
    const hi = pickHint(mem, me, obs.timeLeft);
    if (hi !== null) {
      mem.noTargets = false;
      const h = mem.hints[hi];
      mem.tgt = { x: h.x, y: h.y, h: hi };
      mem.tgtT = 0;
      tgt = mem.tgt;
    } else if (carried > 0) {
      mem.noTargets = true;
      mem.mode = 'deliver';
      return out;
    } else {
      mem.noTargets = true;
      mem.tgt = wanderPoint(mem, me);
      mem.tgtT = 0;
      tgt = mem.tgt;
    }
  }

  const d = dist(me.x, me.y, tgt.x, tgt.y);
  const e = wrap(brg(me.x, me.y, tgt.x, tgt.y) - hd);
  return drive(e, d > 10 ? 0.5 : (d > 4 ? 0.4 : 0.3), rays);
}

function act(obs, mem) {
  if (!mem.init) init(obs, mem);
  const out = core(obs, mem);
  out.left = clamp(out.left || 0, -1, 1);
  out.right = clamp(out.right || 0, -1, 1);
  out.drill = !!out.drill;
  mem.cmdAcc = (mem.cmdAcc || 0) + (out.left + out.right) / 2;
  mem.cmdN = (mem.cmdN || 0) + 1;
  return { left: out.left, right: out.right, drill: out.drill };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function sanitize(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function init(obs, mem) {
  const m = obs.mission || {};
  const b = m.base || { x: obs.x, y: obs.y };
  mem.base = { x: b.x, y: b.y };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map(h => ({
    x: h.x, y: h.y,
    est: typeof h.estimate === 'number' ? h.estimate : 1,
    done: false, fails: 0
  }));
  mem.seed = 4242;
  mem.tick = 0;
  mem.hb = [];
  mem.off = 0; mem.calDone = false; mem.calT = 0;
  mem.gref = null;
  mem.pivot = 0;
  mem.mode = 'pick';
  mem.hi = -1; mem.goT = 0; mem.goLimit = 0;
  mem.wps = null; mem.wpI = 0; mem.srchT = 0;
  mem.exT = 0; mem.wander = null;
  mem.backPh = 0; mem.backT = 0; mem.backDir = 1;
  mem.dT = 0; mem.dCarried = 0; mem.dPos = null;
  mem.ignore = 0; mem.siteT = 0;
  mem.stkP = null; mem.stkT = 0; mem.stkC = 0; mem.stkW = 0; mem.stkN = 0;
  mem.lastL = 0; mem.lastR = 0;
  mem.noTargets = false; mem.noDeliver = 0;
  mem.dockT = 0; mem.charging = false; mem.chargeT = 0;
  mem.visited = [];
  mem.init = true;
}

// Median-like filter (medoid of last 3 compass readings) to reject jumps.
function compassMedian(mem, h) {
  mem.hb.push(h);
  if (mem.hb.length > 3) mem.hb.shift();
  if (mem.hb.length < 3) return h;
  let best = mem.hb[0], bs = Infinity;
  for (const a of mem.hb) {
    let s = 0;
    for (const b of mem.hb) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

// Heading offset calibration from GPS track over straight forward segments.
function updateCal(obs, mem, me, hm) {
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const straight = Math.abs(wl - wr) < 0.25 && (wl + wr) / 2 > 0.25;
  if (!straight || !mem.gref) { mem.gref = { x: me.x, y: me.y }; return; }
  const d = dist(me.x, me.y, mem.gref.x, mem.gref.y);
  if (d >= 3) {
    const gh = brg(mem.gref.x, mem.gref.y, me.x, me.y);
    const s = wrap(gh - hm);
    if (!mem.calDone) { mem.off = s; mem.calDone = true; }
    else mem.off = wrap(mem.off + 0.2 * wrap(s - mem.off));
    mem.gref = { x: me.x, y: me.y };
  }
}

function freeDir(rays, mem) {
  const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
  const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
  if (Math.abs(L - R) < 0.5) return rnd(mem) < 0.5 ? -1 : 1;
  return L > R ? 1 : -1;
}

// Steering with hysteresis pivot and simple obstacle avoidance.
// e: bearing error in degrees, positive = target to the left.
function steer(e, v, rays, mem) {
  const front = Math.min(rays[3], rays[4], rays[5]);
  let ee = e, vv = v;
  if (front < 1.2) {
    const L = (rays[6] + rays[7] + rays[8]) / 3;
    const R = (rays[0] + rays[1] + rays[2]) / 3;
    ee = L >= R ? 70 : -70;
    vv = 0;
  } else {
    if (front < 3) vv = Math.min(vv, 0.25);
    let adj = 0;
    for (let i = 0; i < 9; i++) {
      const r = rays[i];
      if (r >= 2.5) continue;
      const ang = -80 + 20 * i;
      adj += -((2.5 - r) / 2.5) * ang * 0.3;
    }
    ee = clamp(ee + adj, -180, 180);
  }
  if (Math.abs(ee) > 35) mem.pivot = 1;
  else if (Math.abs(ee) < 12) mem.pivot = 0;
  if (mem.pivot) {
    const s = clamp(0.3 + Math.abs(ee) / 360, 0.3, 0.5);
    const sg = ee >= 0 ? 1 : -1;
    return { left: -sg * s, right: sg * s, drill: false };
  }
  const fwd = vv * clamp(1 - Math.abs(ee) / 60, 0.5, 1);
  const turn = clamp(ee / 40, -1, 1) * 0.4;
  return { left: clamp(fwd - turn, -1, 1), right: clamp(fwd + turn, -1, 1), drill: false };
}

function pickHint(mem, me, tl) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.5 > tl - 60) continue;
    const sc = Math.max(h.est, 0.05) / (d1 + 0.6 * d2 + 25);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function markHintDone(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function buildWps(cx, cy, me, mem) {
  const a0 = brg(cx, cy, me.x, me.y) * D2R;
  const ring = (r, n) => {
    const p = [];
    for (let k = 0; k < n; k++) {
      const a = a0 + 2 * Math.PI * k / n;
      p.push({
        x: clamp(cx + r * Math.cos(a), 3, 397),
        y: clamp(cy + r * Math.sin(a), 3, 397)
      });
    }
    return p;
  };
  return ring(7, 6).concat(ring(14, 10));
}

function core(obs, mem) {
  mem.tick++;
  const me = { x: obs.x, y: obs.y };
  const hm = compassMedian(mem, obs.heading || 0);
  const hd = wrap(hm + mem.off);
  updateCal(obs, mem, me, hm);
  const rays = sanitize(obs.rays);
  const carried = obs.carried || 0;
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const wmag = (Math.abs(wl) + Math.abs(wr)) / 2;
  const dBase = dist(me.x, me.y, mem.base.x, mem.base.y);
  const out = { left: 0, right: 0, drill: false };
  const brakeOut = () => ({
    left: clamp(-wl * 1.5, -0.3, 0.3),
    right: clamp(-wr * 1.5, -0.3, 0.3),
    drill: false
  });

  // Stuck monitor: commanded motion but no GPS progress and no wheel motion.
  if (!mem.stkP) { mem.stkP = { x: me.x, y: me.y }; }
  mem.stkT++; mem.stkN++;
  mem.stkC += (Math.abs(mem.lastL) + Math.abs(mem.lastR)) / 2;
  mem.stkW += wmag;
  if (mem.stkT >= 30) {
    const moved = dist(me.x, me.y, mem.stkP.x, mem.stkP.y);
    const avgC = mem.stkC / mem.stkN, avgW = mem.stkW / mem.stkN;
    if (avgC > 0.25 && moved < 0.3 && avgW < 0.12 && mem.mode !== 'drill' && dBase > 3) {
      mem.backPh = 1; mem.backT = 15; mem.backDir = freeDir(rays, mem);
    }
    mem.stkP = { x: me.x, y: me.y };
    mem.stkT = 0; mem.stkC = 0; mem.stkW = 0; mem.stkN = 0;
  }

  // Back-off sequence (reverse, then turn)
  if (mem.backPh > 0 && mem.mode !== 'drill') {
    mem.backT--;
    if (mem.backPh === 1) {
      out.left = -0.4; out.right = -0.4;
      if (mem.backT <= 0) { mem.backPh = 2; mem.backT = 12; }
    } else {
      const s = 0.4 * mem.backDir;
      out.left = -s; out.right = s;
      if (mem.backT <= 0) mem.backPh = 0;
    }
    return out;
  }
  if (obs.bumped && mem.mode !== 'drill') {
    mem.backPh = 1; mem.backT = 10; mem.backDir = freeDir(rays, mem);
    out.left = -0.4; out.right = -0.4;
    return out;
  }

  // Drilling
  if (mem.mode === 'drill') {
    mem.dT++;
    out.drill = true;
    const b = brakeOut(); out.left = b.left; out.right = b.right;
    if (carried > mem.dCarried) {
      if (mem.dPos) markHintDone(mem, mem.dPos, 20);
      mem.mode = 'pick'; mem.siteT = 0; out.drill = false;
    } else if (mem.dT >= 100 || (obs.drilling || 0) >= 8) {
      mem.ignore = mem.tick + 150; mem.mode = 'pick'; mem.siteT = 0; out.drill = false;
    }
    return out;
  }

  // Initial calibration drive (straight, to learn heading offset from GPS)
  if (!mem.calDone && mem.calT < 70 && mem.mode === 'pick' && !obs.site &&
      Math.min(rays[3], rays[4], rays[5]) > 2.5) {
    mem.calT++;
    out.left = 0.4; out.right = 0.4;
    return out;
  }

  // Charging at base with low battery and nothing carried
  if (dBase >= 2.3) mem.charging = false;
  if (carried === 0 && dBase < 2.3 && mem.mode !== 'deliver') {
    if (!mem.charging && obs.battery < 0.4 && obs.timeLeft > 250) mem.charging = true;
    if (mem.charging) {
      mem.chargeT++;
      if (obs.battery >= 0.9 || mem.chargeT > 200 || obs.timeLeft < 200) {
        mem.charging = false; mem.chargeT = 0;
      } else {
        return brakeOut();
      }
    }
  }

  // Visible site: approach and sample
  const site = obs.site;
  if (site && carried < mem.cap && mem.tick >= mem.ignore && mem.mode !== 'deliver') {
    mem.siteT++;
    if (mem.siteT > 400) {
      mem.ignore = mem.tick + 200; mem.siteT = 0;
    } else if (site.distance <= 1.4) {
      if (wmag < 0.15) {
        mem.mode = 'drill'; mem.dT = 0; mem.dCarried = carried;
        mem.dPos = { x: me.x, y: me.y };
        out.drill = true;
        return out;
      }
      return brakeOut();
    } else {
      return steer(site.bearing, clamp(site.distance * 0.3, 0.2, 0.4), rays, mem);
    }
  } else {
    mem.siteT = 0;
  }

  const urgentT = obs.timeLeft < dBase / 0.5 + 60;
  const urgentB = obs.battery < 0.15 + dBase * 0.002;
  const wantDeliver = carried > 0 && mem.tick >= mem.noDeliver &&
    (carried >= mem.cap || urgentT || urgentB || (carried >= 2 && dBase < 45) || mem.noTargets);

  for (let g = 0; g < 4; g++) {
    if (mem.mode !== 'deliver' && wantDeliver) { mem.mode = 'deliver'; mem.dockT = 0; }

    if (mem.mode === 'deliver') {
      if (carried === 0) { mem.mode = 'pick'; continue; }
      if (dBase < 2.3 || obs.docked) {
        mem.dockT++;
        if (mem.dockT > 100) {
          mem.mode = 'pick'; mem.noDeliver = mem.tick + 300; mem.dockT = 0;
          continue;
        }
        return brakeOut();
      }
      const e = obs.beacon ? obs.beacon.bearing : wrap(brg(me.x, me.y, mem.base.x, mem.base.y) - hd);
      return steer(e, dBase > 8 ? 0.5 : 0.3, rays, mem);
    }

    if (mem.mode === 'pick') {
      const hi = pickHint(mem, me, obs.timeLeft);
      if (hi >= 0) {
        const h = mem.hints[hi];
        mem.mode = 'go'; mem.hi = hi; mem.goT = 0;
        mem.goLimit = Math.max(400, dist(me.x, me.y, h.x, h.y) * 30);
        mem.noTargets = false;
        continue;
      }
      mem.noTargets = true;
      if (carried > 0) { mem.mode = 'deliver'; mem.dockT = 0; continue; }
      mem.mode = 'explore'; mem.exT = 0; mem.wander = null;
      continue;
    }

    if (mem.mode === 'go') {
      const h = mem.hints[mem.hi];
      if (!h || h.done) { mem.mode = 'pick'; continue; }
      const d = dist(me.x, me.y, h.x, h.y);
      mem.goT++;
      if (d < 6) {
        mem.mode = 'search';
        mem.wps = buildWps(h.x, h.y, me, mem);
        mem.wpI = 0; mem.srchT = 0;
        continue;
      }
      if (mem.goT > mem.goLimit) { h.done = true; mem.mode = 'pick'; continue; }
      return steer(wrap(brg(me.x, me.y, h.x, h.y) - hd), d > 10 ? 0.55 : 0.4, rays, mem);
    }

    if (mem.mode === 'search') {
      const h = mem.hints[mem.hi];
      mem.srchT++;
      while (mem.wpI < mem.wps.length &&
             dist(me.x, me.y, mem.wps[mem.wpI].x, mem.wps[mem.wpI].y) < 2.5) mem.wpI++;
      if (mem.wpI >= mem.wps.length || mem.srchT > 900) {
        if (h) h.done = true;
        mem.mode = 'pick';
        continue;
      }
      const w = mem.wps[mem.wpI];
      const d = dist(me.x, me.y, w.x, w.y);
      return steer(wrap(brg(me.x, me.y, w.x, w.y) - hd), d > 6 ? 0.45 : 0.35, rays, mem);
    }

    if (mem.mode === 'explore') {
      mem.exT++;
      if (mem.exT % 40 === 0) {
        const hi = pickHint(mem, me, obs.timeLeft);
        if (hi >= 0) { mem.mode = 'pick'; continue; }
      }
      if (!mem.wander || dist(me.x, me.y, mem.wander.x, mem.wander.y) < 6 || mem.exT % 600 === 0) {
        mem.wander = { x: 40 + rnd(mem) * 320, y: 40 + rnd(mem) * 320 };
      }
      return steer(wrap(brg(me.x, me.y, mem.wander.x, mem.wander.y) - hd), 0.4, rays, mem);
    }

    mem.mode = 'pick';
  }
  return out;
}

function act(obs, mem) {
  if (!mem.init) init(obs, mem);
  let out;
  try {
    out = core(obs, mem);
  } catch (e) {
    out = { left: 0, right: 0, drill: false };
  }
  const l = clamp(Number(out.left) || 0, -1, 1);
  const r = clamp(Number(out.right) || 0, -1, 1);
  mem.lastL = l; mem.lastR = r;
  return { left: l, right: r, drill: !!out.drill };
}

const R2D = 180 / Math.PI, D2R = Math.PI / 180;
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function sanitizeRays(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function medoid(arr) {
  let best = arr[arr.length - 1], bs = Infinity;
  for (const a of arr) {
    let s = 0;
    for (const b of arr) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

function init(obs, mem) {
  const m = obs.mission || {};
  const b = m.base || { x: num(obs.x), y: num(obs.y) };
  mem.base = { x: num(b.x), y: num(b.y) };
  mem.cap = num(m.capacity, 5) || 5;
  mem.hints = [];
  const hs = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hs) {
    if (!h || !isFinite(h.x) || !isFinite(h.y)) continue;
    mem.hints.push({
      x: h.x, y: h.y,
      est: (typeof h.estimate === 'number' && isFinite(h.estimate)) ? h.estimate : 1,
      done: false, fails: 0
    });
  }
  mem.seed = 98765;
  mem.tick = 0;
  mem.ch = [];
  mem.off = 0; mem.offInit = false; mem.seg = null;
  mem.mode = 'cal'; mem.calT = 0;
  mem.tgt = null; mem.hi = -1; mem.goT = 0; mem.goLim = 0;
  mem.wps = null; mem.wi = 0; mem.srT = 0;
  mem.dT = 0; mem.dC0 = 0; mem.dPos = null;
  mem.rec = 0; mem.recDir = 1; mem.stuckN = 0; mem.lastRec = null;
  mem.cmdAcc = 0; mem.cmdN = 0; mem.spos = null; mem.wd = 0; mem.swd = 0;
  mem.stale = 0; mem.pgx = null; mem.pgy = null; mem.dr = null;
  mem.lastL = 0; mem.lastR = 0;
  mem.wander = null; mem.wT = 0;
  mem.dockT = 0; mem.chargeT = 0;
  mem.ign = [];
  mem.siteT = 0;
  mem.hold = 0;
  mem.noTargets = false;
  mem.init = true;
}

function brakeCmd(mem, vAvg) {
  mem.hold = clamp(mem.hold - 0.3 * vAvg, -0.4, 0.4);
  return { left: mem.hold, right: mem.hold };
}

function ringPts(c, me) {
  const a0 = brg(c.x, c.y, me.x, me.y) * D2R;
  const pts = [];
  const rings = [[6, 6], [14, 10]];
  for (const rn of rings) {
    const r = rn[0], n = rn[1];
    for (let k = 0; k < n; k++) {
      const a = a0 + 2 * Math.PI * k / n;
      pts.push({
        x: clamp(c.x + r * Math.cos(a), 4, 396),
        y: clamp(c.y + r * Math.sin(a), 4, 396)
      });
    }
  }
  return pts;
}

function pickHint(mem, me, timeLeft) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.4 + 60 > timeLeft) continue;
    const sc = (Math.max(h.est, 0) + 0.1) / (d1 + 0.8 * d2 + 30);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function markNearHint(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function nearIgn(mem, p) {
  for (const q of mem.ign) if (dist(p.x, p.y, q.x, q.y) < 2.5) return true;
  return false;
}

function siteWorld(me, hd, site) {
  const a = (hd + num(site.bearing)) * D2R;
  return { x: me.x + num(site.distance) * Math.cos(a), y: me.y + num(site.distance) * Math.sin(a) };
}

// e: bearing error in degrees (positive = target to the left)
function steer(e, v, rays, mem, out) {
  let adj = 0;
  for (let i = 0; i < 9; i++) {
    const r = rays[i];
    if (r >= 2.5) continue;
    const ang = -80 + 20 * i;
    adj += -((2.5 - r) / 2.5) * ang * 0.5;
  }
  const front = rays[4];
  if (front < 2.5) {
    const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
    const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
    adj += (L >= R ? 1 : -1) * 30 * (2.5 - front) / 2.5;
  }
  const ee = clamp(e + adj, -180, 180);
  const fr = Math.min(rays[3], rays[4], rays[5]);
  const cap = fr < 1.2 ? 0.1 : (fr < 2.5 ? 0.15 : (fr < 4 ? 0.2 : 1));
  const vv = Math.min(v, cap);
  const a = Math.abs(ee);
  let fwd, turn;
  if (a > 70) {
    fwd = 0;
    turn = (ee >= 0 ? 1 : -1) * 0.25;
  } else {
    fwd = vv * clamp(1 - (a - 20) / 50, 0, 1);
    turn = clamp(ee / 60, -1, 1) * 0.25;
  }
  out.left = clamp(fwd - turn, -1, 1);
  out.right = clamp(fwd + turn, -1, 1);
  out.drill = false;
  return out;
}

function startRecovery(mem, me) {
  if (mem.lastRec && dist(me.x, me.y, mem.lastRec.x, mem.lastRec.y) > 8) mem.stuckN = 0;
  mem.lastRec = { x: me.x, y: me.y };
  mem.stuckN++;
  mem.rec = 14;
  mem.recDir = rnd(mem) < 0.5 ? -1 : 1;
  if (mem.stuckN >= 3 && (mem.mode === 'goto' || mem.mode === 'search' || mem.mode === 'wander')) {
    if (mem.mode !== 'wander' && mem.hi >= 0) mem.hints[mem.hi].done = true;
    mem.wander = null;
    mem.mode = 'pick';
    mem.stuckN = 0;
  }
}

function core(obs, mem) {
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  const gx = num(obs.x), gy = num(obs.y);
  const wl = num(obs.wheelLeft), wr = num(obs.wheelRight);
  const vAvg = (wl + wr) / 2;
  const carried = num(obs.carried);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const rays = sanitizeRays(obs.rays);
  const fr = Math.min(rays[3], rays[4], rays[5]);

  // GPS staleness and dead reckoning fallback
  if (mem.pgx === gx && mem.pgy === gy) mem.stale++;
  else { mem.stale = 0; mem.pgx = gx; mem.pgy = gy; }

  mem.ch.push(num(obs.heading));
  if (mem.ch.length > 5) mem.ch.shift();
  const hd = wrap(medoid(mem.ch) + mem.off);

  if (!mem.dr || mem.stale === 0) mem.dr = { x: gx, y: gy };
  else mem.dr = {
    x: mem.dr.x + vAvg * 0.1 * Math.cos(hd * D2R),
    y: mem.dr.y + vAvg * 0.1 * Math.sin(hd * D2R)
  };
  const useDR = mem.stale > 30;
  const me = useDR ? { x: mem.dr.x, y: mem.dr.y } : { x: gx, y: gy };
  const dBase = dist(me.x, me.y, mem.base.x, mem.base.y);

  // Heading offset calibration along straight GPS segments
  const straight = mem.lastL > 0.12 && Math.abs(mem.lastL - mem.lastR) < 0.05 && !obs.bumped && !useDR;
  if (straight) {
    if (!mem.seg) mem.seg = { x: me.x, y: me.y, s: 0, c: 0, n: 0 };
    const rr = num(obs.heading) * D2R;
    mem.seg.s += Math.sin(rr); mem.seg.c += Math.cos(rr); mem.seg.n++;
    const d = dist(me.x, me.y, mem.seg.x, mem.seg.y);
    if (d >= 4 && mem.seg.n >= 15) {
      const gh = brg(mem.seg.x, mem.seg.y, me.x, me.y);
      const cm = Math.atan2(mem.seg.s, mem.seg.c) * R2D;
      const sv = wrap(gh - cm);
      if (!mem.offInit) { mem.off = sv; mem.offInit = true; }
      else mem.off = wrap(mem.off + 0.2 * wrap(sv - mem.off));
      mem.seg = { x: me.x, y: me.y, s: 0, c: 0, n: 0 };
    }
  } else mem.seg = null;

  // Stuck monitor: commanded motion but no GPS or wheel progress
  mem.cmdAcc += (Math.abs(mem.lastL) + Math.abs(mem.lastR)) / 2;
  mem.cmdN++;
  mem.wd += Math.abs(vAvg) * 0.1;
  if (!mem.spos) { mem.spos = { x: me.x, y: me.y }; mem.swd = mem.wd; }
  if (mem.cmdN >= 30) {
    const avgC = mem.cmdAcc / mem.cmdN;
    const disp = dist(me.x, me.y, mem.spos.x, mem.spos.y);
    const dw = mem.wd - mem.swd;
    if (avgC > 0.15 && disp < 0.3 && dw < 0.3 && mem.mode !== 'drill' && mem.mode !== 'cal' &&
        dBase > 3.5 && mem.rec === 0) {
      startRecovery(mem, me);
    }
    mem.spos = { x: me.x, y: me.y }; mem.swd = mem.wd;
    mem.cmdAcc = 0; mem.cmdN = 0;
  }

  // Drilling: hold still with drill on until a sample arrives
  if (mem.mode === 'drill') {
    mem.dT++;
    const b = brakeCmd(mem, vAvg);
    out.left = b.left; out.right = b.right;
    if (carried > mem.dC0) {
      markNearHint(mem, mem.dPos, 25);
      mem.mode = 'pick';
      out.drill = false;
      mem.stuckN = 0;
      return out;
    }
    if (mem.dT >= 110) {
      mem.ign.push({ x: mem.dPos.x, y: mem.dPos.y });
      mem.mode = 'pick';
      out.drill = false;
      return out;
    }
    out.drill = true;
    return out;
  }

  // Bump and stuck recovery
  if (obs.bumped && mem.rec === 0) startRecovery(mem, me);
  if (mem.rec > 0) {
    mem.rec--;
    if (mem.rec >= 7) { out.left = -0.3; out.right = -0.3; }
    else { out.left = -0.25 * mem.recDir; out.right = 0.25 * mem.recDir; }
    if (mem.rec === 0) { mem.spos = null; mem.cmdAcc = 0; mem.cmdN = 0; }
    return out;
  }

  // Urgent delivery conditions
  if (mem.mode !== 'deliver' && mem.mode !== 'cal' && carried > 0) {
    if (carried >= mem.cap || timeLeft < dBase / 0.4 + 60 || battery < 0.1 + dBase * 0.001) {
      mem.mode = 'deliver'; mem.dockT = 0; mem.chargeT = 0;
    }
  }

  // Opportunistic sampling of visible sites
  const site = obs.site;
  if (site && carried < mem.cap && mem.mode !== 'deliver' && mem.mode !== 'cal') {
    const sw = siteWorld(me, hd, site);
    if (!nearIgn(mem, sw)) {
      mem.siteT++;
      if (mem.siteT > 300) {
        mem.ign.push(sw); mem.siteT = 0;
      } else if (num(site.distance, 99) <= 1.25) {
        if (Math.abs(vAvg) < 0.08 && Math.abs(wl) < 0.12 && Math.abs(wr) < 0.12) {
          mem.mode = 'drill';
          mem.dT = 0; mem.dC0 = carried; mem.dPos = { x: me.x, y: me.y }; mem.hold = 0;
          out.drill = true;
          return out;
        }
        const b = brakeCmd(mem, vAvg);
        out.left = b.left; out.right = b.right;
        return out;
      } else {
        return steer(num(site.bearing), clamp(num(site.distance) * 0.35, 0.2, 0.3), rays, mem, out);
      }
    }
  } else {
    mem.siteT = 0;
  }

  // Calibration drive at start
  if (mem.mode === 'cal') {
    mem.calT++;
    if (!mem.offInit && mem.calT <= 200 && fr > 2.5) {
      out.left = 0.25; out.right = 0.25;
      return out;
    }
    mem.mode = 'pick';
  }

  // Mission planner
  if (mem.mode === 'pick') {
    mem.stuckN = 0;
    if (carried > 0 && (dBase < 12 || mem.noTargets)) {
      mem.mode = 'deliver'; mem.dockT = 0; mem.chargeT = 0;
    } else if (battery < 0.2 && timeLeft > 150) {
      mem.mode = 'deliver'; mem.dockT = 0; mem.chargeT = 0;
    } else {
      const hi = pickHint(mem, me, timeLeft);
      if (hi >= 0) {
        const h = mem.hints[hi];
        mem.hi = hi;
        mem.tgt = { x: h.x, y: h.y };
        mem.mode = 'goto';
        mem.goT = 0;
        mem.goLim = dist(me.x, me.y, h.x, h.y) * 20 + 200;
        mem.noTargets = false;
      } else if (carried > 0) {
        mem.mode = 'deliver'; mem.dockT = 0; mem.chargeT = 0;
      } else {
        mem.noTargets = true;
        mem.mode = 'wander';
        mem.wander = null; mem.wT = 0;
      }
    }
  }

  if (mem.mode === 'goto') {
    const h = mem.tgt;
    const d = dist(me.x, me.y, h.x, h.y);
    mem.goT++;
    if (d < 4) {
      mem.mode = 'search';
      mem.wps = ringPts(h, me);
      mem.wi = 0; mem.srT = 0;
    } else if (mem.goT > mem.goLim) {
      if (mem.hi >= 0) mem.hints[mem.hi].done = true;
      mem.mode = 'pick';
      return out;
    } else {
      return steer(wrap(brg(me.x, me.y, h.x, h.y) - hd), d > 10 ? 0.25 : 0.2, rays, mem, out);
    }
  }

  if (mem.mode === 'search') {
    mem.srT++;
    while (mem.wi < mem.wps.length &&
           dist(me.x, me.y, mem.wps[mem.wi].x, mem.wps[mem.wi].y) < 2.2) mem.wi++;
    if (mem.wi >= mem.wps.length || mem.srT > 1500) {
      if (mem.hi >= 0) mem.hints[mem.hi].done = true;
      mem.mode = 'pick';
      return out;
    }
    const w = mem.wps[mem.wi];
    const d = dist(me.x, me.y, w.x, w.y);
    return steer(wrap(brg(me.x, me.y, w.x, w.y) - hd), clamp(d * 0.3, 0.15, 0.25), rays, mem, out);
  }

  if (mem.mode === 'deliver') {
    if (dBase <= 2.4 || (obs.docked && dBase <= 3.0)) {
      mem.dockT++;
      if (mem.dockT === 1) mem.hold = 0;
      const b = brakeCmd(mem, vAvg);
      out.left = b.left; out.right = b.right;
      if (carried === 0) {
        if (battery < 0.3 && timeLeft > 120 && mem.chargeT < 1500) {
          mem.chargeT++;
          if (battery < 0.75) return out;
        }
        mem.mode = 'pick'; mem.dockT = 0; mem.chargeT = 0;
        return out;
      }
      if (mem.dockT > 60) { mem.mode = 'pick'; mem.dockT = 0; }
      return out;
    }
    if (carried === 0 && battery >= 0.2) { mem.mode = 'pick'; return out; }
    mem.dockT = 0;
    const e = wrap(brg(me.x, me.y, mem.base.x, mem.base.y) - hd);
    return steer(e, dBase > 8 ? 0.25 : 0.2, rays, mem, out);
  }

  if (mem.mode === 'wander') {
    mem.wT++;
    if (!mem.wander || dist(me.x, me.y, mem.wander.x, mem.wander.y) < 5 || mem.wT > 400) {
      mem.wander = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
      mem.wT = 0;
    }
    if (mem.tick % 50 === 0) {
      const hi = pickHint(mem, me, timeLeft);
      if (hi >= 0) { mem.mode = 'pick'; return out; }
    }
    return steer(wrap(brg(me.x, me.y, mem.wander.x, mem.wander.y) - hd), 0.25, rays, mem, out);
  }

  mem.mode = 'pick';
  return out;
}

function act(obs, mem) {
  if (!mem.init) init(obs, mem);
  let out;
  try {
    out = core(obs, mem);
  } catch (e) {
    out = { left: 0, right: 0, drill: false };
  }
  const l = clamp(num(out.left), -1, 1);
  const r = clamp(num(out.right), -1, 1);
  mem.lastL = l; mem.lastR = r;
  return { left: l, right: r, drill: !!out.drill };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function medoid(arr) {
  let best = arr[arr.length - 1], bs = Infinity;
  for (const a of arr) {
    let s = 0;
    for (const b of arr) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

function sanitizeRays(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function init(obs, mem) {
  const m = obs.mission || {};
  const x0 = num(obs.x), y0 = num(obs.y);
  const b = m.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(m.capacity, 5) || 5;
  mem.hints = [];
  const hs = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hs) {
    if (h && isFinite(h.x) && isFinite(h.y)) {
      mem.hints.push({ x: h.x, y: h.y, est: num(h.estimate, 1), done: false, fails: 0 });
    }
  }
  mem.seed = 98765; mem.tick = 0;
  mem.hbuf = []; mem.H = null; mem.off = 0; mem.offInit = false; mem.seg = null;
  mem.dr = null; mem.lgx = null; mem.lgy = null; mem.gStale = 0;
  mem.hist = [];
  mem.piv = false;
  mem.recPh = 0; mem.recT = 0; mem.recDir = 1;
  mem.mode = 'cal'; mem.calT = 0;
  mem.hi = -1; mem.goT = 0;
  mem.sp = null; mem.ign = [];
  mem.dT = 0; mem.dC0 = 0; mem.dPos = null; mem.dSite = null;
  mem.siteT = 0;
  mem.dockT = 0; mem.noDeliver = 0;
  mem.wander = null; mem.wT = 0;
  mem.sciCool = 0;
  mem.lastL = 0; mem.lastR = 0;
  mem.init = true;
}

function markNearHint(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function pickHint(mem, me, timeLeft) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.35 + 60 > timeLeft) continue;
    const sc = Math.max(h.est, 0.1) / (d1 + 0.7 * d2 + 25);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function siteWorld(me, H, site) {
  const a = (H + num(site.bearing, 0)) * D2R, d = num(site.distance, 0);
  return { x: me.x + d * Math.cos(a), y: me.y + d * Math.sin(a) };
}

function isIgn(mem, p) {
  for (const q of mem.ign) if (dist(p.x, p.y, q.x, q.y) < 3) return true;
  return false;
}

function holdCmd(wl, wr) {
  return { left: clamp(-0.6 * wl, -0.2, 0.2), right: clamp(-0.6 * wr, -0.2, 0.2), drill: false };
}

// Steering toward a bearing error e (deg, positive = target to the left), with ray avoidance.
function steerOut(e, v, rays, mem) {
  let adj = 0;
  for (let i = 0; i < 9; i++) {
    const r = rays[i];
    if (r < 3) adj -= ((3 - r) / 3) * (-80 + 20 * i) * 0.5;
  }
  const front = Math.min(rays[3], rays[4], rays[5]);
  const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
  const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
  const side = L >= R ? 1 : -1;
  if (front < 3) adj += side * 70 * (3 - front) / 3;
  const ee = clamp(e + adj, -180, 180);
  let vv = v;
  if (front < 4) vv = Math.min(vv, 0.25);
  if (front < 2.2) vv = Math.min(vv, 0.15);
  if (Math.abs(ee) > 55) mem.piv = true; else if (Math.abs(ee) < 25) mem.piv = false;
  if (mem.piv) {
    const s = ee >= 0 ? 1 : -1;
    return { left: -0.3 * s, right: 0.3 * s, drill: false };
  }
  const fwd = vv * clamp(1 - Math.abs(ee) / 70, 0.3, 1);
  const turn = clamp(ee / 50, -1, 1) * 0.35;
  return { left: clamp(fwd - turn, -1, 1), right: clamp(fwd + turn, -1, 1), drill: false };
}

function startRec(mem, rays) {
  mem.recPh = 1; mem.recT = 12;
  const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
  const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
  if (Math.abs(L - R) < 0.3) mem.recDir = rnd(mem) < 0.5 ? -1 : 1;
  else mem.recDir = L > R ? 1 : -1;
  if (mem.mode === 'go' || mem.mode === 'search') {
    if (mem.hi >= 0 && mem.hints[mem.hi]) mem.hints[mem.hi].fails += 0.5;
  }
}

function recStep(mem) {
  mem.recT--;
  if (mem.recPh === 1) {
    if (mem.recT <= 0) { mem.recPh = 2; mem.recT = 10; }
    return { left: -0.35, right: -0.35, drill: false };
  }
  if (mem.recT <= 0) mem.recPh = 0;
  const s = 0.35 * mem.recDir;
  return { left: -s, right: s, drill: false };
}

function siteStep(mem, me, H, site, rays, wl, wr, carried, wMag) {
  mem.siteT++;
  const d = num(site.distance, 99), e = num(site.bearing, 0);
  if (mem.siteT > 600) {
    mem.ign.push(siteWorld(me, H, site));
    mem.mode = 'pick'; mem.siteT = 0;
    return holdCmd(wl, wr);
  }
  if (d <= 1.2) {
    const h = holdCmd(wl, wr);
    if (wMag < 0.12) {
      mem.mode = 'drill'; mem.dT = 0; mem.dC0 = carried;
      mem.dPos = { x: me.x, y: me.y };
      mem.dSite = siteWorld(me, H, site);
      return { left: h.left, right: h.right, drill: true };
    }
    return h;
  }
  const v = clamp(0.12 + 0.12 * d, 0.15, 0.3);
  return steerOut(e, v, rays, mem);
}

function pickStep(mem, me, carried, timeLeft, battery, dBase, urgentT, urgentB) {
  const hi = pickHint(mem, me, timeLeft);
  const wantD = carried > 0 && mem.tick >= mem.noDeliver &&
    (carried >= mem.cap || urgentT || urgentB || hi < 0 || carried >= 3);
  const needCharge = carried === 0 && battery < 0.25 && timeLeft > 200 && dBase > 3 && mem.tick >= mem.noDeliver;
  if (wantD || needCharge) { mem.mode = 'deliver'; mem.dockT = 0; return; }
  if (hi >= 0) { mem.mode = 'go'; mem.hi = hi; mem.goT = 0; return; }
  mem.mode = 'explore'; mem.wander = null; mem.wT = 0;
}

function core(obs, mem) {
  mem.tick++;
  const dt = 0.1;
  const wl = num(obs.wheelLeft), wr = num(obs.wheelRight);
  const gx = num(obs.x), gy = num(obs.y);
  const carried = num(obs.carried);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const rays = sanitizeRays(obs.rays);
  const site = (obs.site && typeof obs.site === 'object') ? obs.site : null;
  const wMag = (Math.abs(wl) + Math.abs(wr)) / 2;
  const base = mem.base;

  // Heading: median compass + offset, propagated by wheel differential
  mem.hbuf.push(num(obs.heading));
  if (mem.hbuf.length > 5) mem.hbuf.shift();
  const cm = medoid(mem.hbuf);
  if (mem.H === null) mem.H = wrap(cm + mem.off);
  else {
    mem.H = wrap(mem.H + (wr - wl) / 0.6 * R2D * dt);
    mem.H = wrap(mem.H + 0.05 * wrap(cm + mem.off - mem.H));
  }
  const H = mem.H;

  // Position: GPS, dead reckoning if GPS frozen
  const changed = mem.lgx === null || gx !== mem.lgx || gy !== mem.lgy;
  if (changed) { mem.gStale = 0; mem.lgx = gx; mem.lgy = gy; } else mem.gStale++;
  const vAvg = (wl + wr) / 2;
  if (!mem.dr || mem.gStale === 0) mem.dr = { x: gx, y: gy };
  else mem.dr = { x: mem.dr.x + vAvg * dt * Math.cos(H * D2R), y: mem.dr.y + vAvg * dt * Math.sin(H * D2R) };
  const useDR = mem.gStale > 30;
  const me = useDR ? { x: mem.dr.x, y: mem.dr.y } : { x: gx, y: gy };
  const dBase = dist(me.x, me.y, base.x, base.y);

  // Compass offset calibration along straight GPS tracks
  const straight = Math.abs(wl - wr) < 0.12 && vAvg > 0.2 && !obs.bumped && mem.gStale < 3 && !useDR;
  if (straight) {
    if (!mem.seg) mem.seg = { x: me.x, y: me.y, s: 0, c: 0, n: 0 };
    const rr = cm * D2R;
    mem.seg.s += Math.sin(rr); mem.seg.c += Math.cos(rr); mem.seg.n++;
    if (dist(me.x, me.y, mem.seg.x, mem.seg.y) >= 8 && mem.seg.n >= 10) {
      const gh = brg(mem.seg.x, mem.seg.y, me.x, me.y);
      const cmean = Math.atan2(mem.seg.s, mem.seg.c) * R2D;
      const err = wrap(gh - cmean);
      if (!mem.offInit) { mem.off = err; mem.offInit = true; }
      else mem.off = wrap(mem.off + 0.3 * wrap(err - mem.off));
      mem.seg = { x: me.x, y: me.y, s: 0, c: 0, n: 0 };
    }
  } else mem.seg = null;

  // Stuck detection: commanded motion but wheels not turning
  const cmdMag = (Math.abs(mem.lastL) + Math.abs(mem.lastR)) / 2;
  mem.hist.push([cmdMag, wMag]);
  if (mem.hist.length > 30) mem.hist.shift();
  if (mem.recPh === 0 && mem.mode !== 'drill' && mem.mode !== 'cal' && mem.hist.length >= 30) {
    let sc = 0, sw = 0;
    for (const p of mem.hist) { sc += p[0]; sw += p[1]; }
    if (sc / 30 > 0.2 && sw / 30 < 0.08) { startRec(mem, rays); mem.hist = []; }
  }
  if (obs.bumped && mem.recPh === 0 && mem.mode !== 'drill') { startRec(mem, rays); mem.hist = []; }
  if (mem.recPh > 0 && mem.mode !== 'drill') return recStep(mem);

  // Drilling: hold still, drill on, until a sample arrives
  if (mem.mode === 'drill') {
    mem.dT++;
    const h = holdCmd(wl, wr);
    if (carried > mem.dC0) {
      if (mem.dPos) markNearHint(mem, mem.dPos, 30);
      if (mem.dSite) mem.ign.push(mem.dSite);
      mem.mode = 'pick';
      return { left: h.left, right: h.right, drill: false };
    }
    if (num(obs.drilling) > 12 || mem.dT > 150) {
      if (mem.dSite) mem.ign.push(mem.dSite);
      mem.mode = 'pick';
      return { left: h.left, right: h.right, drill: false };
    }
    return { left: h.left, right: h.right, drill: true };
  }

  const urgentT = timeLeft < dBase / 0.4 + 60;
  const urgentB = battery < 0.12 + dBase * 0.003;

  // Opportunistic sampling of any visible site
  if (site && carried < mem.cap && !urgentT && !urgentB && mem.mode !== 'cal') {
    const sw = siteWorld(me, H, site);
    if (!isIgn(mem, sw)) {
      if (mem.mode !== 'site') { mem.mode = 'site'; mem.siteT = 0; }
      return siteStep(mem, me, H, site, rays, wl, wr, carried, wMag);
    }
  }
  if (mem.mode === 'site') mem.mode = 'pick';

  // Initial calibration drive
  if (mem.mode === 'cal') {
    mem.calT++;
    const fr = Math.min(rays[3], rays[4], rays[5]);
    if (mem.offInit || mem.calT > 150 || fr < 2.5) mem.mode = 'pick';
    else return { left: 0.35, right: 0.35, drill: false };
  }

  if (mem.mode === 'pick') pickStep(mem, me, carried, timeLeft, battery, dBase, urgentT, urgentB);

  if (mem.mode === 'go') {
    const h = mem.hints[mem.hi];
    if (!h || h.done) { mem.mode = 'pick'; return holdCmd(wl, wr); }
    const d = dist(me.x, me.y, h.x, h.y);
    mem.goT++;
    if (d < 3) {
      mem.mode = 'search';
      mem.sp = { cx: h.x, cy: h.y, t: 0 };
      return holdCmd(wl, wr);
    }
    if (mem.goT > Math.max(400, d * 15)) {
      h.fails += 1; mem.mode = 'pick'; return holdCmd(wl, wr);
    }
    return steerOut(wrap(brg(me.x, me.y, h.x, h.y) - H), d > 8 ? 0.45 : 0.3, rays, mem);
  }

  if (mem.mode === 'search') {
    const sp = mem.sp;
    const h = mem.hi >= 0 ? mem.hints[mem.hi] : null;
    sp.t++;
    const rx = me.x - sp.cx, ry = me.y - sp.cy;
    const r = Math.hypot(rx, ry), ang = Math.atan2(ry, rx);
    if (r >= 16 || sp.t > 2500) {
      if (h) h.done = true;
      mem.mode = 'pick';
      return holdCmd(wl, wr);
    }
    const rt = Math.max(r, 2) + 1.5, A = ang + 0.8;
    const tx = sp.cx + rt * Math.cos(A), ty = sp.cy + rt * Math.sin(A);
    return steerOut(wrap(brg(me.x, me.y, tx, ty) - H), 0.4, rays, mem);
  }

  if (mem.mode === 'deliver') {
    const bd = (obs.beacon && typeof obs.beacon.distance === 'number') ? Math.min(dBase, obs.beacon.distance) : dBase;
    if (bd <= 2.6 || obs.docked) {
      mem.dockT++;
      const out = holdCmd(wl, wr);
      if (carried === 0) {
        if (battery < 0.5 && timeLeft > 150 && mem.dockT < 300) return out;
        mem.mode = 'pick'; mem.dockT = 0; return out;
      }
      if (mem.dockT > 120) { mem.mode = 'pick'; mem.dockT = 0; mem.noDeliver = mem.tick + 300; }
      return out;
    }
    mem.dockT = 0;
    let e;
    if (obs.beacon && typeof obs.beacon.bearing === 'number') e = obs.beacon.bearing;
    else e = wrap(brg(me.x, me.y, base.x, base.y) - H);
    return steerOut(e, dBase > 8 ? 0.45 : 0.3, rays, mem);
  }

  if (mem.mode === 'explore') {
    mem.wT++;
    if (num(obs.science) > 1.5 && mem.tick > mem.sciCool) {
      mem.mode = 'search'; mem.hi = -1; mem.sp = { cx: me.x, cy: me.y, t: 0 };
      mem.sciCool = mem.tick + 400;
      return holdCmd(wl, wr);
    }
    if (!mem.wander || mem.wT > 500 || dist(me.x, me.y, mem.wander.x, mem.wander.y) < 6) {
      mem.wander = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
      mem.wT = 0;
    }
    if (mem.tick % 20 === 0 && pickHint(mem, me, timeLeft) >= 0) { mem.mode = 'pick'; return holdCmd(wl, wr); }
    return steerOut(wrap(brg(me.x, me.y, mem.wander.x, mem.wander.y) - H), 0.4, rays, mem);
  }

  mem.mode = 'pick';
  return holdCmd(wl, wr);
}

function act(obs, mem) {
  if (!mem.init) init(obs, mem);
  let out;
  try {
    out = core(obs, mem);
  } catch (e) {
    out = { left: 0, right: 0, drill: false };
  }
  const l = clamp(num(out.left), -1, 1);
  const r = clamp(num(out.right), -1, 1);
  mem.lastL = l; mem.lastR = r;
  return { left: l, right: r, drill: !!out.drill };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function medoid(arr) {
  let best = arr[arr.length - 1], bs = Infinity;
  for (const a of arr) {
    let s = 0;
    for (const b of arr) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

function sanitizeRays(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function init(obs, mem) {
  const m = obs.mission || {};
  const x0 = num(obs.x), y0 = num(obs.y);
  const b = m.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(m.capacity, 5) || 5;
  mem.hints = [];
  const hs = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hs) {
    if (h && isFinite(h.x) && isFinite(h.y)) {
      mem.hints.push({ x: h.x, y: h.y, est: num(h.estimate, 1), done: false, fails: 0 });
    }
  }
  mem.seed = 4242; mem.tick = 0;
  mem.cb = []; mem.off = 0; mem.offInit = false; mem.H = null;
  mem.dr = null; mem.lgx = null; mem.lgy = null; mem.stale = 0;
  mem.fx = []; mem.hp = [];
  mem.lastL = 0; mem.lastR = 0;
  mem.mode = 'pick'; mem.hi = -1; mem.tgt = null; mem.navT = 0; mem.navLim = 1000;
  mem.sp = null; mem.wd = null; mem.wT = 0;
  mem.rec = 0; mem.recDir = 1; mem.recN = 0;
  mem.ign = []; mem.siteT = 0;
  mem.dT = 0; mem.dC0 = 0; mem.dPos = null; mem.dSite = null;
  mem.dockT = 0; mem.noDel = 0; mem.sciCool = 0;
  mem.init = true;
}

function isIgn(mem, p) {
  for (const q of mem.ign) if (dist(p.x, p.y, q.x, q.y) < 3) return true;
  return false;
}

function siteWorld(me, H, site) {
  const a = (H + num(site.bearing, 0)) * D2R, d = num(site.distance, 0);
  return { x: me.x + d * Math.cos(a), y: me.y + d * Math.sin(a) };
}

function markNearHint(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function pickHint(mem, me, timeLeft) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.5 + 60 > timeLeft) continue;
    const sc = (Math.max(h.est, 0) + 0.1) / (d1 + 0.6 * d2 + 40);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

// Heading of motion from GPS fixes (chord of at least 4 m back)
function motionHeading(mem) {
  const fx = mem.fx, n = fx.length;
  if (n < 2) return null;
  const c = fx[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    if (dist(c.x, c.y, fx[i].x, fx[i].y) >= 4) return brg(fx[i].x, fx[i].y, c.x, c.y);
  }
  return null;
}

// e: bearing error in degrees (positive = target to the left)
function steerTo(e, v, rays, mem, out) {
  let adj = 0;
  for (let i = 0; i < 9; i++) {
    const r = rays[i];
    if (r < 3) adj -= ((3 - r) / 3) * (-80 + 20 * i) * 0.6;
  }
  const front = Math.min(rays[3], rays[4], rays[5]);
  if (rays[4] < 3) {
    const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
    const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
    adj += (L >= R ? 1 : -1) * 60 * (3 - rays[4]) / 3;
  }
  const ee = clamp(e + adj, -180, 180);
  let vv = v;
  if (front < 2.5) vv = Math.min(vv, 0.2);
  if (front < 1.2) vv = Math.min(vv, 0.12);
  const a = Math.abs(ee);
  const fwd = vv * clamp(1 - a / 110, 0.15, 1);
  const turn = clamp(ee / 40, -1, 1) * 0.35;
  out.left = clamp(fwd - turn, -1, 1);
  out.right = clamp(fwd + turn, -1, 1);
  out.drill = false;
  return out;
}

function spiralPt(sp, k) {
  const th = 0.3 * k, r = 0.66 * k;
  return { x: clamp(sp.cx + r * Math.cos(th), 3, 397), y: clamp(sp.cy + r * Math.sin(th), 3, 397) };
}

function startRec(mem) {
  mem.rec = 14;
  mem.recDir = rnd(mem) < 0.5 ? -1 : 1;
  mem.hp = [];
}

function recStep(mem, out) {
  mem.rec--;
  if (mem.rec >= 6) { out.left = -0.3; out.right = -0.3; }
  else { out.left = -0.35 * mem.recDir; out.right = 0.35 * mem.recDir; }
  out.drill = false;
  return out;
}

function giveUp(mem) {
  if ((mem.mode === 'nav' || mem.mode === 'search') && mem.hi >= 0 && mem.hints[mem.hi]) {
    mem.hints[mem.hi].done = true;
  }
  mem.hi = -1;
  mem.wd = null;
  mem.mode = 'pick';
}

function drillStep(mem, carried, vAvg, out) {
  mem.dT++;
  const h = clamp(-vAvg, -0.15, 0.15);
  out.left = h; out.right = h;
  out.drill = true;
  if (carried > mem.dC0) {
    if (mem.dPos) markNearHint(mem, mem.dPos, 25);
    if (mem.dSite) mem.ign.push(mem.dSite);
    mem.mode = 'pick';
    out.drill = false;
    mem.siteT = 0;
    return out;
  }
  if (mem.dT > 150) {
    if (mem.dSite) mem.ign.push(mem.dSite);
    mem.mode = 'pick';
    out.drill = false;
  }
  return out;
}

function pickStep(mem, me, carried, timeLeft, battery, dBase, sci) {
  const hi = pickHint(mem, me, timeLeft);
  const urgent = timeLeft < dBase / 0.5 + 60;
  if (carried > 0 && mem.tick >= mem.noDel &&
      (carried >= mem.cap || urgent || battery < 0.12 || hi < 0 || (carried >= 2 && dBase < 40))) {
    mem.mode = 'deliver'; mem.dockT = 0; return;
  }
  if (hi >= 0) {
    const h = mem.hints[hi];
    mem.hi = hi;
    mem.tgt = { x: h.x, y: h.y };
    mem.mode = 'nav';
    mem.navT = 0;
    mem.navLim = dist(me.x, me.y, h.x, h.y) * 30 + 300;
    mem.recN = 0;
    return;
  }
  if (carried > 0 && mem.tick >= mem.noDel) { mem.mode = 'deliver'; mem.dockT = 0; return; }
  mem.hi = -1;
  mem.recN = 0;
  if (sci > 2.0 && mem.tick > mem.sciCool) {
    mem.mode = 'search'; mem.sp = { cx: me.x, cy: me.y, k: 0, t: 0 }; return;
  }
  mem.mode = 'wander'; mem.wd = null; mem.wT = 0;
}

function navStep(mem, me, H, rays, out) {
  const h = mem.tgt;
  const d = dist(me.x, me.y, h.x, h.y);
  mem.navT++;
  if (d < 4) {
    mem.mode = 'search';
    mem.sp = { cx: h.x, cy: h.y, k: 0, t: 0 };
    return out;
  }
  if (mem.navT > mem.navLim) {
    if (mem.hi >= 0 && mem.hints[mem.hi]) mem.hints[mem.hi].done = true;
    mem.mode = 'pick';
    return out;
  }
  return steerTo(wrap(brg(me.x, me.y, h.x, h.y) - H), d > 10 ? 0.4 : 0.3, rays, mem, out);
}

function searchStep(mem, me, H, rays, out) {
  const sp = mem.sp;
  sp.t++;
  while (sp.k < 34) {
    const w = spiralPt(sp, sp.k);
    if (dist(me.x, me.y, w.x, w.y) < 2.5) sp.k++; else break;
  }
  if (sp.k >= 34 || sp.t > 2000) {
    if (mem.hi >= 0 && mem.hints[mem.hi]) mem.hints[mem.hi].done = true;
    mem.hi = -1;
    mem.sciCool = mem.tick + 600;
    mem.mode = 'pick';
    return out;
  }
  const w = spiralPt(sp, sp.k);
  return steerTo(wrap(brg(me.x, me.y, w.x, w.y) - H), 0.3, rays, mem, out);
}

function wanderStep(mem, me, H, rays, out, timeLeft, sci) {
  mem.wT++;
  if (sci > 2.0 && mem.tick > mem.sciCool) {
    mem.mode = 'search'; mem.hi = -1;
    mem.sp = { cx: me.x, cy: me.y, k: 0, t: 0 };
    return out;
  }
  if (!mem.wd || mem.wT > 1500 || dist(me.x, me.y, mem.wd.x, mem.wd.y) < 6) {
    mem.wd = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
    mem.wT = 0;
  }
  if (mem.tick % 20 === 0 && pickHint(mem, me, timeLeft) >= 0) {
    mem.mode = 'pick';
    return out;
  }
  return steerTo(wrap(brg(me.x, me.y, mem.wd.x, mem.wd.y) - H), 0.35, rays, mem, out);
}

function deliverStep(mem, me, dBase, H, vAvg, carried, obs, rays, out) {
  if (carried <= 0) { mem.mode = 'pick'; return out; }
  let bd = dBase;
  const bc = obs.beacon;
  if (bc && typeof bc.distance === 'number' && isFinite(bc.distance)) bd = Math.min(bd, bc.distance);
  if (obs.docked) bd = 0;
  if (bd <= 2.4) {
    mem.dockT++;
    const h = clamp(-vAvg, -0.15, 0.15);
    out.left = h; out.right = h;
    if (mem.dockT > 60) {
      mem.noDel = mem.tick + 400;
      mem.mode = 'pick';
      mem.dockT = 0;
    }
    return out;
  }
  mem.dockT = 0;
  let e;
  if (bc && typeof bc.bearing === 'number' && isFinite(bc.bearing) && num(bc.distance, 99) < 20) {
    e = bc.bearing;
  } else {
    e = wrap(brg(me.x, me.y, mem.base.x, mem.base.y) - H);
  }
  return steerTo(e, bd > 8 ? 0.4 : 0.28, rays, mem, out);
}

function core(obs, mem) {
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  const gx = num(obs.x), gy = num(obs.y);
  const wl = num(obs.wheelLeft), wr = num(obs.wheelRight);
  const vAvg = (wl + wr) / 2;
  const carried = num(obs.carried);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const rays = sanitizeRays(obs.rays);
  const site = (obs.site && typeof obs.site === 'object') ? obs.site : null;
  const sci = num(obs.science);
  const base = mem.base;

  mem.cb.push(num(obs.heading));
  if (mem.cb.length > 7) mem.cb.shift();
  const cm = medoid(mem.cb);

  // GPS freshness and fix history
  const changed = mem.lgx === null || gx !== mem.lgx || gy !== mem.lgy;
  if (changed) {
    mem.stale = 0; mem.lgx = gx; mem.lgy = gy;
    mem.fx.push({ x: gx, y: gy });
    if (mem.fx.length > 80) mem.fx.shift();
  } else mem.stale++;

  const Hprev = mem.H === null ? wrap(cm + mem.off) : mem.H;
  if (!mem.dr || mem.stale === 0) mem.dr = { x: gx, y: gy };
  else mem.dr = {
    x: mem.dr.x + vAvg * 0.1 * Math.cos(Hprev * D2R),
    y: mem.dr.y + vAvg * 0.1 * Math.sin(Hprev * D2R)
  };
  const useDR = mem.stale > 30;
  const me = useDR ? { x: mem.dr.x, y: mem.dr.y } : { x: gx, y: gy };
  const dBase = dist(me.x, me.y, base.x, base.y);

  // Heading: GPS motion direction when moving forward, otherwise compass plus learned offset
  let mh = null;
  if (mem.stale === 0 && vAvg > 0.12) mh = motionHeading(mem);
  if (mh !== null) {
    const err = wrap(mh - cm);
    if (!mem.offInit) { mem.off = err; mem.offInit = true; }
    else if (Math.abs(mem.lastL - mem.lastR) < 0.1) mem.off = wrap(mem.off + 0.05 * wrap(err - mem.off));
    mem.H = mh;
  } else {
    mem.H = wrap(cm + mem.off);
  }
  const H = mem.H;

  // Stuck and bump detection
  mem.hp.push({ x: me.x, y: me.y, c: Math.abs(mem.lastL + mem.lastR) / 2 });
  if (mem.hp.length > 30) mem.hp.shift();
  let stuck = false;
  if (obs.bumped && mem.rec === 0 && mem.mode !== 'drill') stuck = true;
  if (mem.hp.length >= 30 && mem.rec === 0 && mem.mode !== 'drill') {
    let cs = 0;
    for (const p of mem.hp) cs += p.c;
    cs /= mem.hp.length;
    const f = mem.hp[0];
    if (cs > 0.15 && dist(me.x, me.y, f.x, f.y) < 0.6) stuck = true;
  }
  if (stuck && mem.mode !== 'drill') {
    startRec(mem);
    mem.recN++;
    if (mem.recN >= 4 && mem.mode !== 'deliver') { giveUp(mem); mem.recN = 0; }
  }
  if (mem.rec > 0) return recStep(mem, out);

  if (mem.mode === 'drill') return drillStep(mem, carried, vAvg, out);

  // Opportunistic sampling of visible sites
  if (site && mem.mode !== 'deliver' && carried < mem.cap) {
    const d = num(site.distance, 99);
    const sw = siteWorld(me, H, site);
    if (d <= 8.5 && !isIgn(mem, sw)) {
      mem.siteT++;
      if (mem.siteT > 400) {
        mem.ign.push(sw); mem.siteT = 0;
      } else if (d <= 1.3) {
        const still = Math.abs(vAvg) < 0.1 && Math.abs(wl) < 0.15 && Math.abs(wr) < 0.15;
        if (still) {
          mem.mode = 'drill';
          mem.dT = 0; mem.dC0 = carried;
          mem.dPos = { x: me.x, y: me.y };
          mem.dSite = sw;
          out.drill = true;
          return out;
        }
        const h = clamp(-vAvg, -0.15, 0.15);
        out.left = h; out.right = h;
        return out;
      } else {
        return steerTo(num(site.bearing), clamp(0.1 + 0.12 * d, 0.15, 0.3), rays, mem, out);
      }
    }
  } else {
    mem.siteT = 0;
  }

  if (mem.mode === 'pick') pickStep(mem, me, carried, timeLeft, battery, dBase, sci);
  if (mem.mode === 'deliver') return deliverStep(mem, me, dBase, H, vAvg, carried, obs, rays, out);
  if (mem.mode === 'nav') return navStep(mem, me, H, rays, out);
  if (mem.mode === 'search') return searchStep(mem, me, H, rays, out);
  if (mem.mode === 'wander') return wanderStep(mem, me, H, rays, out, timeLeft, sci);

  mem.mode = 'pick';
  return out;
}

function act(obs, mem) {
  let out;
  try {
    if (!mem.init) init(obs, mem);
    out = core(obs, mem);
  } catch (e) {
    out = { left: 0, right: 0, drill: false };
  }
  const l = clamp(num(out.left), -1, 1);
  const r = clamp(num(out.right), -1, 1);
  mem.lastL = l; mem.lastR = r;
  return { left: l, right: r, drill: !!out.drill };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function medoid(arr) {
  let best = arr[arr.length - 1], bs = Infinity;
  for (const a of arr) {
    let s = 0;
    for (const b of arr) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

function sanitizeRays(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function init(obs, mem) {
  const m = obs.mission || {};
  const x0 = num(obs.x), y0 = num(obs.y);
  const b = m.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(m.capacity, 5) || 5;
  mem.hints = [];
  const hs = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hs) {
    if (h && isFinite(h.x) && isFinite(h.y)) {
      mem.hints.push({ x: h.x, y: h.y, est: num(h.estimate, 1), done: false, fails: 0 });
    }
  }
  mem.seed = 4242; mem.tick = 0;
  mem.cb = []; mem.off = 0; mem.offInit = false; mem.hd = null; mem.fa = 0;
  mem.dr = null; mem.lgx = null; mem.lgy = null; mem.stale = 0;
  mem.fx = []; mem.ph = [];
  mem.lastL = 0; mem.lastR = 0;
  mem.mode = 'cal'; mem.calT = 0;
  mem.hi = -1; mem.tgt = null; mem.navT = 0; mem.navLim = 1000;
  mem.sp = null; mem.wd = null; mem.wT = 0;
  mem.rec = 0; mem.recDir = 1; mem.recN = 0; mem.piv = false;
  mem.ign = []; mem.siteT = 0;
  mem.dT = 0; mem.dC0 = 0; mem.dPos = null; mem.dSite = null;
  mem.dockT = 0; mem.noDel = 0; mem.sciCool = 0;
  mem.init = true;
}

function isIgn(mem, p) {
  for (const q of mem.ign) if (dist(p.x, p.y, q.x, q.y) < 3) return true;
  return false;
}

function siteWorld(me, H, site) {
  const a = (H + num(site.bearing, 0)) * D2R, d = num(site.distance, 0);
  return { x: me.x + d * Math.cos(a), y: me.y + d * Math.sin(a) };
}

function markNear(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function pickHint(mem, me, timeLeft) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.4 + 60 > timeLeft) continue;
    const sc = (Math.max(h.est, 0) + 0.2) / (d1 + 0.6 * d2 + 40);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

// e: bearing error (deg, positive = target to the left). Writes out.
function steer(mem, e, v, rays, out) {
  let adj = 0;
  for (let i = 0; i < 9; i++) {
    const r = rays[i];
    if (r < 2.5) adj -= ((2.5 - r) / 2.5) * (-80 + 20 * i) * 0.6;
  }
  const front = Math.min(rays[3], rays[4], rays[5]);
  if (front < 3) {
    const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
    const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
    adj += (L >= R ? 1 : -1) * 60 * (3 - front) / 3;
  }
  const ee = clamp(e + adj, -180, 180);
  let vv = v;
  if (front < 3) vv = Math.min(vv, 0.22);
  if (front < 1.5) vv = Math.min(vv, 0.1);
  if (Math.abs(ee) > 75) mem.piv = true; else if (Math.abs(ee) < 30) mem.piv = false;
  if (mem.piv) {
    const s = ee >= 0 ? 1 : -1;
    out.left = -0.32 * s; out.right = 0.32 * s; out.drill = false;
    return out;
  }
  const fwd = vv * clamp(1 - Math.abs(ee) / 90, 0.25, 1);
  const turn = clamp(ee / 35, -1, 1) * 0.3;
  out.left = clamp(fwd - turn, -1, 1);
  out.right = clamp(fwd + turn, -1, 1);
  out.drill = false;
  return out;
}

function spiralPt(sp, k) {
  const th = 0.3 * k, r = 0.66 * k;
  return { x: clamp(sp.cx + r * Math.cos(th), 3, 397), y: clamp(sp.cy + r * Math.sin(th), 3, 397) };
}

function startRec(mem, rays) {
  mem.rec = 25;
