  else { const s = 0.35 * mem.recDir; out.left = -s; out.right = s; }
  out.drill = false;
  return out;
}

function pickStep(mem, me, carried, timeLeft, battery, dBase, urgentT, urgentB) {
  const hi = pickHint(mem, me, timeLeft);
  const wantD = carried > 0 && mem.tick >= mem.noDel &&
    (carried >= mem.cap || urgentT || urgentB || hi < 0 || carried >= 3);
  const needCharge = carried === 0 && battery < 0.2 && timeLeft > 200 && dBase > 3 && mem.tick >= mem.noDel;
  if (wantD || needCharge) { mem.mode = 'deliver'; mem.dockT = 0; return; }
  if (hi >= 0) {
    const h = mem.hints[hi];
    mem.hi = hi; mem.mode = 'nav'; mem.navT = 0; mem.recN = 0;
    mem.navLim = dist(me.x, me.y, h.x, h.y) * 25 + 300;
    return;
  }
  mem.mode = 'explore'; mem.hi = -1; mem.wd = null; mem.wT = 0;
}

function navStep(mem, me, H, rays, out) {
  const h = mem.hints[mem.hi];
  if (!h || h.done || h.fails >= 2) { mem.mode = 'pick'; mem.hi = -1; return out; }
  const d = dist(me.x, me.y, h.x, h.y);
  mem.navT++;
  if (d < 4) {
    mem.mode = 'search';
    mem.sp = { cx: h.x, cy: h.y, k: 0, t: 0 };
    return out;
  }
  if (mem.navT > mem.navLim) { h.fails += 1; mem.mode = 'pick'; return out; }
  return steer(mem, wrap(brg(me.x, me.y, h.x, h.y) - H), d > 10 ? 0.4 : 0.3, rays, out);
}

function searchStep(mem, me, H, rays, out) {
  const sp = mem.sp;
  sp.t++;
  while (sp.k < 34) {
    const w = spiralPt(sp, sp.k);
    if (dist(me.x, me.y, w.x, w.y) < 2.5) sp.k++; else break;
  }
  if (sp.k >= 34 || sp.t > 1800) {
    if (mem.hi >= 0 && mem.hints[mem.hi]) mem.hints[mem.hi].done = true;
    else mem.sciCool = mem.tick + 600;
    mem.hi = -1;
    mem.mode = 'pick';
    return out;
  }
  const w = spiralPt(sp, sp.k);
  return steer(mem, wrap(brg(me.x, me.y, w.x, w.y) - H), 0.3, rays, out);
}

function deliverStep(mem, me, dBase, H, vAvg, carried, obs, rays, out) {
  if (carried <= 0) { mem.mode = 'pick'; return out; }
  let bd = dBase;
  const bc = obs.beacon;
  if (bc && typeof bc.distance === 'number' && isFinite(bc.distance)) bd = Math.min(bd, bc.distance);
  if (obs.docked) bd = 0;
  if (bd <= 2.4) {
    mem.dockT++;
    const h = clamp(-0.6 * vAvg, -0.15, 0.15);
    out.left = h; out.right = h; out.drill = false;
    if (mem.dockT > 60) { mem.noDel = mem.tick + 400; mem.mode = 'pick'; mem.dockT = 0; }
    return out;
  }
  mem.dockT = 0;
  let e;
  if (bc && typeof bc.bearing === 'number' && isFinite(bc.bearing) && num(bc.distance, 99) < 20) {
    e = bc.bearing;
  } else {
    e = wrap(brg(me.x, me.y, mem.base.x, mem.base.y) - H);
  }
  return steer(mem, e, bd > 8 ? 0.4 : 0.28, rays, out);
}

function wanderStep(mem, me, H, rays, out, timeLeft, sci) {
  mem.wT++;
  if (sci > 2.0 && mem.tick > mem.sciCool) {
    mem.mode = 'search'; mem.hi = -1;
    mem.sp = { cx: me.x, cy: me.y, k: 0, t: 0 };
    return out;
  }
  if (!mem.wd || mem.wT > 1500 || dist(me.x, me.y, mem.wd.x, mem.wd.y) < 6) {
    mem.wd = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
    mem.wT = 0;
  }
  if (mem.tick % 20 === 0 && pickHint(mem, me, timeLeft) >= 0) {
    mem.mode = 'pick';
    return out;
  }
  return steer(mem, wrap(brg(me.x, me.y, mem.wd.x, mem.wd.y) - H), 0.35, rays, out);
}

function core(obs, mem) {
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  const gx = num(obs.x), gy = num(obs.y);
  const wl = num(obs.wheelLeft), wr = num(obs.wheelRight);
  const vAvg = (wl + wr) / 2;
  const carried = num(obs.carried);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const rays = sanitizeRays(obs.rays);
  const site = (obs.site && typeof obs.site === 'object') ? obs.site : null;
  const sci = num(obs.science);
  const base = mem.base;

  // compass median
  mem.cb.push(num(obs.heading));
  if (mem.cb.length > 5) mem.cb.shift();
  const cm = medoid(mem.cb);

  // GPS freshness
  const fresh = mem.lgx === null || gx !== mem.lgx || gy !== mem.lgy;
  if (fresh) { mem.lgx = gx; mem.lgy = gy; mem.stale = 0; } else mem.stale++;

  // smoothed forward command
  mem.fa = 0.9 * mem.fa + 0.1 * ((mem.lastL + mem.lastR) / 2);

  // heading: compass with learned offset, corrected by GPS chords
  if (mem.hd === null) mem.hd = wrap(cm + mem.off);
  mem.hd = wrap(mem.hd + 0.15 * wrap(cm + mem.off - mem.hd));
  if (fresh) {
    mem.fx.push({ x: gx, y: gy, t: mem.tick });
    if (mem.fx.length > 80) mem.fx.shift();
    const n = mem.fx.length, c = mem.fx[n - 1];
    let j = -1;
    for (let i = n - 2; i >= 0; i--) {
      const f = mem.fx[i];
      if (mem.tick - f.t > 150) break;
      if (dist(c.x, c.y, f.x, f.y) >= 5) { j = i; break; }
    }
    if (j >= 0 && mem.fa > 0.2) {
      const f = mem.fx[j];
      const ch = brg(f.x, f.y, c.x, c.y);
      if (!mem.offInit) {
        mem.off = wrap(ch - cm); mem.offInit = true; mem.hd = ch;
      } else {
        mem.hd = wrap(mem.hd + 0.4 * wrap(ch - mem.hd));
        mem.off = wrap(mem.off + 0.08 * wrap(ch - cm - mem.off));
      }
    }
  }
  const H = mem.hd;

  // position: GPS, dead reckoning when GPS frozen
  if (!mem.dr || fresh) mem.dr = { x: gx, y: gy };
  else {
    const hr = H * D2R;
    mem.dr = { x: mem.dr.x + vAvg * 0.1 * Math.cos(hr), y: mem.dr.y + vAvg * 0.1 * Math.sin(hr) };
  }
  const useDR = mem.stale > 50;
  const me = useDR ? { x: mem.dr.x, y: mem.dr.y } : { x: gx, y: gy };
  const dBase = dist(me.x, me.y, base.x, base.y);

  // stuck and bump detection
  mem.ph.push({ x: me.x, y: me.y, f: (mem.lastL + mem.lastR) / 2 });
  if (mem.ph.length > 25) mem.ph.shift();
  if (mem.rec === 0 && mem.mode !== 'drill') {
    let stuck = !!obs.bumped;
    if (mem.ph.length >= 25) {
      const f0 = mem.ph[0];
      let fa = 0;
      for (const p of mem.ph) fa += p.f;
      fa /= mem.ph.length;
      if (fa > 0.2 && dist(me.x, me.y, f0.x, f0.y) < 0.5) stuck = true;
    }
    if (stuck) startRec(mem, rays);
  }
  if (mem.rec > 0 && mem.mode !== 'drill') return recStep(mem, out);

  // drilling: hold still, drill on, until a sample arrives
  if (mem.mode === 'drill') {
    mem.dT++;
    const h = clamp(-0.6 * vAvg, -0.15, 0.15);
    out.left = h; out.right = h;
    if (carried > mem.dC0) {
      if (mem.dPos) markNear(mem, mem.dPos, 15);
      if (mem.dSite) mem.ign.push(mem.dSite);
      mem.mode = 'pick';
      out.left = 0; out.right = 0; out.drill = false;
      return out;
    }
    if (mem.dT > 160) {
      if (mem.dSite) mem.ign.push(mem.dSite);
      mem.mode = 'pick';
      out.drill = false;
      return out;
    }
    out.drill = true;
    return out;
  }

  const urgentT = timeLeft < dBase / 0.35 + 60;
  const urgentB = battery < 0.1 + dBase * 0.003;

  // opportunistic sampling of a visible site
  if (site && carried < mem.cap && !urgentT && !urgentB && mem.mode !== 'deliver' && mem.mode !== 'cal') {
    const d = num(site.distance, 99);
    const sw = siteWorld(me, H, site);
    if (!isIgn(mem, sw)) {
      mem.siteT++;
      if (mem.siteT > 300) {
        mem.ign.push(sw); mem.siteT = 0;
      } else if (d <= 1.3) {
        const still = Math.abs(vAvg) < 0.1 && Math.abs(wl) < 0.2 && Math.abs(wr) < 0.2;
        if (still) {
          mem.mode = 'drill';
          mem.dT = 0; mem.dC0 = carried;
          mem.dPos = { x: me.x, y: me.y };
          mem.dSite = sw;
          out.drill = true;
          return out;
        }
        const h = clamp(-0.6 * vAvg, -0.15, 0.15);
        out.left = h; out.right = h;
        return out;
      } else {
        return steer(mem, num(site.bearing), clamp(0.15 + 0.1 * d, 0.15, 0.3), rays, out);
      }
    }
  } else {
    mem.siteT = 0;
  }

  // initial calibration drive (learns compass offset from GPS chord)
  if (mem.mode === 'cal') {
    mem.calT++;
    const fr = Math.min(rays[3], rays[4], rays[5]);
    if (mem.offInit || mem.calT > 120 || fr < 2.5) mem.mode = 'pick';
    else { out.left = 0.35; out.right = 0.35; return out; }
  }

  if (mem.mode === 'pick') pickStep(mem, me, carried, timeLeft, battery, dBase, urgentT, urgentB);
  if (mem.mode === 'nav') return navStep(mem, me, H, rays, out);
  if (mem.mode === 'search') return searchStep(mem, me, H, rays, out);
  if (mem.mode === 'deliver') return deliverStep(mem, me, dBase, H, vAvg, carried, obs, rays, out);
  if (mem.mode === 'explore') return wanderStep(mem, me, H, rays, out, timeLeft, sci);

  mem.mode = 'pick';
  return out;
}

function act(obs, mem) {
  let out;
  try {
    if (!mem.init) init(obs, mem);
    out = core(obs, mem);
  } catch (e) {
    out = { left: 0, right: 0, drill: false };
  }
  const l = clamp(num(out.left), -1, 1);
  const r = clamp(num(out.right), -1, 1);
  mem.lastL = l; mem.lastR = r;
  return { left: l, right: r, drill: !!out.drill };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 100, CS = 4;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }
function cellIdx(x, y) {
  const cx = clamp(Math.floor(x / CS), 0, GN - 1);
  const cy = clamp(Math.floor(y / CS), 0, GN - 1);
  return cy * GN + cx;
}
function cellCenter(c) { return { x: ((c % GN) + 0.5) * CS, y: (Math.floor(c / GN) + 0.5) * CS }; }

function medoid(arr) {
  let best = arr[arr.length - 1], bs = Infinity;
  for (const a of arr) {
    let s = 0;
    for (const b of arr) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

function sanitizeRays(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function init(obs, mem) {
  const m = obs.mission || {};
  const x0 = num(obs.x), y0 = num(obs.y);
  const b = m.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(m.capacity, 5) || 5;
  mem.hints = [];
  const hs = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hs) {
    if (h && isFinite(h.x) && isFinite(h.y)) {
      mem.hints.push({ x: h.x, y: h.y, est: num(h.estimate, 1), done: false, fails: 0 });
    }
  }
  mem.seed = 4242; mem.tick = 0;
  mem.cb = []; mem.off = 0; mem.offInit = false; mem.hd = null;
  mem.lgx = null; mem.lgy = null; mem.stale = 0; mem.fx = []; mem.dr = null;
  mem.occ = new Float32Array(GN * GN);
  mem.lastL = 0; mem.lastR = 0; mem.lastF = 0;
  mem.ph = []; mem.piv = false;
  mem.mode = 'cal'; mem.calT = 0;
  mem.hi = -1; mem.navT = 0; mem.navLim = 1000; mem.tryN = 0;
  mem.path = null; mem.pathT = -100; mem.pathGoal = null;
  mem.sr = null; mem.wd = null; mem.wT = 0; mem.sciCool = 0;
  mem.rec = 0; mem.recDir = 1; mem.recN = 0;
  mem.ign = []; mem.siteT = 0;
  mem.dT = 0; mem.dC0 = 0; mem.dPos = null; mem.dSite = null;
  mem.dockT = 0; mem.noDel = 0;
  mem.init = true;
}

function isIgn(mem, p) {
  for (const q of mem.ign) if (dist(p.x, p.y, q.x, q.y) < 3) return true;
  return false;
}

function siteWorld(me, H, site) {
  const a = (H + num(site.bearing, 0)) * D2R, d = num(site.distance, 0);
  return { x: me.x + d * Math.cos(a), y: me.y + d * Math.sin(a) };
}

function markNear(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function pickHint(mem, me, timeLeft) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    if (isIgn(mem, h)) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.35 + 120 > timeLeft) continue;
    const sc = (Math.max(h.est, 0) + 0.3) / (d1 + 0.6 * d2 + 40);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

// Occupancy map from range rays (cells of CS metres)
function mapUpdate(mem, me, H, rays) {
  const occ = mem.occ;
  for (let i = 0; i < 9; i++) {
    const r = rays[i];
    const a = (H + (-80 + 20 * i)) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    const top = Math.min(r, 14.5);
    for (let s = 1.5; s < top - 1.0; s += 1.5) {
      const k = cellIdx(me.x + s * ca, me.y + s * sa);
      if (occ[k] > 0) occ[k] = Math.max(0, occ[k] - 0.3);
    }
    if (r < 14.5 && r > 0.6) {
      const k = cellIdx(me.x + r * ca, me.y + r * sa);
      occ[k] = Math.min(occ[k] + 1, 6);
    }
  }
}

function heapPush(h, f, v) {
  let i = h.f.length;
  h.f.push(f); h.v.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (h.f[p] <= f) break;
    h.f[i] = h.f[p]; h.v[i] = h.v[p];
    i = p;
  }
  h.f[i] = f; h.v[i] = v;
}

function heapPop(h) {
  const top = h.v[0];
  const last = h.f.length - 1;
  const lf = h.f[last], lv = h.v[last];
  h.f.pop(); h.v.pop();
  const n = last;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && h.f[c + 1] < h.f[c]) c++;
      if (h.f[c] >= lf) break;
      h.f[i] = h.f[c]; h.v[i] = h.v[c];
      i = c;
    }
    h.f[i] = lf; h.v[i] = lv;
  }
  return top;
}

function astar(mem, sx, sy, tx, ty) {
  const occ = mem.occ, N = GN * GN;
  const s = cellIdx(sx, sy), g = cellIdx(tx, ty);
  if (s === g) return [g];
  const gs = new Float32Array(N).fill(1e9);
  const came = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const gx = g % GN, gy = Math.floor(g / GN);
  const hh = (c) => {
    const dx = Math.abs((c % GN) - gx), dy = Math.abs(Math.floor(c / GN) - gy);
    return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
  };
  const hp = { f: [], v: [] };
  gs[s] = 0;
  heapPush(hp, hh(s), s);
  let exp = 0, found = false;
  while (hp.f.length > 0 && exp < 9000) {
    const cur = heapPop(hp);
    if (closed[cur]) continue;
    closed[cur] = 1; exp++;
    if (cur === g) { found = true; break; }
    const cx = cur % GN, cy = Math.floor(cur / GN);
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const nx = cx + dx, ny = cy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const n = ny * GN + nx;
        if (closed[n]) continue;
        if (n !== g && occ[n] >= 2) continue;
        if (dx && dy && (occ[cy * GN + nx] >= 2 || occ[ny * GN + cx] >= 2)) continue;
        const step = (dx && dy) ? 1.414 : 1;
        const ng = gs[cur] + step + (occ[n] > 0.5 ? 1.0 : 0);
        if (ng < gs[n]) {
          gs[n] = ng; came[n] = cur;
          heapPush(hp, ng + hh(n), n);
        }
      }
    }
  }
  if (!found) return null;
  const path = [];
  let c = g;
  while (c !== -1 && c !== s) { path.push(c); c = came[c]; }
  path.push(s);
  path.reverse();
  return path;
}

function clearLine(mem, ax, ay, bx, by) {
  const d = dist(ax, ay, bx, by);
  const n = Math.max(1, Math.ceil(d / 1.5));
  for (let i = 1; i < n; i++) {
    const t = i / n;
    if (mem.occ[cellIdx(ax + (bx - ax) * t, ay + (by - ay) * t)] >= 2) return false;
  }
  return true;
}

function lookTarget(mem, me, path) {
  for (let k = path.length - 1; k >= 1; k--) {
    const p = cellCenter(path[k]);
    if (clearLine(mem, me.x, me.y, p.x, p.y)) return p;
  }
  if (path.length > 1) return cellCenter(path[1]);
  return null;
}

// Drive towards (tx,ty) using the map path when the straight line is blocked
function navTo(mem, me, H, tx, ty, v, rays, out) {
  let wx = tx, wy = ty;
  if (!clearLine(mem, me.x, me.y, tx, ty)) {
    const newGoal = !mem.pathGoal || dist(mem.pathGoal.x, mem.pathGoal.y, tx, ty) > 3;
    if (newGoal || mem.tick - mem.pathT >= 8) {
      mem.path = astar(mem, me.x, me.y, tx, ty);
      mem.pathT = mem.tick;
      mem.pathGoal = { x: tx, y: ty };
    }
    if (mem.path) {
      const p = lookTarget(mem, me, mem.path);
      if (p) { wx = p.x; wy = p.y; }
    }
  }
  const e = wrap(brg(me.x, me.y, wx, wy) - H);
  return drive(mem, e, v, rays, out);
}

// e: bearing error (deg, positive = target to the left)
function drive(mem, e, v, rays, out) {
  const front = Math.min(rays[3], rays[4], rays[5]);
  let vv = v;
  if (front < 1.5) vv = Math.min(vv, 0.15);
  if (front < 0.8) vv = 0;
  let ee = clamp(e, -180, 180);
  if (front < 2.5) {
    const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
    const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
    ee = clamp(ee + (L >= R ? 1 : -1) * 25 * (2.5 - front) / 2.5, -180, 180);
  }
  if (Math.abs(ee) > 70) mem.piv = true;
  else if (Math.abs(ee) < 35) mem.piv = false;
  if (mem.piv) {
    const s = ee >= 0 ? 1 : -1;
    out.left = -0.35 * s; out.right = 0.35 * s; out.drill = false;
    return out;
  }
  const fwd = vv * clamp(1 - Math.abs(ee) / 90, 0.2, 1);
  const turn = clamp(ee / 35, -1, 1) * 0.3;
  out.left = clamp(fwd - turn, -1, 1);
  out.right = clamp(fwd + turn, -1, 1);
  out.drill = false;
  return out;
}

function startRec(mem, me, H, rays) {
  mem.rec = 25; mem.ph = [];
  const a = H * D2R;
  const k = cellIdx(me.x + 2.5 * Math.cos(a), me.y + 2.5 * Math.sin(a));
  mem.occ[k] = Math.max(mem.occ[k], 1.5);
  const L = (rays[5] + rays[6] + rays[7] + rays[8]) / 4;
  const R = (rays[0] + rays[1] + rays[2] + rays[3]) / 4;
  mem.recDir = Math.abs(L - R) < 0.3 ? (rnd(mem) < 0.5 ? -1 : 1) : (L > R ? 1 : -1);
  mem.recN++; mem.tryN++;
  if (mem.tryN >= 4 && (mem.mode === 'go' || mem.mode === 'search')) giveUp(mem);
}

function recStep(mem, out) {
  mem.rec--;
  if (mem.rec >= 12) { out.left = -0.3; out.right = -0.3; }
  else { const s = 0.35 * mem.recDir; out.left = -s; out.right = s; }
  out.drill = false;
  return out;
}

function giveUp(mem) {
  if (mem.mode === 'go' || mem.mode === 'search') {
    const h = mem.hints[mem.hi];
    if (h) { h.fails += 1; if (h.fails >= 2) h.done = true; }
  }
  mem.mode = 'pick'; mem.hi = -1; mem.tryN = 0; mem.sr = null;
}

function startSearch(mem, me, cx, cy, hi, timeLeft) {
  const a0 = Math.atan2(me.y - cy, me.x - cx);
  const list = [];
  for (let k = 0; k < 8; k++) {
    const a = a0 + k * Math.PI / 4;
    list.push({ x: clamp(cx + 8 * Math.cos(a), 3, 397), y: clamp(cy + 8 * Math.sin(a), 3, 397) });
  }
  if (timeLeft > 450) {
    for (let k = 0; k < 8; k++) {
      const a = a0 + Math.PI / 8 + k * Math.PI / 4;
      list.push({ x: clamp(cx + 16 * Math.cos(a), 3, 397), y: clamp(cy + 16 * Math.sin(a), 3, 397) });
    }
  }
  mem.sr = { list: list, k: 0, wt: 0, t: 0, hi: hi };
  mem.mode = 'search';
  mem.tryN = 0;
}

function finishSearch(mem) {
  const s = mem.sr;
  if (s && s.hi >= 0 && mem.hints[s.hi]) mem.hints[s.hi].done = true;
  else mem.sciCool = mem.tick + 600;
  mem.sr = null; mem.mode = 'pick'; mem.hi = -1;
}

function searchStep(mem, me, H, rays, out, timeLeft) {
  const s = mem.sr;
  if (!s) { mem.mode = 'pick'; return out; }
  s.t++;
  if (s.k >= s.list.length || s.t > 1500 || timeLeft < 60) { finishSearch(mem); return out; }
  const w = s.list[s.k];
  if (dist(me.x, me.y, w.x, w.y) < 2.5 || s.wt > 300) { s.k++; s.wt = 0; return out; }
  s.wt++;
  return navTo(mem, me, H, w.x, w.y, 0.35, rays, out);
}

function drillStep(mem, carried, vAvg, out) {
  mem.dT++;
  const h = clamp(-vAvg, -0.15, 0.15);
  out.left = h; out.right = h; out.drill = true;
  if (carried > mem.dC0) {
    if (mem.dPos) markNear(mem, mem.dPos, 20);
    if (mem.dSite) mem.ign.push(mem.dSite);
    mem.mode = 'pick'; mem.siteT = 0;
    out.left = 0; out.right = 0; out.drill = false;
    return out;
  }
  if (mem.dT > 200) {
    if (mem.dSite) mem.ign.push(mem.dSite);
    mem.mode = 'pick'; mem.siteT = 0;
    out.left = 0; out.right = 0; out.drill = false;
    return out;
  }
  return out;
}

function pickStep(mem, me, carried, timeLeft, battery, dBase) {
  if (carried > 0 && mem.tick >= mem.noDel && (carried >= mem.cap || battery < 0.15)) {
    mem.mode = 'deliver'; mem.dockT = 0; return;
  }
  const hi = pickHint(mem, me, timeLeft);
  if (hi >= 0) {
    const h = mem.hints[hi];
    mem.hi = hi; mem.mode = 'go'; mem.navT = 0;
    mem.navLim = dist(me.x, me.y, h.x, h.y) * 25 + 300;
    mem.tryN = 0;
    return;
  }
  if (carried > 0 && mem.tick >= mem.noDel) { mem.mode = 'deliver'; mem.dockT = 0; return; }
  mem.mode = 'wander'; mem.wd = null; mem.wT = 0; mem.hi = -1; mem.tryN = 0;
}

function goStep(mem, me, H, rays, out, timeLeft) {
  const h = mem.hints[mem.hi];
  if (!h || h.done) { mem.mode = 'pick'; mem.hi = -1; return out; }
  const d = dist(me.x, me.y, h.x, h.y);
  mem.navT++;
  if (d <= 4) {
    startSearch(mem, me, h.x, h.y, mem.hi, timeLeft);
    return searchStep(mem, me, H, rays, out, timeLeft);
  }
  if (mem.navT > mem.navLim) {
    h.fails += 1; if (h.fails >= 2) h.done = true;
    mem.mode = 'pick'; mem.hi = -1;
    return out;
  }
  return navTo(mem, me, H, h.x, h.y, d > 10 ? 0.4 : 0.3, rays, out);
}

function deliverStep(mem, me, dBase, H, vAvg, carried, obs, rays, out) {
  if (carried <= 0) { mem.mode = 'pick'; return out; }
  const bc = obs.beacon;
  let bd = dBase;
  if (bc && isFinite(bc.distance)) bd = Math.min(bd, bc.distance);
  if (obs.docked || bd <= 2.2) {
    mem.dockT++;
    out.left = clamp(-vAvg, -0.15, 0.15); out.right = out.left;
    if (mem.dockT > 80) { mem.noDel = mem.tick + 300; mem.mode = 'pick'; mem.dockT = 0; }
    return out;
  }
  mem.dockT = 0;
  if (bc && isFinite(bc.bearing) && isFinite(bc.distance) && bc.distance < 8) {
    return drive(mem, bc.bearing, 0.25, rays, out);
  }
  return navTo(mem, me, H, mem.base.x, mem.base.y, bd > 8 ? 0.45 : 0.3, rays, out);
}

function wanderStep(mem, me, H, rays, out, timeLeft, sci) {
  if (sci > 2.0 && mem.tick > mem.sciCool) {
    startSearch(mem, me, me.x, me.y, -1, timeLeft);
    return out;
  }
  if (mem.tick % 25 === 0 && pickHint(mem, me, timeLeft) >= 0) { mem.mode = 'pick'; return out; }
  if (!mem.wd || mem.wT > 400 || dist(me.x, me.y, mem.wd.x, mem.wd.y) < 6) {
    mem.wd = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
    mem.wT = 0;
  }
  mem.wT++;
  return navTo(mem, me, H, mem.wd.x, mem.wd.y, 0.35, rays, out);
}

function core(obs, mem) {
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  const gx = num(obs.x), gy = num(obs.y);
  const wl = num(obs.wheelLeft), wr = num(obs.wheelRight);
  const vAvg = (wl + wr) / 2;
  const carried = num(obs.carried);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const rays = sanitizeRays(obs.rays);
  const site = (obs.site && typeof obs.site === 'object') ? obs.site : null;
  const sci = num(obs.science);

  // compass median
  mem.cb.push(num(obs.heading));
  if (mem.cb.length > 5) mem.cb.shift();
  const cm = medoid(mem.cb);

  // GPS freshness and fix history
  const fresh = mem.lgx === null || gx !== mem.lgx || gy !== mem.lgy;
  if (fresh) {
    mem.lgx = gx; mem.lgy = gy; mem.stale = 0;
    mem.fx.push({ x: gx, y: gy, t: mem.tick });
    if (mem.fx.length > 60) mem.fx.shift();
  } else mem.stale++;

  // heading: compass with learned offset, corrected by GPS chords when driving straight
  if (mem.hd === null) mem.hd = wrap(cm + mem.off);
  mem.hd = wrap(mem.hd + 0.15 * wrap(cm + mem.off - mem.hd));
  if (fresh && mem.fx.length >= 2) {
    const n = mem.fx.length, c = mem.fx[n - 1];
    let j = -1;
    for (let i = n - 2; i >= 0; i--) {
      const f = mem.fx[i];
      if (mem.tick - f.t > 200) break;
      if (dist(c.x, c.y, f.x, f.y) >= 5) { j = i; break; }
    }
    if (j >= 0 && mem.lastF > 0.15 && Math.abs(mem.lastL - mem.lastR) < 0.15) {
      const f = mem.fx[j];
      const ch = brg(f.x, f.y, c.x, c.y);
      if (!mem.offInit) {
        mem.off = wrap(ch - cm); mem.offInit = true; mem.hd = ch;
      } else {
        mem.hd = wrap(mem.hd + 0.3 * wrap(ch - mem.hd));
        mem.off = wrap(mem.off + 0.1 * wrap(ch - cm - mem.off));
      }
    }
  }
  const H = mem.hd;

  // position: GPS, dead reckoning when GPS is frozen
  if (!mem.dr || fresh) mem.dr = { x: gx, y: gy };
  else {
    const hr = H * D2R, vv = clamp(vAvg, -1, 1);
    mem.dr = { x: mem.dr.x + vv * 0.1 * Math.cos(hr), y: mem.dr.y + vv * 0.1 * Math.sin(hr) };
  }
  const useDR = mem.stale > 40;
  const me = useDR ? { x: clamp(mem.dr.x, 0, 400), y: clamp(mem.dr.y, 0, 400) } : { x: gx, y: gy };
  const dBase = dist(me.x, me.y, mem.base.x, mem.base.y);

  mapUpdate(mem, me, H, rays);

  // stuck and bump detection
  mem.ph.push({ x: me.x, y: me.y, f: mem.lastF > 0.15 ? 1 : 0 });
  if (mem.ph.length > 30) mem.ph.shift();
  if (mem.rec === 0 && mem.mode !== 'drill') {
    let stuck = !!obs.bumped;
    if (mem.ph.length >= 30) {
      let fc = 0, md = 0;
      for (const p of mem.ph) { fc += p.f; md = Math.max(md, dist(p.x, p.y, me.x, me.y)); }
      if (fc >= 22 && md < 0.5) stuck = true;
    }
    if (stuck) startRec(mem, me, H, rays);
  }
  if (mem.rec > 0) return recStep(mem, out);

  if (mem.mode === 'drill') return drillStep(mem, carried, vAvg, out);

  // initial straight drive to learn the compass offset from a GPS chord
  if (mem.mode === 'cal') {
    mem.calT++;
    const fr = Math.min(rays[3], rays[4], rays[5]);
    if (mem.offInit || mem.calT > 150 || fr < 2.5) mem.mode = 'pick';
    else { out.left = 0.35; out.right = 0.35; return out; }
  }

  const urgentT = carried > 0 && timeLeft < dBase / 0.3 + 60;
  if (carried > 0 && (urgentT || battery < 0.08) && mem.mode !== 'deliver') {
    mem.mode = 'deliver'; mem.dockT = 0;
  }

  // opportunistic sampling of a visible site
  if (mem.mode !== 'deliver' && carried < mem.cap && !urgentT && site) {
    const d = num(site.distance, 99);
    const sw = siteWorld(me, H, site);
    if (d <= 8.5 && !isIgn(mem, sw)) {
      mem.siteT++;
      if (mem.siteT > 250) {
        mem.ign.push(sw); mem.siteT = 0;
      } else if (d <= 1.3) {
        const still = Math.abs(vAvg) < 0.1 && Math.abs(wl) < 0.15 && Math.abs(wr) < 0.15;
        if (still) {
          mem.mode = 'drill';
          mem.dT = 0; mem.dC0 = carried;
          mem.dPos = { x: me.x, y: me.y };
          mem.dSite = sw;
          out.drill = true;
          return out;
        }
        out.left = clamp(-vAvg, -0.15, 0.15); out.right = out.left;
        return out;
      } else {
        return drive(mem, num(site.bearing), clamp(0.12 + 0.1 * d, 0.15, 0.3), rays, out);
      }
    }
  } else {
    mem.siteT = 0;
  }

  if (mem.mode === 'pick') pickStep(mem, me, carried, timeLeft, battery, dBase);
  if (mem.mode === 'deliver') return deliverStep(mem, me, dBase, H, vAvg, carried, obs, rays, out);
  if (mem.mode === 'go') return goStep(mem, me, H, rays, out, timeLeft);
  if (mem.mode === 'search') return searchStep(mem, me, H, rays, out, timeLeft);
  if (mem.mode === 'wander') return wanderStep(mem, me, H, rays, out, timeLeft, sci);

  mem.mode = 'pick';
  return out;
}

function act(obs, mem) {
  let out = { left: 0, right: 0, drill: false };
  try {
    if (!mem.init) init(obs, mem);
    out = core(obs, mem) || out;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    if (mem.init) { mem.mode = 'pick'; mem.rec = 0; mem.sr = null; mem.hi = -1; }
  }
  const l = clamp(num(out.left), -1, 1);
  const r = clamp(num(out.right), -1, 1);
  mem.lastL = l; mem.lastR = r; mem.lastF = (l + r) / 2;
  return { left: l, right: r, drill: !!out.drill };
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) * R2D; }
function rnd(mem) { mem.seed = (mem.seed * 16807) % 2147483647; return mem.seed / 2147483647; }

function medoid(arr) {
  let best = arr[arr.length - 1], bs = Infinity;
  for (const a of arr) {
    let s = 0;
    for (const b of arr) s += Math.abs(wrap(a - b));
    if (s < bs) { bs = s; best = a; }
  }
  return best;
}

function sanitizeRays(r) {
  const o = [];
  for (let i = 0; i < 9; i++) {
    const v = (r && typeof r[i] === 'number' && isFinite(r[i])) ? r[i] : 15;
    o.push(clamp(v, 0.05, 15));
  }
  return o;
}

function avgRay(rays, a, b) {
  let s = 0;
  for (let i = a; i <= b; i++) s += rays[i];
  return s / (b - a + 1);
}

function init(obs, mem) {
  const m = obs.mission || {};
  const x0 = num(obs.x), y0 = num(obs.y);
  const b = m.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(m.capacity, 5) || 5;
  mem.hints = [];
  const hs = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hs) {
    if (h && isFinite(h.x) && isFinite(h.y)) {
      mem.hints.push({ x: h.x, y: h.y, est: num(h.estimate, 1), done: false, fails: 0 });
    }
  }
  mem.seed = 4242; mem.tick = 0;
  mem.cb = []; mem.off = 0; mem.offInit = false;
  mem.fx = []; mem.lgx = null; mem.lgy = null; mem.stale = 0; mem.dr = null;
  mem.lastL = 0; mem.lastR = 0;
  mem.piv = false; mem.bias = 0; mem.biasT = 0; mem.tt = 0; mem.td = 1;
  mem.man = []; mem.cpPos = null; mem.cpT = 0; mem.cpMove = 0; mem.bumpCd = 0;
  mem.mode = 'pick'; mem.hi = -1; mem.navT = 0; mem.navLim = 500;
  mem.sr = null; mem.wd = null; mem.wT = 0; mem.sciCool = 0;
  mem.ign = []; mem.siteT = 0;
  mem.dT = 0; mem.dC0 = 0; mem.dPos = null; mem.dSite = null;
  mem.dockT = 0; mem.noDel = 0;
  mem.init = true;
}

function isIgn(mem, p) {
  for (const q of mem.ign) if (dist(p.x, p.y, q.x, q.y) < 3) return true;
  return false;
}

function siteWorld(me, H, site) {
  const a = (H + num(site.bearing, 0)) * D2R, d = num(site.distance, 0);
  return { x: me.x + d * Math.cos(a), y: me.y + d * Math.sin(a) };
}

function markNear(mem, p, r) {
  let bi = -1, bd = r;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done) continue;
    const d = dist(p.x, p.y, h.x, h.y);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].done = true;
}

function pickHint(mem, me, timeLeft) {
  let best = -1, bs = -Infinity;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    if (isIgn(mem, h)) continue;
    const d1 = dist(me.x, me.y, h.x, h.y);
    const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d1 + d2) / 0.35 + 120 > timeLeft) continue;
    const sc = (Math.max(h.est, 0) + 0.3) / (d1 + 0.6 * d2 + 40);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function startUnstick(mem, rays, back) {
  const Lc = avgRay(rays, 5, 8), Rc = avgRay(rays, 0, 3);
  const s = Math.abs(Lc - Rc) < 0.3 ? (rnd(mem) < 0.5 ? -1 : 1) : (Lc > Rc ? 1 : -1);
  mem.man = [[-0.3, -0.3, back], [-0.3 * s, 0.3 * s, 12]];
  mem.bias = s * 45; mem.biasT = 50;
  mem.tt = 0;
}

// Continuous steering with committed avoidance turns.
// e: target bearing error in degrees (positive = target to the left)
function drive(mem, e, v, rays, out) {
  const front = Math.min(rays[3], rays[4], rays[5]);
  if (front < 1.5 && mem.tt === 0) {
    mem.td = avgRay(rays, 5, 8) >= avgRay(rays, 0, 3) ? 1 : -1;
    mem.tt = 10;
    mem.bias = mem.td * 40; mem.biasT = 40;
  }
  if (mem.tt > 0) {
    mem.tt--;
    out.left = -0.3 * mem.td; out.right = 0.3 * mem.td; out.drill = false;
    return out;
  }
  let vv = v;
  if (front < 3) vv = Math.min(vv, 0.18);
  let ee = clamp(e + mem.bias, -180, 180);
  for (let i = 0; i < 9; i++) {
    if (i === 4) continue;
    const r = rays[i];
    if (r < 2.5) {
      const a = -80 + 20 * i;
      ee -= (2.5 - r) / 2.5 * 30 * Math.sign(a);
    }
  }
  ee = clamp(ee, -180, 180);
  if (Math.abs(ee) > 85) mem.piv = true;
  else if (Math.abs(ee) < 40) mem.piv = false;
  if (mem.piv) {
    const s = ee >= 0 ? 1 : -1;
    out.left = -0.3 * s; out.right = 0.3 * s; out.drill = false;
    return out;
  }
  const fwd = vv * clamp(1 - Math.abs(ee) / 100, 0.2, 1);
  const turn = clamp(ee / 30, -1, 1) * 0.3;
  out.left = clamp(fwd - turn, -1, 1);
  out.right = clamp(fwd + turn, -1, 1);
  out.drill = false;
  return out;
}

function startSearch(mem, me, cx, cy, hi, timeLeft) {
  const list = [];
  for (let k = 0; k < 8; k++) {
    const a = k * Math.PI / 4;
    list.push({ x: clamp(cx + 9 * Math.cos(a), 3, 397), y: clamp(cy + 9 * Math.sin(a), 3, 397) });
  }
  if (timeLeft > 400) {
    for (let k = 0; k < 8; k++) {
      const a = Math.PI / 8 + k * Math.PI / 4;
      list.push({ x: clamp(cx + 18 * Math.cos(a), 3, 397), y: clamp(cy + 18 * Math.sin(a), 3, 397) });
    }
  }
  mem.sr = { list: list, k: 0, wt: 0, t: 0, hi: hi };
  mem.mode = 'search';
}

function finishSearch(mem) {
  const s = mem.sr;
  if (s && s.hi >= 0 && mem.hints[s.hi]) mem.hints[s.hi].done = true;
  else mem.sciCool = mem.tick + 600;
  mem.sr = null; mem.mode = 'pick'; mem.hi = -1;
}

function searchStep(mem, me, H, rays, out, timeLeft) {
  const s = mem.sr;
  if (!s) { mem.mode = 'pick'; return out; }
  s.t++;
  if (s.k >= s.list.length || s.t > 1200 || timeLeft < 60) { finishSearch(mem); return out; }
  const w = s.list[s.k];
  if (dist(me.x, me.y, w.x, w.y) < 2.5 || s.wt > 200) { s.k++; s.wt = 0; return out; }
  s.wt++;
  return drive(mem, wrap(brg(me.x, me.y, w.x, w.y) - H), 0.25, rays, out);
}

function goStep(mem, me, H, rays, out, timeLeft) {
  const h = mem.hints[mem.hi];
  if (!h || h.done || h.fails >= 2) { mem.mode = 'pick'; mem.hi = -1; return out; }
  const d = dist(me.x, me.y, h.x, h.y);
  mem.navT++;
  if (d <= 5) {
    startSearch(mem, me, h.x, h.y, mem.hi, timeLeft);
    return out;
  }
  if (mem.navT > mem.navLim) {
    h.fails += 1; mem.mode = 'pick'; mem.hi = -1;
    return out;
  }
  return drive(mem, wrap(brg(me.x, me.y, h.x, h.y) - H), d > 10 ? 0.3 : 0.22, rays, out);
}

function deliverStep(mem, me, H, dBase, vAvg, carried, obs, rays, out) {
  if (carried <= 0) { mem.mode = 'pick'; return out; }
  const bc = obs.beacon;
  let bd = dBase;
  if (bc && isFinite(bc.distance)) bd = Math.min(bd, bc.distance);
  if (obs.docked || bd <= 2.5) {
    mem.dockT++;
    out.left = clamp(-vAvg, -0.1, 0.1); out.right = out.left; out.drill = false;
    if (mem.dockT > 80) { mem.noDel = mem.tick + 300; mem.mode = 'pick'; mem.dockT = 0; }
    return out;
  }
  mem.dockT = 0;
  let e;
  if (bc && isFinite(bc.bearing) && isFinite(bc.distance) && bc.distance < 8) e = bc.bearing;
  else e = wrap(brg(me.x, me.y, mem.base.x, mem.base.y) - H);
  return drive(mem, e, bd > 8 ? 0.3 : 0.2, rays, out);
}

function wanderStep(mem, me, H, rays, out, timeLeft, sci) {
  if (sci > 2.0 && mem.tick > mem.sciCool) {
    startSearch(mem, me, me.x, me.y, -1, timeLeft);
    return out;
  }
  if (mem.tick % 25 === 0 && pickHint(mem, me, timeLeft) >= 0) {
    mem.mode = 'pick';
    return out;
  }
  if (!mem.wd || mem.wT > 400 || dist(me.x, me.y, mem.wd.x, mem.wd.y) < 6) {
    mem.wd = { x: 30 + rnd(mem) * 340, y: 30 + rnd(mem) * 340 };
    mem.wT = 0;
  }
  mem.wT++;
  return drive(mem, wrap(brg(me.x, me.y, mem.wd.x, mem.wd.y) - H), 0.25, rays, out);
}

function pickStep(mem, me, carried, timeLeft, battery, dBase) {
  const hi = pickHint(mem, me, timeLeft);
  const endgame = timeLeft < dBase / 0.35 + 90;
  if (carried > 0 && mem.tick >= mem.noDel &&
      (carried >= mem.cap || endgame || battery < 0.2 || hi < 0 || (carried >= 2 && dBase < 40))) {
    mem.mode = 'deliver'; mem.dockT = 0; return;
  }
  if (hi >= 0) {
    mem.hi = hi; mem.mode = 'go'; mem.navT = 0;
    mem.navLim = dist(me.x, me.y, mem.hints[hi].x, mem.hints[hi].y) * 6 + 200;
    return;
  }
  mem.mode = 'wander'; mem.wd = null; mem.wT = 0; mem.hi = -1;
}

function core(obs, mem) {
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  const gx = num(obs.x), gy = num(obs.y);
  const wl = num(obs.wheelLeft), wr = num(obs.wheelRight);
  const vAvg = (wl + wr) / 2;
  const carried = num(obs.carried);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const rays = sanitizeRays(obs.rays);
  const site = (obs.site && typeof obs.site === 'object') ? obs.site : null;
  const sci = num(obs.science);

  // compass median
  mem.cb.push(num(obs.heading));
  if (mem.cb.length > 5) mem.cb.shift();
  const cm = medoid(mem.cb);

  // GPS freshness and fix history
  const fresh = mem.lgx === null || gx !== mem.lgx || gy !== mem.lgy;
  if (fresh) {
    mem.lgx = gx; mem.lgy = gy; mem.stale = 0;
    mem.fx.push({ x: gx, y: gy, t: mem.tick });
    if (mem.fx.length > 60) mem.fx.shift();
  } else mem.stale++;

  // compass offset learned from GPS chords while driving straight
  if (fresh && mem.fx.length >= 2) {
    const n = mem.fx.length, c = mem.fx[n - 1];
    let j = -1;
    for (let i = n - 2; i >= 0; i--) {
      const f = mem.fx[i];
      if (mem.tick - f.t > 150) break;
      if (dist(c.x, c.y, f.x, f.y) >= 4) { j = i; break; }
    }
    if (j >= 0 && mem.lastL > 0.2 && mem.lastR > 0.2 && Math.abs(mem.lastL - mem.lastR) < 0.12) {
      const f = mem.fx[j];
      const ch = brg(f.x, f.y, c.x, c.y);
      if (!mem.offInit) { mem.off = wrap(ch - cm); mem.offInit = true; }
      else mem.off = wrap(mem.off + 0.05 * wrap(ch - cm - mem.off));
    }
  }
  const H = wrap(cm + mem.off);

  // position: GPS, dead reckoning when GPS is frozen
  if (!mem.dr || fresh) mem.dr = { x: gx, y: gy };
  else {
    const hr = H * D2R, vv = clamp(vAvg, -1, 1);
    mem.dr = { x: mem.dr.x + vv * 0.1 * Math.cos(hr), y: mem.dr.y + vv * 0.1 * Math.sin(hr) };
  }
  const useDR = mem.stale > 40;
  const me = useDR ? { x: clamp(mem.dr.x, 0, 400), y: clamp(mem.dr.y, 0, 400) } : { x: gx, y: gy };
  const dBase = dist(me.x, me.y, mem.base.x, mem.base.y);

  // stuck detection: commanded motion but no displacement
  mem.cpT++;
  if (Math.abs(mem.lastL) + Math.abs(mem.lastR) > 0.2) mem.cpMove++;
  if (!mem.cpPos) mem.cpPos = { x: me.x, y: me.y };
  if (mem.cpT >= 30) {
    const d = dist(me.x, me.y, mem.cpPos.x, mem.cpPos.y);
    if (d < 0.6 && mem.cpMove >= 20 && mem.man.length === 0 && mem.mode !== 'drill') {
      startUnstick(mem, rays, 15);
    }
    mem.cpPos = { x: me.x, y: me.y }; mem.cpT = 0; mem.cpMove = 0;
  }
  // bump detection
  if (mem.bumpCd > 0) mem.bumpCd--;
  if (obs.bumped && mem.bumpCd === 0 && mem.man.length === 0 && mem.mode !== 'drill') {
    startUnstick(mem, rays, 8);
    mem.bumpCd = 30;
  }
  // scripted maneuver
  if (mem.man.length > 0) {
    const s = mem.man[0];
    s[2]--;
    out.left = s[0]; out.right = s[1]; out.drill = false;
    if (s[2] <= 0) mem.man.shift();
    return out;
  }
  if (mem.biasT > 0) mem.biasT--; else mem.bias = 0;

  // drilling: hold still with drill on until a sample arrives
  if (mem.mode === 'drill') {
    mem.dT++;
    if (carried > mem.dC0) {
      if (mem.dPos) markNear(mem, mem.dPos, 20);
      if (mem.dSite) mem.ign.push(mem.dSite);
      mem.mode = 'pick'; mem.siteT = 0;
      return out;
    }
    if (mem.dT > 150 || (!site && mem.dT > 20)) {
      if (mem.dSite) mem.ign.push(mem.dSite);
      mem.mode = 'pick'; mem.siteT = 0;
      return out;
    }
    const still = Math.abs(vAvg) < 0.15 && Math.abs(wl) < 0.2 && Math.abs(wr) < 0.2;
    out.left = clamp(-vAvg, -0.1, 0.1); out.right = out.left;
    out.drill = still;
    return out;
  }

  // opportunistic sampling of a visible site
  if (mem.mode !== 'deliver' && carried < mem.cap && site && timeLeft > 30) {
    const d = num(site.distance, 99);
    const sw = siteWorld(me, H, site);
    if (d <= 8.5 && !isIgn(mem, sw)) {
      mem.siteT++;
      if (mem.siteT > 250) {
        mem.ign.push(sw); mem.siteT = 0;
      } else if (d <= 1.4) {
        const still = Math.abs(vAvg) < 0.12 && Math.abs(wl) < 0.15 && Math.abs(wr) < 0.15;
        if (still) {
          mem.mode = 'drill';
          mem.dT = 0; mem.dC0 = carried;
          mem.dPos = { x: me.x, y: me.y };
          mem.dSite = sw;
          out.drill = true;
          return out;
        }
        out.left = clamp(-vAvg, -0.1, 0.1); out.right = out.left;
        return out;
      } else {
        return drive(mem, num(site.bearing), clamp(0.1 + 0.08 * d, 0.12, 0.25), rays, out);
      }
    }
  } else {
    mem.siteT = 0;
  }

  if (mem.mode === 'pick') pickStep(mem, me, carried, timeLeft, battery, dBase);
  if (mem.mode === 'deliver') return deliverStep(mem, me, H, dBase, vAvg, carried, obs, rays, out);
  if (mem.mode === 'go') return goStep(mem, me, H, rays, out, timeLeft);
  if (mem.mode === 'search') return searchStep(mem, me, H, rays, out, timeLeft);
  if (mem.mode === 'wander') return wanderStep(mem, me, H, rays, out, timeLeft, sci);

  mem.mode = 'pick';
  return out;
}

function act(obs, mem) {
  let out = { left: 0, right: 0, drill: false };
  try {
    if (!mem.init) init(obs, mem);
    out = core(obs, mem) || out;
  } catch (e) {
    out = { left: 0, right: 0, drill: false };
    if (mem.init) { mem.mode = 'pick'; mem.man = []; mem.sr = null; mem.hi = -1; }
  }
  const l = clamp(num(out.left), -1, 1);
  const r = clamp(num(out.right), -1, 1);
  mem.lastL = l; mem.lastR = r;
  return { left: l, right: r, drill: !!out.drill };
}
